\label{lemma-flat-universally-injective}
Let $f : X \to Y$ be a morphism of schemes. Let $X^0$ denote the set
of generic points of irreducible components of $X$. If
\begin{enumerate}
\item $f$ is flat and separated,
\item for $\xi \in X^0$ we have $\kappa(f(\xi)) = \kappa(\xi)$, and
\item if $\xi, \xi' \in X^0$, $\xi \not = \xi'$, then $f(\xi) \not = f(\xi')$,
\end{enumerate}
then $f$ is universally injective.

\label{lemma-characterize-open-immersion}
Let $f : X \to Y$ be a morphism of schemes. Let $X^0$ denote the set
of generic points of irreducible components of $X$. If
\begin{enumerate}
\item $f$ is \'etale and separated,
\item for $\xi \in X^0$ we have $\kappa(f(\xi)) = \kappa(\xi)$, and
\item if $\xi, \xi' \in X^0$, $\xi \not = \xi'$, then $f(\xi) \not = f(\xi')$,
\end{enumerate}
then $f$ is an open immersion.

\label{lemma-locally-finite-presentation-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite presentation''
is fppf local on the source.

\label{lemma-locally-finite-type-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite type''
is fppf local on the source.

\label{lemma-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is open''
is fppf local on the source.

\label{lemma-universally-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is universally open''
is fppf local on the source.

\label{lemma-syntomic-syntomic-local-source}
The property $\mathcal{P}(f)=$``$f$ is syntomic''
is syntomic local on the source.

\label{lemma-smooth-smooth-local-source}
The property $\mathcal{P}(f)=$``$f$ is smooth''
is smooth local on the source.

\label{lemma-etale-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is \'etale''
is \'etale local on the source.

\label{lemma-locally-quasi-finite-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally quasi-finite''
is \'etale local on the source.

\label{definition-local-source-target}
Let $\mathcal{P}$ be a property of morphisms of schemes.
We say $\mathcal{P}$ is {\it \'etale local on source-and-target} if
\begin{enumerate}
\item (stable under precomposing with \'etale maps)
if $f : X \to Y$ is \'etale and $g : Y \to Z$ has $\mathcal{P}$,
then $g \circ f$ has $\mathcal{P}$,
\item (stable under \'etale base change)
if $f : X \to Y$ has $\mathcal{P}$ and $Y' \to Y$ is \'etale, then
the base change $f' : Y' \times_Y X \to Y'$ has $\mathcal{P}$, and
\item (locality) given a morphism $f : X \to Y$ the following are equivalent
\begin{enumerate}
\item $f$ has $\mathcal{P}$,
\item for every $x \in X$ there exists a commutative diagram
$$
\xymatrix{
U \ar[d]_a \ar[r]_h & V \ar[d]^b \\
X \ar[r]^f & Y
}
$$
with \'etale vertical arrows and $u \in U$ with $a(u) = x$ such that
$h$ has $\mathcal{P}$.
\end{enumerate}
\end{enumerate}

\label{lemma-etale-etale-local-source-target}
Let $\mathcal{P}$ be a property of morphisms of schemes which
is \'etale local on the source-and-target.
Given a commutative diagram of schemes
$$
\vcenter{
\xymatrix{
X' \ar[d]_{g'} \ar[r]_{f'} & Y' \ar[d]^g \\
X \ar[r]^f & Y
}
}
\quad\text{with points}\quad
\vcenter{
\xymatrix{
x' \ar[d] \ar[r] & y' \ar[d] \\
x \ar[r] & y
}
}
$$
such that $g'$ is \'etale at $x'$ and $g$ is \'etale at $y'$, then
$x \in W(f) \Leftrightarrow x' \in W(f')$
where $W(-)$ is as in Lemma \ref{lemma-largest-open-of-the-source}.

\label{lemma-etale-tau-local-source-target}
Let $\mathcal{P}$ be a property of morphisms of schemes. Assume
\begin{enumerate}
\item $\mathcal{P}$ is \'etale local on the source,
\item $\mathcal{P}$ is smooth local on the target,
\item $\mathcal{P}$ is stable under postcomposing with open immersions:
if $f : X \to Y$ has $\mathcal{P}$ and $Y \subset Z$ is an open
subscheme then $X \to Z$ has $\mathcal{P}$.
\end{enumerate}
Given a commutative diagram of schemes
$$
\vcenter{
\xymatrix{
X' \ar[d]_{g'} \ar[r]_{f'} & Y' \ar[d]^g \\
X \ar[r]^f & Y
}
}
\quad\text{with points}\quad
\vcenter{
\xymatrix{
x' \ar[d] \ar[r] & y' \ar[d] \\
x \ar[r] & y
}
}
$$
such that $g$ is smooth $y'$ and $X' \to X \times_Y Y'$ is \'etale
at $x'$, then $x \in W(f) \Leftrightarrow x' \in W(f')$
where $W(-)$ is as in Lemma \ref{lemma-largest-open-of-the-source}.

\label{definition-local-source-target-at-point}
Let $\mathcal{Q}$ be a property of morphisms of germs of schemes.
We say $\mathcal{Q}$ is  {\it \'etale local on the source-and-target}
if for any commutative diagram
$$
\xymatrix{
(U', u') \ar[d]_a \ar[r]_{h'} & (V', v') \ar[d]^b \\
(U, u) \ar[r]^h & (V, v)
}
$$
of germs with \'etale vertical arrows we have
$\mathcal{Q}(h) \Leftrightarrow \mathcal{Q}(h')$.

\label{lemma-etale-on-fiber}
Consider a commutative diagram of morphisms of schemes
$$
\xymatrix{
U' \ar[r] \ar[d] & V' \ar[d] \\
U \ar[r] & V
}
$$
with \'etale vertical arrows and a point $v' \in V'$ mapping to $v \in V$.
Then the morphism of fibres $U'_{v'} \to U_v$ is \'etale.

\label{lemma-dimension-local-ring-fibre}
Let $d \in \{0, 1, 2, \ldots, \infty\}$.
The property of morphisms of germs
$$
\mathcal{P}_d((X, x) \to (S, s)) =
\text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre has dimension }d
$$
is \'etale local on the source-and-target.

\label{lemma-family-is-one}
Let $S$ be a scheme.
Let $\{X_i \to S\}_{i \in I}$ be a family of morphisms with target $S$.
Set $X = \coprod_{i \in I} X_i$, and consider it as an $S$-scheme.
There is a canonical equivalence of categories
$$
\begin{matrix}
\text{category of descent data } \\
\text{relative to the family } \{X_i \to S\}_{i \in I}
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/S
\end{matrix}
$$
which maps $(V_i, \varphi_{ij})$ to $(V, \varphi)$ with
$V = \coprod_{i\in I} V_i$ and $\varphi = \coprod \varphi_{ij}$.

\label{lemma-surjective-flat-epi}
A surjective and flat morphism is an epimorphism in the
category of schemes.

\label{lemma-faithful}
In the situation of Lemma \ref{lemma-pullback}
assume that $f : X' \to X$ is surjective
and flat. Then the pullback functor is faithful.

\label{lemma-fully-faithful}
In the situation of Lemma \ref{lemma-pullback}
assume
\begin{enumerate}
\item $\{f : X' \to X\}$ is an fpqc covering (for example if $f$ is
surjective, flat, and quasi-compact), and
\item $S = S'$.
\end{enumerate}
Then the pullback functor is fully faithful.

\label{lemma-descent-data-sheaves}
Let $\tau \in \{Zariski, fppf, \etale, smooth, syntomic\}$\footnote{The
fact that fpqc is missing is not a typo. See discussion
in Topologies, Section \ref{topologies-section-fpqc}.}.
Let $\Sch_\tau$ be a big $\tau$-site.
Let $S \in \Ob(\Sch_\tau)$.
Let $\{S_i \to S\}_{i \in I}$ be a covering in the
site $(\Sch/S)_\tau$. There is an equivalence of
categories
$$
\left\{
\begin{matrix}
\text{descent data }(X_i, \varphi_{ii'})\text{ such that}\\
\text{each }X_i \in \Ob((\Sch/S)_\tau)
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{sheaves }F\text{ on }(\Sch/S)_\tau\text{ such that}\\
\text{each }h_{S_i} \times F\text{ is representable}
\end{matrix}
\right\}.
$$
Moreover,
\begin{enumerate}
\item the objects representing $h_{S_i} \times F$ on the right hand side
correspond to the schemes $X_i$ on the left hand side, and
\item the sheaf $F$ is representable if and only if the
corresponding descent datum $(X_i, \varphi_{ii'})$ is effective.
\end{enumerate}

\label{definition-homomorphism-dga}
A {\it homomorphism of differential graded algebras}
$f : (A, \text{d}) \to (B, \text{d})$ is an algebra map $f : A \to B$
compatible with the gradings and $\text{d}$.

\label{lemma-dgm-abelian}
Let $(A, d)$ be a differential graded algebra. The category
$\text{Mod}_{(A, \text{d})}$ is abelian and has arbitrary limits and colimits.

\label{definition-admissible-ses}
Let $(A, \text{d})$ be a differential graded algebra.
\begin{enumerate}
\item A homomorphism $K \to L$ of differential graded $A$-modules
is an {\it admissible monomorphism} if there exists a graded $A$-module
map $L \to K$ which is left inverse to $K \to L$.
\item A homomorphism $L \to M$ of differential graded $A$-modules
is an {\it admissible epimorphism} if there exists a graded $A$-module
map $M \to L$ which is right inverse to $L \to M$.
\item A short exact sequence $0 \to K \to L \to M \to 0$ of differential
graded $A$-modules is an {\it admissible short exact sequence}
if it is split as a sequence of graded $A$-modules.
\end{enumerate}

\label{lemma-make-commute-map}
Let $(A, \text{d})$ be a differential graded algebra. Let
$$
\xymatrix{
K \ar[r]_f \ar[d]_a & L \ar[d]^b \\
M \ar[r]^g & N
}
$$
be a diagram of homomorphisms of differential graded $A$-modules
commuting up to homotopy.
\begin{enumerate}
\item If $f$ is an admissible monomorphism, then $b$ is homotopic to a
homomorphism which makes the diagram commute.
\item If $g$ is an admissible epimorphism, then $a$ is homotopic to a
morphism which makes the diagram commute.
\end{enumerate}

\label{lemma-nilpotent}
Let $(A, \text{d})$ be a differential graded algebra.
Let $0 \to K_i \to L_i \to M_i \to 0$, $i = 1, 2, 3$
be admissible short exact sequence of differential graded $A$-modules.
Let $b : L_1 \to L_2$ and $b' : L_2 \to L_3$
be homomorphisms of differential graded modules such that
$$
\vcenter{
\xymatrix{
K_1 \ar[d]_0 \ar[r] &
L_1 \ar[r] \ar[d]_b &
M_1 \ar[d]_0 \\
K_2 \ar[r] & L_2 \ar[r] & M_2
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
K_2 \ar[d]^0 \ar[r] &
L_2 \ar[r] \ar[d]^{b'} &
M_2 \ar[d]^0 \\
K_3 \ar[r] & L_3 \ar[r] & M_3
}
}
$$
commute up to homotopy. Then $b' \circ b$ is homotopic to $0$.

\label{lemma-triangle-independent-splittings}
Let $(A, \text{d})$ be a differential graded algebra. Let
$0 \to K \to L \to M \to 0$ be an admissible short exact sequence
of differential graded $A$-modules. The triangle
\begin{equation}
\label{equation-triangle-associated-to-admissible-ses}
K \to L \to M \xrightarrow{\delta} K[1]
\end{equation}
with $\delta$ as in Lemma \ref{lemma-admissible-ses} is, up to canonical
isomorphism in $K(\text{Mod}_{(A, \text{d})})$, independent of the choices
made in Lemma \ref{lemma-admissible-ses}.

\label{lemma-resolve}
Let $(A, \text{d})$ be a differential graded algebra.
Let $M$ be a differential graded $A$-module. There exists a homomorphism
$P \to M$ of differential graded $A$-modules such that
\begin{enumerate}
\item $P \to M$ is a quasi-isomorphism, and
\item $P$ has property (P).
\end{enumerate}

\label{lemma-right-resolution}
Let $(A, \text{d})$ be a differential graded algebra.
Let $M$ be a differential graded $A$-module. There exists a homomorphism
$M \to I$ of differential graded $A$-modules such that
\begin{enumerate}
\item $M \to I$ is a quasi-isomorphism, and
\item $I$ has property (I).
\end{enumerate}

\label{lemma-derived-products}
Let $(A, \text{d})$ be a differential graded algebra. Then
\begin{enumerate}
\item $D(A, \text{d})$ has both direct sums and products,
\item direct sums are obtained by taking direct sums of differential graded
modules,
\item products are obtained by taking products of differential
graded modules.
\end{enumerate}

\label{definition-functor-dga-categories}
Let $R$ be a ring. A {\it functor of differential graded categories over $R$}
is a functor $F : \mathcal{A} \to \mathcal{B}$ where for all objects
$x, y$ of $\mathcal{A}$ the map
$F : \Hom_\mathcal{A}(x, y) \to \Hom_\mathcal{A}(F(x), F(y))$
is a homomorphism of differential graded $R$-modules.

\label{lemma-id-cone-null}
In Situation \ref{situation-ABC}
given any object $x$ of $\mathcal{A}$, and the cone $C(1_x)$ of the
identity morphism $1_x : x \to x$, the identity morphism on
$C(1_x)$ is homotopic to zero.

\label{lemma-homo-change}
In Situation \ref{situation-ABC} given a diagram
$$
\xymatrix{x\ar[r]^f\ar[d]_a & y\ar[d]^b\\
z\ar[r]^g & w}
$$
in $\text{Comp}(\mathcal{A})$ commuting up to homotopy. Then
\begin{enumerate}
\item If $f$ is an admissible monomorphism, then $b$ is homotopic
to a morphism $b'$ which makes the diagram commute.
\item If $g$ is an admissible epimorphism, then $a$ is homotopic
to a morphism $a'$ which makes the diagram commute.
\end{enumerate}

\label{lemma-triseq}
In Situation \ref{situation-ABC} let $x_i \to y_i \to z_i$
be morphisms in $\mathcal{A}$ ($i=1,2,3$) such that
$x_2 \to y_2\to z_2$ is an admissible short exact sequence.
Let $b : y_1 \to y_2$ and $b' : y_2\to y_3$ be morphisms
in $\text{Comp}(\mathcal{A})$ such that
$$
\vcenter{
\xymatrix{
x_1 \ar[d]_0 \ar[r] &
y_1 \ar[r] \ar[d]_b &
z_1 \ar[d]_0 \\
x_2 \ar[r] & y_2 \ar[r] & z_2
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
x_2 \ar[d]^0 \ar[r] &
y_2 \ar[r] \ar[d]^{b'} &
z_2 \ar[d]^0 \\
x_3 \ar[r] & y_3 \ar[r] & z_3
}
}
$$
commute up to homotopy. Then $b'\circ b$ is homotopic to $0$.

\label{lemma-analogue-triangle-independent-splittings}
In Situation \ref{situation-ABC}
let $0 \to x \to y \to z \to 0$ be an admissible short
exact sequence in $\text{Comp}(\mathcal{A})$. The triangle
$$
\xymatrix{x\ar[r] & y\ar[r] & z\ar[r]^{\delta} & x[1]}
$$
with $\delta : z \to x[1]$ as defined in Lemma \ref{lemma-get-triangle}
is up to canonical isomorphism in $K(\mathcal{A})$, independent of the
choices made in Lemma \ref{lemma-get-triangle}.

\label{lemma-restate-axiom-c}
In Situation \ref{situation-ABC}
let $f: x \to y$ be a morphism in $\text{Comp}(\mathcal{A})$.
The triangle $(y, c(f), x[1], i, p, f[1])$ is the triangle associated
to the admissible short exact sequence 
$$
\xymatrix{y\ar[r] & c(f) \ar[r] & x[1]}
$$
where the cone $c(f)$ is defined as in Lemma \ref{lemma-get-triangle}.

\label{lemma-bimodule-over-tensor}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$
be differential graded algebras over $R$. The construction above
defines an equivalence of categories
$$
\begin{matrix}
\text{differential graded}\\
(A, B)\text{-bimodules}
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{right differential graded }\\
A^{opp} \otimes_R B\text{-modules}
\end{matrix}
$$

\label{lemma-derived-restriction}
In the situation above, the right derived functor of $F$ exists.
We denote it $R\Hom(N, -) : D(B, \text{d}) \to D(A, \text{d})$.

\label{lemma-tensor-with-compact-fully-faithful}
With notation and assumptions as in Lemma \ref{lemma-tensor-hom-adjoint}.
Assume
\begin{enumerate}
\item $N$ defines a compact object of $D(B, \text{d})$, and
\item the map $H^k(A) \to \Hom_{D(B, \text{d})}(N, N[k])$ is an
isomorphism for all $k \in \mathbf{Z}$.
\end{enumerate}
Then the functor $-\otimes_A^\mathbf{L} N$ is fully faithful.

\label{proposition-compact}
Let $(A, \text{d})$ be a differential graded algebra. Let $E$ be an
object of $D(A, \text{d})$. Then the following are equivalent
\begin{enumerate}
\item $E$ is a compact object,
\item $E$ is a direct summand of an object of $D(A, \text{d})$
which is represented by a differential graded module $P$ which
has a finite filtration $F_\bullet$ by differential graded submodules
such that $F_iP/F_{i - 1}P$ are finite direct sums of shifts of $A$.
\end{enumerate}

\label{lemma-rickard}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$ be
differential graded $R$-algebras. Assume that $A = H^0(A)$.
The following are equivalent
\begin{enumerate}
\item $D(A, \text{d})$ and $D(B, \text{d})$ are equivalent as $R$-linear
triangulated categories, and
\item there exists an object $P$ of $D(B, \text{d})$ such that
\begin{enumerate}
\item $P$ is a compact object of $D(B, \text{d})$,
\item if $N \in D(B, \text{d})$ with $\Hom_{D(B, \text{d})}(P, N[i]) = 0$
for $i \in \mathbf{Z}$, then $N = 0$,
\item $\Hom_{D(B, \text{d})}(P, P[i]) = 0$ for $i \not = 0$ and
equal to $A$ for $i = 0$.
\end{enumerate}
\end{enumerate}
The equivalence $D(A, \text{d}) \to D(B, \text{d})$
constructed in (2) sends $A$ to $P$.

\label{proposition-rickard}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$ be
differential graded $R$-algebras. Let $F : D(A, \text{d}) \to D(B, \text{d})$
be an $R$-linear equivalence of triangulated categories. Assume that
\begin{enumerate}
\item $A = H^0(A)$, and
\item $B$ is K-flat as a complex of $R$-modules.
\end{enumerate}
Then there exists an $(A, B)$-bimodule $N$ as in
Lemma \ref{lemma-tilting-equivalence}.

\label{lemma-rickard-rings}
Let $R$ be a ring.
Let $A$ and $B$ be $R$-algebras. The following are equivalent
\begin{enumerate}
\item there is an $R$-linear equivalence $D(A) \to D(B)$
of triangulated categories,
\item there exists an object $P$ of $D(B)$ such that
\begin{enumerate}
\item $P$ can be represented by a finite complex
of finite projective $B$-modules,
\item if $K \in D(B)$ with $\Ext^i_B(P, K) = 0$ for
$i \in \mathbf{Z}$, then $K = 0$, and
\item $\Ext^i_B(P, P) = 0$ for $i \not = 0$ and
equal to $A$ for $i= 0$.
\end{enumerate}
\end{enumerate}
Moreover, if $B$ is flat as an $R$-module, then this is also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $(A, B)$-bimodule $N$ such that
$- \otimes_A^\mathbf{L} N : D(A) \to D(B)$ is an equivalence.
\end{enumerate}

\label{lemma-K-flat-resolution}
Let $R$ be a ring. Let $(B, \text{d})$ be a differential graded $R$-algebra.
There exists a quasi-isomorphism $(A, \text{d}) \to (B, \text{d})$ of
differential graded $R$-algebras with the following properties
\begin{enumerate}
\item $A$ is K-flat as a complex of $R$-modules,
\item $A$ is a free graded $R$-algebra.
\end{enumerate}

\label{lemma-countable}
Let $(A, \text{d})$ be a differential graded algebra with
$H^i(A)$ countable for each $i$. Let $M$ be an object of $D(A, \text{d})$.
Then the following are equivalent
\begin{enumerate}
\item $M = \text{hocolim} E_n$ with $E_n$ compact in $D(A, \text{d})$, and
\item $H^i(M)$ is countable for each $i$.
\end{enumerate}

\label{lemma-dualizing-well-defined}
The module (\ref{equation-dualizing}) is well defined, i.e.,
independent of the choice of the factorization.

\label{lemma-localize-dualizing}
Let $A \to B$ be a quasi-finite map of Noetherian rings.
\begin{enumerate}
\item If $A \to B$ factors as $A \to A_f \to B$ for some $f \in A$,
then $\omega_{B/A} = \omega_{B/A_f}$.
\item If $g \in B$, then $(\omega_{B/A})_g = \omega_{B_g/A}$.
\item If $f \in A$, then $\omega_{B_f/A_f} = (\omega_{B/A})_f$.
\end{enumerate}

\label{lemma-dualizing-base-flat-flat}
Let $A \to B$ be a flat quasi-finite homomorphism of Noetherian rings.
Then $\omega_{B/A}$ is a flat $A$-module.

\label{lemma-dualizing-base-change-of-flat}
If $A \to B$ is flat, then the base change map (\ref{equation-bc-dualizing})
induces an isomorphism $\omega_{B/A} \otimes_B B_1 \to \omega_{B_1/A_1}$.

\label{lemma-discriminant}
Let $\pi : X \to Y$ be a morphism of schemes which is finite locally
free. Then $\pi$ is \'etale if and only if its discriminant is empty.

\label{lemma-trace-unique}
Let $A \to B$ be a flat quasi-finite map of Noetherian rings.
Then there is at most one trace element in $\omega_{B/A}$.

\label{lemma-finite-flat-trace}
Let $A \to B$ be a finite flat map of Noetherian rings.
Then $\text{Trace}_{B/A} \in \omega_{B/A}$ is the trace element.

\label{lemma-dualizing-tau}
Let $A \to B$ be a flat quasi-finite map of Noetherian rings.
There exists a trace element $\tau \in \omega_{B/A}$.

\label{lemma-tau-nonzero}
Let $k$ be a field and let $A$ be a finite $k$-algebra. Assume $A$
is local with residue field $k'$. The following are equivalent
\begin{enumerate}
\item $\text{Trace}_{A/k}$ is nonzero,
\item $\tau_{A/k} \in \omega_{A/k}$ is nonzero, and
\item $k'/k$ is separable and $\text{length}_A(A)$ is prime
to the characteristic of $k$.
\end{enumerate}

\label{lemma-noether-different-product}
Let $A \to B_i$, $i = 1, 2$ be ring maps. Set $B = B_1 \times B_2$.
\begin{enumerate}
\item The annihilator $J$ of $\Ker(B \otimes_A B \to B)$ is $J_1 \times J_2$
where $J_i$ is the annihilator of $\Ker(B_i \otimes_A B_i \to B_i)$.
\item The Noether different $\mathfrak{D}$ of $B$ over $A$ is
$\mathfrak{D}_1 \times \mathfrak{D}_2$, where $\mathfrak{D}_i$ is
the Noether different of $B_i$ over $A$.
\end{enumerate}

\label{lemma-noether-different-base-change}
Let $A \to B$ be a finite type ring map. Let $A \to A'$ be a flat ring map.
Set $B' = B \otimes_A A'$.
\begin{enumerate}
\item The annihilator $J'$ of $\Ker(B' \otimes_{A'} B' \to B')$ is
$J \otimes_A A'$ where $J$ is the annihilator of $\Ker(B \otimes_A B \to B)$.
\item The Noether different $\mathfrak{D}'$ of $B'$ over $A'$ is
$\mathfrak{D}B'$, where $\mathfrak{D}$ is
the Noether different of $B$ over $A$.
\end{enumerate}

\label{lemma-noether-pairing-compatibilities}
Let $A \to B$ be a quasi-finite homomorphism of Noetherian rings.
\begin{enumerate}
\item If $A \to A'$ is a flat map of Noetherian rings, then
$$
\xymatrix{
\omega_{B/A} \times J \ar[r] \ar[d] & B \ar[d]  \\
\omega_{B'/A'} \times J' \ar[r] & B'
}
$$
is commutative where notation as in
Lemma \ref{lemma-noether-different-base-change}
and horizontal arrows are given by
(\ref{equation-pairing-noether}).
\item If $B = B_1 \times B_2$, then
$$
\xymatrix{
\omega_{B/A} \times J \ar[r] \ar[d] & B \ar[d]  \\
\omega_{B_i/A} \times J_i \ar[r] & B_i
}
$$
is commutative for $i = 1, 2$ where notation as in
Lemma \ref{lemma-noether-different-product}
and horizontal arrows are given by
(\ref{equation-pairing-noether}).
\end{enumerate}

\label{definition-kahler-different}
Let $f : Y \to X$ be a morphism of schemes which is locally of finite type.
The {\it K\"ahler different} is the $0$th fitting ideal of $\Omega_{Y/X}$.

\label{lemma-flat-dedekind-complementary-module-trace}
If the Dedekind different of $A \to B$ is defined and $A \to B$ is flat, then
\begin{enumerate}
\item the canonical isomorphism $\mathcal{L}_{B/A} \to \omega_{B/A}$
sends $1 \in \mathcal{L}_{B/A}$ to the trace element
$\tau_{B/A} \in \omega_{B/A}$, and
\item the Dedekind different is
$\mathfrak{D}_{B/A} = \{b \in B \mid b\omega_{B/A} \subset B\tau_{B/A}\}$.
\end{enumerate}

\label{lemma-dualizing-syntomic-quasi-finite}
Let $f : Y \to X$ be a morphism of locally Noetherian schemes. If $f$
satisfies the equivalent conditions of Lemma \ref{lemma-syntomic-quasi-finite}
then $\omega_{Y/X}$ is an invertible $\mathcal{O}_Y$-module.

\label{lemma-universal-finite-syntomic}
With notation as in Example \ref{example-universal-finite-syntomic}
there is an open subscheme $U_d \subset X_d$ with the following property:
a morphism of schemes $X \to X_d$ factors through $U_d$ if and only
if $Y_d \times_{X_d} X \to X$ is syntomic.

\label{lemma-universal-finite-syntomic-smooth}
With notation as in Example \ref{example-universal-finite-syntomic}
and $U_d$ as in Lemma \ref{lemma-universal-finite-syntomic}
then $U_d$ is smooth over $\Spec(\mathbf{Z})$.

\label{lemma-universal-finite-syntomic-etale}
With notation as in Example \ref{example-universal-finite-syntomic}
consider the open subscheme $U'_d \subset X_d$ over which
$\pi_d$ is \'etale. Then $U'_d$ is a dense subset of the
open $U_d$ of Lemma \ref{lemma-universal-finite-syntomic}.

\label{lemma-tate}
\begin{reference}
\cite[Appendix]{Mazur-Roberts}
\end{reference}
Let $A \to P$ be a ring map. Let $f_1, \ldots, f_n \in P$ be a
Koszul regular sequence. Assume $B = P/(f_1, \ldots, f_n)$
is flat over $A$. Let $g_1, \ldots, g_n \in P \otimes_A B$
be a Koszul regular sequence generating the kernel of the multiplication
map $P \otimes_A B \to B$. Write $f_i \otimes 1 = \sum g_{ij} g_j$.
Then the annihilator of $\Ker(B \otimes_A B \to B)$ is a principal
ideal generated by the image of $\det(g_{ij})$.

\label{lemma-different-syntomic-quasi-finite}
Let $f : Y \to X$ be a morphism of Noetherian schemes. If $f$
satisfies the equivalent conditions of Lemma \ref{lemma-syntomic-quasi-finite}
then the different $\mathfrak{D}_f$ of $f$ is the K\"ahler different
of $f$.

\label{proposition-tate-map}
There exists a unique rule that to every locally quasi-finite syntomic
morphism of locally Noetherian schemes $Y \to X$ assigns an isomorphism
$$
c_{Y/X} : \det(\NL_{Y/X}) \longrightarrow \omega_{Y/X}
$$
satisfying the following two properties
\begin{enumerate}
\item the section $\delta(\NL_{Y/X})$ is mapped to $\tau_{Y/X}$, and
\item the rule is compatible with restriction to opens and with
base change.
\end{enumerate}

\label{lemma-S1-no-embedded}
Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathcal{F}$ has no embedded associated points, and
\item $\mathcal{F}$ has property $(S_1)$.
\end{enumerate}

\label{lemma-noetherian-dim-1-CM-no-embedded-points}
Let $X$ be a locally Noetherian scheme of dimension $\leq 1$.
The following are equivalent
\begin{enumerate}
\item $X$ is Cohen-Macaulay, and
\item $X$ has no embedded points.
\end{enumerate}

\label{lemma-scheme-theoretically-dense-contain-embedded-points}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an
open subscheme. The following are equivalent
\begin{enumerate}
\item $U$ is scheme theoretically dense in $X$
(Morphisms, Definition \ref{morphisms-definition-scheme-theoretically-dense}),
\item $U$ is dense in $X$ and $U$ contains all embedded points of $X$, and
\item $U$ contains all associated points of $X$.
\end{enumerate}

\label{lemma-weakly-associated-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is weakly associated to $M$, and
\item $x$ is weakly associated to $\mathcal{F}$.
\end{enumerate}

\label{lemma-check-injective-on-weakass}
Let $X$ be a scheme. Let $\varphi : \mathcal{F} \to \mathcal{G}$ be a map of
quasi-coherent $\mathcal{O}_X$-modules. Assume that for every $x \in X$
at least one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x \to \mathcal{G}_x$ is injective, or
\item $x \not \in \text{WeakAss}(\mathcal{F})$.
\end{enumerate}
Then $\varphi$ is injective.

\label{lemma-weakass-reduced}
Let $X$ be a reduced scheme. Then the weakly associated points of $X$
are exactly the generic points of the irreducible components of $X$.

\label{lemma-fitting-ideal-finite-locally-free}
Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. Let $r \geq 0$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally free of rank $r$
\item $\text{Fit}_{r - 1}(\mathcal{F}) = 0$ and
$\text{Fit}_r(\mathcal{F}) = \mathcal{O}_S$, and
\item $\text{Fit}_k(\mathcal{F}) = 0$ for $k < r$ and
$\text{Fit}_k(\mathcal{F}) = \mathcal{O}_S$ for $k \geq r$.
\end{enumerate}

\label{lemma-locally-free-rank-r-pullback}
Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. The closed subschemes
$$
S = Z_{-1} \supset Z_0 \supset Z_1 \supset Z_2 \ldots
$$
defined by the Fitting ideals of $\mathcal{F}$ have the following
properties
\begin{enumerate}
\item The intersection $\bigcap Z_r$ is empty.
\item The functor $(\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ is locally generated by }
\leq r\text{ sections} \\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the open subscheme $S \setminus Z_r$.
\item The functor $F_r : (\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ locally free rank }r\\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the locally closed subscheme $Z_{r - 1} \setminus Z_r$
of $S$.
\end{enumerate}
If $\mathcal{F}$ is of finite presentation, then
$Z_r \to S$, $S \setminus Z_r \to S$, and $Z_{r - 1} \setminus Z_r \to S$
are of finite presentation.

\label{definition-torsion}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module.
\begin{enumerate}
\item We say a local section of $\mathcal{F}$ is {\it torsion}
if it satisfies the equivalent conditions of Lemma \ref{lemma-torsion-sections}.
\item We say $\mathcal{F}$ is {\it torsion free} if every torsion section
of $\mathcal{F}$ is $0$.
\end{enumerate}

\label{lemma-check-torsion-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a torsion free $\mathcal{O}(U)$-module.
\end{enumerate}

\label{lemma-flat-torsion-free}
Let $X$ be an integral scheme. Any flat quasi-coherent $\mathcal{O}_X$-module
is torsion free.

\label{lemma-flat-over-integral-integral-fibre}
Let $f : X \to Y$ be a flat morphism of schemes. If $Y$ is integral
and the generic fibre of $f$ is integral, then $X$ is integral.

\label{lemma-torsion-free-over-regular-dim-1}
Let $X$ be an integral regular scheme of dimension $\leq 1$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-check-rank-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. Let $r$ be a cardinal. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ has rank $r$,
\item for all $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$, and
\item for some $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$.
\end{enumerate}

\label{lemma-finite-module-rank}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a finite type
quasi-coherent $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $\mathcal{F}$ has finite rank $r \geq 0$, and
\item there exists a nonempty open $U \subset X$
such that $\mathcal{F}|_U$ is free of rank $r$.
\end{enumerate}

\label{lemma-check-reflexive-on-affines}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$ be a
coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a reflexive $\mathcal{O}(U)$-module.
\end{enumerate}

\label{lemma-reflexive-torsion-free}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $\mathcal{F}$ is reflexive, then $\mathcal{F}$ is torsion free.
\item The map $j : \mathcal{F} \longrightarrow \mathcal{F}^{**}$
is injective if and only if $\mathcal{F}$ is torsion free.
\end{enumerate}

\label{lemma-check-reflexive}
Let $X$ be an integral locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module
for all $x \in X$,
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module
for all closed points $x \in X$.
\end{enumerate}

\label{lemma-reflexive-depth-2}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-reflexive-S2}
Let $X$ be an integral locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent reflexive $\mathcal{O}_X$-module.
Let $x \in X$.
\begin{enumerate}
\item If $\text{depth}(\mathcal{O}_{X, x}) \geq 2$, then
$\text{depth}(\mathcal{F}_x) \geq 2$.
\item If $X$ is $(S_2)$, then $\mathcal{F}$ is $(S_2)$.
\end{enumerate}

\label{lemma-reflexive-over-normal}
Let $X$ be an integral locally Noetherian normal scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is torsion free and has property $(S_2)$, and
\item there exists an open subscheme $j : U \to X$ such that
\begin{enumerate}
\item every irreducible component of $X \setminus U$
has codimension $\geq 2$ in $X$,
\item $j^*\mathcal{F}$ is finite locally free, and
\item $\mathcal{F} = j_*j^*\mathcal{F}$.
\end{enumerate}
\end{enumerate}

\label{lemma-reflexive-over-regular-dim-2}
Let $X$ be a regular scheme of dimension $\leq 2$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{definition-effective-Cartier-divisor}
Let $S$ be a scheme.
\begin{enumerate}
\item A {\it locally principal closed subscheme} of $S$ is a closed subscheme
whose sheaf of ideals is locally generated by a single element.
\item An {\it effective Cartier divisor} on $S$ is a closed subscheme
$D \subset S$ whose ideal sheaf $\mathcal{I}_D \subset \mathcal{O}_S$
is an invertible $\mathcal{O}_S$-module.
\end{enumerate}

\label{lemma-characterize-effective-Cartier-divisor}
Let $S$ be a scheme.
Let $D \subset S$ be a closed subscheme.
The following are equivalent:
\begin{enumerate}
\item The subscheme $D$ is an effective Cartier divisor on $S$.
\item For every $x \in D$ there exists an affine open neighbourhood
$\Spec(A) = U \subset S$ of $x$ such that
$U \cap D = \Spec(A/(f))$ with $f \in A$ a nonzerodivisor.
\end{enumerate}

\label{lemma-complement-locally-principal-closed-subscheme}
Let $S$ be a scheme. Let $Z \subset S$ be a locally principal closed
subscheme. Let $U = S \setminus Z$. Then $U \to S$ is an affine morphism.

\label{lemma-sum-effective-Cartier-divisors}
The sum of two effective Cartier divisors is an effective
Cartier divisor.

\label{lemma-regular-section-structure-sheaf}
Let $X$ be a locally ringed space. Let $f \in \Gamma(X, \mathcal{O}_X)$.
The following are equivalent:
\begin{enumerate}
\item $f$ is a regular section, and
\item for any $x \in X$ the image $f \in \mathcal{O}_{X, x}$
is a nonzerodivisor.
\end{enumerate}
If $X$ is a scheme these are also equivalent to
\begin{enumerate}
\item[(3)] for any affine open $\Spec(A) = U \subset X$
the image $f \in A$ is a nonzerodivisor,
\item[(4)] there exists an affine open covering
$X = \bigcup \Spec(A_i)$ such that
the image of $f$ in $A_i$ is a nonzerodivisor for all $i$.
\end{enumerate}

\label{lemma-characterize-OD}
\begin{slogan}
Effective Cartier divisors on a scheme are the same as invertible sheaves
with fixed regular global section.
\end{slogan}
Let $X$ be a scheme.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{isomorphism classes of pairs }(\mathcal{L}, s)\\
\text{consisting of an invertible }
\mathcal{O}_X\text{-module}\\
\mathcal{L}\text{ and a regular global section }s
\end{matrix}
\right\}
$$

\label{lemma-effective-Cartier-codimension-1}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item Let $D \subset X$ be a locally principal closed subscheme.
Let $\xi \in D$ be a generic point of an irreducible component of $D$.
Then $\dim(\mathcal{O}_{X, \xi}) \leq 1$.
\item Let $D \subset X$ be an effective Cartier divisor.
Let $\xi \in D$ be a generic point of an irreducible component of $D$.
Then $\dim(\mathcal{O}_{X, \xi}) = 1$.
\end{enumerate}

\label{lemma-effective-Cartier-divisor-Sk}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be an
effective Cartier divisor. If $X$ is $(S_k)$, then $D$ is $(S_{k - 1})$.

\label{lemma-normal-effective-Cartier-divisor-S1}
Let $X$ be a locally Noetherian normal scheme. Let $D \subset X$ be an
effective Cartier divisor. Then $D$ is $(S_1)$.

\label{lemma-weil-divisor-is-cartier-UFD}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be an integral
closed subscheme. Assume that
\begin{enumerate}
\item $D$ has codimension $1$ in $X$, and
\item $\mathcal{O}_{X, x}$ is a UFD for all $x \in D$.
\end{enumerate}
Then $D$ is an effective Cartier divisor.

\label{lemma-codimension-1-is-effective-Cartier}
Let $Z \subset X$ be a closed subscheme of a Noetherian scheme. Assume
\begin{enumerate}
\item $Z$ has no embedded points,
\item every irreducible component of $Z$ has codimension $1$ in $X$,
\item every local ring $\mathcal{O}_{X, x}$, $x \in Z$ is
a UFD or $X$ is regular.
\end{enumerate}
Then $Z$ is an effective Cartier divisor.

\label{lemma-complement-affine-open-immersion}
\begin{reference}
\cite[EGA IV, Corollaire 21.12.7]{EGA4}
\end{reference}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an open subscheme
such that the inclusion morphism $U \to X$ is affine.
For every generic point $\xi$ of an irreducible component of
$X \setminus U$ the local ring $\mathcal{O}_{X, \xi}$
has dimension $\leq 1$. If $U$ is dense or if $\xi$ is in the closure
of $U$, then $\dim(\mathcal{O}_{X, \xi}) = 1$.

\label{lemma-norm-quasi-affine}
Let $\pi : X \to Y$ be a finite morphism of schemes. Assume $X$ is quasi-affine
and there exists a norm of degree $d$ for $\pi$. Then $Y$ is quasi-affine.

\label{proposition-push-down-ample}
Let $\pi : X \to Y$ be a finite surjective morphism of schemes.
Assume that $X$ has an ample invertible $\mathcal{O}_X$-module. If
\begin{enumerate}
\item $\pi$ is finite locally free, or
\item $Y$ is an integral normal scheme, or
\item $Y$ is Noetherian, $p\mathcal{O}_Y = 0$, and $X = Y_{red}$,
\end{enumerate}
then $Y$ has an ample invertible $\mathcal{O}_Y$-module.

\label{lemma-push-down-quasi-affine}
Let $\pi : X \to Y$ be a finite surjective morphism of schemes.
Assume that $X$ is quasi-affine. If either
\begin{enumerate}
\item $\pi$ is finite locally free, or
\item $Y$ is an integral normal scheme
\end{enumerate}
then $Y$ is quasi-affine.

\label{definition-conormal-sheaf}
Let $f : Z \to X$ be an immersion. The {\it conormal algebra
$\mathcal{C}_{Z/X, *}$ of $Z$ in $X$} or the {\it conormal algebra of $f$}
is the quasi-coherent sheaf of graded $\mathcal{O}_Z$-algebras
$\bigoplus_{n \geq 0} \mathcal{I}^n/\mathcal{I}^{n + 1}$ described above.

\label{lemma-conormal-algebra-functorial-flat}
Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a fibre product diagram in the category of schemes with
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X', *} \to \mathcal{C}_{Z/X, *}$ of
Lemma \ref{lemma-conormal-algebra-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{lemma-regular-ideal-sheaf-quasi-coherent}
Any regular, Koszul-regular, $H_1$-regular, or quasi-regular sheaf
of ideals on a scheme is a finite type quasi-coherent sheaf of ideals.

\label{lemma-quasi-regular-immersion}
Let $i : Z \to X$ be an immersion of schemes. Then $i$ is a quasi-regular
immersion if and only if the following conditions are satisfied
\begin{enumerate}
\item $i$ is locally of finite presentation,
\item the conormal sheaf $\mathcal{C}_{Z/X}$ is finite locally free, and
\item the map (\ref{equation-conormal-algebra-quotient}) is an isomorphism.
\end{enumerate}

\label{lemma-composition-regular-immersion}
Let $i : Z \to Y$ and $j : Y \to X$ be immersions of schemes.
\begin{enumerate}
\item If $i$ and $j$ are regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are Koszul-regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are $H_1$-regular immersions, so is $j \circ i$.
\item If $i$ is an $H_1$-regular immersion and $j$ is a quasi-regular
immersion, then $j \circ i$ is a quasi-regular immersion.
\end{enumerate}

\label{lemma-immersion-regular-regular-immersion}
Let $i : Z \to X$ be an immersion. If $Z$ and $X$ are
regular schemes, then $i$ is a regular immersion.

\label{definition-relative-H1-regular-immersion}
Let $f : X \to S$ be a morphism of schemes.
Let $i : Z \to X$ be an immersion.
\begin{enumerate}
\item We say $i$ is a {\it relative quasi-regular immersion}
if $Z \to S$ is flat and $i$ is a quasi-regular immersion.
\item We say $i$ is a {\it relative $H_1$-regular immersion}
if $Z \to S$ is flat and $i$ is an $H_1$-regular immersion.
\end{enumerate}

\label{lemma-relative-regular-immersion-flat-in-neighbourhood}
Let $X \to S$ be a morphism of schemes.
Let $Z \to X$ be an immersion.
Assume
\begin{enumerate}
\item $X \to S$ is flat and locally of finite presentation,
\item $Z \to X$ is a relative quasi-regular immersion.
\end{enumerate}
Then $Z \to X$ is a regular immersion and
the same remains true after any base change.

\label{lemma-flat-relative-H1-regular}
Let $X \to S$ be a morphism of schemes.
Let $Z \to X$ be a relative $H_1$-regular immersion.
Assume $X \to S$ is locally of finite presentation. Then
\begin{enumerate}
\item there exists an open subscheme $U \subset X$ such that
$Z \subset U$ and such that $U \to S$ is flat, and
\item $Z \to X$ is a regular immersion and the same remains
true after any base change.
\end{enumerate}

\label{lemma-locally-Noetherian-K}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item For any $x \in X$ we have $\mathcal{S}_x \subset \mathcal{O}_{X, x}$
is the set of nonzerodivisors, and hence $\mathcal{K}_{X, x}$
is the total quotient ring of $\mathcal{O}_{X, x}$.
\item For any affine open $U \subset X$ the ring
$\mathcal{K}_X(U)$ equals the total quotient ring of $\mathcal{O}_X(U)$.
\end{enumerate}

\label{lemma-local-rings-UFD-c1-bijective}
Let $X$ be a locally Noetherian integral scheme. Consider the map
(\ref{equation-c1}) $\Pic(X) \to \text{Cl}(X)$.
The following are equivalent
\begin{enumerate}
\item the local rings of $X$ are UFDs, and
\item $X$ is normal and $\Pic(X) \to \text{Cl}(X)$
is surjective.
\end{enumerate}
In this case $\Pic(X) \to \text{Cl}(X)$ is an isomorphism.

\label{lemma-open-subscheme-UFD}
Let $R$ be a UFD. The Picard groups of the following are
trivial.
\begin{enumerate}
\item $\Spec(R)$ and any open subscheme of it.
\item $\mathbf{A}^n_R = \Spec(R[x_1, \ldots, x_n])$ and any open subscheme
of it.
\end{enumerate}
In particular, the Picard group of any open subscheme of affine
$n$-space $\mathbf{A}^n_k$ over a field $k$ is trivial.

\label{lemma-affine-Xs}
Assumptions and notation as in Lemma \ref{lemma-structure-sheaf-Xs}.
The following are equivalent
\begin{enumerate}
\item the inclusion morphism $j : U \to X$ is affine, and
\item for every $x \in X \setminus U$ there is an $n > 0$
such that $s^n \in \mathfrak m_x \mathcal{F}^{[n]}_x$.
\end{enumerate}

\label{lemma-conormal-sheaf-section-projective-bundle}
Let $X$ be a scheme. Let $\mathcal{E}$ be a quasi-coherent
$\mathcal{O}_X$-module. There is a bijection
$$
\left\{
\begin{matrix}
\text{sections }\sigma\text{ of the } \\
\text{morphism } \mathbf{P}(\mathcal{E}) \to X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{surjections }\mathcal{E} \to \mathcal{L}\text{ where} \\
\mathcal{L}\text{ is an invertible }\mathcal{O}_X\text{-module}
\end{matrix}
\right\}
$$
In this case $\sigma$ is a closed immersion and there is a canonical
isomorphism
$$
\Ker(\mathcal{E} \to \mathcal{L})
\otimes_{\mathcal{O}_X} \mathcal{L}^{\otimes -1}
\longrightarrow
\mathcal{C}_{\sigma(X)/\mathbf{P}(\mathcal{E})}
$$
Both the bijection and isomorphism are compatible with base change.

\label{lemma-flat-base-change-blowing-up}
\begin{slogan}
Blowing up commutes with flat base change.
\end{slogan}
Let $X_1 \to X_2$ be a flat morphism of schemes. Let $Z_2 \subset X_2$ be a
closed subscheme. Let $Z_1$ be the inverse image of $Z_2$ in $X_1$.
Let $X'_i$ be the blowup of $Z_i$ in $X_i$. Then there exists a cartesian
diagram
$$
\xymatrix{
X_1' \ar[r] \ar[d] & X_2' \ar[d] \\
X_1 \ar[r] & X_2
}
$$
of schemes.

\label{lemma-blow-up-effective-Cartier-divisor}
Let $X$ be a scheme. Let $Z \subset X$ be an effective Cartier divisor.
The blowup of $X$ in $Z$ is the identity morphism of $X$.

\label{lemma-blowing-up-projective}
Let $X$ be a scheme. Let $\mathcal{I} \subset \mathcal{O}_X$ be a
quasi-coherent sheaf of ideals. Let $b : X' \to X$ be the blowing up of $X$
in the ideal sheaf $\mathcal{I}$. If $\mathcal{I}$ is of finite type, then
\begin{enumerate}
\item $b : X' \to X$ is a projective morphism, and
\item $\mathcal{O}_{X'}(1)$ is a $b$-relatively ample invertible sheaf.
\end{enumerate}

\label{lemma-composition-finite-type-blowups}
\begin{slogan}
Composition of blowing ups is a blowing up
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $Z \subset X$ be a closed subscheme of finite presentation.
Let $b : X' \to X$ be the blowing up with center $Z$. Let $Z' \subset X'$ be
a closed subscheme of finite presentation.
Let $X'' \to X'$ be the blowing up with center $Z'$.
There exists a closed subscheme $Y \subset X$ of finite presentation,
such that
\begin{enumerate}
\item $Y = Z \cup b(Z')$ set theoretically, and
\item the composition $X'' \to X$ is isomorphic to the blowing up
of $X$ in $Y$.
\end{enumerate}

\label{lemma-strict-transform}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item The strict transform $X'$ of $X$ is the blowup of $X$ in the closed
subscheme $f^{-1}Z$ of $X$.
\item For a quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
strict transform $\mathcal{F}'$ is canonically isomorphic to
the pushforward along $X' \to X \times_S S'$ of the strict transform of
$\mathcal{F}$ relative to the blowing up $X' \to X$.
\end{enumerate}

\label{lemma-strict-transform-flat}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item If $X$ is flat over $S$ at all points lying over $Z$, then
the strict transform of $X$ is equal to the base change $X \times_S S'$.
\item Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $\mathcal{F}$ is flat over $S$ at all points lying over $Z$, then
the strict transform $\mathcal{F}'$ of $\mathcal{F}$ is equal to the
pullback $\text{pr}_X^*\mathcal{F}$.
\end{enumerate}

\label{lemma-composition-admissible-blowups}
\begin{slogan}
Admissible blowups are stable under composition.
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U \subset X$ be a quasi-compact open subscheme.
Let $b : X' \to X$ be a $U$-admissible blowup.
Let $X'' \to X'$ be a $U$-admissible blowup.
Then the composition $X'' \to X$ is a $U$-admissible blowup.

\label{lemma-separate-disjoint-opens-by-blowing-up}
\begin{slogan}
Separate irreducible components by blowing up.
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U, V$ be quasi-compact disjoint open subschemes of $X$.
Then there exist a $U \cup V$-admissible blowup $b : X' \to X$
such that $X'$ is a disjoint union of open subschemes
$X' = X'_1 \amalg X'_2$ with $b^{-1}(U) \subset X'_1$ and
$b^{-1}(V) \subset X'_2$.

\label{lemma-extend-rational-map-after-modification}
Let $S$ be a scheme. Let $X$, $Y$ be schemes over $S$.
Assume $X$ is Noetherian and $Y$ is proper over $S$.
Given an $S$-rational map $f : U \to Y$ from $X$ to $Y$
there exists a morphism $p : X' \to X$ and an
$S$-morphism $f' : X' \to Y$ such that
\begin{enumerate}
\item $p$ is proper and $p^{-1}(U) \to U$ is an isomorphism,
\item $f'|_{p^{-1}(U)}$ is equal to $f \circ p|_{p^{-1}(U)}$.
\end{enumerate}

\label{definition-divided-powers}
Let $A$ be a ring. Let $I$ be an ideal of $A$. A collection of maps
$\gamma_n : I \to I$, $n > 0$ is called a {\it divided power structure}
on $I$ if for all $n \geq 0$, $m > 0$, $x, y \in I$, and $a \in A$ we have
\begin{enumerate}
\item $\gamma_1(x) = x$, we also set $\gamma_0(x) = 1$,
\item $\gamma_n(x)\gamma_m(x) = \frac{(n + m)!}{n! m!} \gamma_{n + m}(x)$,
\item $\gamma_n(ax) = a^n \gamma_n(x)$,
\item $\gamma_n(x + y) = \sum_{i = 0, \ldots, n} \gamma_i(x)\gamma_{n - i}(y)$,
\item $\gamma_n(\gamma_m(x)) = \frac{(nm)!}{n! (m!)^n} \gamma_{nm}(x)$.
\end{enumerate}

\label{lemma-silly}
Let $A$ be a ring. Let $I$ be an ideal of $A$.
\begin{enumerate}
\item If $\gamma$ is a divided power structure\footnote{Here
and in the following, $\gamma$ stands short for a sequence
of maps $\gamma_1, \gamma_2, \gamma_3, \ldots$ from $I$ to $I$.}
on $I$, then
$n! \gamma_n(x) = x^n$ for $n \geq 1$, $x \in I$.
\end{enumerate}
Assume $A$ is torsion free as a $\mathbf{Z}$-module.
\begin{enumerate}
\item[(2)] A divided power structure on $I$, if it exists, is unique.
\item[(3)] If $\gamma_n : I \to I$ are maps then
$$
\gamma\text{ is a divided power structure}
\Leftrightarrow
n! \gamma_n(x) = x^n\ \forall x \in I, n \geq 1.
$$
\item[(4)] The ideal $I$ has a divided power structure
if and only if there exists
a set of generators $x_i$ of $I$ as an ideal such that
for all $n \geq 1$ we have $x_i^n \in (n!)I$.
\end{enumerate}

\label{lemma-check-on-generators}
Let $A$ be a ring. Let $I$ be an ideal of $A$. Let $\gamma_n : I \to I$,
$n \geq 1$ be a sequence of maps. Assume
\begin{enumerate}
\item[(a)] (1), (3), and (4) of Definition \ref{definition-divided-powers}
hold for all $x, y \in I$, and
\item[(b)] properties (2) and (5) hold for $x$ in
some set of generators of $I$ as an ideal.
\end{enumerate}
Then $\gamma$ is a divided power structure on $I$.

\label{lemma-limits}
The category of divided power rings has all limits and they agree with
limits in the category of rings.

\label{lemma-kernel}
Let $(A, I, \gamma)$ be a divided power ring.
\begin{enumerate}
\item If $\varphi : (A, I, \gamma) \to (B, J, \delta)$ is a
homomorphism of divided power rings, then $\Ker(\varphi) \cap I$
is preserved by $\gamma_n$ for all $n \geq 1$.
\item Let $\mathfrak a \subset A$ be an ideal and set
$I' = I \cap \mathfrak a$. The following are equivalent
\begin{enumerate}
\item $I'$ is preserved by $\gamma_n$ for all $n > 0$,
\item $\gamma$ extends to $A/\mathfrak a$, and
\item there exist a set of generators $x_i$ of $I'$ as an ideal
such that $\gamma_n(x_i) \in I'$ for all $n > 0$.
\end{enumerate}
\end{enumerate}

\label{lemma-regular-sequence}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Let
$I \subset J \subset A$ be proper ideals. Assume
\begin{enumerate}
\item $A/J$ has finite tor dimension over $A/I$, and
\item $J$ is generated by a regular sequence.
\end{enumerate}
Then $I$ is generated by a regular sequence and $J/I$
is generated by a regular sequence.

\label{proposition-avramov}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B^\wedge$ is a complete intersection,
\item $A^\wedge$ and $(B/\mathfrak m_A B)^\wedge$ are complete intersections.
\end{enumerate}

\label{definition-lci}
Let $A$ be a Noetherian ring.
\begin{enumerate}
\item If $A$ is local, then we say $A$ is a {\it complete intersection}
if its completion is a complete intersection in the sense above.
\item In general we say $A$ is a {\it local complete intersection}
if all of its local rings are complete intersections.
\end{enumerate}

\label{lemma-check-lci-agrees}
Let $S$ be a finite type algebra over a field $k$.
\begin{enumerate}
\item for a prime $\mathfrak q \subset S$ the local ring $S_\mathfrak q$
is a complete intersection in the sense of
Algebra, Definition \ref{algebra-definition-lci-local-ring}
if and only if $S_\mathfrak q$ is a complete
intersection in the sense of Definition \ref{definition-lci}, and
\item $S$ is a local complete intersection in the sense of
Algebra, Definition \ref{algebra-definition-lci-field}
if and only if $S$ is a local complete
intersection in the sense of Definition \ref{definition-lci}.
\end{enumerate}

\label{lemma-avramov}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B$ is a complete intersection,
\item $A$ and $B/\mathfrak m_A B$ are complete intersections.
\end{enumerate}

\label{lemma-ci-map-well-defined}
Let $A \to B$ be a local homomorphism of Noetherian complete local rings.
The following are equivalent
\begin{enumerate}
\item for some good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence, and
\item for every good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence.
\end{enumerate}

\label{proposition-avramov-map}
Let $A \to B$ be a local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B$ is a complete intersection and
$\text{Tor}^A_p(B, A/\mathfrak m_A)$ is nonzero for only finitely many $p$,
\item $A$ is a complete intersection and
$A^\wedge \to B^\wedge$ is a complete intersection homomorphism
in the sense defined above.
\end{enumerate}

\label{lemma-well-defined-if-you-can-find-good-factorization}
Consider a commutative diagram
$$
\xymatrix{
S \ar[r] & B \\
& A \ar[lu] \ar[u]
}
$$
of Noetherian local rings with $S \to B$ surjective, $A \to S$ flat, and
$S/\mathfrak m_A S$ a regular local ring. The following are equivalent
\begin{enumerate}
\item $\Ker(S \to B)$ is generated by a regular sequence, and
\item $A^\wedge \to B^\wedge$ is a complete intersection homomorphism
as defined above.
\end{enumerate}

\label{lemma-free-summand-in-ideal-finite-proj-dim}
\begin{reference}
\cite{Vasconcelos}
\end{reference}
Let $R$ be a Noetherian local ring. Let $I \subset R$ be an ideal
of finite projective dimension over $R$. If $F \subset I/I^2$ is a
direct summand isomorphic to $R/I$, then there exists a nonzerodivisor
$x \in I$ such that the image of $x$ in $I/I^2$ generates $F$.

\label{lemma-vasconcelos}
\begin{reference}
Local version of \cite[Theorem 1.1]{Vasconcelos}
\end{reference}
Let $R$ be a Noetherian local ring. Let $I \subset R$ be an ideal
of finite projective dimension over $R$. If $F \subset I/I^2$
is a direct summand free of rank $r$, then there exists a regular sequence
$x_1, \ldots, x_r \in I$ such that $x_1 \bmod I^2, \ldots, x_r \bmod I^2$
generate $F$.

\label{proposition-regular-ideal}
\begin{reference}
Variant of \cite[Corollary 1]{Vasconcelos}. See also
\cite{Iyengar} and \cite{Ferrand-lci}.
\end{reference}
Let $R$ be a Noetherian ring. Let $I \subset R$ be an ideal
which has finite projective dimension and such that $I/I^2$ is
finite locally free over $R/I$. Then $I$ is a regular ideal
(More on Algebra, Definition \ref{more-algebra-definition-regular-ideal}).

\label{lemma-dimension-function-scheme}
Let $X$ be a locally Noetherian scheme. Let $\omega_X^\bullet$
be a dualizing complex on $X$. Then $X$ is universally catenary
and the function
$X \to \mathbf{Z}$ defined by
$$
x \longmapsto \delta(x)\text{ such that }
\omega_{X, x}^\bullet[-\delta(x)]
\text{ is a normalized dualizing complex over }
\mathcal{O}_{X, x}
$$
is a dimension function.

\label{lemma-twisted-inverse-image}
\begin{reference}
This is almost the same as \cite[Example 4.2]{Neeman-Grothendieck}.
\end{reference}
Let $f : X \to Y$ be a morphism between quasi-separated and quasi-compact
schemes. The functor $Rf_* : D_\QCoh(\mathcal{O}_X) \to D_\QCoh(\mathcal{O}_Y)$
has a right adjoint.

\label{lemma-sheaf-with-exact-support-quasi-coherent}
Let $i : Z \to X$ be a pseudo-coherent closed immersion of schemes
(any closed immersion if $X$ is locally Noetherian).
Then
\begin{enumerate}
\item $R\SheafHom(\mathcal{O}_Z, -)$ maps $D^+_\QCoh(\mathcal{O}_X)$
into $D^+_\QCoh(\mathcal{O}_Z)$, and
\item if $X = \Spec(A)$ and $Z = \Spec(B)$, then the diagram
$$
\xymatrix{
D^+(B) \ar[r] & D_\QCoh^+(\mathcal{O}_Z) \\
D^+(A) \ar[r] \ar[u]^{R\Hom(B, -)} &
D_\QCoh^+(\mathcal{O}_X) \ar[u]_{R\SheafHom(\mathcal{O}_Z, -)}
}
$$
is commutative.
\end{enumerate}

\label{lemma-sheafhom-affine-adjoint}
With notation as above. The functor $R\SheafHom(f_*\mathcal{O}_Y, -)$
is the right adjoint of the functor $D(f_*\mathcal{O}_Y) \to D(\mathcal{O}_X)$.

[Rigidity]
\label{lemma-van-den-bergh}
Let $Y$ be a quasi-compact and quasi-separated scheme.
Let $f : X \to Y$ be a proper, flat morphism of finite presentation
with relative dualizing complex $\omega_{X/Y}^\bullet$
(Remark \ref{remark-relative-dualizing-complex}).
There is a canonical isomorphism
\begin{equation}
\label{equation-pre-rigid}
\mathcal{O}_X =
c(L\text{pr}_1^*\omega_{X/Y}^\bullet) =
c(L\text{pr}_2^*\omega_{X/Y}^\bullet)
\end{equation}
and a canonical isomorphism
\begin{equation}
\label{equation-rigid}
\omega_{X/Y}^\bullet =
c\left(L\text{pr}_1^*\omega_{X/Y}^\bullet
\otimes_{\mathcal{O}_{X \times_Y X}}^\mathbf{L}
L\text{pr}_2^*\omega_{X/Y}^\bullet\right)
\end{equation}
where $c$ is the right adjoint of
Lemma \ref{lemma-twisted-inverse-image}
for the diagonal $\Delta : X \to X \times_Y X$.

\label{lemma-pseudo-functor}
In Situation \ref{situation-shriek} the constructions of
Lemmas \ref{lemma-shriek-well-defined} and \ref{lemma-upper-shriek-composition}
define a pseudo functor from the category $\textit{FTS}_S$
into the $2$-category of categories (see Categories, Definition
\ref{categories-definition-functor-into-2-category}).

\label{lemma-lci-shriek}
In Situation \ref{situation-shriek} let $f : X \to Y$ be a morphism of
$\textit{FTS}_S$. Assume $f : X \to Y$ is a local complete
intersection morphism. Then
\begin{enumerate}
\item $f^!\mathcal{O}_Y$ is an invertible object of $D(\mathcal{O}_X)$, and
\item $f^!$ maps perfect complexes to perfect complexes.
\end{enumerate}

\label{definition-good-dualizing}
Let $S$ be a Noetherian scheme and let $\omega_S^\bullet$ be a dualizing
complex on $S$. Let $X$ be a scheme of finite type over $S$.
The complex $K$ constructed above is called the
{\it dualizing complex normalized relative to $\omega_S^\bullet$}
and is denoted $\omega_X^\bullet$.

\label{lemma-affine-flat-Noetherian-CM}
In Situation \ref{situation-shriek} let $f : X \to Y$ be a morphism
of $\textit{FTS}_S$. Let $x \in X$. If $f$ is flat, then
the following are equivalent
\begin{enumerate}
\item $f$ is Cohen-Macaulay at $x$,
\item $f^!\mathcal{O}_Y$ has a unique nonzero cohomology sheaf
in a neighbourhood of $x$.
\end{enumerate}

\label{definition-gorenstein}
Let $X$ be a scheme. We say $X$ is {\it Gorenstein} if $X$ is
locally Noetherian and $\mathcal{O}_{X, x}$ is Gorenstein for all $x \in X$.

\label{lemma-gorenstein}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $X$ has a dualizing complex $\omega_X^\bullet$, then
\begin{enumerate}
\item $X$ is Gorenstein $\Leftrightarrow$ $\omega_X^\bullet$ is an invertible
object of $D(\mathcal{O}_X)$,
\item $\mathcal{O}_{X, x}$ is Gorenstein $\Leftrightarrow$
$\omega_{X, x}^\bullet$ is an invertible object of $D(\mathcal{O}_{X, x})$,
\item $U = \{x \in X \mid \mathcal{O}_{X, x}\text{ is Gorenstein}\}$
is an open Gorenstein subscheme.
\end{enumerate}
\item If $X$ is Gorenstein, then $X$ has a dualizing complex if and
only if $\mathcal{O}_X[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-gorenstein-lci}
If $f : Y \to X$ is a local complete intersection morphism
with $X$ a Gorenstein scheme, then $Y$ is Gorenstein.

\label{lemma-gorenstein-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is Gorenstein''
is local in the syntomic topology.

\label{definition-gorenstein-morphism}
Let $f : X \to Y$ be a morphism of schemes.
Assume that all the fibres $X_y$ are locally Noetherian schemes.
\begin{enumerate}
\item Let $x \in X$, and $y = f(x)$. We say that $f$ is
{\it Gorenstein at $x$} if $f$ is flat at $x$, and the
local ring of the scheme $X_y$ at $x$ is Gorenstein.
\item We say $f$ is a {\it Gorenstein morphism} if $f$ is
Gorenstein at every point of $X$.
\end{enumerate}

\label{lemma-gorenstein-morphism}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Gorenstein, and
\item $f$ is flat and its fibres are Gorenstein schemes.
\end{enumerate}

\label{lemma-lci-gorenstein}
A syntomic morphism is Gorenstein. Equivalently a flat
local complete intersection morphism is Gorenstein.

\label{lemma-flat-morphism-from-gorenstein-scheme}
\begin{slogan}
Gorensteinnes of the total space of a flat fibration implies
same for base and fibres
\end{slogan}
Let $f : X \to Y$ be a flat morphism of locally Noetherian schemes.
If $X$ is Gorenstein, then $f$ is Gorenstein and $\mathcal{O}_{Y, f(x)}$
is Gorenstein for all $x \in X$.

\label{lemma-descent-ascent}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes. Assume
\begin{enumerate}
\item $f$ is syntomic and surjective, or
\item $f$ is a surjective flat local complete intersection morphism, or
\item $f$ is a surjective Gorenstein morphism of finite type.
\end{enumerate}
Then $K \in D_\QCoh(\mathcal{O}_Y)$ is a dualizing complex on $Y$ if and only
if $Lf^*K$ is a dualizing complex on $X$.

\label{lemma-lift-map-plus}
The result of Lemma \ref{lemma-lift-map} holds even for
$L \in D^+_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-lower-shriek-well-defined}
The functor $Rf_!$ is, up to isomorphism, independent
of the choice of the compactification.

\label{definition-essential}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item An injection $A \subset B$ of $\mathcal{A}$ is {\it essential},
or we say that $B$ is an {\it essential extension of} $A$,
if every nonzero subobject $B' \subset B$ has nonzero intersection with $A$.
\item A surjection $f : A \to B$ of $\mathcal{A}$ is {\it essential}
if for every proper subobject $A' \subset A$ we have $f(A') \not = B$.
\end{enumerate}

\label{lemma-essential-extension}
Let $R$ be a ring. Let $M \subset N$ be $R$-modules. The following
are equivalent
\begin{enumerate}
\item $M \subset N$ is an essential extension,
\item for all $x \in N$ nonzero there exists an $f \in R$ such that $fx \in M$
and $fx \not = 0$.
\end{enumerate}

\label{lemma-injective-flat}
Let $R \to S$ be a flat ring map. If $E$ is an injective $S$-module,
then $E$ is injective as an $R$-module.

\label{lemma-injective-epimorphism}
Let $R \to S$ be an epimorphism of rings. Let $E$ be an $S$-module.
If $E$ is injective as an $R$-module, then $E$ is an injective $S$-module.

\label{lemma-hom-injective}
Let $R \to S$ be a ring map. If $E$ is an injective $R$-module,
then $\Hom_R(S, E)$ is an injective $S$-module.

\label{lemma-essential-extensions-in-injective}
Let $R$ be a ring. Let $I$ be an injective $R$-module. Let $E \subset I$
be a submodule. The following are equivalent
\begin{enumerate}
\item $E$ is injective, and
\item for all $E \subset E' \subset I$ with $E \subset E'$ essential
we have $E = E'$.
\end{enumerate}
In particular, an $R$-module is injective if and only if every essential
extension is trivial.

\label{lemma-sum-injective-modules}
Let $R$ be a Noetherian ring. A direct sum of injective modules
is injective.

\label{lemma-injective-module-divide}
Let $R$ be a Noetherian ring. Let $I$ be an injective $R$-module.
\begin{enumerate}
\item Let $f \in R$. Then $E = \bigcup I[f^n] = I[f^\infty]$
is an injective submodule of $I$.
\item Let $J \subset R$ be an ideal. Then the $J$-power torsion
submodule $I[J^\infty]$ is an injective submodule of $I$.
\end{enumerate}

\label{lemma-projective-cover-unique}
Let $R$ be a ring and let $M$ be an $R$-module. If a projective cover
of $M$ exists, then it is unique up to isomorphism.

\label{lemma-projective-covers-local}
Let $(R, \mathfrak m, \kappa)$ be a local ring. Any finite $R$-module has
a projective cover.

\label{definition-indecomposable}
An object $X$ of an additive category is called {\it indecomposable}
if it is nonzero and if $X = Y \oplus Z$, then either $Y = 0$ or $Z = 0$.

\label{lemma-injective-hull-indecomposable}
Let $\mathfrak p \subset R$ be a prime of a ring $R$.
Let $E$ be the injective hull of $R/\mathfrak p$. Then
\begin{enumerate}
\item $E$ is indecomposable,
\item $E$ is the injective hull of $\kappa(\mathfrak p)$,
\item $E$ is the injective hull of $\kappa(\mathfrak p)$
over the ring $R_\mathfrak p$.
\end{enumerate}

\label{lemma-describe-categories}
Let $(R, \mathfrak m, \kappa)$ be a Noetherian local ring.
Let $E$ be an injective hull of $\kappa$.
\begin{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the ascending chain condition,
\item $M$ is a finite $R$-module, and
\item there exist $n, m$ and an exact sequence
$R^{\oplus m} \to R^{\oplus n} \to M \to 0$.
\end{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the descending chain condition,
\item $M$ is $\mathfrak m$-power torsion and
$\dim_\kappa(M[\mathfrak m]) < \infty$, and
\item there exist $n, m$ and an exact sequence
$0 \to M \to E^{\oplus n} \to E^{\oplus m}$.
\end{enumerate}
\end{enumerate}

[Matlis duality]
\label{proposition-matlis}
Let $(R, \mathfrak m, \kappa)$ be a complete local Noetherian ring.
Let $E$ be an injective hull of $\kappa$ over $R$. The functor
$D(-) = \Hom_R(-, E)$ induces an anti-equivalence
$$
\left\{
\begin{matrix}
R\text{-modules with the} \\
\text{descending chain condition}
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
R\text{-modules with the} \\
\text{ascending chain condition}
\end{matrix}
\right\}
$$
and we have $D \circ D = \text{id}$ on either side of the equivalence.

\label{lemma-local-cohomology-noetherian}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
\begin{enumerate}
\item the adjunction $R\Gamma_I(K) \to K$ is an isomorphism
for $K \in D_{I^\infty\text{-torsion}}(A)$,
\item the functor
(\ref{equation-compare-torsion})
$D(I^\infty\text{-torsion}) \to D_{I^\infty\text{-torsion}}(A)$
is an equivalence,
\item the transformation of functors
(\ref{equation-compare-torsion-functors}) is an isomorphism,
in other words $R\Gamma_I(K) = R\Gamma_Z(K)$ for $K \in D(A)$.
\end{enumerate}

\label{lemma-depth-drops-by-one}
Let $A$ be a Noetherian ring, let $I \subset A$ be an ideal, and
let $M$ a finite $A$-module with $IM \not = M$.
\begin{enumerate}
\item If $x \in I$ is a nonzerodivisor on $M$, then
$\text{depth}_I(M/xM) = \text{depth}_I(M) - 1$.
\item Any $M$-regular sequence $x_1, \ldots, x_r$ in $I$ can be extended to an
$M$-regular sequence in $I$ of length $\text{depth}_I(M)$.
\end{enumerate}

\label{lemma-divide-by-torsion}
Let $A$ be a ring and let $I \subset A$ be a finitely generated ideal.
Let $M$ be an $A$-module. Let $Z = V(I)$.
Then $H^0_I(M) = H^0_Z(M)$. Let $N$ be the common value and
set $M' = M/N$. Then
\begin{enumerate}
\item $H^0_I(M') = 0$ and $H^p_I(M) = H^p_I(M')$ and $H^p_I(N) = 0$
for all $p > 0$,
\item $H^0_Z(M') = 0$ and $H^p_Z(M) = H^p_Z(M')$ and $H^p_Z(N) = 0$
for all $p > 0$.
\end{enumerate}

\label{proposition-torsion-complete}
\begin{reference}
This is a special case of \cite[Theorem 1.1]{Porta-Liran-Yekutieli}.
\end{reference}
Let $A$ be a ring and let $I \subset A$ be a finitely generated ideal.
The functors $R\Gamma_Z$ and ${\ }^\wedge$
define quasi-inverse equivalences of categories
$$
D_{I^\infty\text{-torsion}}(A) \leftrightarrow D_{comp}(A, I)
$$

\label{lemma-RHom-is-tensor}
In Situation \ref{situation-resolution} assume that
\begin{enumerate}
\item $E$ viewed as an object of $D(R)$ is compact, and
\item $N = \Hom^\bullet_R(E^\bullet, R)$ computes $R\Hom(E, R)$.
\end{enumerate}
Then $R\Hom(E, -) : D(R) \to D(E)$ is isomorphic to
$K \mapsto K \otimes_R^\mathbf{L} N$.

\label{lemma-flat-bc-surjection}
Let $R \to A$ and $R \to R'$ be ring maps and $A' = A \otimes_R R'$.
Assume
\begin{enumerate}
\item $A$ is pseudo-coherent as an $R$-module,
\item $R'$ has finite tor dimension as an $R$-module (for example
$R \to R'$ is flat),
\item $A$ and $R'$ are tor independent over $R$.
\end{enumerate}
Then (\ref{equation-base-change}) is an isomorphism for $K \in D^+(R)$.

\label{lemma-bc-surjection}
Let $R \to A$ and $R \to R'$ be ring maps and $A' = A \otimes_R R'$.
Assume
\begin{enumerate}
\item $A$ is perfect as an $R$-module,
\item $A$ and $R'$ are tor independent over $R$.
\end{enumerate}
Then (\ref{equation-base-change}) is an isomorphism for all $K \in D(R)$.

\label{definition-dualizing}
Let $A$ be a Noetherian ring. A {\it dualizing complex} is a
complex of $A$-modules $\omega_A^\bullet$ such that
\begin{enumerate}
\item $\omega_A^\bullet$ has finite injective dimension,
\item $H^i(\omega_A^\bullet)$ is a finite $A$-module for all $i$, and
\item $A \to R\Hom_A(\omega_A^\bullet, \omega_A^\bullet)$
is a quasi-isomorphism.
\end{enumerate}

\label{lemma-universally-catenary}
Let $A$ be a Noetherian ring which has a dualizing
complex. Then $A$ is universally catenary of finite dimension.

\label{lemma-depth-dualizing-module}
Let $(A, \mathfrak m, \kappa)$ be a Noetherian local ring with
normalized dualizing complex $\omega_A^\bullet$. Let $d = \dim(A)$
and $\omega_A = H^{-d}(\omega_A^\bullet)$. Then
\begin{enumerate}
\item the support of $\omega_A$ is the union of the irreducible components
of $\Spec(A)$ of dimension $d$,
\item $\omega_A$ satisfies $(S_2)$, see
Algebra, Definition \ref{algebra-definition-conditions}.
\end{enumerate}

\label{definition-gorenstein}
Gorenstein rings.
\begin{enumerate}
\item Let $A$ be a Noetherian local ring. We say $A$ is {\it Gorenstein}
if $A[0]$ is a dualizing complex for $A$.
\item Let $A$ be a Noetherian ring. We say $A$ is {\it Gorenstein}
if $A_\mathfrak p$ is Gorenstein for every prime $\mathfrak p$ of $A$.
\end{enumerate}

\label{lemma-regular-gorenstein}
A regular local ring is Gorenstein.
A regular ring is Gorenstein.

\label{lemma-gorenstein}
Let $A$ be a Noetherian ring.
\begin{enumerate}
\item If $A$ has a dualizing complex $\omega_A^\bullet$, then
\begin{enumerate}
\item $A$ is Gorenstein $\Leftrightarrow$ $\omega_A^\bullet$ is an invertible
object of $D(A)$,
\item $A_\mathfrak p$ is Gorenstein $\Leftrightarrow$
$(\omega_A^\bullet)_\mathfrak p$ is an invertible object of
$D(A_\mathfrak p)$,
\item $\{\mathfrak p \in \Spec(A) \mid A_\mathfrak p\text{ is Gorenstein}\}$
is an open subset.
\end{enumerate}
\item If $A$ is Gorenstein, then $A$ has a dualizing complex if and
only if $A[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-characterize-gorenstein}
Let $A$ be a Noetherian ring. The following are equivalent
\begin{enumerate}
\item $A$ has finite injective dimension as a module over itself,
\item $A$ is Gorenstein and finite dimensional.
\end{enumerate}
In this case $A[0]$ is a dualizing complex.

\label{lemma-gorenstein-lci}
If $A \to B$ is a local complete intersection homomorphism of rings and
$A$ is a Noetherian Gorenstein ring, then $B$ is a Gorenstein ring.

\label{lemma-flat-under-gorenstein}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
The following are equivalent
\begin{enumerate}
\item $B$ is Gorenstein, and
\item $A$ and $B/\mathfrak m_A B$ are Gorenstein.
\end{enumerate}

\label{lemma-formal-fibres-gorenstein}
Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a Gorenstein ring''.

\label{lemma-dualizing-gorenstein-formal-fibres}
Let $A$ be a Noetherian local ring. If $A$ has a dualizing complex,
then the formal fibres of $A$ are Gorenstein.

\label{lemma-formal-fibres-lci}
Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a local complete intersection''.
See Divided Power Algebra, Definition \ref{dpa-definition-lci}.

\label{lemma-shriek-boundedness}
Let $\varphi : R \to A$ be a finite type homomorphism of Noetherian rings.
\begin{enumerate}
\item $\varphi^!$ maps $D^+(R)$ into $D^+(A)$ and
$D^+_{\textit{Coh}}(R)$ into $D^+_{\textit{Coh}}(A)$.
\item if $\varphi$ is perfect, then $\varphi^!$ maps
$D^-(R)$ into $D^-(A)$,
$D^-_{\textit{Coh}}(R)$ into $D^-_{\textit{Coh}}(A)$, and
$D^b_{\textit{Coh}}(R)$ into $D^b_{\textit{Coh}}(A)$.
\end{enumerate}

\label{lemma-relative-dualizing-algebraic}
Let $\varphi : R \to A$ be a finite type map of Noetherian rings.
\begin{enumerate}
\item If $\varphi$ is perfect, then
\begin{enumerate}
\item $\omega_{A/R}^\bullet$ is in $D^b_{\textit{Coh}}(A)$,
\item $\omega_{A/R}^\bullet$ has finite tor dimension over $R$, and
\item $A \to R\Hom_A(\omega_{A/R}^\bullet, \omega_{A/R}^\bullet)$
is an isomorphism.
\end{enumerate}
\item If $\varphi$ is flat, then (1)(a), (1)(b), and (1)(c) hold and
\begin{enumerate}
\item $\omega_{A/R}^\bullet$ is $R$-perfect
(More on Algebra,
Definition \ref{more-algebra-definition-relatively-perfect}), and
\item for every map $R \to k$ to a field the base change
$\omega_{A/R}^\bullet \otimes_A^\mathbf{L} (A \otimes_R k)$
is a dualizing complex for $A \otimes_R k$.
\end{enumerate}
\end{enumerate}

\label{lemma-gorenstein-shriek}
Let $\varphi : R \to A$ be a flat finite type homomorphism of Noetherian rings.
The following are equivalent
\begin{enumerate}
\item the fibres $A \otimes_R \kappa(\mathfrak p)$ are Gorenstein
for all primes $\mathfrak p \subset R$, and
\item $\omega_{A/R}^\bullet$ is an invertible object of $D(A)$, see
More on Algebra, Lemma \ref{more-algebra-lemma-invertible-derived}.
\end{enumerate}

\label{lemma-descent-ascent}
Let $\varphi : A \to B$ be a homomorphism of Noetherian rings. Assume
\begin{enumerate}
\item $A \to B$ is syntomic and induces a surjective map on spectra, or
\item $A \to B$ is a faithfully flat local complete intersection, or
\item $A \to B$ is faithfully flat of finite type with Gorenstein fibres.
\end{enumerate}
Then $K \in D(A)$ is a dualizing complex for $A$ if and only if
$K \otimes_A^\mathbf{L} B$ is a dualizing complex for $B$.

\label{definition-relative-dualizing-complex}
Let $R \to A$ be a flat ring map of finite presentation.
A {\it relative dualizing complex} is an object $K \in D(A)$ such that
\begin{enumerate}
\item $K$ is $R$-perfect (More on Algebra, Definition
\ref{more-algebra-definition-relatively-perfect}), and
\item $R\Hom_{A \otimes_R A}(A, K \otimes_A^\mathbf{L} (A \otimes_R A))$
is isomorphic to $A$.
\end{enumerate}

\label{lemma-uniqueness-relative-dualizing}
Let $R \to A$ be a flat ring map of finite presentation.
Any two relative dualizing complexes for $R \to A$ are isomorphic.

\label{lemma-relative-dualizing-noetherian}
Let $\varphi : R \to A$ be a flat finite type ring map of Noetherian rings.
Then the relative dualizing complex $\omega_{A/R}^\bullet = \varphi^!(R)$
of Section \ref{section-relative-dualizing-complexes-Noetherian}
is a relative dualizing complex in the sense of
Definition \ref{definition-relative-dualizing-complex}.

\label{lemma-perfect-for-R}
With $k$, $n$, and $R$ as above, for an object $K$ of $D(R)$
the following are equivalent
\begin{enumerate}
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(K) < \infty$, and
\item $K$ is a compact object.
\end{enumerate}

\label{lemma-coherent-on-projective-space}
Let $k$ be a field. Let $n \geq 0$. Let
$K \in D_\QCoh(\mathcal{O}_{\mathbf{P}^n_k})$.
The following are equivalent
\begin{enumerate}
\item $K$ is in $D^b_{\textit{Coh}}(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k H^i(\mathbf{P}^n_k, E \otimes^\mathbf{L} K) < \infty$
for each perfect object $E$ of
$D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k \Ext^i_{\mathbf{P}^n_k}(E, K) < \infty$
for each perfect object $E$ of $D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(\mathbf{P}^n_k,
K \otimes^\mathbf{L} \mathcal{O}_{\mathbf{P}^n_k}(d)) < \infty$
for $d = 0, 1, \ldots, n$.
\end{enumerate}

\label{lemma-characterize-dbcoh-projective}
\begin{reference}
In the projective case this is \cite[Lemma 7.46]{Rouquier-dimensions}
and implicit in \cite[Theorem A.1]{BvdB}
\end{reference}
Let $X$ be a proper scheme over a field $k$. Let
$K \in \Ob(D_\QCoh(\mathcal{O}_X))$. The following are equivalent
\begin{enumerate}
\item $K \in D^b_{\textit{Coh}}(\mathcal{O}_X)$, and
\item $\sum_{i \in \mathbf{Z}} \dim_k \Ext^i_X(E, K) < \infty$
for all perfect $E$ in $D(\mathcal{O}_X)$.
\end{enumerate}

\label{lemma-van-den-bergh}
\begin{reference}
\cite[Lemma 2.14]{CKN}
\end{reference}
Let $k$ be a field. Let $\mathcal{D}$ be a $k$-linear triangulated category
which has direct sums and is compactly generated.
Denote $\mathcal{D}_c$ the full
subcategory of compact objects. Let $H : \mathcal{D}_c^{opp} \to \text{Vect}_k$
be a $k$-linear cohomological functor such that
$\dim_k H(X) < \infty$ for all $X \in \Ob(\mathcal{D}_c)$.
Then $H$ is isomorphic to the functor $X \mapsto \Hom(X, Y)$
for some $Y \in \Ob(\mathcal{D})$.

\label{theorem-bondal-van-den-bergh}
\begin{reference}
In the projective case this is \cite[Theorem A.1]{BvdB}
\end{reference}
Let $X$ be a proper scheme over a field $k$.
Let $F : D_{perf}(\mathcal{O}_X)^{opp} \to \text{Vect}_k$
be a $k$-linear cohomological functor such that
$$
\sum\nolimits_{n \in \mathbf{Z}} \dim_k F(E[n]) < \infty
$$
for all $E \in D_{perf}(\mathcal{O}_X)$. Then $F$ is isomorphic to a functor
of the form $E \mapsto \Hom_X(E, K)$ for some
$K \in D^b_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-Ext-0-regular}
Let $X$ be a regular Noetherian scheme of dimension $d < \infty$. Then
\begin{enumerate}
\item for $\mathcal{F}$, $\mathcal{G}$ coherent $\mathcal{O}_X$-modules
we have $\Ext^n_X(\mathcal{F}, \mathcal{G}) = 0$ for $n > d$, and
\item for $K, L \in D^b_{\textit{Coh}}(\mathcal{O}_X)$ and $a \in \mathbf{Z}$
if $H^i(K) = 0$ for $i < a + d$ and $H^i(L) = 0$ for $i \geq a$ then
$\Hom_X(K, L) = 0$.
\end{enumerate}

\label{definition-siblings}
Let $\mathcal{A}$ be an abelian category. Let $\mathcal{D}$ be a
triangulated category. We say two exact functors of triangulated categories
$$
F, F' : D^b(\mathcal{A}) \longrightarrow \mathcal{D}
$$
are {\it siblings}, or we say $F'$ is a {\it sibling} of $F$,
if the following two conditions are satisfied
\begin{enumerate}
\item the functors $F \circ i$ and $F' \circ i$ are isomorphic
where $i : \mathcal{A} \to D^b(\mathcal{A})$ is the inclusion functor, and
\item $F(K) \cong F'(K)$ for any $K$ in $D^b(\mathcal{A})$.
\end{enumerate}

\label{lemma-sibling-faithful}
Let $F$ and $F'$ be siblings as in Definition \ref{definition-siblings}.
Then
\begin{enumerate}
\item if $F$ is essentially surjective, then $F'$ is essentially
surjective,
\item if $F$ is fully faithful, then $F'$ is fully faithful.
\end{enumerate}

\label{proposition-siblings-isomorphic}
\begin{reference}
\cite[Proposition 2.16]{Orlov-K3}; the fact that we do not need
to assume vanishing of $\Ext^q(N, X)$ for $q > 0$ in the definition
of negative objects above is due to \cite{Canonaco-Stellari}.
\end{reference}
Let $F$ and $F'$ be siblings as in Definition \ref{definition-siblings}.
Assume that $F$ is fully faithful and that $\mathcal{A}$ has enough
negative objects (see above). Then $F$ and $F'$ are isomorphic functors.

\label{lemma-get-fully-faithful}
\begin{reference}
Variant of \cite[Lemma 2.15]{Orlov-K3}
\end{reference}
Let $F : \mathcal{D} \to \mathcal{D}'$ be an exact functor of
triangulated categories. Let $S \subset \Ob(\mathcal{D})$ be
a set of objects. Assume
\begin{enumerate}
\item $F$ has both right and left adjoints,
\item for $K \in \mathcal{D}$ if $\Hom(E, K[i]) = 0$ for all
$E \in S$ and $i \in \mathbf{Z}$ then $K = 0$,
\item for $K \in \mathcal{D}$ if $\Hom(K, E[i]) = 0$ for all
$E \in S$ and $i \in \mathbf{Z}$ then $K = 0$,
\item the map $\Hom(E, E'[i]) \to \Hom(F(E), F(E')[i])$ induced by $F$
is bijective for all $E, E' \in S$ and $i \in \mathbf{Z}$.
\end{enumerate}
Then $F$ is fully faithful.

\label{lemma-hom-into-point-sheaf}
Let $X$ be a Noetherian scheme. Let $x \in X$ be a closed point and
denote $\mathcal{O}_x$ the skyscraper sheaf at $x$ with value $\kappa(x)$.
Let $K$ in $D^b_{\textit{Coh}}(\mathcal{O}_X)$. Let $b \in \mathbf{Z}$.
The following are equivalent
\begin{enumerate}
\item $H^i(K)_x = 0$ for all $i > b$ and
\item $\Hom_X(K, \mathcal{O}_x[-i]) = 0$ for all $i > b$.
\end{enumerate}

\label{lemma-noah-pre}
\begin{reference}
Email from Noah Olander of Jun 9, 2020
\end{reference}
Let $k$ be a field. Let $X$ be a proper scheme over $k$ which is regular.
Let $F : D_{perf}(\mathcal{O}_X) \to D_{perf}(\mathcal{O}_X)$
be a $k$-linear exact functor. Assume for every coherent
$\mathcal{O}_X$-module $\mathcal{F}$ with $\dim(\text{Supp}(\mathcal{F})) = 0$
there is an isomorphism $\mathcal{F} \cong F(\mathcal{F})$.
Then $F$ is fully faithful.

[Orlov]
\label{theorem-fully-faithful}
\begin{reference}
\cite[Theorem 2.2]{Orlov-K3}; this is shown in \cite{Noah}
without the assumption that $X$ be projective
\end{reference}
Let $k$ be a field. Let $X$ and $Y$ be smooth proper schemes over $k$
with $X$ projective over $k$. Any $k$-linear fully faithful exact 
functor $F : D_{perf}(\mathcal{O}_X) \to D_{perf}(\mathcal{O}_Y)$
is a Fourier-Mukai functor for some kernel in
$D_{perf}(\mathcal{O}_{X \times Y})$.

\label{lemma-countable-finite-type}
Let $R$ be a countable Noetherian ring. Then the category of schemes of finite
type over $R$ is countable.

\label{lemma-countable-abelian}
Let $\mathcal{A}$ be a countable abelian category.
Then $D^b(\mathcal{A})$ is countable.

\label{theorem-countable}
\begin{reference}
Slight improvement of \cite{AT}
\end{reference}
Let $K$ be an algebraically closed field. Let $\mathbf{X}$ be a smooth proper
scheme over $K$. There are at most countably many isomorphism classes
of smooth proper schemes $\mathbf{Y}$ over $K$ which are derived
equivalent to $\mathbf{X}$.

\label{definition-family-morphisms-fixed-target}
Let $\mathcal{C}$ be a category. A {\it family of morphisms with fixed target}
$\mathcal{U} = \{\varphi_i : U_i \to U\}_{i\in I}$ is the data of
\begin{enumerate}
\item an object $U \in \mathcal{C}$,
\item a set $I$ (possibly empty), and
\item for all $i\in I$, a morphism $\varphi_i : U_i \to U$ of $\mathcal{C}$
with target $U$.
\end{enumerate}

\label{definition-0-cech}
Let $\mathcal{F}$ be a presheaf on the site $\mathcal{C}$ and
$\mathcal{U} = \{U_i \to U\} \in \text{Cov} (\mathcal{C})$.
We define the {\it zeroth {\v C}ech cohomology group} of
$\mathcal{F}$ with respect to $\mathcal{U}$ by
$$
\check H^0 (\mathcal{U}, \mathcal{F}) =
\left\{
(s_i)_{i\in I} \in \prod\nolimits_{i\in I }\mathcal{F}(U_i)
\text{ such that }
s_i|_{U_i \times_U U_j} = s_j |_{U_i \times_U U_j}
\right\}.
$$

\label{theorem-enough-injectives}
The category of abelian sheaves on a site is an abelian category
which has enough injectives.

\label{lemma-site-fpqc}
The collection of fpqc coverings on the category of schemes
satisfies the axioms of site.

\label{lemma-representable-sheaf-fpqc}
Any representable presheaf on $\Sch/S$ satisfies the
sheaf condition for the fpqc topology.

\label{lemma-algebra-descent}
If $A \to B$ is faithfully flat, then the complex $(B/A)_\bullet$ is exact in
positive degrees, and $H^0((B/A)_\bullet) = A$.

\label{theorem-descent-modules}
If $A \to B$ is faithfully flat then descent data with respect to $A\to B$
are effective.

\label{proposition-quasi-coherent-sheaf-fpqc}
For any quasi-coherent sheaf $\mathcal{F}$ on $S$ the presheaf
$$
\begin{matrix}
\mathcal{F}^a : & \Sch/S & \to & \textit{Ab}\\
& (f: T \to S) & \mapsto & \Gamma(T, f^*\mathcal{F})
\end{matrix}
$$
is an $\mathcal{O}$-module which satisfies the sheaf condition for the
fpqc topology.

\label{lemma-exact}
Notation and assumptions as in Definition \ref{definition-cech-complex}.
The complex of abelian presheaves
\begin{align*}
\mathbf{Z}_\mathcal{U}^\bullet \quad : \quad
\bigoplus_{i_0 \in I} \mathbf{Z}_{U_{i_0}} \leftarrow
\bigoplus_{i_0, i_1 \in I} \mathbf{Z}_{U_{i_0} \times_U U_{i_1}} \leftarrow
\bigoplus_{i_0, i_1, i_2 \in I}
\mathbf{Z}_{U_{i_0} \times_U U_{i_1} \times_U U_{i_2}} \leftarrow
\ldots
\end{align*}
is exact in all degrees except $0$ in $\textit{PAb}(\mathcal{C})$.

\label{lemma-forget-injectives}
The forgetful functor $\textit{Ab}(\mathcal{C})\to \textit{PAb}(\mathcal{C})$
transforms injectives into injectives.

\label{definition-etale-topos}
Let $S$ be a scheme.
\begin{enumerate}
\item The {\it \'etale topos}, or the {\it small \'etale topos}
of $S$ is the category $\Sh(S_\etale)$ of sheaves of sets on
the small \'etale site of $S$.
\item The {\it Zariski topos}, or the {\it small Zariski topos}
of $S$ is the category $\Sh(S_{Zar})$ of sheaves of sets on the
small Zariski site of $S$.
\item For $\tau \in \{fppf, syntomic, smooth, \etale, Zariski\}$ a
{\it big $\tau$-topos} is the category of sheaves of set on a
big $\tau$-topos of $S$.
\end{enumerate}

\label{theorem-picard-group}
For any scheme $X$ we have canonical identifications
\begin{align*}
H_{fppf}^1(X, \mathbf{G}_m) & = H^1_{syntomic}(X, \mathbf{G}_m) \\
& = H^1_{smooth}(X, \mathbf{G}_m) \\
& = H_\etale^1(X, \mathbf{G}_m) \\
& = H^1_{Zar}(X, \mathbf{G}_m) \\
& = \Pic(X) \\
& = H^1(X, \mathcal{O}_X^*)
\end{align*}

\label{definition-etale-covering}
An {\it \'etale covering} of a scheme $U$ is a family of morphisms
of schemes
$\{\varphi_i : U_i \to U\}_{i \in I}$ such that
\begin{enumerate}
\item each $\varphi_i$ is an \'etale morphism,
\item the $U_i$ cover $U$, i.e., $U = \bigcup_{i\in I}\varphi_i(U_i)$.
\end{enumerate}

\label{lemma-finite-over-henselian}
If $R$ is henselian and $A$ is a finite $R$-algebra, then $A$ is a finite
product of henselian local rings.

\label{definition-strictly-henselian}
A local ring $R$ is called {\it strictly henselian} if it is henselian and its
residue field is separably closed.

\label{lemma-sections-upstairs}
Let $S$ be a scheme. Let $f : T \to S$ be a morphism such that
\begin{enumerate}
\item $f$ is flat and quasi-compact, and
\item the geometric fibres of $f$ are connected.
\end{enumerate}
Let $\mathcal{F}$ be a sheaf on $S_\etale$.
Then $\Gamma(S, \mathcal{F}) = \Gamma(T, f^{-1}_{small}\mathcal{F})$.

\label{lemma-sections-upstairs-submersive}
Let $S$ be a scheme. Let $f : X \to S$ be a morphism such that
\begin{enumerate}
\item $f$ is submersive, and
\item the geometric fibres of $f$ are connected.
\end{enumerate}
Let $\mathcal{F}$ be a sheaf on $S_\etale$.
Then $\Gamma(S, \mathcal{F}) = \Gamma(X, f^{-1}_{small}\mathcal{F})$.

\label{lemma-locally-quasi-finite-A}
Let $f : X \to Y$ be a separated locally quasi-finite morphism of schemes.
Then property (A) above holds.

\label{lemma-integral-A}
Let $f : X \to Y$ be an integral morphism of schemes.
Then property (A) holds.

\label{lemma-finite-B}
Let $f : X \to Y$ be a finite morphism of schemes.
Then property (B) holds.

\label{lemma-integral-B}
Let $f : X \to Y$ be an integral morphism of schemes.
Then property (B) holds.

\label{theorem-topological-invariance}
\begin{reference}
\cite[IV Theorem 18.1.2]{EGA}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes.
Assume $f$ is integral, universally injective and surjective
(i.e., $f$ is a universal homeomorphism, see
Morphisms, Lemma \ref{morphisms-lemma-universal-homeomorphism}).
The functor
$$
V \longmapsto V_X = X \times_Y V
$$
defines an equivalence of categories
$$
\{
\text{schemes }V\text{ \'etale over }Y
\}
\leftrightarrow
\{
\text{schemes }U\text{ \'etale over }X
\}
$$

\label{lemma-compare-structure-sheaves}
Let $X$ be a scheme. Let
$\tau \in \{Zariski, \etale, smooth, syntomic, fppf\}$.
Let $\mathcal{C}_1 \subset \mathcal{C}_2 \subset (\Sch/X)_\tau$ be full
subcategories with the following properties:
\begin{enumerate}
\item For an object $U/X$ of $\mathcal{C}_t$,
\begin{enumerate}
\item if $\{U_i \to U\}$ is a covering of $(\Sch/X)_\tau$, then
$U_i/X$ is an object of $\mathcal{C}_t$,
\item $U \times \mathbf{A}^1/X$ is an object of $\mathcal{C}_t$.
\end{enumerate}
\item $X/X$ is an object of $\mathcal{C}_t$.
\end{enumerate}
We endow $\mathcal{C}_t$ with the structure of a site whose coverings are
exactly those coverings $\{U_i \to U\}$ of $(\Sch/X)_\tau$ with
$U \in \Ob(\mathcal{C}_t)$. Then
\begin{enumerate}
\item[(a)] The functor $\mathcal{C}_1 \to \mathcal{C}_2$
is fully faithful, continuous, and cocontinuous.
\end{enumerate}
Denote $g : \Sh(\mathcal{C}_1) \to \Sh(\mathcal{C}_2)$ the corresponding
morphism of topoi. Denote $\mathcal{O}_t$ the restriction of $\mathcal{O}$
to $\mathcal{C}_t$. Denote $g_!$ the functor of
Modules on Sites, Definition \ref{sites-modules-definition-g-shriek}.
\begin{enumerate}
\item[(b)] The canonical map $g_!\mathcal{O}_1 \to \mathcal{O}_2$
is an isomorphism.
\end{enumerate}

\label{lemma-prepare-leray}
Let $f: X \to Y$ be a morphism and $\mathcal{I}$ an injective object of
$\textit{Ab}(X_\etale)$. Let $V \in \Ob(Y_\etale)$. Then
\begin{enumerate}
\item for any covering $\mathcal{V} = \{V_j\to V\}_{j \in J}$ we have
$\check H^p(\mathcal{V}, f_*\mathcal{I}) = 0$ for all $p > 0$,
\item $f_*\mathcal{I}$ is acyclic for the functor $\Gamma(V, -)$, and
\item if $g : Y \to Z$, then $f_*\mathcal{I}$ is acyclic for $g_*$.
\end{enumerate}

\label{lemma-modules-abelian}
Let $G$ be a topological group. Let $R$ be a ring.
For every $i \geq 0$ the diagram
$$
\xymatrix{
\text{Mod}_{R, G} \ar[rr]_{H^i(G, -)} \ar[d] & &
\text{Mod}_R \ar[d] \\
\text{Mod}_G \ar[rr]^{H^i(G, -)} & &
\textit{Ab}
}
$$
whose vertical arrows are the forgetful functors is commutative.

\label{lemma-profinite-group-cohomology-torsion}
Let $G$ be a profinite topological group.
Then
\begin{enumerate}
\item $H^i(G, M)$ is torsion for $i > 0$ and any $G$-module $M$, and
\item $H^i(G, M) = 0$ if $M$ is a $\mathbf{Q}$-vector space.
\end{enumerate}

\label{lemma-all-modules-quasi-coherent}
Let $R$ be a local ring of dimension $0$. Let $S = \Spec(R)$.
Then every $\mathcal{O}_S$-module on $S_\etale$ is quasi-coherent.

\label{lemma-brauer-inverse}
Let $A$ be a finite central simple algebra over $K$. Then
$$
\begin{matrix}
A \otimes_K A^{opp} & \longrightarrow & \text{End}_K(A) \\
\ a \otimes a' & \longmapsto & (x \mapsto a x a')
\end{matrix}
$$
is an isomorphism of algebras over $K$.

\label{lemma-central-simple-algebra-pgln}
\begin{slogan}
Central simple algebras are classified by Galois cohomology of PGL.
\end{slogan}
Let $K$ be a field and let $K^{sep}$ be a separable algebraic closure.
Then the set of isomorphism classes of central simple algebras of degree
$d$ over $K$ is in bijection with the non-abelian cohomology
$H^1(\text{Gal}(K^{sep}/K), \text{PGL}_d(K^{sep}))$.

\label{lemma-annihilated-by-degree}
\begin{reference}
Argument taken from \cite{Saltman-torsion}.
\end{reference}
Let $S$ be a scheme. Let $\mathcal{A}$ be an Azumaya algebra which is
locally free of rank $d^2$ over $S$. Then the class
of $\mathcal{A}$ in the Brauer group of $S$ is annihilated by $d$.

\label{lemma-vanishing-affine-char-p-p}
Let $p$ be a prime. Let $S$ be a scheme of characteristic $p$.
\begin{enumerate}
\item If $S$ is affine, then
$H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$ for all
$q \geq 2$.
\item If $S$ is a quasi-compact and quasi-separated scheme of
dimension $d$, then $H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$
for all $q \geq 2 + d$.
\end{enumerate}

\label{lemma-characterize-finite-locally-constant}
Let $X$ be a scheme and $\mathcal{F}$ a sheaf of sets on $X_\etale$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally constant, and
\item $\mathcal{F} = h_U$ for some finite \'etale morphism $U \to X$.
\end{enumerate}

\label{lemma-locally-constant-on-connected}
Let $X$ be a connected scheme. Let $\overline{x}$ be a geometric point of $X$.
\begin{enumerate}
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of sets on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-sets}
\end{matrix}
\right\}
$$
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of abelian groups on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules}
\end{matrix}
\right\}
$$
\item Let $\Lambda$ be a finite ring. There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite type, locally constant}\\
\text{sheaves of }\Lambda\text{-modules on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules endowed}\\
\text{with commuting }\Lambda\text{-module structure}
\end{matrix}
\right\}
$$
\end{enumerate}

\label{lemma-locally-constant-on-connected-geom-unibranch}
Let $X$ be an irreducible, geometrically unibranch scheme.
Let $\overline{x}$ be a geometric point of $X$.
Let $\Lambda$ be a ring. There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite type, locally constant}\\
\text{sheaves of }\Lambda\text{-modules on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\Lambda\text{-modules }M\text{ endowed}\\
\text{with a continuous }\pi_1(X, \overline{x})\text{-action}
\end{matrix}
\right\}
$$

\label{proposition-serre-galois}
\begin{reference}
\cite[Chapter II, Section 3, Proposition 5]{SerreGaloisCohomology}
\end{reference}
Let $K$ be a field with separable algebraic closure $K^{sep}$.
Assume that for any finite extension $K'$ of $K$ we have
$\text{Br}(K') = 0$. Then
\begin{enumerate}
\item $H^q(\text{Gal}(K^{sep}/K), (K^{sep})^*) = 0$
for all $q \geq 1$, and
\item $H^q(\text{Gal}(K^{sep}/K), M) = 0$
for any torsion $\text{Gal}(K^{sep}/K)$-module $M$ and any $q \geq 2$,
\end{enumerate}

\label{definition-Cr}
A field $K$ is called {\it $C_r$}
if for every $0 < d^r < n$ and every $f \in K[T_1,
\ldots, T_n]$ homogeneous of degree $d$, there exist $\alpha = (\alpha_1,
\ldots, \alpha_n)$, $\alpha_i \in K$ not all zero, such that $f(\alpha) = 0$.
Such an $\alpha$ is called a {\it nontrivial solution} of $f$.

\label{definition-variety}
Let $k$ be a field. A {\it variety} is separated, integral scheme of
finite type over $k$. A {\it curve} is a variety of dimension $1$.

\label{lemma-cohomology-istar-Z}
For all $q \geq 1$, $H_\etale^q(X, \bigoplus_{x \in X_0} {i_x}_*
\underline{\mathbf{Z}}) = 0$.

\label{lemma-vanishing-cohomology-mu-smooth-curve}
Let $X$ be an affine smooth curve over an algebraically closed field $k$ and
$n \in k^*$. Let $X \subset \overline{X}$ be a smooth projective
compactification
(Varieties, Remark \ref{varieties-remark-smooth-projective-compactification}).
Let $g$ be the genus of $\overline{X}$ and let $r$ be the number of
points of $\overline{X} \setminus X$. Then
\begin{enumerate}
\item $H_\etale^0(X, \mu_n) = \mu_n(k)$;
\item $H_\etale^1(X, \mu_n) \cong (\mathbf{Z}/n\mathbf{Z})^{2g+r-1}$, and
\item $H_\etale^q(X, \mu_n) = 0$ for all $q \geq 2$.
\end{enumerate}

\label{lemma-shriek-equals-star-finite-etale}
Let $j : U \to X$ be finite and \'etale. Then the map
$j_! \to j_*$ of Lemma \ref{lemma-shriek-into-star-separated-etale}
is an isomorphism
on abelian sheaves and sheaves of $\Lambda$-modules.

\label{lemma-decompose-quasi-finite-morphism}
Let $f : Y \to X$ be a quasi-finite and finitely presented
morphism of affine schemes.
\begin{enumerate}
\item There exists a surjective morphism of affine schemes $X' \to X$ and a
closed subscheme $Z' \subset Y' = X' \times_X Y$ such that
\begin{enumerate}
\item $Z' \subset Y'$ is a thickening, and
\item $Z' \to X'$ is a finite \'etale morphism.
\end{enumerate}
\item There exists a finite partition $X = \coprod X_i$ by
locally closed, constructible, affine strata, and surjective finite locally
free morphisms $X'_i \to X_i$ such that the reduction of
$Y'_i = X'_i \times_X Y \to X'_i$ is isomorphic to
$\coprod_{j = 1}^{n_i} (X'_i)_{red} \to (X'_i)_{red}$ for some $n_i$.
\end{enumerate}

\label{lemma-category-constructible-abelian}
Let $X$ be a quasi-compact and quasi-separated scheme. The category of
constructible abelian sheaves is exactly the category of abelian
sheaves of the form
$$
\Coker\left(
\bigoplus\nolimits_{j = 1, \ldots, m}
j_{V_j!}\underline{\mathbf{Z}/m_j\mathbf{Z}}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n}
j_{U_i!}\underline{\mathbf{Z}/n_i\mathbf{Z}}_{U_i}
\right)
$$
with $V_j$ and $U_i$ quasi-compact and quasi-separated objects of
$X_\etale$ and $m_j$, $n_i$ positive integers.
In fact, we can even assume $U_i$ and $V_j$ affine.

\label{lemma-push-constant-sheaf-from-open}
Let $X$ be an integral normal scheme with function field $K$.
Let $E$ be a set.
\begin{enumerate}
\item Let $g : \Spec(K) \to X$ be the inclusion of the generic point.
Then $g_*\underline{E} = \underline{E}$.
\item Let $j : U \to X$ be the inclusion of a nonempty open. Then
$j_*\underline{E} = \underline{E}$.
\end{enumerate}

\label{lemma-restrict-and-shriek-from-etale-c}
Let $\Lambda$ be a Noetherian ring.
If $j : U \to X$ is an \'etale morphism of schemes, then
\begin{enumerate}
\item $K|_U \in D_c(U_\etale, \Lambda)$ if $K \in D_c(X_\etale, \Lambda)$, and
\item $j_!M \in D_c(X_\etale, \Lambda)$ if $M \in D_c(U_\etale, \Lambda)$ and
the morphism $j$ is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-restrict-and-shriek-from-etale-ctf}
Let $\Lambda$ be a Noetherian ring.
If $j : U \to X$ is an \'etale morphism of schemes, then
\begin{enumerate}
\item $K|_U \in D_{ctf}(U_\etale, \Lambda)$ if
$K \in D_{ctf}(X_\etale, \Lambda)$, and
\item $j_!M \in D_{ctf}(X_\etale, \Lambda)$ if
$M \in D_{ctf}(U_\etale, \Lambda)$ and
the morphism $j$ is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-torsion-cohomology}
Let $X$ be a quasi-compact and quasi-separated scheme.
\begin{enumerate}
\item If $\mathcal{F}$ is a torsion abelian sheaf on $X_\etale$, then
$H^n_\etale(X, \mathcal{F})$ is a torsion abelian group for all $n$.
\item If $K$ in $D^+(X_\etale)$ has torsion cohomology sheaves, then
$H^n_\etale(X, K)$ is a torsion abelian group for all $n$.
\end{enumerate}

\label{lemma-torsion-direct-image}
Let $f : X \to Y$ be a quasi-compact and quasi-separated
morphism of schemes.
\begin{enumerate}
\item If $\mathcal{F}$ is a torsion abelian sheaf on $X_\etale$, then
$R^nf_*\mathcal{F}$ is a torsion abelian sheaf on $Y_\etale$ for all $n$.
\item If $K$ in $D^+(X_\etale)$ has torsion cohomology sheaves, then
$Rf_*K$ is an object of $D^+(Y_\etale)$ whose cohomology sheaves are
torsion abelian sheaves.
\end{enumerate}

\label{lemma-normal-scheme-with-alg-closed-function-field}
Let $X$ be an integral normal scheme with separably closed
function field.
\begin{enumerate}
\item A separated \'etale morphism $U \to X$ is a
disjoint union of open immersions.
\item All local rings of $X$ are strictly henselian.
\end{enumerate}

\label{lemma-lift-points-H-to-G}
Let $R$ be an $A$-algebra which is absolutely integrally closed. Then
$G(R) \to H(R)$ is surjective.

\label{lemma-constant-smooth-statements}
In Situation \ref{situation-what-to-prove}
assume $X$ is smooth and $\mathcal{F} = \underline{\mathbf{Z}/\ell\mathbf{Z}}$
for some prime number $\ell$. Then statements
(\ref{item-vanishing}) -- (\ref{item-surjective}) hold
for $\mathcal{F}$.

\label{lemma-constant-statements-coefficients}
Let $\Lambda$ be a Noetherian ring, let $M$ be a finite $\Lambda$-module which
is annihilated by an integer $n > 0$, let $k$ be an algebraically closed field,
and let $X$ be a separated, finite type scheme of dimension $\leq 1$ over $k$.
Then
\begin{enumerate}
\item $H^q_\etale(X, \underline{M})$ is a finite $\Lambda$-module
if $n$ is prime to $\text{char}(k)$,
\item $H^q_\etale(X, \underline{M})$ is a finite $\Lambda$-module
if $X$ is proper.
\end{enumerate}

\label{lemma-restrict-to-open-coefficients}
Let $\Lambda$ be a Noetherian ring, let $k$ be an algebraically closed field,
let $X$ be a separated finite type scheme over $k$ of dimension $\leq 1$,
let $\mathcal{F}$ be a constructible sheaf of $\Lambda$-modules on $X_\etale$,
and let $j : X' \to X$ be the inclusion of a dense open subscheme. Then
$H^q_\etale(X, \mathcal{F})$ is a finite $\Lambda$-module if and only if
$H^q_\etale(X, j_!j^{-1}\mathcal{F})$ is a finite $\Lambda$-module.

\label{lemma-somewhat-easier-coefficients}
Let $\Lambda$ be a Noetherian ring, let $M$ be a finite $\Lambda$-module which
is annihilated by an integer $n > 0$, let $k$ be an algebraically closed field,
let $X$ be a separated, finite type scheme of dimension $\leq 1$ over $k$, and
let $j : U \to X$ be an open immersion. Then
\begin{enumerate}
\item $H^q_\etale(X, j_!\underline{M})$ is a finite $\Lambda$-module
if $n$ is prime to $\text{char}(k)$,
\item $H^q_\etale(X, j_!\underline{M})$ is a finite $\Lambda$-module
if $X$ is proper.
\end{enumerate}

\label{lemma-vanishing-easier-coefficients}
Let $\Lambda$ be a Noetherian ring, let $k$ be an algebraically closed field,
let $X$ be a separated, finite type scheme of dimension $\leq 1$ over $k$,
let $j : U \to X$ be an open immersion with $U$ connected, let
$\ell$ be a prime number, let $n > 0$, and let $\mathcal{G}$ be a finite type,
locally constant sheaf of $\Lambda$-modules on $U_\etale$ annihilated by
$\ell^n$. Then
\begin{enumerate}
\item $H^q_\etale(X, j_!\mathcal{G})$ is a finite $\Lambda$-module
if $\ell$ is prime to $\text{char}(k)$,
\item $H^q_\etale(X, j_!\mathcal{G})$ is a finite $\Lambda$-module
if $X$ is proper.
\end{enumerate}

\label{theorem-vanishing-affine-curves-coefficients}
Let $\Lambda$ be a Noetherian ring, let $k$ be an algebraically closed field,
let $X$ be a separated, finite type scheme of dimension $\leq 1$ over $k$,
and let $\mathcal{F}$ be a constructible sheaf of $\Lambda$-modules
on $X_\etale$ which is torsion. Then
\begin{enumerate}
\item
\label{item-finite-prime-to-p-coefficients}
$H^q_\etale(X, \mathcal{F})$ is a finite $\Lambda$-module
if $\mathcal{F}$ is torsion prime to $\text{char}(k)$,
\item
\label{item-finite-proper-coefficients}
$H^q_\etale(X, \mathcal{F})$ is a finite $\Lambda$-module if $X$ is proper.
\end{enumerate}

\label{lemma-base-change-q-integral-top}
With $f : X \to S$ and $n$ as in Remark \ref{remark-base-change-holds}
assume for some $q \geq 1$ we have $BC(f, n, q - 1)$. Consider
commutative diagrams
$$
\vcenter{
\xymatrix{
X \ar[d]_f &
X' \ar[d]_{f'} \ar[l] &
Y \ar[l]^h \ar[d]^e &
Y' \ar[l]^{\pi'} \ar[d]^{e'} \\
S &
S' \ar[l] &
T \ar[l]_g &
T' \ar[l]_\pi
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
X' \ar[d]_{f'} & & Y' \ar[ll]^{h' = h \circ \pi'} \ar[d]^{e'} \\
S' & & T' \ar[ll]_{g' = g \circ \pi}
}
}
$$
where all squares are cartesian, $g$ quasi-compact and quasi-separated, and
$\pi$ is integral surjective. Let $\mathcal{F}$ be an abelian sheaf
on $T_\etale$ annihilated by $n$ and set $\mathcal{F}' = \pi^{-1}\mathcal{F}$.
If the base change map
$$
(f')^{-1}R^qg'_*\mathcal{F}' \longrightarrow R^qh'_*(e')^{-1}\mathcal{F}'
$$
is an isomorphism, then the base change map
$(f')^{-1}R^qg_*\mathcal{F} \to R^qh_*e^{-1}\mathcal{F}$
is an isomorphism.

\label{lemma-base-change-q-integral-bottom}
With $f : X \to S$ and $n$ as in Remark \ref{remark-base-change-holds}
assume for some $q \geq 1$ we have $BC(f, n, q - 1)$. Consider
commutative diagrams
$$
\vcenter{
\xymatrix{
X \ar[d]_f &
X' \ar[d]_{f'} \ar[l] &
X'' \ar[l]^{\pi'} \ar[d]_{f''} &
Y \ar[l]^{h'} \ar[d]^e \\
S &
S' \ar[l] &
S'' \ar[l]_\pi &
T \ar[l]_{g'}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
X' \ar[d]_{f'} & & Y \ar[ll]^{h = h' \circ \pi'} \ar[d]^e \\
S' & & T \ar[ll]_{g = g' \circ \pi}
}
}
$$
where all squares are cartesian, $g'$ quasi-compact and quasi-separated, and
$\pi$ is integral. Let $\mathcal{F}$ be an abelian sheaf
on $T_\etale$ annihilated by $n$. If the base change map
$$
(f')^{-1}R^qg_*\mathcal{F} \longrightarrow R^qh_*e^{-1}\mathcal{F}
$$
is an isomorphism, then the base change map
$(f'')^{-1}R^qg'_*\mathcal{F} \to R^qh'_*e^{-1}\mathcal{F}$
is an isomorphism.

\label{lemma-smooth-base-change-separably-closed}
Let $K/k$ be an extension of separably closed fields. Let $X$
be a quasi-compact and quasi-separated scheme over $k$.
Let $E \in D^+(X_\etale)$ have cohomology sheaves whose stalks
are torsion of orders invertible in $k$. Then
\begin{enumerate}
\item the maps $H^q_\etale(X, E) \to H^q_\etale(X_K, E|_{X_K})$
are isomorphisms, and
\item $E \to R(X_K \to X)_*E|_{X_K}$ is an isomorphism.
\end{enumerate}

\label{lemma-sandwich}
Let $f : X \to Y$ and $g : Y \to Z$ be proper morphisms of schemes. Assume
\begin{enumerate}
\item cohomology commutes with base change for $f$,
\item cohomology commutes with base change for $g \circ f$, and
\item $f$ is surjective.
\end{enumerate}
Then cohomology commutes with base change for $g$.

\label{lemma-composition}
Let $f : X \to Y$ and $g : Y \to Z$ be proper morphisms of schemes. Assume
\begin{enumerate}
\item cohomology commutes with base change for $f$, and
\item cohomology commutes with base change for $g$.
\end{enumerate}
Then cohomology commutes with base change for $g \circ f$.

\label{lemma-finite}
\begin{slogan}
Proper base change for \'etale cohomology holds for finite morphisms.
\end{slogan}
Let $f : X \to Y$ be a finite morphism of schemes.
Then cohomology commutes with base change for $f$.

\label{proposition-smooth-locally-acyclic}
Let $f : X \to S$ be a smooth morphism of schemes.
Then $f$ is universally locally acyclic.

\label{lemma-specialization-cospecialization}
In the situation above, if in addition
$f$ is quasi-compact and quasi-separated, then the diagram
$$
\xymatrix{
(Rf_*K)_{\overline{s}} \ar[r] \ar[d]_{sp} &
R\Gamma(X_{\overline{s}}, K) \\
(Rf_*K)_{\overline{t}} \ar[r] &
R\Gamma(X_{\overline{t}}, K) \ar[u]_{cosp}
}
$$
is commutative.

\label{lemma-cd-field-extension}
Let $L/K$ be a field extension. Then we have
$\text{cd}(L) \leq \text{cd}(K) + \text{trdeg}_K(L)$.

\label{proposition-cd-affine}
Let $K$ be a field. Let $X$ be an affine scheme of finite type over $K$.
Then we have $\text{cd}(X) \leq \dim(X) + \text{cd}(K)$.

\label{lemma-finite-cd}
Let $K$ be a field.
\begin{enumerate}
\item If $f : X \to Y$ is a morphism of finite type schemes over $K$,
then $\text{cd}(f) < \infty$.
\item If $\text{cd}(K) < \infty$, then $\text{cd}(X) < \infty$
for any finite type scheme $X$ over $K$.
\end{enumerate}

\label{lemma-compare-injectives}
Let $S$ be a scheme. Let $T$ be an object of $(\Sch/S)_\etale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in $\textit{Ab}((\Sch/S)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(T_\etale)$,
\item $\mathcal{I}|_{S_\etale}$ is injective in $\textit{Ab}(S_\etale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\Sch/S)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(T_\etale)$,
\item $\mathcal{I}^\bullet|_{S_\etale}$ is a K-injective complex in
$\textit{Ab}(S_\etale)$,
\end{enumerate}
\end{enumerate}
The corresponding statements for modules do not hold.

\label{lemma-compare-higher-direct-image-proper}
Let $f : T \to S$ be a proper morphism of schemes. Then we have
\begin{enumerate}
\item $\pi_S^{-1} \circ f_{small, *} = f_{big, *} \circ \pi_T^{-1}$
as functors $\Sh(T_\etale) \to \Sh((\Sch/S)_\etale)$,
\item $\pi_S^{-1}Rf_{small, *}K = Rf_{big, *}\pi_T^{-1}K$
for $K$ in $D^+(T_\etale)$ whose cohomology sheaves are torsion,
\item $\pi_S^{-1}Rf_{small, *}K = Rf_{big, *}\pi_T^{-1}K$
for $K$ in $D(T_\etale, \mathbf{Z}/n\mathbf{Z})$, and
\item $\pi_S^{-1}Rf_{small, *}K = Rf_{big, *}\pi_T^{-1}K$
for all $K$ in $D(T_\etale)$ if $f$ is finite.
\end{enumerate}

\label{lemma-proper-push-pull-fppf-etale}
In Lemma \ref{lemma-push-pull-fppf-etale} if $f$ is proper, then we have
$a_Y^{-1} \circ f_{small, *} = f_{big, fppf, *} \circ a_X^{-1}$.

\label{lemma-descent-sheaf-fppf-etale}
In Lemma \ref{lemma-push-pull-fppf-etale} assume
$f$ is flat, locally of finite presentation, and surjective.
Then the functor
$$
\Sh(Y_\etale) \longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\middle|
\begin{matrix}
\mathcal{G} \in \Sh(X_\etale),\ \mathcal{H} \in \Sh((\Sch/Y)_{fppf}), \\
\alpha : a_X^{-1}\mathcal{G} \to f_{big, fppf}^{-1}\mathcal{H}
\text{ an isomorphism}
\end{matrix}
\right\}
$$
sending $\mathcal{F}$ to
$(f_{small}^{-1}\mathcal{F}, a_Y^{-1}\mathcal{F}, can)$ is an equivalence.

\label{lemma-compare-cohomology-etale-fppf}
For a scheme $X$ and $a_X : \Sh((\Sch/X)_{fppf}) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_{fppf}(X, a_X^{-1}\mathcal{F})$
for an abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_{fppf}(X, a_X^{-1}K)$ for $K \in D^+(X_\etale)$.
\end{enumerate}
Example: if $A$ is an abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_{fppf}(X, \underline{A})$.

\label{lemma-proper-push-pull-ph-etale}
In Lemma \ref{lemma-push-pull-ph-etale} if $f$ is proper, then we have
$a_Y^{-1} \circ f_{small, *} = f_{big, ph, *} \circ a_X^{-1}$.

\label{lemma-compare-cohomology-etale-ph}
For a scheme $X$ and $a_X : \Sh((\Sch/X)_{ph}) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_{ph}(X, a_X^{-1}\mathcal{F})$
for a torsion abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_{ph}(X, a_X^{-1}K)$
for $K \in D^+(X_\etale)$ with torsion cohomology sheaves.
\end{enumerate}
Example: if $A$ is a torsion abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_{ph}(X, \underline{A})$.

\label{lemma-proper-push-pull-h-etale}
In Lemma \ref{lemma-push-pull-h-etale} if $f$ is proper, then we have
$a_Y^{-1} \circ f_{small, *} = f_{big, h, *} \circ a_X^{-1}$.

\label{lemma-compare-cohomology-etale-h}
For a scheme $X$ and $a_X : \Sh((\Sch/X)_h) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_h(X, a_X^{-1}\mathcal{F})$
for a torsion abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_h(X, a_X^{-1}K)$
for $K \in D^+(X_\etale)$ with torsion cohomology sheaves.
\end{enumerate}
Example: if $A$ is a torsion abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_h(X, \underline{A})$.

\label{lemma-blow-up-square-h}
With notation as above, if $K$ is in the essential image
of $R\epsilon_*$, then the maps $c^K_{X, Z, X', E}$ of
Cohomology on Sites, Lemma \ref{sites-cohomology-lemma-c-square}
are quasi-isomorphisms.

\label{definition-unramified-rings}
Let $A$, $B$ be Noetherian local rings. A local homomorphism $A \to B$
is said to be {\it unramified homomorphism of local rings} if
\begin{enumerate}
\item $\mathfrak m_AB = \mathfrak m_B$,
\item $\kappa(\mathfrak m_B)$ is a finite separable extension of
$\kappa(\mathfrak m_A)$, and
\item $B$ is essentially of finite type over $A$ (this means
that $B$ is the localization of a finite type $A$-algebra at a prime).
\end{enumerate}

\label{lemma-characterize-unramified-Noetherian}
\begin{slogan}
Unramifiedness is a stalk local condition.
\end{slogan}
Let $A \to B$ be of finite type with $A$ a Noetherian ring.
Let $\mathfrak q$ be a prime of $B$ lying over $\mathfrak p \subset A$.
Then $A \to B$ is unramified at $\mathfrak q$ if and only if
$A_{\mathfrak p} \to B_{\mathfrak q}$ is an unramified homomorphism
of local rings.

\label{lemma-characterize-unramified-completions}
Let $A$, $B$ be Noetherian local rings.
Let $A \to B$ be a local homomorphism such that $B$ is
essentially of finite type over $A$.
The following are equivalent
\begin{enumerate}
\item $A \to B$ is an unramified homomorphism of local rings
\item $A^\wedge \to B^\wedge$ is an unramified homomorphism of local rings, and
\item $A^\wedge \to B^\wedge$ is unramified.
\end{enumerate}

\label{definition-unramified-schemes}
(See Morphisms, Definition \ref{morphisms-definition-unramified}
for the definition in the general case.)
Let $Y$ be a locally Noetherian scheme.
Let $f : X \to Y$ be locally of finite type.
Let $x \in X$.
\begin{enumerate}
\item We say $f$ is {\it unramified at $x$} if
$\mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$
is an unramified homomorphism of local rings.
\item The morphism $f : X \to Y$ is said to be {\it unramified}
if it is unramified at all points of $X$.
\end{enumerate}

\label{proposition-properties-sections}
Sections of unramified morphisms.
\begin{enumerate}
\item Any section of an unramified morphism is an open immersion.
\item Any section of a separated morphism is a closed immersion.
\item Any section of an unramified separated morphism is open and closed.
\end{enumerate}

\label{theorem-sections-unramified-maps}
Let $Y$ be a connected scheme.
Let $f : X \to Y$ be unramified and separated.
Every section of $f$ is an isomorphism onto a connected component.
There exists a bijective correspondence
$$
\text{sections of }f
\leftrightarrow
\left\{
\begin{matrix}
\text{connected components }X'\text{ of }X\text{ such that}\\
\text{the induced map }X' \to Y\text{ is an isomorphism}
\end{matrix}
\right\}
$$
In particular, given $x \in X$ there is at most one
section passing through $x$.

\label{definition-flat-rings}
Flatness of modules and rings.
\begin{enumerate}
\item A module $N$ over a ring $A$ is said to be {\it flat}
if the functor $M \mapsto M \otimes_A N$ is exact.
\item If this functor is also faithful, we say that
$N$ is {\it faithfully flat} over $A$.
\item A morphism of rings $f : A \to B$ is said to be
{\it flat (resp. faithfully flat)}
if the functor $M \mapsto M \otimes_A B$ is exact
(resp. faithful and exact).
\end{enumerate}

\label{theorem-flat-is-quotient}
A faithfully flat quasi-compact morphism is a quotient map for
the Zariski topology.

\label{definition-etale-ring}
Let $A$, $B$ be Noetherian local rings.
A local homomorphism $f : A \to B$ is said to be an
{\it \'etale homomorphism of local rings}
if it is flat and an unramified homomorphism of local rings
(please see Definition \ref{definition-unramified-rings}).

\label{theorem-structure-etale}
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a localization of $B'$ at a prime.
\end{enumerate}

\label{theorem-structure-unramified}
Let $f : A \to B$ be an unramified morphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a quotient of a localization of $B'$ at a prime.
\end{enumerate}

\label{theorem-etale-radicial-open}
Let $f : X \to Y$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is an open immersion,
\item $f$ is universally injective and \'etale, and
\item $f$ is a flat monomorphism, locally of finite presentation.
\end{enumerate}

[Une equivalence remarquable de cat\'egories]
\label{theorem-remarkable-equivalence}
\begin{reference}
\cite[IV, Theorem 18.1.2]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $S_0 \subset S$ be a closed subscheme with the same underlying
topological space (for example if the ideal sheaf of $S_0$ in $S$
has square zero). The functor
$$
X \longmapsto X_0 = S_0 \times_S X
$$
defines an equivalence of categories
$$
\{
\text{schemes }X\text{ \'etale over }S
\}
\leftrightarrow
\{
\text{schemes }X_0\text{ \'etale over }S_0
\}
$$

\label{proposition-etale-CM}
\begin{slogan}
Being Cohen-Macaulay ascends and descends along \'etale maps.
\end{slogan}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is Cohen-Macaulay if and only if $B$ is so.

\label{proposition-etale-normal}
\begin{reference}
\cite[Expose I, Theorem 9.5 part (i)]{SGA1}
\end{reference}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is a normal domain if and only if $B$ is so.

\label{lemma-faithful}
If $f : X \to S$ is surjective, then the functor
(\ref{equation-descent-etale}) is faithful.

\label{lemma-fully-faithful-cases}
Let $f : X \to S$ be a morphism of schemes. In the following
cases the functor (\ref{equation-descent-etale}) is fully faithful:
\begin{enumerate}
\item $f$ is surjective and universally closed
(e.g., finite, integral, or proper),
\item $f$ is surjective and universally open
(e.g., locally of finite presentation and flat, smooth, or etale),
\item $f$ is surjective, quasi-compact, and flat.
\end{enumerate}

\label{proposition-effective}
Let $f : X \to S$ be a surjective integral morphism.
The functor (\ref{equation-descent-etale}) induces an equivalence
$$
\begin{matrix}
\text{schemes quasi-compact,}\\
\text{separated, \'etale over }S
\end{matrix}
\longrightarrow
\begin{matrix}
\text{descent data }(V, \varphi)\text{ relative to }X/S\text{ with}\\
V\text{ quasi-compact, separated, \'etale over }X
\end{matrix}
$$

\label{lemma-smooth-pullback-strict-normal-crossings}
\begin{slogan}
Pullback of a strict normal crossings divisor by a smooth
morphism is a strict normal crossings divisor.
\end{slogan}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a
strict normal crossings divisor. If $f : Y \to X$ is a smooth
morphism of schemes, then the pullback $f^*D$ is a
strict normal crossings divisor on $Y$.

\label{definition-normal-crossings}
Let $X$ be a locally Noetherian scheme. A {\it normal crossings divisor}
on $X$ is an effective Cartier divisor $D \subset X$ such that for
every $p \in D$ there exists an \'etale morphism $U \to X$ with
$p$ in the image and $D \times_X U$ a
strict normal crossings divisor on $U$.

\label{lemma-smooth-pullback-normal-crossings}
\begin{slogan}
Pullback of a normal crossings divisor by a smooth
morphism is a normal crossings divisor.
\end{slogan}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a
normal crossings divisor. If $f : Y \to X$ is a smooth
morphism of schemes, then the pullback $f^*D$ is a
normal crossings divisor on $Y$.

\label{lemma-characterize-normal-crossings}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a closed
subscheme. If $X$ is J-2 or Nagata, then the following are equivalent
\begin{enumerate}
\item $D$ is a normal crossings divisor in $X$,
\item for every $p \in D$ the pullback of $D$ to the spectrum of the
strict henselization $\mathcal{O}_{X, p}^{sh}$
is a strict normal crossings divisor.
\end{enumerate}

\label{lemma-finite-projective-modules-RS}
Example \ref{example-finite-projective-modules}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_V$ is a deformation category
for any finite dimensional vector space $V$ over $k$.

\label{lemma-representations-RS}
Example \ref{example-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-continuous-representations-RS}
Example \ref{example-continuous-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional continuous representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-graded-algebras-RS}
Example \ref{example-graded-algebras}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_P$ is a deformation category
for any graded $k$-algebra $P$.

\label{lemma-rings-RS}
Example \ref{example-rings}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_P$ is a deformation category
for any $k$-algebra $P$.

\label{lemma-smooth}
In Example \ref{example-rings} let $P$ be a smooth $k$-algebra. Then
$T\Deformationcategory_P = (0)$.

\label{lemma-finite-type-rings-TI}
In Lemma \ref{lemma-rings-TI} if $P$ is a finite type $k$-algebra, then
\begin{enumerate}
\item $\text{Inf}(\Deformationcategory_P)$ is finite dimensional if and only if
$\dim(P) = 0$, and
\item $T\Deformationcategory_P$ is finite dimensional if
$\Spec(P) \to \Spec(k)$ is smooth except at a finite number of points.
\end{enumerate}

\label{lemma-schemes-RS}
Example \ref{example-schemes}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any scheme $X$ over $k$.

\label{lemma-glueing}
In Situation \ref{situation-glueing}
there is an equivalence
$$
\Deformationcategory_X =
\Deformationcategory_{P_1}
\times_{\Deformationcategory_{P_{12}}}
\Deformationcategory_{P_2}
$$
of deformation categories, see Examples \ref{example-schemes} and
\ref{example-rings}.

\label{lemma-schemes-morphisms-RS}
Example \ref{example-schemes-morphisms}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{X \to Y}$ is a deformation category
for any morphism of schemes $X \to Y$ over $k$.

\label{lemma-spaces-RS}
Example \ref{example-spaces}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any algebraic space $X$ over $k$.

\label{lemma-smooth-completion}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $P^\wedge$ the $J$-adic completion. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-completion}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^\wedge}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-smooth-localization}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $S \subset P$ be a multiplicative subset. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth at all points of
$V(g)$ for all $g \in S$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-localization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{S^{-1}P}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-smooth-henselization}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $(P^h, J^h)$ the henselization of the pair $(P, J)$. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$,
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-henselization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^h}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-curve-isolated-lci}
In Example \ref{example-schemes} let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then $\Deformationcategory_X$ is unobstructed.

\label{lemma-smoothing-curve-isolated-lci}
Let $k$ be a field and let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then there exists a flat, separated, finite type morphism $Y \to \Spec(k[[t]])$
whose generic fibre is smooth and whose special fibre is
isomorphic to $X$.

\label{lemma-finite-type}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item The category of finite type $\mathcal{O}_X$-modules has a
set of isomorphism classes.
\item The category of finite type quasi-coherent
$\mathcal{O}_X$-modules has a set of isomorphism classes.
\end{enumerate}

\label{lemma-finite-etale-stack}
The functor
$$
p : \textit{F\'Et} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack over $(\Sch/S)_{fppf}$.

\label{lemma-torsors-sheaf-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : \mathcal{G}\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-variant-torsors-sheaf-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p :
\mathcal{G}/\mathcal{B}\textit{-Torsors}
\longrightarrow
(\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-torsors-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : G\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-group-quotient-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : [[X/G]] \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-picard-stack}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
\Picardstack_{X/B} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{definition-hilbert-d-stack}
We will denote $\mathcal{H}_d(\mathcal{X}/\mathcal{Y})$
the {\it degree $d$ finite Hilbert stack of $\mathcal{X}$ over $\mathcal{Y}$}
constructed above. If $\mathcal{Y} = S$ we write
$\mathcal{H}_d(\mathcal{X}) = \mathcal{H}_d(\mathcal{X}/\mathcal{Y})$.
If $\mathcal{X} = \mathcal{Y} = S$ we denote it $\mathcal{H}_d$.

\label{lemma-lim-not-quasi-compact}
There exists an inverse system of quasi-compact topological spaces
over $\mathbf{N}$ whose limit is not quasi-compact.

\label{lemma-noncomplete-completion}
There exists a local ring $R$ and a maximal ideal $\mathfrak m$ such that
the completion $R^\wedge$ of $R$ with respect to $\mathfrak m$ has the
following properties
\begin{enumerate}
\item $R^\wedge$ is local, but its maximal ideal is not equal to
$\mathfrak m R^\wedge$,
\item $R^\wedge$ is not a complete local ring, and
\item $R^\wedge$ is not $\mathfrak m$-adically complete as an $R$-module.
\end{enumerate}

\label{lemma-completion-not-exact}
\begin{slogan}
Completion is neither left nor right exact in general.
\end{slogan}
Completion is not an exact functor in general; it is not even
right exact in general. This holds even when $I$ is finitely
generated on the category of finitely presented modules.

\label{lemma-closed-is-complete}
Let $I \subset R$ be an ideal of a ring. Let $M$ be an $I$-adically complete
$R$-module and let $N \subset M$ be a submodule. The following are equivalent
\begin{enumerate}
\item $N$ is closed in $M$,
\item $N = \bigcap_{n \geq 1} (N + I^n M)$,
\item $M/N$ is $I$-adically complete
\end{enumerate}
If $I$ is finitely generated, these conditions imply that $N$
is $I$-adically complete.

\label{lemma-countable-coherent}
Let $R$ be a countable ring. Then $R$ is coherent if and only if
$R^\mathbf{N}$ is a flat $R$-module.

\label{lemma-completion-polynomial-ring-not-flat}
There exists a ring such that the completion $R[[x]]$ of $R[x]$
at $(x)$ is not flat over $R$ and a fortiori not flat over $R[x]$.

\label{lemma-completion-polynomial-ring-not-flat-bis}
If $R$ is a valuation ring of dimension $> 1$, then $R[[x]]$
is flat over $R$ but not flat over $R[x]$.

\label{lemma-nonsplit-locally-split}
There exists a ring $R$ and a nonsplit sequence of modules
which becomes split Zariski locally.

\label{lemma-complement-of-affine-does-not-contain-qc-dense-open}
Nonexistence quasi-compact opens of affines:
\begin{enumerate}
\item There exist an affine scheme $S$ and affine open $U \subset S$
such that there is no quasi-compact open $V \subset S$ with
$U \cap V = \emptyset$ and $U \cup V$ dense in $S$.
\item There exists an affine scheme $S$ and a closed point $s \in S$ such that
$S \setminus \{s\}$ does not contain a quasi-compact dense open.
\end{enumerate}

\label{lemma-no-dense-separated-quasi-compact-open-in-qcqs}
There exists a quasi-compact and quasi-separated scheme $X$ which does
not contain a separated quasi-compact dense open.

\label{lemma-nonexistence-qc-dense-open-subscheme}
There exists a quasi-compact and quasi-separated algebraic space
which does not contain a quasi-compact dense open subscheme.

\label{lemma-pushforward-quasi-coherent}
Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
is sharp in the sense that one can neither drop the assumption
of quasi-compactness nor the assumption of quasi-separatedness.

\label{lemma-finite-flat-non-projective}
Strange flat modules.
\begin{enumerate}
\item There exists a ring $R$ and a finite flat $R$-module $M$ which is
not projective.
\item There exists a closed immersion which is flat but not open.
\end{enumerate}

\label{lemma-ideal-projective-not-locally-free}
There exists a ring $R$ and an ideal $I$ such that $I$ is projective as
an $R$-module but not locally free as an $R$-module.

\label{lemma-zero-dimensional-flat-ideal}
\begin{slogan}
Zero dimensional ring with flat ideal.
\end{slogan}
There exists a local ring $R$ with a unique prime ideal
and a nonzero ideal $I \subset R$ which is a flat $R$-module

\label{lemma-epi-not-surjective}
There exists an epimorphism of local rings of dimension $0$
which is not a surjection.

\label{lemma-formally-etale-nontrivial-cotangent-complex}
There exists a formally \'etale surjective ring map $A \to B$
with $L_{B/A}$ not equal to zero.

\label{lemma-not-ind-etale}
There is a ring map $A \to B$ which identifies local rings but
which is not ind-\'etale. A fortiori it is not ind-Zariski.

\label{lemma-non-separated-group-scheme}
There exists a flat group scheme of finite type over the affine line
which is not separated.

\label{lemma-non-quasi-separated-group-scheme}
There exists a flat group scheme of finite type over the infinite
dimensional affine space which is not quasi-separated.

\label{lemma-non-flat-group-scheme}
There exists a group scheme $G$ over a base $S$ whose identity
component is flat over $S$ but which is not flat over $S$.

\label{lemma-non-separated-group-space}
There exists a group algebraic space of finite type over a field
which is not separated (and not even quasi-separated or locally separated).

\label{lemma-etale-not-dominated-zariski-finite-etale}
The \'etale cover $U \to X$ cannot be refined by any finite composition
of open immersions and finite \'etale morphisms.

\label{lemma-sheaf-zero-on-low-dimension}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(X) = 0$ whenever $\dim(X) < n$,
\item $G(X)$ is not zero if $\dim(X) \geq n$, and
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$.
\end{enumerate}

\label{lemma-weird-sheaf}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(\Spec(k)) = 0$ whenever $k$ is a field,
\item $G$ is limit preserving,
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$, and
\item $G$ is not zero.
\end{enumerate}

\label{lemma-big-abelian-category}
There exists a ``big'' abelian category $\mathcal{A}$ whose
$\Ext$-groups are proper classes.

\label{lemma-example-schematically-dense-missing-weakly-associated-point}
There exists a reduced scheme $X$ and a schematically dense open
$U \subset X$ such that some weakly associated point $x \in X$ is not in $U$.

\label{lemma-nonfinite-h0}
Non-finite $H^0$.
\begin{enumerate}
\item There exists a ring $R$ and a projective scheme $X$
over $R$ such that $H^0(X, \mathcal{O}_X)$ is not
a finite $R$-module.
\item There exists a ring $R$ and a finite type quasi-coherent module
$\mathcal{F}$ on $\mathbf{P}^1_R$ such that
$H^0(\mathbf{P}^1_R, \mathcal{F})$ is not a finite $R$-module.
\end{enumerate}

\label{lemma-non-descending-property-projective}
The properties
\begin{enumerate}
\item[] $\mathcal{P}(f) =$``$f$ is projective'', and
\item[] $\mathcal{P}(f) =$``$f$ is quasi-projective''
\end{enumerate}
are not Zariski local on the base. A fortiori, they are not fpqc local
on the base.

\label{lemma-family-of-curves-not-scheme}
There exists a field $k$ and a family of curves
$X \to \mathbf{A}^1_k$ such that $X$ is not a scheme.

\label{lemma-torsors-over-field-torsion}
Let $G$ be a smooth commutative group algebraic space over a field $K$.
Then $H^1_{fppf}(\Spec(K), G)$ is torsion.

\label{lemma-not-essentially-surjective}
The canonical map $\mathcal{X}(S) \to \lim \mathcal{X}(S_n)$
is not essentially surjective.

\label{lemma-counter-Grothendieck-existence}
Counter examples to algebraization of coherent sheaves.
\begin{enumerate}
\item Grothendieck's existence theorem as stated in
Cohomology of Schemes, Theorem \ref{coherent-theorem-grothendieck-existence}
is false if we drop the assumption that $X \to \Spec(A)$ is separated.
\item The stack of coherent sheaves $\Cohstack_{X/B}$
of Quot, Theorems \ref{quot-theorem-coherent-algebraic-general} and
\ref{quot-theorem-coherent-algebraic} is in general
not algebraic if we drop the assumption that $X \to S$ is separated
\item The functor $\Quotfunctor_{\mathcal{F}/X/B}$ of
Quot, Proposition \ref{quot-proposition-quot}
is not an algebraic space in general if we drop the assumption
that $X \to B$ is separated.
\end{enumerate}

\label{lemma-Z-not-quasi-compact}
The scheme $\Spec(\mathbf{Z})$ is not quasi-compact
in the canonical topology on the category of schemes.

\label{definition-colimit}
The ring $A$ constructed in Exercise \ref{exercise-directed-colimit}
is called the {\it colimit} of the system. Notation $\colim A_i$.

\label{definition-quasi-compact}
A topological space $X$ is called {\it quasi-compact}
if for any open covering $X = \bigcup_{i\in I} U_i$ there is a finite
subset $\{i_1, \ldots, i_n\}\subset I$ such that $X = U_{i_1}\cup\ldots
U_{i_n}$.

\label{definition-closed}
A point $x\in X$ is called {\it closed} if $\overline{\{x\}} = \{ x\}$.
Let $x, y$ be points of $X$. We say that $x$ is a {\it specialization}
of $y$, or that $y$ is a {\it generalization} of $x$ if
$x\in \overline{\{y\}}$.

\label{definition-connected-component}
A topological space $X$ is called {\it connected} if it is nonempty and not the
union of two nonempty disjoint open subsets. A {\it connected component}
of $X$ is a maximal connected subset. Any point of $X$ is contained
in a connected component of $X$ and any connected component of $X$ is
closed in $X$. (But in general a connected component need not be open in $X$.)

\label{definition-GU-GD}
Let $\phi : A \to B$ be a homomorphism of rings. We say
that the {\it going-up theorem} holds for $\phi$ if the
following condition is satisfied:
\begin{itemize}
\item[(GU)] for any ${\mathfrak p}, {\mathfrak p}' \in \Spec(A)$ such that
${\mathfrak p} \subset {\mathfrak p}'$, and for any $P \in \Spec(B)$ lying
over ${\mathfrak p}$, there exists $P'\in \Spec(B)$ lying
over ${\mathfrak p}'$ such that $P \subset P'$.
\end{itemize}
Similarly, we say that the {\it going-down theorem} holds for $\phi$
if the following condition is satisfied:
\begin{itemize}
\item[(GD)] for any ${\mathfrak p}, {\mathfrak p}' \in \Spec(A)$ such that
${\mathfrak p} \subset {\mathfrak p}'$, and for any
$P' \in \Spec(B)$ lying
over ${\mathfrak p}'$, there exists $P\in \Spec(B)$ lying
over ${\mathfrak p}$ such that $P \subset P'$.
\end{itemize}

\label{definition-numerical-polynomial}
A {\it numerical polynomial} is a polynomial $f(x) \in {\mathbf Q}[x]$
such that $f(n) \in {\mathbf Z}$ for every integer $n$.

\label{definition-Proj-R}
We define the {\it homogeneous spectrum $\text{Proj}(R)$}
of the graded ring $R$ to be the set of homogeneous, prime ideals
${\mathfrak p}$ of $R$ such that $R_{+} \not \subset {\mathfrak p}$.
Note that $\text{Proj}(R)$ is a subset of $\Spec(R)$ and hence has a
natural induced topology.

\label{definition-CM}
A Noetherian local ring $A$ is said to be {\it Cohen-Macaulay}
of dimension $d$ if it has dimension $d$ and there exists a system
of parameters $x_1, \ldots, x_d$ for $A$ such that $x_i$ is a nonzerodivisor
in $A/(x_1, \ldots, x_{i-1})$ for $i = 1, \ldots, d$.

\label{definition-tangent-space}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$. We dub the set of dotted arrows
of Exercise \ref{exercise-tangent-space-Zariski}
the {\it tangent space of $X$ over $S$}
and we denote it $T_{X/S, x}$. An element of this
space is called a {\it tangent vector} of $X/S$ at $x$.

\label{definition-quasi-coherent}
Let $X$ be a scheme.
A sheaf $\mathcal{F}$ of $\mathcal{O}_X$-modules is {\it quasi-coherent}
if for every affine open $\Spec(R) = U \subset X$ the restriction
$\mathcal{F}|_U$ is of the form $\widetilde M$ for some $R$-module
$M$.

\label{definition-field}
A {\it field} is a nonzero ring where every nonzero element is invertible.
Given a field a {\it subfield} is a subring that is itself a field.

\label{definition-domain}
A {\it domain} or an {\it integral domain} is a nonzero ring where $0$
is the only zerodivisor.

\label{lemma-field-maps-injective}
If $F$ is a field and $R$ is a nonzero ring, then any ring homomorphism
$\varphi : F \to R$ is injective.

\label{lemma-finite-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is finite over $F$, then $K$ is finite over $E$.

\label{lemma-finite-finitely-generated}
A finite extension of fields is a finitely generated field extension.
The converse is not true.

\label{definition-number-field}
A field $K$ is said to be a {\it number field} if it has characteristic
$0$ and the extension $K/\mathbf{Q}$ is finite.

\label{lemma-algebraic-goes-up}
Let $K/E/F$ be a tower of field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is algebraic over $F$, then $\alpha$ is algebraic
over $E$.
\item If $K$ is algebraic over $F$, then $K$ is algebraic over $E$.
\end{enumerate}

\label{lemma-algebraic-finitely-generated}
\begin{slogan}
A finitely generated algebraic extension is finite.
\end{slogan}
Let $k$ be a field, and let $\alpha_1, \alpha_2, \ldots, \alpha_n$ be elements
of some extension field such that each $\alpha_i$ is algebraic over $k$. Then
the extension $k(\alpha_1, \ldots, \alpha_n)/k$ is finite.
That is, a finitely generated algebraic extension is finite.

\label{lemma-algebraic-elements}
Let $E/k$ be a field extension. Then the elements of $E$ algebraic over $k$
form a subextension of $E/k$.

\label{lemma-algebraic-permanence}
Let $E/k$ and $F/E$ be algebraic extensions of fields. Then $F/k$ is an
algebraic extension of fields.

\label{lemma-size-algebraic-extension}
Let $E/F$ be an algebraic extension of fields. Then the cardinality $|E|$
of $E$ is at most $\max(\aleph_0, |F|)$.

\label{lemma-subalgebra-algebraic-extension-field}
Let $E/F$ be a finite or more generally an algebraic extension of fields.
Any subring $F \subset R \subset E$ is a field.

\label{lemma-algebraic-extension-self-map}
Let $E/F$ an algebraic extension of fields. Any $F$-algebra map
$f : E \to E$ is an automorphism.

\label{definition-minimal-polynomial}
The polynomial $P$ above is called the {\it minimal polynomial}
of $\alpha$ over $k$.

\label{definition-algebraically-closed}
A field $F$ is said to be {\it algebraically closed} if every algebraic
extension $E/F$ is trivial, i.e., $E = F$.

\label{lemma-algebraically-closed}
Let $F$ be a field. The following are equivalent
\begin{enumerate}
\item $F$ is algebraically closed,
\item every irreducible polynomial over $F$ is linear,
\item every nonconstant polynomial over $F$ has a root,
\item every nonconstant polynomial over $F$ is a product of linear factors.
\end{enumerate}

\label{definition-algebraic-closure}
Let $F$ be a field. An {\it algebraic closure} of $F$ is a field
$\overline{F}$ containing $F$ such that:
\begin{enumerate}
\item $\overline{F}$ is algebraic over $F$.
\item $\overline{F}$ is algebraically closed.
\end{enumerate}

\label{definition-relatively-prime}
If $k$ is any field, we say that two polynomials in $k[x]$ are
{\it relatively prime} if they generate the unit ideal in $k[x]$.

\label{lemma-relatively-prime-polynomials}
Two polynomials in $k[x]$ are relatively prime precisely when they
have no common roots in an algebraic closure $\overline{k}$ of $k$.

\label{definition-separable}
Let $F$ be a field. Let $K/F$ be an extension of fields.
\begin{enumerate}
\item We say an irreducible polynomial $P$ over $F$ is {\it separable}
if it is relatively prime to its derivative.
\item Given $\alpha \in K$ algebraic over $F$ we say $\alpha$ is
{\it separable} over $F$ if its minimal polynomial is separable over $F$.
\item If $K$ is an algebraic extension of $F$, we say $K$ is
{\it separable}\footnote{For nonalgebraic extensions
this definition does not make sense and is not the correct one. We refer
the reader to Algebra, Sections \ref{algebra-section-separability} and
\ref{algebra-section-separability-continued}.}
over $F$ if every element of $K$ is separable over $F$.
\end{enumerate}

\label{lemma-separable-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is separable over $F$, then $\alpha$ is separable
over $E$.
\item if $K$ is separable over $F$, then $K$ is separable over $E$.
\end{enumerate}

\label{lemma-count-embeddings-explicitly}
In Situation \ref{situation-finitely-generated} we have
$|\Mor_F(K, \overline{F})| = \prod_{i = 1}^n \deg_s(P_i)$.

\label{lemma-separable-permanence}
Let $E/k$ and $F/E$ be separable algebraic extensions of fields. Then $F/k$
is a separable extension of fields.

\label{lemma-separable-elements}
Let $E/k$ be a field extension. Then the elements of $E$ separable
over $k$ form a subextension of $E/k$.

\label{definition-purely-inseparable}
Let $F$ be a field of characteristic $p > 0$. Let $K/F$ be an extension.
\begin{enumerate}
\item An element $\alpha \in K$ is {\it purely inseparable} over $F$
if there exists a power $q$ of $p$ such that $\alpha^q \in F$.
\item The extension $K/F$ is said to be {\it purely inseparable}
if and only if every element of $K$ is purely inseparable over $F$.
\end{enumerate}
If we have a field extension $L/M$ (with no condition on the characteristic
of $M$), then we will say the extension is {\it purely inseparable}
if either $L = M$ or the characteristic of $M$ is a prime number $p$
and $L/M$ is purely inseparable in the sense defined above.

\label{lemma-purely-inseparable-permanence}
Let $E/k$ and $F/E$ be purely inseparable extensions of fields. Then $F/k$
is a purely inseparable extension of fields.

\label{lemma-purely-inseparable-elements}
Let $E/k$ be a field extension. Then the elements of $E$ purely-inseparable
over $k$ form a subextension of $E/k$.

\label{lemma-separable-first}
\begin{slogan}
Any algebraic field extension is uniquely a separable field extension
followed by a purely inseparable one.
\end{slogan}
Let $E/F$ be an algebraic field extension. There exists a unique subextension
$E/E_{sep}/F$ such that $E_{sep}/F$ is separable and $E/E_{sep}$ is
purely inseparable.

\label{definition-insep-degree}
Let $E/F$ be an algebraic field extension. Let $E_{sep}$ be the subextension
found in Lemma \ref{lemma-separable-first}.
\begin{enumerate}
\item The integer $[E_{sep} : F]$ is called the {\it separable
degree} of the extension. Notation $[E : F]_s$.
\item The integer $[E : E_{sep}]$ is called the {\it inseparable
degree}, or the {\it degree of inseparability} of the extension.
Notation $[E : F]_i$.
\end{enumerate}

\label{lemma-separable-degree}
Let $K/F$ be a finite extension. Let $\overline{F}$ be an algebraic
closure of $F$. Then $[K : F]_s = |\Mor_F(K, \overline{F})|$.

\label{definition-normal}
Let $E/F$ be an algebraic field extension. We say $E$ is {\it normal}
over $F$ if for all $\alpha \in E$ the minimal polynomial $P$
of $\alpha$ over $F$ splits completely into linear factors over $E$.

\label{lemma-normal-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is normal over $F$, then $K$ is normal over $E$.

\label{lemma-separable-first-normal}
Let $E/F$ be a normal algebraic field extension. Then the subextension
$E/E_{sep}/F$ of Lemma \ref{lemma-separable-first} is normal.

\label{lemma-characterize-normal}
Let $E/F$ be an algebraic extension of fields. Let $\overline{F}$ be an
algebraic closure of $F$. The following are equivalent
\begin{enumerate}
\item $E$ is normal over $F$, and
\item for every pair $\sigma, \sigma' \in \Mor_F(E, \overline{F})$ we
have $\sigma(E) = \sigma'(E)$.
\end{enumerate}

\label{lemma-lift-maps}
Let $L/M/K$ be a tower of algebraic extensions.
\begin{enumerate}
\item If $M/K$ is normal, then any automorphism $\tau$ of $L/K$
induces an automorphism $\tau|_M : M \to M$.
\item If $L/K$ is normal, then any $K$-algebra map $\sigma : M \to L$
extends to an automorphism of $L$.
\end{enumerate}

\label{definition-splitting-field}
Let $F$ be a field. Let $P \in F[x]$ be a nonconstant polynomial.
The field extension $E/F$ constructed in Lemma \ref{lemma-splitting-field}
is called the {\it splitting field of $P$ over $F$}.

\label{lemma-normal-closure}
\begin{slogan}
Existence of normal closure of finite extensions of fields.
\end{slogan}
Let $E/F$ be a finite extension of fields. There exists a unique
smallest finite extension $K/E$ such that $K$ is normal over $F$.

\label{definition-normal-closure}
Let $E/F$ be a finite extension of fields. The field extension $K/E$
constructed in Lemma \ref{lemma-normal-closure}
is called the {\it normal closure $E$ over $F$}.

\label{lemma-normal-closure-inside-normal}
Let $L/K$ be an algebraic normal extension.
\begin{enumerate}
\item If $L/M/K$ is a subextension with $M/K$ finite, then there exists
a tower $L/M'/M/K$ with $M'/K$ finite and normal.
\item If $L/M'/M/K$ is a tower with $M/K$ normal and $M'/M$ finite,
then there exists a tower $L/M''/M'/M/K$ with $M''/M$
finite and $M''/K$ normal.
\end{enumerate}

[Primitive element]
\label{lemma-primitive-element}
Let $E/F$ be a finite extension of fields. The following are equivalent
\begin{enumerate}
\item there exists a primitive element for $E$ over $F$, and
\item there are finitely many subextensions $E/K/F$.
\end{enumerate}
Moreover, (1) and (2) hold if $E/F$ is separable.

\label{definition-trace-norm}
Let $L/K$ be a finite extension of fields. For $\alpha \in L$ we define
the {\it trace}
$\text{Trace}_{L/K}(\alpha) = \text{Trace}_K(\alpha : L \to L)$
and the {\it norm}
$\text{Norm}_{L/K}(\alpha) = \det_K(\alpha : L \to L)$.

\label{lemma-trace-and-norm-tower}
Let $M/L/K$ be a tower of finite extensions of fields. Then
$$
\text{Trace}_{M/K} = \text{Trace}_{L/K} \circ \text{Trace}_{M/L}
\quad\text{and}\quad
\text{Norm}_{M/K} = \text{Norm}_{L/K} \circ \text{Norm}_{M/L}
$$

\label{lemma-separable-trace-pairing}
Let $L/K$ be a finite extension of fields. The following are equivalent:
\begin{enumerate}
\item $L/K$ is separable,
\item $\text{Trace}_{L/K}$ is not identically zero, and
\item the trace pairing $Q_{L/K}$ is nondegenerate.
\end{enumerate}

\label{definition-galois}
A field extension $E/F$ is called {\it Galois} if it is algebraic,
separable, and normal.

\label{lemma-finite-Galois}
Let $E/F$ be a finite extension of fields. Then $E$ is Galois over $F$
if and only if $|\text{Aut}(E/F)| = [E : F]$.

\label{definition-galois-group}
If $E/F$ is a Galois extension, then the group $\text{Aut}(E/F)$ is
called the {\it Galois group} and it is denoted $\text{Gal}(E/F)$.

\label{lemma-galois-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is Galois over $F$, then $K$ is Galois over $E$.

[Fundamental theorem of algebra]
\label{lemma-C-algebraically-closed}
The field $\mathbf{C}$ is algebraically closed.

\label{lemma-subfields-kummer}
\begin{reference}
\cite[Theorem 5.2]{Radical}
\end{reference}
Let $K$ be a field. Let $L/K$ be a finite extension of degree $e$
which is generated by an element $\alpha$ with $a = \alpha^e \in K$.
If every $e$th root of unity in $L$ is contained in $K$, then 
any sub extension $L/L'/K$ is generated by $\alpha^d$ for some $d | e$.

\label{lemma-transcendence-degree}
Let $E/F$ be a field extension. A transcendence basis of $E$ over $F$ exists.
Any two transcendence bases have the same cardinality.

\label{definition-algebraically-closed-in}
Let $K/k$ be a field extension.
\begin{enumerate}
\item The {\it algebraic closure of $k$ in $K$} is the subfield
$k'$ of $K$ consisting of elements of $K$ which are algebraic over $k$.
\item We say $k$ is {\it algebraically closed in $K$} if
every element of $K$ which is algebraic over $k$ is
contained in $k$.
\end{enumerate}

\label{lemma-algebraic-closure-in-finitely-generated}
Let $K/k$ be a finitely generated field extension.
The algebraic closure of $k$ in $K$ is finite over $k$.

\label{definition-compositum}
Consider a diagram
\begin{equation}
\label{equation-inside-omega}
\vcenter{
\xymatrix{
L \ar[r] & \Omega \\
k \ar[r] \ar[u] & K \ar[u]
}
}
\end{equation}
of field extensions. The {\it compositum of $K$ and $L$ in $\Omega$}
written $KL$ is the smallest subfield of $\Omega$ containing both
$L$ and $K$.

\label{lemma-normal-case}
Let $E/F$ be a normal algebraic field extension. There exist subextensions
$E / E_{sep} /F$ and $E / E_{insep} / F$ such that
\begin{enumerate}
\item $F \subset E_{sep}$ is Galois and $E_{sep} \subset E$
is purely inseparable,
\item $F \subset E_{insep}$ is purely inseparable and $E_{insep} \subset E$
is Galois,
\item $E = E_{sep} \otimes_F E_{insep}$.
\end{enumerate}

\label{definition-separable-algebraic}
Algebraic field extensions.
\begin{enumerate}
\item A field extension $K/k$ is called {\it algebraic}
if every element of $K$ is algebraic over $k$.
\item An algebraic extension $k'/k$ is called {\it separable}
if every $\alpha \in k'$ is separable over $k$.
\item An algebraic
extension $k'/k$ is called {\it purely inseparable} if
the characteristic of $k$ is $p > 0$ and for every element
$\alpha \in k'$ there exists a power $q$ of $p$ such that
$\alpha^q \in k$.
\item An algebraic extension $k'/k$ is called {\it normal}
if for every $\alpha \in k'$ the minimal polynomial $P(T) \in k[T]$
of $\alpha$ over $k$ splits completely into linear factors over $k'$.
\item An algebraic extension $k'/k$ is called {\it Galois}
if it is separable and normal.
\end{enumerate}

\label{lemma-flat-up-down-henselization}
Let $S$ be a scheme and $s \in S$ a point. Denote $\mathcal{O}_{S, s}^h$
(resp.\ $\mathcal{O}_{S, s}^{sh}$) the henselization (resp.\ strict
henselization), see
Algebra, Definition \ref{algebra-definition-henselization}.
Let $M^{sh}$ be a $\mathcal{O}_{S, s}^{sh}$-module.
The following are equivalent
\begin{enumerate}
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}$,
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^h$, and
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^{sh}$.
\end{enumerate}
If $M^{sh} = M^h \otimes_{\mathcal{O}_{S, s}^h} \mathcal{O}_{S, s}^{sh}$
this is also equivalent to
\begin{enumerate}
\item[(4)] $M^h$ is flat over $\mathcal{O}_{S, s}$, and
\item[(5)] $M^h$ is flat over $\mathcal{O}_{S, s}^h$.
\end{enumerate}
If $M^h = M \otimes_{\mathcal{O}_{S, s}} \mathcal{O}_{S, s}^h$
this is also equivalent to
\begin{enumerate}
\item[(6)] $M$ is flat over $\mathcal{O}_{S, s}$.
\end{enumerate}

\label{lemma-devissage-flat}
Assumptions and notation as in
Lemma \ref{lemma-elementary-devissage}.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is flat over $S$ in a neighbourhood of $x$,
\item $\mathcal{G}$ is flat over $S'$ in a neighbourhood of $z'$, and
\item $\pi_*\mathcal{G}$ is flat over $S'$ in a neighbourhood of $y'$.
\end{enumerate}
The following are equivalent also
\begin{enumerate}
\item[(a)] $\mathcal{F}_x$ is flat over $\mathcal{O}_{S, s}$,
\item[(b)] $\mathcal{G}_{z'}$ is flat over $\mathcal{O}_{S', s'}$, and
\item[(c)] $(\pi_*\mathcal{G})_{y'}$ is flat over $\mathcal{O}_{S', s'}$.
\end{enumerate}

\label{lemma-shrink}
With assumption and notation as in
Definition \ref{definition-shrink}
we have:
\begin{enumerate}
\item
\label{item-shrink-base}
If $S' \subset S$ is a standard open neighbourhood of $s$, then
setting $X' = X_{S'}$, $Z' = Z_{S'}$ and $Y' = Y_{S'}$ we obtain a
standard shrinking.
\item
\label{item-shrink-on-Y}
Let $W \subset Y$ be a standard open neighbourhood of $y$.
Then there exists a standard shrinking with $Y' = W \times_S S'$.
\item
\label{item-shrink-on-X}
Let $U \subset X$ be an open neighbourhood of $x$.
Then there exists a standard shrinking with $X' \subset U$.
\end{enumerate}

\label{lemma-shrink-complete}
With assumption and notation as in
Definition \ref{definition-shrink-complete}
we have:
\begin{enumerate}
\item
\label{item-shrink-base-complete}
If $S' \subset S$ is a standard open neighbourhood of $s$, then
setting $X' = X_{S'}$, $Z'_k = Z_{S'}$ and $Y'_k = Y_{S'}$ we obtain a
standard shrinking.
\item
\label{item-shrink-on-Y-complete}
Let $W \subset Y_n$ be a standard open neighbourhood of $y$.
Then there exists a standard shrinking with $Y'_n = W \times_S S'$.
\item
\label{item-shrink-on-X-complete}
Let $U \subset X$ be an open neighbourhood of $x$.
Then there exists a standard shrinking with $X' \subset U$.
\end{enumerate}

\label{lemma-fibres-irreducible-flat-projective-nonnoetherian}
Let $R$ be a ring. Let $R \to S$ be a ring map.
Assume
\begin{enumerate}
\item $R \to S$ is of finite presentation and flat, and
\item every fibre ring $S \otimes_R \kappa(\mathfrak p)$ is
geometrically integral over $\kappa(\mathfrak p)$.
\end{enumerate}
Then $S$ is projective as an $R$-module.

\label{lemma-flat-finite-type-finitely-presented-over-dense-open}
\begin{slogan}
$S$-flat and finite type extensions of finitely presented modules
on a (good) open are also $X$-finitely presented.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes. Let $\mathcal{F}$ be a
quasi-coherent $\mathcal{O}_X$-module. Let $U \subset S$ be open.
Assume
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $\mathcal{F}$ is of finite type and flat over $S$,
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\item $\mathcal{F}|_{f^{-1}U}$ is of finite presentation.
\end{enumerate}
Then $\mathcal{F}$ is of finite presentation.

\label{lemma-flat-finite-type-finitely-presented-over-dense-open-X}
Let $f : X \to S$ be a morphism of schemes. Let $U \subset S$ be open.
Assume
\begin{enumerate}
\item $f$ is locally of finite type and flat,
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\item $f|_{f^{-1}U} : f^{-1}U \to U$ is locally of finite presentation.
\end{enumerate}
Then $f$ is of locally of finite presentation.

\label{lemma-zariski}
Let $f : X \to S$ be a morphism of schemes and $U \subset S$ an open. If
\begin{enumerate}
\item $f$ is separated, locally of finite type, and flat,
\item $f^{-1}(U) \to U$ is an isomorphism, and
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\end{enumerate}
then $f$ is an open immersion.

\label{theorem-finite-type-flat}
\begin{slogan}
The flat locus is open (non-Noetherian version).
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Assume
\begin{enumerate}
\item $X \to S$ is locally of finite presentation,
\item $\mathcal{F}$ is an $\mathcal{O}_X$-module of finite type, and
\item the set of weakly associated points of $S$ is locally finite in $S$.
\end{enumerate}
Then $U = \{x \in X \mid \mathcal{F}\text{ flat at }x\text{ over }S\}$
is open in $X$ and $\mathcal{F}|_U$ is an $\mathcal{O}_U$-module
of finite presentation and flat over $S$.

\label{proposition-flat-finite-type-finite-presentation-domain}
Let $R$ be a domain. Let $R \to S$ be a ring map of finite type.
Let $M$ be a finite $S$-module.
\begin{enumerate}
\item If $S$ is flat over $R$, then $S$ is a finitely presented $R$-algebra.
\item If $M$ is flat as an $R$-module, then $M$ is finitely presented
as an $S$-module.
\end{enumerate}

\label{definition-impurity}
In
Situation \ref{situation-pre-pure}
we say a diagram (\ref{equation-impurity}) defines an
{\it impurity of $\mathcal{F}$ above $s$}
if $\xi \in \text{Ass}_{X_T/T}(\mathcal{F}_T)$ and
$\overline{\{\xi\}} \cap X_t = \emptyset$. We will indicate
this by saying ``let $(g : T \to S, t' \leadsto t, \xi)$ be
an impurity of $\mathcal{F}$ above $s$''.

\label{lemma-proper-pure}
Let $f : X \to S$ be a morphism of schemes which is of finite type.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If the support of $\mathcal{F}$ is proper over $S$, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then $X$ is universally pure relative to $S$.
\end{enumerate}

\label{lemma-free-at-generic-points}
In Situation \ref{situation-free-at-generic-points}.
\begin{enumerate}
\item The functor $H_p$ satisfies the sheaf property for the fpqc topology.
\item If $\mathcal{F}$ is of finite presentation, then functor $H_p$ is
limit preserving.
\end{enumerate}

\label{definition-flat-dimension-n}
Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module of finite type.
Let $n \geq 0$.
We say {\it $\mathcal{F}$ is flat over $S$ in dimensions $\geq n$}
if the equivalent conditions of Lemma \ref{lemma-pre-flat-dimension-n}
are satisfied.

\label{lemma-flat-dimension-n}
In Situation \ref{situation-flat-dimension-n}.
\begin{enumerate}
\item The functor $F_n$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor $F_n$ is
limit preserving.
\end{enumerate}

\label{lemma-flat}
In Situation \ref{situation-flat}.
\begin{enumerate}
\item The functor $F_{flat}$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor
$F_{flat}$ is limit preserving.
\end{enumerate}

\label{definition-flattening}
Let $X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
We say that the {\it universal flattening of $\mathcal{F}$ exists}
if the functor $F_{flat}$ defined in Situation \ref{situation-flat}
is representable by a scheme $S'$ over $S$.
We say that the {\it universal flattening of $X$ exists}
if the universal flattening of $\mathcal{O}_X$ exists.

\label{definition-flattening-stratification}
Let $X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
We say that $\mathcal{F}$ has a {\it flattening stratification}
if the functor $F_{flat}$ defined in Situation \ref{situation-flat}
is representable by a monomorphism $S' \to S$ associated
to a stratification of $S$ by locally closed subschemes.
We say that $X$ has a {\it flattening stratification}
if $\mathcal{O}_X$ has a flattening stratification.

\label{lemma-flattening-module-map}
Let $A$ be a ring. Let $u : M \to N$ be a surjective map of $A$-modules.
If $M$ is projective as an $A$-module, then there exists an ideal
$I \subset A$ such that for any ring map $\varphi : A \to B$
the following are equivalent
\begin{enumerate}
\item $u \otimes 1 : M \otimes_A B \to N \otimes_A B$ is an
isomorphism, and
\item $\varphi(I) = 0$.
\end{enumerate}

\label{theorem-flattening-map}
In
Situation \ref{situation-iso}
assume
\begin{enumerate}
\item $f$ is of finite presentation,
\item $\mathcal{F}$ is of finite presentation, flat over $S$, and
pure relative to $S$, and
\item $u$ is surjective.
\end{enumerate}
Then $F_{iso}$ is representable by a closed immersion $Z \to S$.
Moreover $Z \to S$ is of finite presentation if $\mathcal{G}$ is
of finite presentation.

\label{lemma-Noetherian-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is Noetherian
then the lemma holds.

\label{lemma-henselian-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is henselian
then the lemma holds.

\label{lemma-valuation-ring-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is a
valuation ring then the lemma holds.

\label{lemma-properties-pure-spreadout}
In (\ref{equation-star}) if there exists a pure spreadout, then
\begin{enumerate}
\item elements of $N$ have content ideals in $A$, and
\item if $u : N \to M$ is a morphism to a flat $A$-module $M$
such that $N/\mathfrak m N \to M/\mathfrak m M$ is injective
for all maximal ideals $\mathfrak m$ of $A$, then $u$ is
$A$-universally injective.
\end{enumerate}

\label{lemma-make-smaller-flatness-ideal}
Let $A$ be a local ring. Let $I \subset A$ be an ideal.
Let $U \subset \Spec(A)$ be quasi-compact open.
Let $M$ be an $A$-module. Assume that
\begin{enumerate}
\item $M/IM$ is flat over $A/I$,
\item $M$ is flat over $U$,
\end{enumerate}
Then $M/I_2M$ is flat over $A/I_2$ where
$I_2 = \Ker(I \to \Gamma(U, I/I^2))$.

\label{theorem-check-flatness-at-associated-points}
Let $f : X \to S$ be locally of finite type.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module of finite type.
Let $x \in X$ with image $s \in S$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is flat at $x$ over $S$, and
\item for every $x' \in \text{Ass}_{X_s}(\mathcal{F}_s)$ which
specializes to $x$ we have that $\mathcal{F}$ is flat at $x'$ over $S$.
\end{enumerate}

\label{lemma-check-along-closed-fibre}
Let $S$ be a local scheme with closed point $s$.
Let $f : X \to S$ be locally of finite type.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_X$-module.
Assume that
\begin{enumerate}
\item every point of $\text{Ass}_{X/S}(\mathcal{F})$ specializes
to a point of the closed fibre $X_s$\footnote{For example this holds if
$f$ is finite type and $\mathcal{F}$ is pure along $X_s$, or
if $f$ is proper.},
\item $\mathcal{F}$ is flat over $S$ at every point of $X_s$.
\end{enumerate}
Then $\mathcal{F}$ is flat over $S$.

[Derived Grothendieck Existence Theorem]
\label{theorem-existence-derived}
In Situation \ref{situation-existence-derived}
there exists a pseudo-coherent $K$ in $D(\mathcal{O}_X)$
such that $K_n = K \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{O}_{X_n}$
for all $n$ compatibly with the maps $\varphi_n$.

\label{theorem-nagata}
\begin{reference}
See \cite{Lutkebohmert}, \cite{Conrad-Nagata}, \cite{Nagata-1},
\cite{Nagata-2}, \cite{Nagata-3}, and \cite{Nagata-4}
\end{reference}
Let $S$ be a quasi-compact and quasi-separated scheme. Let
$X \to S$ be a separated, finite type morphism.
Then $X$ has a compactification over $S$.

\label{lemma-equivalence-h-v-locally-finite-presentation}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms
of schemes with fixed target with $f_i$ locally of finite
presentation for all $i$. The following are equivalent
\begin{enumerate}
\item $\{X_i \to X\}$ is a ph covering, and
\item $\{X_i \to X\}$ is a V covering.
\end{enumerate}

\label{lemma-Noetherian-h-covering}
Let $X$ be a Noetherian scheme. Let $\{X_i \to X\}_{i \in I}$
be a finite family of finite type morphisms. The following are equivalent
\begin{enumerate}
\item $\coprod_{i \in I} X_i \to X$ is universally submersive
(Morphisms, Definition
\ref{morphisms-definition-submersive}), and
\item $\{X_i \to X\}_{i \in I}$ is an h covering.
\end{enumerate}

\label{lemma-zariski-h}
An fppf covering is a h covering. Hence syntomic, smooth, \'etale,
and Zariski coverings are h coverings as well.

\label{lemma-surjective-proper-finite-presentation-h}
Let $f : Y \to X$ be a surjective proper morphism of schemes
which is of finite presentation. Then $\{Y \to X\}$ is an h covering.

\label{lemma-refine-by-h}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms such that $f_i$ is locally of finite presentation for all $i$.
The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is an h covering,
\item there is an h covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is an h covering.
\end{enumerate}

\label{lemma-verify-site-h}
Let $S$ be a scheme. Let $\Sch_h$ be a big h
site containing $S$. Then $(\textit{Aff}/S)_h$ is a site.

\label{lemma-characterize-sheaf-h}
Let $\mathcal{F}$ be a presheaf on $(\Sch/S)_h$.
Then $\mathcal{F}$ is a sheaf if and only if
\begin{enumerate}
\item $\mathcal{F}$ satisfies the sheaf condition for
Zariski coverings, and
\item if $f : V \to U$ is proper, surjective, and of finite presentation, then
$\mathcal{F}(U)$ maps bijectively to the equalizer
of the two maps $\mathcal{F}(V) \to \mathcal{F}(V \times_U V)$.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to
property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$ as in (2) with $U$ affine.
\end{enumerate}

\label{lemma-base-change-almost-blow-up}
Consider an almost blow up square (\ref{equation-almost-blow-up-square}).
Let $Y \to X$ be any morphism. Then the base change
$$
\xymatrix{
Y \times_X E \ar[d] \ar[r] & Y \times_X X' \ar[d] \\
Y \times_X Z \ar[r] & Y
}
$$
is an almost blow up square too.

\label{lemma-perfect-weankly-normal}
Let $p$ be a prime number. An $\mathbf{F}_p$-algebra $A$ is
absolutely weakly normal if and only if it is perfect.

\label{lemma-char-p}
Let $p$ be a prime number.
\begin{enumerate}
\item If $A$ is an $\mathbf{F}_p$-algebra, then $\colim_F A = A^{awn}$.
\item If $S$ is a scheme over $\mathbf{F}_p$, then the
h sheafification of $\mathcal{O}$ sends a quasi-compact
and quasi-separated $X$ to $\colim_F \Gamma(X, \mathcal{O}_X)$.
\end{enumerate}

\label{lemma-factor-small-extension}
Let $f: B \to A$ be a surjective ring map in $\mathcal{C}_\Lambda$.
Then $f$ can be factored as a composition of small extensions.

\label{lemma-surjective}
Let $A \to B$ be a ring map in $\mathcal{C}_\Lambda$.
The following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $\mathfrak m_A/\mathfrak m_A^2 \to \mathfrak m_B/\mathfrak m_B^2$
is surjective, and
\item $\mathfrak m_A/(\mathfrak m_\Lambda A + \mathfrak m_A^2)
\to \mathfrak m_B/(\mathfrak m_\Lambda B + \mathfrak m_B^2)$ is surjective.
\end{enumerate}

\label{definition-essential-surjection}
Let $f: B \to A$ be a ring map in $\mathcal{C}_\Lambda$.  We say $f$
is an {\it essential surjection} if it has the following properties:
\begin{enumerate}
\item $f$ is surjective.
\item If $g: C \to B$ is a ring map in $\mathcal{C}_\Lambda$ such that
$f \circ g$ is surjective, then $g$ is surjective.
\end{enumerate}

\label{definition-completion-CLambda}
Let $\Lambda$ be a Noetherian ring and let $\Lambda \to k$ be a finite
ring map where $k$ is a field. We define {\it $\widehat{\mathcal{C}}_\Lambda$}
to be the category with
\begin{enumerate}
\item objects are pairs $(R, \varphi)$ where $R$ is a Noetherian complete
local $\Lambda$-algebra and where $\varphi : R/\mathfrak m_R \to k$ is a
$\Lambda$-algebra isomorphism, and
\item morphisms $f : (S, \psi) \to (R, \varphi)$ are local $\Lambda$-algebra
homomorphisms such that $\varphi \circ (f \bmod \mathfrak m) = \psi$.
\end{enumerate}

\label{lemma-CLambdahat-coproducts}
The category $\widehat{\mathcal{C}}_\Lambda$ admits coproducts
of pairs of objects.

\label{lemma-derivations-finite}
Let $S$ be an object of $\widehat{\mathcal{C}}_\Lambda$.
Then $\dim_k \text{Der}_\Lambda(S, k) < \infty$.

\label{lemma-formal-objects-different-filtration}
In the situation above, $\widehat{\mathcal{F}}_\mathcal{I}(R)$ is equivalent
to the category $\widehat{\mathcal{F}}(R)$.

\label{lemma-smooth-properties}
Let $\varphi : \mathcal{F} \to \mathcal{G}$ and $\psi : \mathcal{G}
\to \mathcal{H}$ be morphisms of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$.
\begin{enumerate}
\item If $\varphi$ and $\psi$ are smooth, then $\psi \circ \varphi$ is smooth.
\item If $\varphi$ is essentially surjective and $\psi \circ \varphi$ is
smooth, then $\psi$ is smooth.
\item If $\mathcal{G}' \to \mathcal{G}$ is a morphism of categories
cofibered in groupoids and $\varphi$ is smooth, then
$\mathcal{F} \times_\mathcal{G} \mathcal{G}' \to \mathcal{G}'$ is smooth.
\end{enumerate}

\label{definition-cofibered-groupoid-projection-smooth}
Let $p : \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. We say $\mathcal{F}$ is {\it smooth} or {\it unobstructed}
if its structure morphism $p$ is smooth
in the sense of Definition \ref{definition-smooth-morphism}.

\label{lemma-smooth}
Let $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\underline{R}|_{\mathcal{C}_\Lambda}$ is smooth,
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology,
\item $\Lambda \to R$ is flat and $R \otimes_\Lambda k'$ is
geometrically regular over $k'$, and
\item $\Lambda \to R$ is flat and $k' \to R \otimes_\Lambda k'$ is
formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case, these are also equivalent to
\begin{enumerate}
\item[(5)] $R$ is isomorphic to $\Lambda[[x_1, \ldots, x_n]]$
for some $n$.
\end{enumerate}

\label{lemma-smooth-power-series-classical}
Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ lying over
$R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{F}$ is unobstructed, and
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case these are also equivalent to
\begin{enumerate}
\item[(3)] $R \cong \Lambda[[x_1, \ldots, x_n]]$ for some $n$.\
\end{enumerate}

\label{lemma-exists-smooth}
There exists an $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$
such that the equivalent conditions of Lemma \ref{lemma-smooth}
hold and moreover $H_1(L_{k/\Lambda}) = \mathfrak m_R/\mathfrak m_R^2$
and $\Omega_{R/\Lambda} \otimes_R k = \Omega_{k/\Lambda}$.

\label{definition-S1-S2}
Let $\mathcal{F}$ be a category cofibered in groupoids over $\mathcal
C_\Lambda$. We define {\it conditions (S1) and (S2)}
on $\mathcal{F}$ as follows:
\begin{enumerate}
\item[(S1)] Every diagram in $\mathcal{F}$
$$
\vcenter{
\xymatrix{
           & x_2 \ar[d] \\
x_1 \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
           & A_2 \ar[d] \\
A_1 \ar[r] & A
}
}
$$
in $\mathcal{C}_\Lambda$ with $A_2 \to A$ surjective can be completed
to a commutative diagram
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d] & x_2 \ar[d] \\
x_1 \ar[r]      & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d] \\
A_1 \ar[r]      & A.
}
}
$$
\item[(S2)]
The condition of (S1) holds for diagrams in $\mathcal{F}$ lying over
a diagram in $\mathcal{C}_\Lambda$ of the form
$$
\xymatrix{
          & k[\epsilon] \ar[d] \\
A  \ar[r] & k.
}
$$
Moreover, if we have two commutative diagrams in $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r]_c \ar[d]_a & x_\epsilon \ar[d]^e \\
x \ar[r]^d          & x_0
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
y' \ar[r]_{c'} \ar[d]_{a'} & x_\epsilon \ar[d]^e \\
x \ar[r]^d                 & x_0
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A \times_k k[\epsilon] \ar[r] \ar[d] & k[\epsilon] \ar[d] \\
A  \ar[r] & k
}
}
$$
then there exists a morphism $b : y \to y'$ in
$\mathcal{F}(A \times_k k[\epsilon])$ such that $a = a' \circ b$.
\end{enumerate}

\label{lemma-S1-S2-localize}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$. Let $x_0 \in \Ob(\mathcal{F}(k))$.
Let $\mathcal{F}_{x_0}$ be the category cofibred in groupoids over
$\mathcal{C}_\Lambda$ constructed in
Remark \ref{remark-localize-cofibered-groupoid}.
\begin{enumerate}
\item If $\mathcal{F}$ satisfies (S1), then so does $\mathcal{F}_{x_0}$.
\item If $\mathcal{F}$ satisfies (S2), then so does $\mathcal{F}_{x_0}$.
\end{enumerate}

\label{lemma-lifting-section}
Let $p: \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. Consider a diagram of $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d]_a & x_\epsilon \ar[d]_e \\
x \ar[r]^d        & x_0
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A \times_k k[\epsilon] \ar[r] \ar[d] & k[\epsilon] \ar[d] \\
A \ar[r] & k.
}
}
$$
in $\mathcal{C}_\Lambda$. Assume $\mathcal{F}$ satisfies (S2).
Then there exists a morphism $s : x \to y$ with $a \circ s = \text{id}_x$
if and only if there exists a morphism $s_\epsilon : x \to x_\epsilon$
with $e \circ s_\epsilon = d$.

\label{lemma-lifting-along-small-extension}
Consider a commutative diagram in a predeformation category $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d] & x_2 \ar[d]^{a_2} \\
x_1 \ar[r]^{a_1}        & x
}
}
\quad\text{lying over}
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d]^{f_2} \\
A_1 \ar[r]^{f_1} & A
}
}
$$
in $\mathcal{C}_\Lambda$ where
$f_2 : A_2 \to A$ is a small extension.
Assume there is a map $h : A_1 \to A_2$ such that $f_2 = f_1 \circ h$.
Let $I = \Ker(f_2)$. Consider the ring map
$$
g : A_1 \times_A A_2 \longrightarrow k[I] = k \oplus I, \quad
(u, v) \longmapsto \overline{u} \oplus (v - h(u))
$$
Choose a pushforward $y \to g_*y$. Assume $\mathcal{F}$ satisfies (S2).
If there exists a morphism $x_1 \to g_*y$, then there exists a
morphism $b: x_1 \to x_2$ such that $a_1 =  a_2 \circ b$.

\label{lemma-linear-functor}
Let $L: \text{Mod}^{fg}_R \to \textit{Sets}$,
resp.\ $L: \text{Mod}_R \to \textit{Sets}$ be a
functor.  Suppose $L(0)$ is a one element set and $L$ preserves finite
products.  Then there exists a unique $R$-linear functor
$\widetilde{L} : \text{Mod}^{fg}_R \to \text{Mod}_R$,
resp.\  $\widetilde{L} : \text{Mod}_R \to \text{Mod}_R$,
such that
$$
\vcenter{
\xymatrix{
& \text{Mod}_R \ar[dr]^{\text{forget}} &   \\
\text{Mod}^{fg}_R  \ar[ur]^{\widetilde{L}} \ar[rr]^{L} &  &
\textit{Sets}
}
}
\quad\text{resp.}\quad
\vcenter{
\xymatrix{
& \text{Mod}_R \ar[dr]^{\text{forget}} &   \\
\text{Mod}_R  \ar[ur]^{\widetilde{L}} \ar[rr]^{L} &  &
\textit{Sets}
}
}
$$
commutes.

\label{lemma-preserves-products}
Let $R$ be an $S$-algebra. Then the functor
$\text{Mod}_R \to S\text{-Alg}/R$ described above preserves finite products.

\label{definition-tangent-space}
Let $\mathcal{F}$ be a predeformation category.
The {\it tangent space $T \mathcal{F}$ of $\mathcal{F}$}
is the set $\overline{\mathcal{F}}(k[\epsilon])$
of isomorphism classes of objects in the fiber category $\mathcal
F(k[\epsilon])$.

\label{lemma-versal-criterion}
Let $\mathcal{F}$ be a predeformation category satisfying (S1) and
(S2). Let $\xi$ be a formal object of $\mathcal{F}$ corresponding to
$\underline{\xi} : \underline{R}|_{\mathcal{C}_\Lambda} \to \mathcal{F}$, see
Remark \ref{remark-formal-objects-yoneda}.
Then $\xi$ is versal if and only if the following two conditions hold:
\begin{enumerate}
\item the map
$d\underline{\xi} : T\underline{R}|_{\mathcal{C}_\Lambda} \to T\mathcal{F}$
on tangent spaces is surjective, and
\item given a diagram in $\widehat{\mathcal{F}}$
$$
\vcenter{
\xymatrix{
            &  y \ar[d] \\
\xi \ar[r]  &  x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[r] &   A
}
}
$$
in $\widehat{\mathcal{C}}_\Lambda$ with $B \to A$ a small extension of
Artinian rings, then there exists a ring map $R \to B$ such that
$$
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[ur] \ar[r] &   A
}
$$
commutes.
\end{enumerate}

\label{lemma-versal-object-existence}
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$. Assume the following conditions hold:
\begin{enumerate}
\item $\mathcal{F}$ is a predeformation category.
\item $\mathcal{F}$ satisfies (S1).
\item $\mathcal{F}$ satisfies (S2).
\item $\dim_k T\mathcal{F}$ is finite.
\end{enumerate}
Then $\mathcal{F}$ has a versal formal object.

\label{lemma-smallest-where-descends-versal}
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$ which has (S1). Let $\xi$ be a versal formal object
of $\mathcal{F}$ lying over $R$. There exists a morphism $\xi' \to \xi$
lying over $R' \subset R$ with the following minimality properties
\begin{enumerate}
\item for every $f : R \to A$ with $A \in \Ob(\mathcal{C}_\Lambda)$
the pushforwards
$$
\vcenter{
\xymatrix{
\xi' \ar[d] \ar[r] & x' \ar[d] \\
\xi \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
R' \ar[d] \ar[r] & f(R') \ar[d] \\
R \ar[r] & A
}
}
$$
produce a minimal object $x' \to x$ of $\mathcal{S}_x$, and
\item for any morphism of formal objects $\xi'' \to \xi'$
the corresponding morphism $R'' \to R'$ is surjective.
\end{enumerate}

\label{lemma-minimal-versal}
Let $\mathcal{F}$ be a predeformation category which
has a versal formal object. Then
\begin{enumerate}
\item $\mathcal{F}$ has a minimal versal formal object,
\item minimal versal objects are unique up to isomorphism, and
\item any versal object is the pushforward of a minimal versal
object along a power series ring extension.
\end{enumerate}

\label{lemma-miniversal-object-existence-1}
Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ such that
(\ref{equation-bijective}) holds. Then
\begin{enumerate}
\item $\mathcal{F}$ satisfies (S1).
\item $\mathcal{F}$ satisfies (S2).
\item $\dim_k T\mathcal{F}$ is finite.
\end{enumerate}

\label{definition-RS}
Let $\mathcal{F}$ be a category cofibered in groupoids over $\mathcal
C_\Lambda$.  We say that $\mathcal{F}$ satisfies {\it condition (RS)}
if for every diagram in $\mathcal{F}$
$$
\vcenter{
\xymatrix{
           & x_2 \ar[d] \\
x_1 \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
           & A_2 \ar[d] \\
A_1 \ar[r] & A
}
}
$$
in $\mathcal{C}_\Lambda$ with $A_2 \to A$ surjective, there exists a
fiber product $x_1 \times_x x_2$ in $\mathcal{F}$ such that the diagram
$$
\vcenter{
\xymatrix{
x_1 \times_x x_2 \ar[r] \ar[d] & x_2 \ar[d] \\
x_1 \ar[r]      & x
}
}
\quad\text{lies over}\quad
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d] \\
A_1 \ar[r]      & A.
}
}
$$

\label{lemma-RS-fiber-square}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$ satisfying (RS). Given a commutative diagram
in $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d] & x_2 \ar[d]   \\
x_1 \ar[r]      & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d] \\
A_1 \ar[r]      & A.
}
}
$$
with $A_2 \to A$ surjective, then it is a fiber square.

\label{lemma-RS-fiber-product-morphisms}
Let
$$
\xymatrix{
\mathcal{H} \times_\mathcal{F} \mathcal{G} \ar[r] \ar[d] &
\mathcal{G} \ar[d]^g \\
\mathcal{H} \ar[r]^f & \mathcal{F}
}
$$
be $2$-fibre product of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$. If $\mathcal{F}, \mathcal{G}, \mathcal{H}$
all satisfy (RS), then $\mathcal{H} \times_\mathcal{F} \mathcal{G}$
satisfies (RS).

\label{lemma-map-between-smooth}
Let $\mathcal{F} \to \mathcal{G} \to \mathcal{H}$ be maps of categories
cofibred in groupoids over $\mathcal{C}_\Lambda$. If
\begin{enumerate}
\item $\mathcal{F}$, $\mathcal{G}$ are deformation categories
\item the map $T\mathcal{F} \to T\mathcal{G}$ is surjective, and
\item $\mathcal{F} \to \mathcal{H}$ is smooth.
\end{enumerate}
Then $\mathcal{F} \to \mathcal{G}$ is smooth.

\label{definition-quotient}
Let $(U, R, s, t, c)$ be a groupoid in functors on a category $\mathcal{C}$.
\begin{enumerate}
\item The assignment $T \mapsto  (U(T), R(T), s, t, c)$ determines a functor
$\mathcal{C} \to \textit{Groupoids}$. The {\it quotient category
cofibered in groupoids $[U/R] \to \mathcal{C}$} is the category
cofibered in groupoids over $\mathcal{C}$ associated to this functor (as in
Remarks \ref{remarks-cofibered-groupoids}
(\ref{item-construction-associated-cofibered-groupoid})).
\item The {\it quotient morphism $U \to [U/R]$} is the morphism of
categories cofibered in groupoids over $\mathcal{C}$ defined by the
rules
\begin{enumerate}
\item $x \in U(T)$ maps to the object $(T, x) \in \Ob([U/R](T))$, and
\item $x \in U(T)$ and $f : T \to T'$ give rise to the morphism
$(f, \text{id}_{U(f)(x)}): (T, x) \to (T, U(f)(x))$ lying over
$f : T \to T'$.
\end{enumerate}
\end{enumerate}

\label{lemma-groupoid-in-functors-prorep-equivalences}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is prorepresentable if and only if its completion is
representable as a groupoid in functors on $\widehat{\mathcal{C}}_\Lambda$.
\item $(U, R, s, t, c)$ is prorepresentable if and only if $U$ and $R$ are
prorepresentable.
\end{enumerate}

\label{definition-smooth-groupoid-in-functors}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$. We
say $(U, R, s, t, c)$ is {\it smooth} if $s, t: R \to U$ are smooth.

\label{lemma-smooth-quotient-morphism}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$.
The following are equivalent:
\begin{enumerate}
\item The groupoid in functors $(U, R, s, t, c)$ is smooth.
\item The morphism $s : R \to U$ is smooth.
\item The morphism $t : R \to U$ is smooth.
\item The quotient morphism $U \to [U/R]$ is smooth.
\end{enumerate}

\label{lemma-smooth-RS-groupoid-in-functors-quotient}
Let $(U, R, s, t, c)$ be a smooth groupoid in functors on $\mathcal{C}_\Lambda$.
Assume $U$ and $R$ satisfy (RS). Then $[U/R]$ satisfies (RS).

\label{theorem-presentation-deformation-groupoid}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$. Then $\mathcal{F}$ admits a presentation by a
smooth prorepresentable groupoid in functors on $\mathcal{C}_\Lambda$
if and only if the following conditions hold:
\begin{enumerate}
\item $\mathcal{F}$ is a deformation category.
\item $\dim_k T\mathcal{F}$ is finite.
\item $\dim_k \text{Inf}(\mathcal{F})$ is finite.
\end{enumerate}

\label{definition-minimal-groupoid-in-functors}
Let $(U, R, s, t, c)$ be a smooth prorepresentable groupoid in functors
on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item We say $(U, R, s, t, c)$ is {\it normalized} if the groupoid
$(U(k[\epsilon]), R(k[\epsilon]), s, t, c)$ is totally disconnected,
i.e., there are no morphisms between distinct objects.
\item We say $(U, R, s, t, c)$ is {\it minimal} if the $U \to [U/R]$
is given by a minimal versal formal object of $[U/R]$.
\end{enumerate}

\label{lemma-characterize-minimal-groupoid-in-functors}
Let $(U, R, s, t, c)$ be a smooth prorepresentable groupoid in
functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is normalized if and only if the morphism
$U \to [U/R]$ induces an isomorphism on tangent spaces, and
\item $(U, R, s, t, c)$ is minimal if and only if the kernel of
$TU \to T[U/R]$ is contained in the image of
$\text{Der}_\Lambda(k, k) \to TU$.
\end{enumerate}

\label{lemma-homotopy}
Being formally homotopic is an equivalence relation on
sets of morphisms in $\widehat{\mathcal{C}}_\Lambda$.

\label{lemma-formal-scheme-sheaf-fppf}
\begin{slogan}
Formal schemes are fpqc sheaves
\end{slogan}
Let $\mathfrak X$ be a formal scheme. The functor of points
$h_\mathfrak X$ (see Lemma \ref{lemma-fully-faithful})
satisfies the sheaf condition for fpqc coverings.

\label{lemma-closure}
Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge$ is exact, and
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$.
\end{enumerate}

\label{lemma-ses}
\begin{reference}
\cite[Theorem 8.1]{Ma}
\end{reference}
Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Assume $M$ has a
countable fundamental system of neighbourhoods of $0$. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge \to 0$ is exact,
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$,
\item $M^\wedge \to (M/N)^\wedge$ is open.
\end{enumerate}

\label{definition-weakly-admissible}
Let $A$ be a linearly topologized ring.
\begin{enumerate}
\item An element $f \in A$ is called {\it topologically nilpotent}
if $f^n \to 0$ as $n \to \infty$.
\item A {\it weak ideal of definition} for $A$ is an open ideal
$I \subset A$ consisting entirely of topologically nilpotent elements.
\item We say $A$ is {\it weakly pre-admissible} if $A$ has a weak
ideal of definition.
\item We say $A$ is {\it weakly admissible} if $A$ is weakly pre-admissible
and complete\footnote{By our conventions this includes separated.}.
\end{enumerate}

\label{lemma-weakly-admissible-henselian}
Let $A$ be a weakly admissible topological ring. Let $I \subset A$
be a weak ideal of definition. Then $(A, I)$ is a henselian pair.

\label{lemma-taut-weakly-admissible}
Let $\varphi : A \to B$ be a continuous map of weakly admissible topological
rings. The following are equivalent
\begin{enumerate}
\item $\varphi$ is taut,
\item for every weak ideal of definition $I \subset A$ the closure of
$\varphi(I)B$ is a weak ideal of definition of $B$ and these form a
fundamental system of weak ideals of definition of $B$.
\end{enumerate}

\label{lemma-completion-taut}
Let $A$ be a linearly topologized ring. The map $A \to A^\wedge$
from $A$ to its completion is taut.

\label{definition-adic-homomorphism}
Let $A$ and $B$ be pre-adic topological rings. A ring homomorphism
$\varphi : A \to B$ is {\it adic}\footnote{This may be nonstandard terminology.}
if there exists an ideal of definition $I \subset A$ such that
the topology on $B$ is the $I$-adic topology.

\label{lemma-adic-taut}
Let $\varphi : A \to B$ be a continuous homomorphism between
pre-adic topological rings. If $\varphi$ is adic, then $\varphi$ is taut.

\label{definition-weakly-adic}
\begin{reference}
\cite[Definition 8.3.8]{Gabber-Ramero}
\end{reference}
Let $A$ be a linearly topologized ring.
\begin{enumerate}
\item We say $A$ is {\it weakly pre-adic}\footnote{In \cite{Gabber-Ramero} the
authors say $A$ is {\it $c$-adic}.} if there exists an ideal
$I \subset A$ such that the closure of $I^n$ is open for all $n \geq 0$
and these closures form a fundamental system of open ideals.
\item We say $A$ is {\it weakly adic} if $A$ is weakly pre-adic
and complete\footnote{By our conventions this includes separated.}.
\end{enumerate}

\label{lemma-taut-descent-countable}
In the situation above, if $B$ has a countable fundamental system of
open ideals, then $A$ has a countable fundamental system of open ideals.

\label{lemma-taut-descent-weakly-admissible}
In the situation above, if $B$ is weakly pre-admissible, then
$A$ is weakly pre-admissible.

\label{lemma-taut-descent-admissible}
In the situation above, if $B$ is pre-admissible, then $A$
is pre-admissible.

\label{lemma-taut-descent-weakly-adic}
In the situation above, if $B$ is weakly pre-adic, then $A$
is weakly pre-adic.

\label{definition-affine-formal-algebraic-space}
Let $S$ be a scheme. We say a sheaf $X$ on $(\Sch/S)_{fppf}$ is an
{\it affine formal algebraic space} if there exist
\begin{enumerate}
\item a directed set $\Lambda$,
\item a system $(X_\lambda, f_{\lambda \mu})$ over $\Lambda$
in $(\Sch/S)_{fppf}$ where
\begin{enumerate}
\item each $X_\lambda$ is affine,
\item each $f_{\lambda \mu} : X_\lambda \to X_\mu$ is a thickening,
\end{enumerate}
\end{enumerate}
such that
$$
X \cong \colim_{\lambda \in \Lambda} X_\lambda
$$
as fppf sheaves and $X$ satisfies a set theoretic condition
(see Remark \ref{remark-set-theoretic}). A
{\it morphism of affine formal algebraic spaces}
over $S$ is a map of sheaves.

\label{lemma-characterize-affine-formal-algebraic-space}
Let $S$ be a scheme. Let $X$ be a sheaf on $(\Sch/S)_{fppf}$.
Then $X$ is an affine formal algebraic space if and only if
the following hold
\begin{enumerate}
\item any morphism $U \to X$ where $U$ is an affine scheme over $S$
factors through a morphism $T \to X$ which is representable and a
thickening with $T$ an affine scheme over $S$, and
\item a set theoretic condition as in Remark \ref{remark-set-theoretic}.
\end{enumerate}

\label{lemma-countable-affine-formal-algebraic-space}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item there exists a system $X_1 \to X_2 \to X_3 \to \ldots$
of thickenings of affine schemes over $S$ such that $X = \colim X_n$,
\item there exists a choice $X = \colim X_\lambda$ as in
Definition \ref{definition-affine-formal-algebraic-space}
such that $\Lambda$ is countable.
\end{enumerate}

\label{lemma-implications-between-types}
Let $X$ be an affine formal algebraic space over a scheme $S$.
\begin{enumerate}
\item If $X$ is Noetherian, then $X$ is adic*.
\item If $X$ is adic*, then $X$ is adic.
\item If $X$ is adic, then $X$ is weakly adic.
\item If $X$ is weakly adic, then $X$ is classical.
\item If $X$ is weakly adic, then $X$ is countably indexed.
\item If $X$ is countably indexed, then $X$ is McQuillan.
\end{enumerate}

\label{lemma-characterize-noetherian-affine}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space.
The following are equivalent
\begin{enumerate}
\item $X$ is Noetherian,
\item $X$ is adic* and for every closed immersion $T \to X$ with $T$ a scheme,
$T$ is Noetherian,
\item $X$ is adic* and for some choice of $X = \colim X_\lambda$ as in
Definition \ref{definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian, and
\item $X$ is weakly adic and for some choice $X = \colim X_\lambda$
as in Definition \ref{definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian.
\end{enumerate}

\label{definition-formal-algebraic-space}
Let $S$ be a scheme. We say a sheaf $X$ on $(\Sch/S)_{fppf}$ is a
{\it formal algebraic space} if there exist a family of maps
$\{X_i \to X\}_{i \in I}$ of sheaves such that
\begin{enumerate}
\item $X_i$ is an affine formal algebraic space,
\item $X_i \to X$ is representable by algebraic spaces and \'etale,
\item $\coprod X_i \to X$ is surjective as a map of sheaves
\end{enumerate}
and $X$ satisfies a set theoretic condition
(see Remark \ref{remark-set-theoretic}). A
{\it morphism of formal algebraic spaces}
over $S$ is a map of sheaves.

\label{definition-completion}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. The formal algebraic space
of Lemma \ref{lemma-completion-is-formal-algebraic-space}
is called the {\it completion of $X$ along $T$}.

\label{lemma-completion-countably-indexed}
\begin{reference}
Email by Ofer Gabber of September 11, 2014.
\end{reference}
Let $S$ be a scheme. Let $X = \Spec(A)$ be an affine scheme over $S$.
Let $T \subset X$ be a closed subscheme.
\begin{enumerate}
\item If the formal completion $X_{/T}$ is countably indexed
and there exist countably many $f_1, f_2, f_3, \ldots \in A$ such that
$T = V(f_1, f_2, f_3, \ldots)$, then $X_{/T}$ is adic*.
\item The conclusion of (1) is wrong if we omit the assumption that
$T$ can be cut out by countably many functions in $X$.
\end{enumerate}

\label{lemma-fibre-products}
Let $S$ be a scheme. The category of formal algebraic spaces over $S$
has fibre products.

\label{definition-separated}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$.
We say
\begin{enumerate}
\item $X$ is {\it quasi-separated} if the equivalent conditions of
Lemma \ref{lemma-characterize-quasi-separated} are satisfied.
\item $X$ is {\it separated} if the equivalent conditions of
Lemma \ref{lemma-characterize-separated} are satisfied.
\end{enumerate}

\label{lemma-structure-quasi-compact-quasi-separated}
\begin{reference}
\cite[Proposition 3.32]{Yasuda}
\end{reference}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
formal algebraic space over $S$. Then $X = \colim X_\lambda$
for a system of algebraic spaces $(X_\lambda, f_{\lambda \mu})$
over a directed set $\Lambda$ where each
$f_{\lambda \mu} : X_\lambda \to X_\mu$ is a thickening.

\label{lemma-type-local}
Let $S$ be a scheme. Let
$$
P \in
\left\{
\begin{matrix}
countably\ indexed,\\
countably\ indexed\ and\ classical,\\
weakly\ adic,\ adic*,\ Noetherian
\end{matrix}
\right\}
$$
Let $X$ be a formal algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item if $Y$ is an affine formal algebraic space and
$f : Y \to X$ is representable by algebraic spaces and \'etale,
then $Y$ has property $P$,
\item for some $\{X_i \to X\}_{i \in I}$ as in
Definition \ref{definition-formal-algebraic-space}
each $X_i$ has property $P$.
\end{enumerate}

\label{definition-types-formal-algebraic-spaces}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$.
We say $X$ is
{\it locally countably indexed},
{\it locally countably indexed and classical},
{\it locally weakly adic},
{\it locally adic*}, or
{\it locally Noetherian}
if the equivalent conditions of Lemma \ref{lemma-type-local}
hold for the corresponding property.

\label{lemma-formal-completion-types}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $X_{/T}$ be the
formal completion of $X$ along $T$.
\begin{enumerate}
\item If $X \setminus T \to X$ is quasi-compact,
then $X_{/T}$ is locally adic*.
\item If $X$ is locally Noetherian, then $X_{/T}$ is locally
Noetherian.
\end{enumerate}

\label{lemma-adic-homomorphism}
Let $A$ and $B$ be pre-adic topological rings. Let
$\varphi : A \to B$ be a continuous ring homomorphism.
\begin{enumerate}
\item If $\varphi$ is adic, then $\varphi$ is taut.
\item If $B$ is complete, $A$ has a finitely generated
ideal of definition, and $\varphi$ is taut, then $\varphi$ is adic.
\end{enumerate}
In particular the conditions ``$\varphi$ is adic'' and ``$\varphi$ is taut''
are equivalent on the category $\textit{WAdm}^{adic*}$.

\label{definition-finite-type}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of formal algebraic
spaces over $S$.
\begin{enumerate}
\item We say $f$ is {\it locally of finite type}
if $f$ is representable by algebraic spaces and is locally
of finite type in the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.
\item We say $f$ is of {\it finite type} if $f$ is locally of finite type and
quasi-compact (Definition \ref{definition-quasi-compact-morphism}).
\end{enumerate}

\label{lemma-characterize-finite-type}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of formal algebraic
spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is of finite type,
\item $f$ is representable by algebraic spaces and is of finite type in
the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.
\end{enumerate}

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{definition-closed-immersion}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of formal algebraic
spaces over $S$. We say $f$ is a {\it closed immersion}
if $f$ is representable by algebraic spaces and a closed immersion
in the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.

\label{lemma-monomorphism-iso-over-red}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of formal algebraic
spaces. Assume
\begin{enumerate}
\item $f$ is representable by algebraic spaces,
\item $f$ is a monomorphism,
\item the inclusion $Y_{red} \to Y$ factors through $f$, and
\item $f$ is locally of finite type or $Y$ is locally Noetherian.
\end{enumerate}
Then $f$ is a closed immersion.

\label{lemma-topologically-finite-type-finite-type}
Let $S$ be a scheme. Let $\varphi : A \to B$ be a continuous map of
weakly admissible topological rings over $S$. The following
are equivalent
\begin{enumerate}
\item $\text{Spf}(\varphi) : Y = \text{Spf}(B) \to \text{Spf}(A) = X$
is of finite type,
\item $\varphi$ is taut and $B$ is topologically of finite type over $A$.
\end{enumerate}

\label{lemma-category-affine-over}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
Assume $X$ is McQuillan and let $A$ be the weakly admissible topological
ring associated to $X$. Then there is an anti-equivalence of categories
between
\begin{enumerate}
\item the category $\mathcal{C}$ introduced above, and
\item the category of maps $Y \to X$ of finite type of
affine formal algebraic spaces.
\end{enumerate}

\label{lemma-quotient-restricted-power-series-admissible}
In Lemma \ref{lemma-quotient-restricted-power-series}
if $B$ is admissible (for example adic), then the equivalent conditions
(a) -- (d) are also equivalent to
\begin{enumerate}
\item[(e)] $B \to A$ is taut and $B/J \to A/I$ is of finite type for
some ideal of definition $J \subset B$ where $I \subset A$ is
the closure of $JA$.
\end{enumerate}

\label{definition-separated-morphism}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of formal algebraic spaces over $S$.
Let $\Delta_{X/Y} : X \to X \times_Y X$ be the diagonal morphism.
\begin{enumerate}
\item We say $f$ is {\it separated} if $\Delta_{X/Y}$ is a closed immersion.
\item We say $f$ is {\it quasi-separated} if $\Delta_{X/Y}$ is quasi-compact.
\end{enumerate}

\label{lemma-base-change-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under base change.

\label{lemma-fibre-product-after-map}
Let $S$ be a scheme. Let $f : X \to Z$, $g : Y \to Z$ and $Z \to T$
be morphisms of formal algebraic spaces over $S$. Consider the induced
morphism $i : X \times_Z Y \to X \times_T Y$. Then
\begin{enumerate}
\item $i$ is representable (by schemes), locally of finite type,
locally quasi-finite, separated, and a monomorphism,
\item if $Z \to T$ is separated, then $i$ is a closed immersion, and
\item if $Z \to T$ is quasi-separated, then $i$ is quasi-compact.
\end{enumerate}

\label{lemma-composition-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under composition of morphisms.

\label{definition-proper}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of formal algebraic
spaces over $S$. We say $f$ is {\it proper}
if $f$ is representable by algebraic spaces and is proper in the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.

\label{lemma-sheaf-fpqc}
\begin{slogan}
Formal algebraic spaces are fpqc sheaves
\end{slogan}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$. Then
$X$ satisfies the sheaf property for the fpqc topology.

\label{lemma-affine-identify-affine-etale}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
Then $X_{affine, \etale}$ is equivalent to the category whose objects
are morphisms $\varphi : U \to X$ of formal algebraic spaces such that
\begin{enumerate}
\item $U$ is an affine formal algebraic space,
\item $\varphi$ is representable by algebraic spaces and \'etale.
\end{enumerate}

\label{lemma-identify-affine-etale}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$.
Then $X_{affine, \etale}$ is equivalent to the category whose objects
are morphisms $\varphi : U \to X$ of formal algebraic spaces such that
\begin{enumerate}
\item $U$ is an affine formal algebraic space,
\item $\varphi$ is representable by algebraic spaces and \'etale.
\end{enumerate}

\label{lemma-higher-vanishing-structure-sheaf}
If $X$ is a countably indexed affine formal algebraic space, then
we have $H^n(X_\etale, \mathcal{O}_X) = 0$ for $n > 0$.

\label{definition-completion-formal-algebraic-space}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$.
Let $T \subset |X_{red}|$ be a closed subset. The formal algebraic space
$X_{/T}$ of Lemma \ref{lemma-completion-is-formal-algebraic-space}
is called the {\it completion of $X$ along $T$}.

\label{lemma-functor-on-modules-fp}
Let $A$ be a ring. Let $\mathcal{B}$ be an additive category
with cokernels. There is an equivalence of categories between
\begin{enumerate}
\item the category of functors $F : \text{Mod}^{fp}_A \to \mathcal{B}$
which are right exact, and
\item the category of pairs $(K, \kappa)$ where $K \in \Ob(\mathcal{B})$
and $\kappa : A \to \text{End}_\mathcal{B}(K)$ is a ring homomorphism
\end{enumerate}
given by the rule sending $F$ to $F(A)$ with its natural $A$-action.

\label{lemma-functor}
Let $A$ and $B$ be rings. Let $F : \text{Mod}_A \to \text{Mod}_B$
be a functor. The following are equivalent
\begin{enumerate}
\item $F$ is isomorphic to the functor $M \mapsto M \otimes_A K$
for some $A \otimes_\mathbf{Z} B$-module $K$,
\item $F$ is right exact and commutes with all direct sums,
\item $F$ commutes with all colimits,
\item $F$ has a right adjoint $G$.
\end{enumerate}

\label{lemma-functor-modules}
Let $R$ be a ring. Let $A$ and $B$ be $R$-algebras. There is an
equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \text{Mod}_A \to \text{Mod}_B$ which
are right exact and commute with arbitrary direct sums, and
\item the category $\text{Mod}_{A \otimes_R B}$.
\end{enumerate}
given by sending $K$ to the functor $F$ in (\ref{equation-FM-modules}).

\label{lemma-functor-fp-modules-exact}
With $A$, $B$, $F$, and $F'$ as in Lemma \ref{lemma-functor-fp-modules}.
\begin{enumerate}
\item If $F$ is additive, then $F'$ is additive and
commutes with arbitrary direct sums, and
\item if $F$ is right exact, then $F'$ is right exact.
\end{enumerate}

\label{lemma-functor-quasi-coherent-from-affine}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$ with $X$ affine.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which are right exact and commute with arbitrary direct sums, and
\item the category $\QCoh(\mathcal{O}_{X \times_R Y})$
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

\label{lemma-coh-noetherian-from-affine-flat}
In Lemma \ref{lemma-functor-quasi-coherent-from-affine}
or in Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal-pre}
if $F$ is an exact functor, then the corresponding object
$\mathcal{K}$ of $\QCoh(\mathcal{O}_{X \times_R Y})$ is flat over $X$.

\label{lemma-functor-quasi-coherent-from-affine-diagonal}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$. Assume $X$ is
quasi-compact with affine diagonal.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear exact functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which commute with arbitrary direct sums, and
\item the full subcategory of $\QCoh(\mathcal{O}_{X \times_R Y})$ consisting
of $\mathcal{K}$ such that
\begin{enumerate}
\item $\mathcal{K}$ is flat over $X$,
\item for $\mathcal{F} \in \QCoh(\mathcal{O}_X)$ we have
$R^q\text{pr}_{2, *}(\text{pr}_1^*\mathcal{F}
\otimes_{\mathcal{O}_{X \times_R Y}} \mathcal{K}) = 0$ for $q > 0$.
\end{enumerate}
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

\label{lemma-persistence-exactness}
Let $R$, $X$, $Y$, and $\mathcal{K}$ be as in
Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal} part (2).
Then for any scheme $T$ over $R$ we have
$$
R^q\text{pr}_{13, *}(\text{pr}_{12}^*\mathcal{F}
\otimes_{\mathcal{O}_{T \times_R X \times_R Y}}
\text{pr}_{23}^*\mathcal{K}) = 0
$$
for $\mathcal{F}$ quasi-coherent on $T \times_R X$ and $q > 0$.

\label{lemma-functor-quasi-coherent-from-separated}
In Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal}
let $F$ and $\mathcal{K}$ correspond. If $X$ is separated and
flat over $R$, then there is a surjection
$\mathcal{O}_X \boxtimes F(\mathcal{O}_X) \to \mathcal{K}$.

\label{proposition-gabriel-rosenberg}
\begin{reference}
Special case of \cite[Theorem 1.2]{Brandenburg}
\end{reference}
Let $X$ and $Y$ be quasi-compact and quasi-separated schemes.
If $F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
is an equivalence, then there exists an isomorphism
$f : Y \to X$ of schemes and an invertible $\mathcal{O}_Y$-module
$\mathcal{L}$ such that $F(\mathcal{F}) = f^*\mathcal{F} \otimes \mathcal{L}$.

\label{lemma-equivalence-coherent-over-field}
\begin{reference}
Weak version of the result in \cite{Gabriel}
stating that the category of quasi-coherent modules
determines the isomorphism class of a scheme.
\end{reference}
Let $k$ be a field. Let $X$, $Y$ be finite type schemes over $k$ with
$X$ separated and $Y$ reduced. If there is a $k$-linear equivalence
$F : \textit{Coh}(\mathcal{O}_X) \to \textit{Coh}(\mathcal{O}_Y)$
of categories, then there is an isomorphism $f : Y \to X$
over $k$ and an invertible $\mathcal{O}_Y$-module $\mathcal{L}$
such that $F(\mathcal{F}) = f^*\mathcal{F} \otimes \mathcal{L}$.

\label{definition-base-change}
In the situation of Lemma \ref{lemma-base-change-on-invariant}
we call $j' : R' \to U' \times_B U'$ the {\it base change} of the pre-relation
$j$ to $X'$. We say it is a {\it flat base change} if $X' \to X$ is a flat
morphism of algebraic spaces.

\label{definition-orbit}
Let $S$ be a scheme, and let $B$ be an algebraic space over $S$.
Let $j : R \to U \times_B U$ be a pre-relation over $B$.
If $u \in |U|$, then the {\it orbit}, or more precisely the
{\it $R$-orbit} of $u$ is
$$
O_u =
\left\{
u' \in |U|\ :
\begin{matrix}
\exists n \geq 1, \ \exists u_0, \ldots, u_n \in |U|\text{ such that }
u_0 = u \text{ and } u_n = u' \\
\text{and for all }i \in \{0, \ldots, n - 1\}\text{ either }
u_i = u_{i + 1}\text{ or } \\
\exists r \in |R|, \ s(r) = u_i, t(r) = u_{i + 1}
\text{ or } \\
\exists r \in |R|, \ t(r) = u_i, s(r) = u_{i + 1}
\end{matrix}
\right\}
$$

\label{lemma-invariant-set-theoretically-invariant}
In the situation of Definition \ref{definition-set-theoretically-invariant}.
An invariant morphism is set-theoretically invariant.

\label{lemma-set-theoretically-invariant-invariant-when-reduced}
In the situation of Definition \ref{definition-set-theoretically-invariant}.
Let $\phi : U \to X$ be a morphism of algebraic spaces over $B$.
Assume
\begin{enumerate}
\item $\phi$ is set-theoretically $R$-invariant,
\item $R$ is reduced, and
\item $X$ is locally separated over $B$.
\end{enumerate}
Then $\phi$ is $R$-invariant.

\label{definition-set-theoretic-equivalence}
Let $S$ be a scheme, and let $B$ be an algebraic space over $S$.
Let $j : R \to U \times_B U$ be a pre-relation over $B$.
\begin{enumerate}
\item We say $j$ is a {\it set-theoretic pre-equivalence relation} if
for all algebraically closed fields $k$ over $B$ the relation
$\sim_R$ on $U(k)$ defined by
$$
\overline{u} \sim_R \overline{u}'
\Leftrightarrow
\begin{matrix}
\exists\text{ field extension }K/k, \ \exists\ r \in R(K), \\
s(r) = \overline{u}, \ t(r) = \overline{u}'
\end{matrix}
$$
is an equivalence relation.
\item We say $j$ is a {\it set-theoretic equivalence relation}
if $j$ is universally injective and a set-theoretic pre-equivalence
relation.
\end{enumerate}

\label{lemma-set-theoretic-pre-equivalence-geometric}
In the situation of Definition \ref{definition-set-theoretic-equivalence}.
The following are equivalent:
\begin{enumerate}
\item The morphism $j$ is a set-theoretic pre-equivalence relation.
\item The subset $j(|R|) \subset |U \times_B U|$ contains the image of
$|j'|$ for any of the morphisms $j'$ as in Equation (\ref{equation-list}).
\item For every algebraically closed field $k$ over $B$ of sufficiently large
cardinality the subset $j(R(k)) \subset U(k) \times U(k)$ is an equivalence
relation.
\end{enumerate}
If $s, t$ are locally of finite type these are also equivalent to
\begin{enumerate}
\item[(4)] For every algebraically closed field $k$ over $B$
the subset $j(R(k)) \subset U(k) \times U(k)$ is an equivalence relation.
\end{enumerate}

\label{definition-orbit-space}
Let $B \to S$ as in Section \ref{section-conventions-notation}.
Let $j : R \to U \times_B U$ be a pre-relation.
We say $\phi : U \to X$ is an {\it orbit space for $R$} if
\begin{enumerate}
\item $\phi$ is $R$-invariant,
\item $\phi$ separates $R$-orbits, and
\item $\phi$ is surjective.
\end{enumerate}

\label{definition-coarse}
Let $S$ be a scheme and $B$ an algebraic space over $S$.
Let $j : R \to U \times_B U$ be a pre-relation.
A morphism $\phi : U \to X$ of algebraic spaces over $B$
is called a {\it coarse quotient} if
\begin{enumerate}
\item $\phi$ is a categorical quotient, and
\item $\phi$ is an orbit space.
\end{enumerate}
If $S = B$, $U$, $R$ are all schemes, then we say a morphism of schemes
$\phi : U \to X$ is a {\it coarse quotient in schemes} if
\begin{enumerate}
\item $\phi$ is a categorical quotient in schemes, and
\item $\phi$ is an orbit space.
\end{enumerate}

\label{definition-functions}
Let $S$ be a scheme and $B$ an algebraic space over $S$.
Let $j : R \to U \times_B U$ be a pre-relation.
Let $\phi : U \to X$ be an $R$-invariant morphism.
Denote $\phi' = \phi \circ s = \phi \circ t : R \to X$.
\begin{enumerate}
\item We denote $(\phi_*\mathcal{O}_U)^R$ the $\mathcal{O}_X$-sub-algebra
of $\phi_*\mathcal{O}_U$ which is the equalizer of the two maps
$$
\xymatrix{
\phi_*\mathcal{O}_U
\ar@<1ex>[rr]^{\phi_*s^\sharp}
\ar@<-1ex>[rr]_{\phi_*t^\sharp}
& &
\phi'_*\mathcal{O}_R
}
$$
on $X_\etale$. We sometimes call this the
{\it sheaf of $R$-invariant functions on $X$}.
\item We say {\it the functions on $X$ are the $R$-invariant functions on
$U$} if the natural map $\mathcal{O}_X \to (\phi_*\mathcal{O}_U)^R$
is an isomorphism.
\end{enumerate}

\label{definition-group-scheme}
Let $S$ be a scheme.
\begin{enumerate}
\item A {\it group scheme over $S$} is a pair $(G, m)$, where
$G$ is a scheme over $S$ and $m : G \times_S G \to G$ is
a morphism of schemes over $S$ with the following property:
For every scheme $T$ over $S$ the pair $(G(T), m)$
is a group.
\item A {\it morphism $\psi : (G, m) \to (G', m')$ of group schemes over $S$}
is a morphism $\psi : G \to G'$ of schemes over $S$ such that for
every $T/S$ the induced map $\psi : G(T) \to G'(T)$ is a homomorphism
of groups.
\end{enumerate}

\label{definition-closed-subgroup-scheme}
Let $S$ be a scheme. Let $(G, m)$ be a group scheme over $S$.
\begin{enumerate}
\item A {\it closed subgroup scheme} of $G$ is a closed subscheme
$H \subset G$ such that $m|_{H \times_S H}$ factors through $H$ and induces a
group scheme structure on $H$ over $S$.
\item An {\it open subgroup scheme} of $G$ is an open subscheme
$G' \subset G$ such that $m|_{G' \times_S G'}$ factors through $G'$
and induces a group scheme structure on $G'$ over $S$.
\end{enumerate}

\label{lemma-closed-subgroup-scheme}
Let $S$ be a scheme. Let $(G, m, e, i)$ be a group scheme over $S$.
\begin{enumerate}
\item A closed subscheme $H \subset G$ is a closed subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\item An open subscheme $H \subset G$ is an open subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\end{enumerate}

\label{lemma-group-scheme-module-differentials}
\begin{reference}
\cite[Proposition 3.15]{BookAV}
\end{reference}
Let $(G, m, e, i)$ be a group scheme over the scheme $S$.
Denote $f : G \to S$ the structure morphism.
Then there exist canonical isomorphisms
$$
\Omega_{G/S} \cong f^*\mathcal{C}_{S/G} \cong f^*e^*\Omega_{G/S}
$$
where $\mathcal{C}_{S/G}$ denotes the conormal sheaf of the
immersion $e$. In particular, if $S$ is the spectrum of a field, then
$\Omega_{G/S}$ is a free $\mathcal{O}_G$-module.

\label{lemma-group-scheme-addition-tangent-vectors}
Let $S$ be a scheme. Let $G$ be a group scheme over $S$.
Let $s \in S$. Then the composition
$$
T_{G/S, e(s)} \oplus T_{G/S, e(s)} = T_{G \times_S G/S, (e(s), e(s))}
\rightarrow T_{G/S, e(s)}
$$
is addition of tangent vectors. Here the $=$ comes from
Varieties, Lemma \ref{varieties-lemma-tangent-space-product}
and the right arrow is induced from $m : G \times_S G \to G$ via
Varieties, Lemma \ref{varieties-lemma-map-tangent-spaces}.

\label{lemma-group-scheme-over-field-open-multiplication}
If $(G, m)$ is a group scheme over a field $k$, then the
multiplication map $m : G \times_k G \to G$ is open.

\label{lemma-group-scheme-over-field-separated}
Let $G$ be a group scheme over a field.
Then $G$ is a separated scheme.

\label{lemma-group-scheme-field-geometrically-irreducible}
Let $G$ be a group scheme over a field $k$.
Then
\begin{enumerate}
\item every local ring $\mathcal{O}_{G, g}$ of $G$ has a unique
minimal prime ideal,
\item there is exactly one irreducible component $Z$ of $G$
passing through $e$, and
\item $Z$ is geometrically irreducible over $k$.
\end{enumerate}

\label{lemma-reduced-subgroup-scheme-perfect}
Let $G$ be a group scheme over a perfect field $k$.
Then the reduction $G_{red}$ of $G$ is a closed subgroup scheme of $G$.

\label{lemma-open-subgroup-closed-over-field}
Let $k$ be a field. Let $\psi : G' \to G$ be a morphism of group schemes
over $k$. If $\psi(G')$ is open in $G$, then $\psi(G')$ is closed in $G$.

\label{lemma-irreducible-group-scheme-over-field-qc}
Let $G$ be a group scheme over a field $k$. If $G$ is irreducible,
then $G$ is quasi-compact.

\label{lemma-connected-group-scheme-over-field-irreducible}
Let $G$ be a group scheme over a field $k$. If $G$ is connected,
then $G$ is irreducible.

\label{proposition-connected-component}
Let $G$ be a group scheme over a field $k$. There exists a canonical closed
subgroup scheme $G^0 \subset G$ with the following properties
\begin{enumerate}
\item $G^0 \to G$ is a flat closed immersion,
\item $G^0 \subset G$ is the connected component of the identity,
\item $G^0$ is geometrically irreducible, and
\item $G^0$ is quasi-compact.
\end{enumerate}

\label{lemma-algebraic-quasi-projective}
Let $k$ be a field. Let $G$ be an algebraic group scheme over $k$.
Then $G$ is quasi-projective over $k$.

\label{lemma-algebraic-center}
Let $k$ be a field. Let $G$ be a locally algebraic group scheme over $k$.
Then the center of $G$ is a closed subgroup scheme of $G$.

\label{lemma-abelian-variety-projective}
Let $k$ be a field. Let $A$ be an abelian variety over $k$.
Then $A$ is projective.

\label{lemma-abelian-variety-smooth}
Let $k$ be a field. Let $A$ be an abelian variety over $k$.
Then $A$ is smooth over $k$.

\label{lemma-abelian-variety-abelian}
An abelian variety is an abelian group scheme, i.e., the group
law is commutative.

\label{lemma-abelian-variety-multiplication-by-d-etale}
\begin{slogan}
Multiplication by an integer on an abelian variety is an etale morphism
if and only if the integer is invertible in the base field.
\end{slogan}
Let $k$ be a field. Let $A$ be a nonzero abelian variety over $k$.
Then $[d] : A \to A$ is \'etale if and only if $d$ is invertible in $k$.

\label{lemma-characterize-trivial-pseudo-torsors}
In the situation of
Definition \ref{definition-pseudo-torsor}.
\begin{enumerate}
\item The scheme $X$ is a pseudo $G$-torsor if and only if for every scheme
$T$ over $S$ the set $X(T)$ is either empty or the action of the group $G(T)$
on $X(T)$ is simply transitive.
\item A pseudo $G$-torsor $X$ is trivial if and only if the morphism
$X \to S$ has a section.
\end{enumerate}

\label{lemma-diagram-pull}
Let $S$ be a scheme.
Let $(U, R, s, t, c, e, i)$ be a groupoid over $S$.
The diagram
\begin{equation}
\label{equation-pull}
\xymatrix{
R \times_{t, U, t} R
\ar@<1ex>[r]^-{\text{pr}_1} \ar@<-1ex>[r]_-{\text{pr}_0}
\ar[d]_{(\text{pr}_0, c \circ (i, 1))} &
R \ar[r]^t \ar[d]^{\text{id}_R} &
U \ar[d]^{\text{id}_U} \\
R \times_{s, U, t} R
\ar@<1ex>[r]^-c \ar@<-1ex>[r]_-{\text{pr}_0} \ar[d]_{\text{pr}_1} &
R \ar[r]^t \ar[d]^s &
U \\
R \ar@<1ex>[r]^s \ar@<-1ex>[r]_t &
U
}
\end{equation}
is commutative. The two top rows are isomorphic via the vertical maps given.
The two lower left squares are cartesian.

\label{definition-groupoid-module}
Let $S$ be a scheme, let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
A {\it quasi-coherent module on $(U, R, s, t, c)$}
is a pair $(\mathcal{F}, \alpha)$, where $\mathcal{F}$ is a quasi-coherent
$\mathcal{O}_U$-module, and $\alpha$ is a $\mathcal{O}_R$-module
map
$$
\alpha : t^*\mathcal{F} \longrightarrow s^*\mathcal{F}
$$
such that
\begin{enumerate}
\item the diagram
$$
\xymatrix{
& \text{pr}_1^*t^*\mathcal{F} \ar[r]_-{\text{pr}_1^*\alpha} &
\text{pr}_1^*s^*\mathcal{F} \ar@{=}[rd] & \\
\text{pr}_0^*s^*\mathcal{F} \ar@{=}[ru] & & & c^*s^*\mathcal{F} \\
& \text{pr}_0^*t^*\mathcal{F} \ar[lu]^{\text{pr}_0^*\alpha} \ar@{=}[r] &
c^*t^*\mathcal{F} \ar[ru]_{c^*\alpha}
}
$$
is a commutative in the category of
$\mathcal{O}_{R \times_{s, U, t} R}$-modules, and
\item the pullback
$$
e^*\alpha : \mathcal{F} \longrightarrow \mathcal{F}
$$
is the identity map.
\end{enumerate}
Compare with the commutative diagrams of Lemma \ref{lemma-diagram}.

\label{lemma-colimits}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
The category of quasi-coherent modules on $(U, R, s, t, c)$ has colimits.

\label{lemma-colimit-coherent}
Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
Assume that
\begin{enumerate}
\item $U$, $R$ are Noetherian,
\item $s, t$ are flat, quasi-compact, and quasi-separated.
\end{enumerate}
Then every quasi-coherent module $(\mathcal{F}, \beta)$ on $(U, R, s, t, c)$
is a filtered colimit of coherent modules.

\label{definition-invariant-open}
Let $(U, R, s, t, c)$ be a groupoid scheme over the base scheme $S$.
\begin{enumerate}
\item A subset $W \subset U$ is {\it set-theoretically $R$-invariant}
if $t(s^{-1}(W)) \subset W$.
\item An open $W \subset U$ is {\it $R$-invariant} if
$t(s^{-1}(W)) \subset W$.
\item A closed subscheme $Z \subset U$ is called {\it $R$-invariant}
if $t^{-1}(Z) = s^{-1}(Z)$. Here we use the scheme theoretic inverse image, see
Schemes, Definition \ref{schemes-definition-inverse-image-closed-subscheme}.
\item A monomorphism of schemes $T \to U$ is {\it $R$-invariant} if
$T \times_{U, t} R = R \times_{s, U} T$ as schemes over $R$.
\end{enumerate}

\label{lemma-cartesian-equivalent-descent-datum}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of schemes over $S$.
The construction of Lemma \ref{lemma-characterize-cartesian-schemes}
determines an equivalence
$$
\begin{matrix}
\text{category of groupoid schemes} \\
\text{cartesian over } (X, X \times_Y X, \ldots)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/Y
\end{matrix}
$$

\label{lemma-diagonal}
Let $S$ be a scheme.
Let $(U, R, s, t, c)$ be a groupoid over $S$.
Let $G \to U$ be the stabilizer group scheme.
\begin{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_S U$ is separated,
\item $G \to U$ is separated, and
\item $e : U \to G$ is a closed immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_S U$ is quasi-separated,
\item $G \to U$ is quasi-separated, and
\item $e : U \to G$ is quasi-compact.
\end{enumerate}
\end{enumerate}

\label{lemma-descend-along-finite-radicial}
Let $X \to Y$ be a surjective finite locally free morphism which is radicial. 
Let $V$ be a scheme over $X$. Then any descent datum on $V/X/Y$ is effective.

\label{definition-additive-category}
A category $\mathcal{A}$ is called {\it additive}
if it is preadditive and finite products exist, in other
words it has a zero object and direct sums.

\label{lemma-split-morphism-kernel-cokernel}
Let $\mathcal{A}$ be a preadditive category,
$x$ and $y$ be objects of $\mathcal{A}$,
and $j : y \to x$ and $q : x \to y$ be morphisms
satisfying $q \circ j = \text{id} _ y$.
Then
\begin{enumerate}
\item $\text{id} _ x - j \circ q$ has kernel $j$.
\item $\text{id} _ x - j \circ q$ has cokernel $q$.
\end{enumerate}

\label{lemma-projectors-have-images}
Let $\mathcal{D}$ be a preadditive category.
\begin{enumerate}
\item If $\mathcal{D}$ has countable products and kernels of maps which
have a right inverse, then $\mathcal{D}$ is Karoubian.
\item If $\mathcal{D}$ has countable coproducts and cokernels of
maps which have a left inverse, then $\mathcal{D}$ is Karoubian.
\end{enumerate}

\label{definition-injective-surjective}
Let $f : x \to y$ be a morphism in an abelian category.
\begin{enumerate}
\item We say $f$ is {\it injective} if $\Ker(f) = 0$.
\item We say $f$ is {\it surjective} if $\Coker(f) = 0$.
\end{enumerate}
If $x \to y$ is injective, then we say that $x$ is a {\it subobject}
of $y$ and we use the notation $x \subset y$. If $x \to y$ is
surjective, then we say that $y$ is a {\it quotient} of $x$.

\label{lemma-characterize-injective}
Let $f : x \to y$ be a morphism in an abelian category $\mathcal{A}$. Then
\begin{enumerate}
\item $f$ is injective if and only if $f$ is a monomorphism,
\item $f$ is surjective if and only if $f$ is an epimorphism, and
\item $f$ is an isomorphism if and only if $f$ is injective and surjective.
\end{enumerate}

\label{lemma-colimit-abelian-category}
Let $\mathcal{A}$ be an abelian category.
All finite limits and finite colimits exist in $\mathcal{A}$.

\label{lemma-epimorphism-universal-abelian-category}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If $x \to y$ is surjective, then for every $z \to y$ the
projection $x \times_y z \to z$ is surjective.
\item If $x \to y$ is injective, then for every $x \to z$ the
morphism $z \to z \amalg_x y$ is injective.
\end{enumerate}

\label{lemma-check-exactness-fibre-product}
Let $\mathcal{A}$ be an abelian category. Let $f:x\to y$ and $g:y\to z$ 
be morphisms with $g\circ f=0$. Then, the following statements are equivalent:
\begin{enumerate}
\item The sequence $x\overset{f}\to y\overset{g}\to z$ is exact.
\item For every $h:w\to y$ with $g\circ h=0$ there exist an object $v$, 
an epimorphism $k:v\to w$ and a morphism $l:v\to x$ with $h\circ k=f\circ l$.
\end{enumerate}

\label{lemma-four-lemma}
Let $\mathcal{A}$ be an abelian category. Let
$$
\xymatrix{
w \ar[r] \ar[d]^\alpha & x \ar[r] \ar[d]^\beta & y \ar[r] \ar[d]^\gamma &
z \ar[d]^\delta \\
w' \ar[r] & x' \ar[r] & y' \ar[r] & z'
}
$$
be a commutative diagram with exact rows.
\begin{enumerate}
\item If $\alpha, \gamma$ are surjective and $\delta$ is injective, then
$\beta$ is surjective.
\item If $\beta, \delta$ are injective and $\alpha$ is surjective, then
$\gamma$ is injective.
\end{enumerate}

\label{lemma-five-lemma}
\begin{reference}
\cite[Lemma 4.5 page 16]{Eilenberg-Steenrod}
\end{reference}
Let $\mathcal{A}$ be an abelian category. Let
$$
\xymatrix{
v \ar[r] \ar[d]^\alpha &
w \ar[r] \ar[d]^\beta &
x \ar[r] \ar[d]^\gamma &
y \ar[r] \ar[d]^\delta &
z \ar[d]^\epsilon \\
v' \ar[r] & w' \ar[r] & x' \ar[r] & y' \ar[r] & z'
}
$$
be a commutative diagram with exact rows. If $\beta, \delta$
are isomorphisms, $\epsilon$ is injective, and $\alpha$ is surjective
then $\gamma$ is an isomorphism.

\label{lemma-adjoint-get-abelian}
Let $a : \mathcal{A} \to \mathcal{B}$ and $b : \mathcal{B} \to \mathcal{A}$
be functors. Assume that
\begin{enumerate}
\item $\mathcal{A}$, $\mathcal{B}$ are additive categories,
$a$, $b$ are additive functors, and $a$ is right adjoint to $b$,
\item $\mathcal{B}$ is abelian and $b$ is left exact, and
\item $ba \cong \text{id}_\mathcal{A}$.
\end{enumerate}
Then $\mathcal{A}$ is abelian.

\label{definition-Artinian}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item We say an object $A$ of $\mathcal{A}$ is {\it Artinian} if and only if
it satisfies the descending chain condition for subobjects.
\item We say $\mathcal{A}$ is {\it Artinian} if every object of
$\mathcal{A}$ is Artinian.
\end{enumerate}

\label{definition-Noetherian}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item We say an object $A$ of $\mathcal{A}$ is {\it Noetherian} if and only if
it satisfies the ascending chain condition for subobjects.
\item We say $\mathcal{A}$ is {\it Noetherian} if every object of
$\mathcal{A}$ is Noetherian.
\end{enumerate}

\label{lemma-finite-length}
Let $\mathcal{A}$ be an abelian category. Let $A$ be an object
of $\mathcal{A}$. The following are equivalent
\begin{enumerate}
\item $A$ is Artinian and Noetherian, and
\item there exists a filtration
$0 \subset A_1 \subset A_2 \subset \ldots \subset A_n = A$
by subobjects such that $A_i/A_{i - 1}$ is simple for $i = 1, \ldots, n$.
\end{enumerate}

\label{definition-serre-subcategory}
\begin{reference}
\cite[Condition (I) on page 259]{Serre_homotopie_classes}
\end{reference}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item A {\it Serre subcategory} of $\mathcal{A}$ is a
nonempty full subcategory $\mathcal{C}$ of $\mathcal{A}$
such that given an exact sequence\footnote{By
Definition \ref{definition-exact} this means $\Im(A \to B) = \Ker(B \to C)$.}
$$
A \to B \to C
$$
with $A, C \in \Ob(\mathcal{C})$, then also
$B \in \Ob(\mathcal{C})$.
\item A {\it weak Serre subcategory} of $\mathcal{A}$ is a nonempty
full subcategory $\mathcal{C}$ of $\mathcal{A}$ such that given an
exact sequence
$$
A_0 \to A_1 \to A_2 \to A_3 \to A_4
$$
with $A_0, A_1, A_3, A_4$ in $\mathcal{C}$, then also $A_2$ in $\mathcal{C}$.
\end{enumerate}

\label{lemma-map-homology-homotopy}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A_\bullet \to B_\bullet$ are
homotopic, then the induced maps $H_i(f)$ and $H_i(g)$
are equal.
\item If the map $f : A_\bullet \to B_\bullet$ is a homotopy
equivalence, then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{lemma-map-cohomology-homotopy-cochain}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A^\bullet \to B^\bullet$ are
homotopic, then the induced maps $H^i(f)$ and $H^i(g)$
are equal.
\item If $f : A^\bullet \to B^\bullet$ is a homotopy equivalence,
then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{definition-graded}
Let $\mathcal{A}$ be an additive category. The {\it category of graded
objects of $\mathcal{A}$}, denoted $\text{Gr}(\mathcal{A})$, is
the category with
\begin{enumerate}
\item objects $A = (A^i)$ are families of objects $A^i$, $i \in \mathbf{Z}$
of objects of $\mathcal{A}$, and
\item morphisms $f : A = (A^i) \to B = (B^i)$ are families of
morphisms $f^i : A^i \to B^i$ of $\mathcal{A}$.
\end{enumerate}

\label{lemma-graded}
Let $\mathcal{A}$ be an abelian category. The category of graded objects
$\text{Gr}(\mathcal{A})$ is abelian.

\label{lemma-Karoubian-dual}
In a Karoubian additive monoidal category every summand
of an object which has a left dual has a left dual.

\label{lemma-filtered}
Let $\mathcal{A}$ be an abelian category.
The category of filtered objects $\text{Fil}(\mathcal{A})$
has the following properties:
\begin{enumerate}
\item It is an additive category.
\item It has a zero object.
\item It has kernels and cokernels, images and coimages.
\item In general it is not an abelian category.
\end{enumerate}

\label{lemma-characterize-strict-general}
Let $\mathcal{A}$ be an abelian category.
Let $f : A \to B$ be a morphism of filtered objects of $\mathcal{A}$.
The following are equivalent
\begin{enumerate}
\item $f$ is strict,
\item the morphism $\Coim(f) \to \Im(f)$ of
Lemma \ref{lemma-coim-im-map}
is an isomorphism.
\end{enumerate}

\label{lemma-composition-strict}
Let $\mathcal{A}$ be an abelian category. Let $f : A \to B$, $g : B \to C$
be strict morphisms of filtered objects.
\begin{enumerate}
\item In general the composition $g \circ f$ is not strict.
\item If $g$ is injective, then $g \circ f$ is strict.
\item If $f$ is surjective, then $g \circ f$ is strict.
\end{enumerate}

\label{lemma-differential-objects-abelian}
\begin{slogan}
The category of differential objects of an abelian category is itself
an abelian category.
\end{slogan}
Let $\mathcal{A}$ be an abelian category.
The category of differential objects of $\mathcal{A}$ is abelian.

\label{lemma-compute-filtered-cohomology}
Let $\mathcal{A}$ be an abelian category. Let $(K, F, d)$ be a filtered
differential object of $\mathcal{A}$. If $Z_\infty^p$ and $B_\infty^p$
exist (see proof), then
\begin{enumerate}
\item the limit $E_\infty$ exists and is graded having
$E_\infty^p = Z_\infty^p/B_\infty^p$ in degree $p$, and
\item the associated graded $\text{gr}(H(K))$ of the cohomology of $K$
is a graded subquotient of the graded limit object $E_\infty$.
\end{enumerate}

\label{definition-filtered-differential-ss-converges}
Let $\mathcal{A}$ be an abelian category.
Let $(K, F, d)$ be a filtered differential object of $\mathcal{A}$.
We say the spectral sequence associated to $(K, F, d)$
\begin{enumerate}
\item {\it weakly converges to $H(K)$} if $\text{gr}H(K) = E_{\infty}$
via Lemma \ref{lemma-compute-filtered-cohomology},
\item {\it abuts to $H(K)$} if it weakly converges to $H(K)$ and
we have $\bigcap F^pH(K) = 0$ and $\bigcup F^pH(K) = H(K)$,
\end{enumerate}

\label{definition-filtered-complex}
Let $\mathcal{A}$ be an abelian category.
A {\it filtered complex $K^\bullet$ of $\mathcal{A}$}
is a complex of $\text{Fil}(\mathcal{A})$ (see
Definition \ref{definition-filtered}).

\label{definition-filtered-complex-ss-converges}
Let $\mathcal{A}$ be an abelian category. Let $(K^\bullet, F)$ be a
filtered complex of $\mathcal{A}$. We say the spectral sequence
associated to $(K^\bullet, F)$
\begin{enumerate}
\item {\it weakly converges to $H^*(K^\bullet)$} if
$\text{gr}^pH^n(K^\bullet) = E_{\infty}^{p, n - p}$
via Lemma \ref{lemma-compute-cohomology-filtered-complex}
for all $p, n \in \mathbf{Z}$,
\item {\it abuts to $H^*(K^\bullet)$} if it weakly converges to
$H^*(K^\bullet)$ and $\bigcap_p F^pH^n(K^\bullet) = 0$ and
$\bigcup_p F^p H^n(K^\bullet) = H^n(K^\bullet)$ for all $n$,
\item {\it converges to $H^*(K^\bullet)$} if it is regular,
abuts to $H^*(K^\bullet)$, and
$H^n(K^\bullet) = \lim_p H^n(K^\bullet)/F^pH^n(K^\bullet)$.
\end{enumerate}

\label{definition-enough-injectives}
Let $\mathcal{A}$ be an abelian category.
We say $\mathcal{A}$ has {\it enough injectives}
if every object $A$ has an injective morphism
$A \to J$ into an injective object $J$.

\label{definition-enough-projectives}
Let $\mathcal{A}$ be an abelian category.
We say $\mathcal{A}$ has {\it enough projectives}
if every object $A$ has an surjective morphism
$P \to A$ from an projective object $P$ onto it.

\label{lemma-adjoint-preserve-injectives}
\begin{slogan}
A functor with an exact left adjoint preserves injectives
\end{slogan}
Let $\mathcal{A}$ and $\mathcal{B}$ be abelian categories.
Let $u : \mathcal{A} \to \mathcal{B}$ and
$v : \mathcal{B} \to \mathcal{A}$ be additive functors with
$u$ right adjoint to $v$. Consider the following conditions:
\begin{enumerate}
\item[(a)] $v$ transforms injective maps into injective maps,
\item[(b)] $v$ is exact, and
\item[(c)] $u$ transforms injectives into injectives.
\end{enumerate}
Then (a) $\Leftrightarrow$ (b) $\Rightarrow$ (c). If $\mathcal{A}$
has enough injectives, then all three conditions are equivalent.

\label{lemma-essentially-constant-into-karoubian}
Let $\mathcal{I}$ be a category, let $\mathcal{A}$ be a pre-additive
Karoubian category, and let $M : \mathcal{I} \to \mathcal{A}$ be a diagram.
\begin{enumerate}
\item Assume $\mathcal{I}$ is filtered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \colim M$ exists and there exists a cofinal filtered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$ such that
$X_{i'}$ maps isomorphically to $X$ and $Z_{i'}$ to zero in $M_{i''}$
for some $i' \to i''$ in $\mathcal{I}'$.
\end{enumerate}
\item Assume $\mathcal{I}$ is cofiltered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \lim M$ exists and there exists an initial cofiltered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$
such that $X$ maps isomorphically to $X_{i'}$ and $M_{i''} \to Z_{i'}$
is zero for some $i'' \to i'$ in $\mathcal{I}'$.
\end{enumerate}
\end{enumerate}

\label{lemma-direct-sum-from-product-colimit}
Let $\mathcal{I}$ be a category. Let $\mathcal{A}$ be an additive, Karoubian
category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $\colim_\mathcal{I} F \oplus G$ exists, and
\item $\colim_\mathcal{I} F$ and $\colim_\mathcal{I} G$ exist.
\end{enumerate}
In this case $\colim_\mathcal{I} F \oplus G =
\colim_\mathcal{I} F \oplus \colim_\mathcal{I} G$.

\label{lemma-direct-sum-from-product-essentially-constant}
Let $\mathcal{I}$ be a filtered category. Let $\mathcal{A}$
be an additive, Karoubian category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $F \oplus G : \mathcal{I} \to \mathcal{A}$
is essentially constant, and
\item $F$ and $G$ are essentially constant.
\end{enumerate}

\label{lemma-inverse-systems-abelian}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item If $\mathcal{C}$ is an additive category, then the category
of inverse systems with values in $\mathcal{C}$ is an additive category.
\item If $\mathcal{C}$ is an abelian category, then the category
of inverse systems with values in $\mathcal{C}$ is an abelian category.
A sequence $(K_i) \to (L_i) \to (M_i)$ of inverse systems
is exact if and only if each $K_i \to L_i \to N_i$ is exact.
\end{enumerate}

\label{definition-SR}
Let $\mathcal{C}$ be a category. We denote $\text{SR}(\mathcal{C})$
the category of {\it semi-representable objects} defined as follows
\begin{enumerate}
\item objects are families of objects $\{U_i\}_{i \in I}$, and
\item morphisms $\{U_i\}_{i \in I} \to \{V_j\}_{j \in J}$ are given by
a map $\alpha : I \to J$ and for each $i \in I$
a morphism $f_i : U_i \to V_{\alpha(i)}$ of $\mathcal{C}$.
\end{enumerate}
Let $X \in \Ob(\mathcal{C})$ be an object of $\mathcal{C}$.
The category of {\it semi-representable objects over $X$}
is the category
$\text{SR}(\mathcal{C}, X) = \text{SR}(\mathcal{C}/X)$.

\label{definition-SR-F}
Let $\mathcal{C}$ be a category.
We denote $F$ the functor {\it which associates a presheaf to a
semi-representable object}. In a formula
\begin{eqnarray*}
F : \text{SR}(\mathcal{C}) & \longrightarrow & \textit{PSh}(\mathcal{C}) \\
\{U_i\}_{i \in I} & \longmapsto & \amalg_{i\in I} h_{U_i}
\end{eqnarray*}
where $h_U$ denotes the representable presheaf associated to
the object $U$.

\label{definition-hypercovering}
Let $\mathcal{C}$ be a site. Assume $\mathcal{C}$ has fibre products.
Let $X \in \Ob(\mathcal{C})$ be an object of $\mathcal{C}$.
A {\it hypercovering of $X$} is a simplicial object
$K$ of $\text{SR}(\mathcal{C}, X)$ such that
\begin{enumerate}
\item The object $K_0$ is a covering of $X$ for the site $\mathcal{C}$.
\item For every $n \geq 0$ the canonical morphism
$$
K_{n + 1} \longrightarrow (\text{cosk}_n \text{sk}_n K)_{n + 1}
$$
is a covering in the sense defined above.
\end{enumerate}

\label{lemma-funny-gamma}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$.
Let $K, L, M$ be simplicial objects of $\text{SR}(\mathcal{C}, X)$.
Let $a : K \to L$, $b : M \to L$ be morphisms.
Assume
\begin{enumerate}
\item $K$ is a hypercovering of $X$,
\item the morphism $M_0 \to L_0$ is a covering, and
\item for all $n \geq 0$ in the diagram
$$
\xymatrix{
M_{n + 1} \ar[dd] \ar[rr] \ar[rd]^\gamma &
&
(\text{cosk}_n \text{sk}_n M)_{n + 1} \ar[dd] \\
&
L_{n + 1}
\times_{(\text{cosk}_n \text{sk}_n L)_{n + 1}}
(\text{cosk}_n \text{sk}_n M)_{n + 1}
\ar[ld] \ar[ru]
& \\
L_{n + 1} \ar[rr] & & (\text{cosk}_n \text{sk}_n L)_{n + 1}
}
$$
the arrow $\gamma$ is a covering.
\end{enumerate}
Then the fibre product $K \times_L M$ is a hypercovering of $X$.

\label{lemma-degeneracy-maps-coverings}
Let $\mathcal{C}$ be a site with fibre products. Let $X$ be an object of
$\mathcal{C}$. Let $K$ be a hypercovering of $X$. Then
\begin{enumerate}
\item $K_n$ is a covering of $X$ for each $n \geq 0$,
\item $d^n_i : K_n \to K_{n - 1}$ is a covering for all $n \geq 1$
and $0 \leq i \leq n$.
\end{enumerate}

\label{lemma-hom-hypercovering}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$.
Let $L$ be a simplicial object of $\text{SR}(\mathcal{C}, X)$.
Let $n \geq 0$. Consider the commutative diagram
\begin{equation}
\label{equation-diagram}
\xymatrix{
\Hom(\Delta[1], L)_{n + 1} \ar[r] \ar[d] &
(\text{cosk}_n \text{sk}_n \Hom(\Delta[1], L))_{n + 1} \ar[d] \\
(L \times L)_{n + 1} \ar[r] &
(\text{cosk}_n \text{sk}_n (L \times L))_{n + 1}
}
\end{equation}
coming from the morphism defined above.
We can identify the terms in this diagram as follows,
where
$\partial \Delta[n + 1] = i_{n!}\text{sk}_n \Delta[n + 1]$
is the $n$-skeleton of the $(n + 1)$-simplex:
\begin{eqnarray*}
\Hom(\Delta[1], L)_{n + 1}
& = &
\Hom(\Delta[1] \times \Delta[n + 1], L)_0 \\
(\text{cosk}_n \text{sk}_n \Hom(\Delta[1], L))_{n + 1}
& = &
\Hom(\Delta[1] \times \partial \Delta[n + 1], L)_0 \\
(L \times L)_{n + 1}
& = &
\Hom(
(\Delta[n + 1] \amalg \Delta[n + 1], L)_0 \\
(\text{cosk}_n \text{sk}_n (L \times L))_{n + 1}
& = &
\Hom(
\partial \Delta[n + 1]
\amalg
\partial \Delta[n + 1], L)_0
\end{eqnarray*}
and the morphism between these objects of $\text{SR}(\mathcal{C}, X)$
come from the commutative diagram of simplicial sets
\begin{equation}
\label{equation-dual-diagram}
\xymatrix{
\Delta[1] \times \Delta[n + 1] &
\Delta[1] \times \partial\Delta[n + 1] \ar[l] \\
\Delta[n + 1] \amalg \Delta[n + 1] \ar[u] &
\partial\Delta[n + 1] \amalg \partial\Delta[n + 1]
\ar[l] \ar[u]
}
\end{equation}
Moreover the fibre product of the bottom arrow and the
right arrow in (\ref{equation-diagram}) is equal to
$$
\Hom(U, L)_0
$$
where $U \subset \Delta[1] \times \Delta[n + 1]$
is the smallest simplicial subset such that both
$\Delta[n + 1] \amalg \Delta[n + 1]$ and
$\Delta[1] \times \partial\Delta[n + 1]$ map into it.

\label{theorem-cohomology-hypercoverings}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$. Let $i \geq 0$.
The functors
\begin{eqnarray*}
\textit{Ab}(\mathcal{C}) & \longrightarrow & \textit{Ab} \\
\mathcal{F} & \longmapsto & H^i(X, \mathcal{F}) \\
\mathcal{F} & \longmapsto & \check{H}^i_{\text{HC}}(X, \mathcal{F})
\end{eqnarray*}
are canonically isomorphic.

\label{lemma-out-of-finite}
Suppose that, in (\ref{equation-compare}), $\mathcal{C}$ is the category
of sets and $A$ is a {\it finite set}, then the map is a bijection.

[Baer's criterion]
\label{lemma-criterion-baer}
\begin{reference}
\cite[Theorem 1]{Baer}
\end{reference}
Let $R$ be a ring. An $R$-module $Q$ is injective if and only if in every
commutative diagram
$$
\xymatrix{
\mathfrak{a} \ar[d] \ar[r] &  Q \\
R \ar@{-->}[ru]
}
$$
for $\mathfrak{a} \subset R$ an ideal, the dotted arrow exists.

\label{proposition-presheaves-injectives}
For abelian presheaves on a category there is a functorial injective
embedding.

\label{lemma-ev-injective-sheaves}
For any $\mathcal{O}$-module $\mathcal{F}$ the evaluation map
$ev : \mathcal{F} \to (\mathcal{F}^\vee)^\vee$ is injective.

\label{lemma-set-iso-classes-bounded-size}
Let $\mathcal{A}$ be a Grothendieck abelian category with generator $U$.
\begin{enumerate}
\item If $|M| \leq \kappa$, then $M$ is the quotient of a direct
sum of at most $\kappa$ copies of $U$.
\item For every cardinal $\kappa$ the isomorphism classes
of objects $M$ with $|M| \leq \kappa$ form a set.
\end{enumerate}

\label{lemma-characterize-injective}
\begin{slogan}
To check that an object is injective, one only needs to check that lifting
holds for subobjects of a generator.
\end{slogan}
Let $\mathcal{A}$ be a Grothendieck abelian category with generator $U$.
An object $I$ of $\mathcal{A}$ is injective if and only if in every
commutative diagram
$$
\xymatrix{
M \ar[d] \ar[r] &  I \\
U \ar@{-->}[ru]
}
$$
for $M \subset U$ a subobject, the dotted arrow exists.

\label{theorem-injective-embedding-grothendieck}
Let $\mathcal{A}$ be a Grothendieck abelian category.
Then $\mathcal{A}$ has functorial injective embeddings.

\label{theorem-K-injective-embedding-grothendieck}
\begin{slogan}
Existence of K-injective complexes for Grothendieck abelian categories.
\end{slogan}
Let $\mathcal{A}$ be a Grothendieck abelian category.
For every complex $M^\bullet$ there exists a quasi-isomorphism
$M^\bullet \to I^\bullet$ such that $M^n \to I^n$ is injective and $I^n$
is an injective object of $\mathcal{A}$ for all $n$ and $I^\bullet$
is a K-injective complex. Moreover, the construction is functorial in
$M^\bullet$.

\label{lemma-derived-products}
Let $\mathcal{A}$ be a Grothendieck abelian category.
Then
\begin{enumerate}
\item $D(\mathcal{A})$ has both direct sums and products,
\item direct sums are obtained by taking termwise direct sums of
any complexes,
\item products are obtained by taking termwise products of
K-injective complexes.
\end{enumerate}

\label{lemma-RF-commutes-with-Rlim}
Let $F : \mathcal{A} \to \mathcal{B}$ be an additive functor of
abelian categories. Assume
\begin{enumerate}
\item $\mathcal{A}$ is a Grothendieck abelian category,
\item $\mathcal{B}$ has exact countable products, and
\item $F$ commutes with countable products.
\end{enumerate}
Then
$RF : D(\mathcal{A}) \to D(\mathcal{B})$ commutes with derived limits.

\label{lemma-gabriel-popescu-left-adjoint}
The functor $G$ above has a left adjoint
$F : \text{Mod}_R \to \mathcal{A}$.

\label{lemma-F-G-monos}
Let $f : M \to G(A)$ be an injective map in $\text{Mod}_R$.
Then the adjoint map $f' : F(M) \to A$ is injective too.

\label{theorem-gabriel-popescu}
Let $\mathcal{A}$ be a Grothendieck abelian category. Then there exists
a (noncommutative) ring $R$ and functors $G : \mathcal{A} \to \text{Mod}_R$
and $F : \text{Mod}_R \to \mathcal{A}$ such that
\begin{enumerate}
\item $F$ is the left adjoint to $G$,
\item $G$ is fully faithful, and
\item $F$ is exact.
\end{enumerate}
Moreover, the functors are the ones constructed above.

\label{lemma-push-coherent}
\begin{reference}
See \cite[Chapter V]{Serre_algebre_locale}.
\end{reference}
Suppose that $f : X \to Y$ is a proper morphism of varieties.
Let $\mathcal{F}$ be a coherent sheaf with
$\dim(\text{Supp}(\mathcal{F})) \leq k$, then
$f_*[\mathcal{F}]_k = [f_*\mathcal{F}]_k$. In particular, if
$Z \subset X$ is a closed subscheme of dimension $\leq k$, then
$f_*[Z]_k = [f_*\mathcal{O}_Z]_k$.

\label{lemma-compose-pushforward}
Let $f : X \to Y$ and $g : Y \to Z$ be proper morphisms of
varieties. Then $g_* \circ f_* = (g \circ f)_*$ as maps $Z_k(X) \to Z_k(Z)$.

\label{lemma-dimension-product-varieties}
Let $X$ and $Y$ be varieties. Then $X \times Y$ is a variety and
$\dim(X \times Y) = \dim(X) + \dim(Y)$.

\label{lemma-pullback-by-regular-immersion}
Let $f : X \to Y$ be a morphism of varieties.
\begin{enumerate}
\item If $Z \subset Y$ is a subvariety of dimension $d$ and $f$ is a regular
immersion of codimension $c$, then every irreducible component
of $f^{-1}(Z)$ has dimension $\geq d - c$.
\item If $Z \subset Y$ is a subvariety of dimension $d$ and
$f$ is a local complete intersection morphism of relative dimension $r$,
then every irreducible component of $f^{-1}(Z)$ has dimension $\geq d + r$.
\end{enumerate}

\label{lemma-diagonal-regular-immersion}
Let $X$ be a nonsingular variety. Then the diagonal
$\Delta : X \to X \times X$ is a regular immersion of codimension $\dim(X)$.

\label{lemma-tensor-coherent}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $\mathcal{F}$ and $\mathcal{G}$ are coherent $\mathcal{O}_X$-modules,
then $\text{Tor}_p^{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ is too.
\item If $L$ and $K$ are in $D^-_{\textit{Coh}}(\mathcal{O}_X)$, then
so is $L \otimes_{\mathcal{O}_X}^\mathbf{L} K$.
\end{enumerate}

\label{theorem-multiplicity-with-koszul}
\begin{reference}
\cite[Theorem 1 in part B of Chapter IV]{Serre_algebre_locale}
\end{reference}
Let $A$ be a Noetherian local ring. Let $I = (f_1, \ldots, f_r) \subset A$
be an ideal of definition. Let $M$ be a finite $A$-module. Then
$$
e_I(M, r) = \sum
(-1)^i\text{length}_A H_i(K_\bullet(f_1, \ldots, f_r) \otimes_A M)
$$

\label{proposition-positivity}
\begin{reference}
This is one of the main results of \cite{Serre_algebre_locale}.
\end{reference}
Let $X$ be a nonsingular variety. Let $V \subset X$ and
$W \subset Y$ be closed subvarieties which intersect properly.
Let $Z \subset V \cap W$ be an irreducible component.
Then $e(X, V \cdot W, Z) > 0$.

\label{lemma-projection-formula-flat}
\begin{reference}
See \cite[Chapter V, C), Section 7, formula (10)]{Serre_algebre_locale}
for a more general formula.
\end{reference}
Let $f : X \to Y$ be a flat proper morphism of nonsingular varieties.
Set $e = \dim(X) - \dim(Y)$. Let $\alpha$ be an $r$-cycle on $X$ and let
$\beta$ be a $s$-cycle on $Y$. Assume that $\alpha$ and $f^*(\beta)$ intersect
properly. Then $f_*(\alpha)$ and $\beta$ intersect properly and
$$
f_*(\alpha) \cdot \beta = f_*( \alpha \cdot f^*\beta)
$$

\label{lemma-make-family}
With notation as above. Let $X, Y$ be closed subvarieties of $\mathbf{P}(V)$
which intersect properly such that $X \not = \mathbf{P}(V)$ and
$X \cap Y \not = \emptyset$. For a general line $\ell \subset \mathbf{P}$
with $[\text{id}_V] \in \ell$ we have
\begin{enumerate}
\item $X \subset U_g$ for all $[g] \in \ell$,
\item $g(X)$ intersects $Y$ properly for all $[g] \in \ell$.
\end{enumerate}

\label{lemma-pullback-and-intersection-product}
Let $f : X \to Y$ be a morphism of nonsingular projective varieties.
The pullback map on chow groups satisfies:
\begin{enumerate}
\item $f^* : \CH^*(Y) \to \CH^*(X)$ is a ring map,
\item $(g \circ f)^* = f^* \circ g^*$ for a composable pair $f, g$,
\item the projection formula holds: $f_*(\alpha) \cdot \beta =
f_*( \alpha \cdot f^*\beta)$, and
\item if $f$ is flat then it agrees with the previous definition.
\end{enumerate}

\label{lemma-infinite-product}
\begin{slogan}
Infinite products of affine schemes exist and are affine.
\end{slogan}
Let $S$ be a scheme. Let $I$ be a set and for each $i \in I$
let $f_i : T_i \to S$ be an affine morphism. Then the
product $T = \prod T_i$ exists in the category of schemes
over $S$. In fact, we have
$$
T = \lim_{\{i_1, \ldots, i_n\} \subset I}
T_{i_1} \times_S \ldots \times_S T_{i_n}
$$
and the projection morphisms $T \to T_{i_1} \times_S \ldots \times_S T_{i_n}$
are affine.

\label{lemma-inverse-limit-top}
\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.

\label{lemma-limit-fibre-product-empty}
In Situation \ref{situation-descent}.
Suppose we are given an $i$ and a morphism $T \to S_i$ such that
\begin{enumerate}
\item $T \times_{S_i} S = \emptyset$, and
\item $T$ is quasi-compact.
\end{enumerate}
Then $T \times_{S_i} S_{i'} = \emptyset$ for all sufficiently large $i'$.

\label{lemma-limit-quasi-affine}
In Situation \ref{situation-descent} if $S$ is quasi-affine, then
for some $i_0 \in I$ the schemes $S_i$ for $i \geq i_0$ are quasi-affine.

\label{lemma-eventually-separated}
Let $S$ be a scheme. Let $X = \lim X_i$ be a directed
limit of schemes over $S$ with affine transition morphisms.
Assume
\begin{enumerate}
\item $S$ quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ separated.
\end{enumerate}
Then $X_i \to S$ is separated for all $i$ large enough.

\label{lemma-eventually-affine}
Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ affine.
\end{enumerate}
Then $X_i \to S$ is affine for $i$ large enough.

\label{lemma-approximate}
Let $S$ be a quasi-compact and quasi-separated scheme. Let $V \subset S$
be a quasi-compact open. Let $I$ be a directed set
and let $(V_i, f_{ii'})$ be an inverse system of schemes over $I$
with affine transition maps, with each $V_i$ of finite type over $\mathbf{Z}$,
and with $V = \lim V_i$. Then there exist
\begin{enumerate}
\item a directed set $J$,
\item an inverse system of schemes $(S_j, g_{jj'})$ over $J$,
\item an order preserving map $\alpha : J \to I$,
\item open subschemes $V'_j \subset S_j$, and
\item isomorphisms $V'_j \to V_{\alpha(j)}$
\end{enumerate}
such that
\begin{enumerate}
\item the transition morphisms $g_{jj'} : S_j \to S_{j'}$ are affine,
\item each $S_j$ is of finite type over $\mathbf{Z}$,
\item $g_{jj'}^{-1}(V'_{j'}) = V'_j$,
\item $S = \lim S_j$ and $V = \lim V'_j$, and
\item the diagrams
$$
\vcenter{
\xymatrix{
V \ar[d] \ar[rd] \\
V'_j \ar[r] & V_{\alpha(j)}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
V'_j \ar[r] \ar[d] & V_{\alpha(j)} \ar[d] \\
V'_{j'} \ar[r] & V_{\alpha(j')}
}
}
$$
are commutative.
\end{enumerate}

\label{proposition-approximate}
Let $S$ be a quasi-compact and quasi-separated scheme.
There exist a directed set $I$
and an inverse system of schemes $(S_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $S_i$ is of finite type over $\mathbf{Z}$, and
\item $S = \lim_i S_i$.
\end{enumerate}

\label{lemma-morphism-glueing-near-closed-point}
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$.
Assume $Y$ is locally of finite presentation over $S$.
Let $x \in X$ be a closed point such that
$U = X \setminus \{x\} \to X$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}) \setminus \{x\}$ there is
a bijection
$$
\left\{
\begin{matrix}
\text{morphisms }X \to Y\text{ over }S
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(a, b)\text{ where }
a : U \to Y\text{ and }b : \Spec(\mathcal{O}_{X, x}) \to Y\\
\text{ are morphisms over }S
\text{ which agree over }V
\end{matrix}
\right\}
$$

\label{lemma-relative-approximation}
Let $f : X \to S$ be a morphism of schemes. Assume that
\begin{enumerate}
\item $X$ is quasi-compact and quasi-separated, and
\item $S$ is quasi-separated.
\end{enumerate}
Then $X = \lim X_i$ is a limit of a directed system of schemes
$X_i$ of finite presentation over $S$ with affine transition morphisms
over $S$.

\label{lemma-descend-finite-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a finite morphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is finite.

\label{lemma-descend-unramified}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is unramified, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is unramified.

\label{lemma-descend-closed-immersion-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a closed immersion, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is a closed immersion.

\label{lemma-descend-separated-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If $f$ is separated, then $f_i$ is separated for some $i \geq 0$.

\label{lemma-descend-flat-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is flat,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is flat for some $i \geq 0$.

\label{lemma-descend-finite-locally-free}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is finite locally free (of degree $d$),
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is finite locally free (of degree $d$) for some $i \geq 0$.

\label{lemma-descend-smooth}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is smooth,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is smooth for some $i \geq 0$.

\label{lemma-descend-etale}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is \'etale,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is \'etale for some $i \geq 0$.

\label{lemma-descend-isomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an isomorphism, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an isomorphism for some $i \geq 0$.

\label{lemma-descend-open-immersion}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an open immersion, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an open immersion for some $i \geq 0$.

\label{lemma-descend-immersion}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an immersion, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is an immersion for some $i \geq 0$.

\label{lemma-descend-monomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a monomorphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is a monomorphism for some $i \geq 0$.

\label{lemma-descend-surjective}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is surjective, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is surjective.

\label{lemma-descend-syntomic}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is syntomic, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is syntomic.

\label{lemma-locally-finite-type-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes.
Assume:
\begin{enumerate}
\item The morphism $f$ is locally of finite type.
\item The scheme $X$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a morphism of finite presentation
$f' : X' \to S$ and an immersion $X \to X'$ of schemes over $S$.

\label{lemma-finite-type-closed-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes.
Assume:
\begin{enumerate}
\item The morphism $f$ is of locally of finite type.
\item The scheme $X$ is quasi-compact and quasi-separated, and
\item The scheme $S$ is quasi-separated.
\end{enumerate}
Then there exists a morphism of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{proposition-separated-closed-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is of finite type and separated, and
\item $S$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a separated morphism of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{lemma-finite-closed-in-finite-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is finite, and
\item $S$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a morphism which is finite and of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{lemma-finite-in-finite-and-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is finite, and
\item $S$ quasi-compact and quasi-separated.
\end{enumerate}
Then $X$ is a directed limit $X = \lim X_i$
where the transition maps are closed immersions and the objects
$X_i$ are finite and of finite presentation over $S$.

\label{lemma-affine}
\begin{slogan}
A scheme, admitting a finite surjective map from an affine scheme, is affine.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that $f$ is surjective and finite, and assume that $X$ is affine.
Then $S$ is affine.

\label{proposition-affine}
\begin{slogan}
A scheme admitting a surjective integral map from an affine scheme is affine.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes. Assume $X$ is affine
and that $f$ is surjective and universally closed\footnote{An integral
morphism is universally closed, see
Morphisms, Lemma \ref{morphisms-lemma-integral-universally-closed}.}.
Then $S$ is affine.

\label{lemma-affines-glued-in-closed-affine}
Let $X$ be a scheme which is set theoretically the union of
finitely many affine closed subschemes. Then $X$ is affine.

\label{lemma-eventually-proper}
\begin{slogan}
If the base change of a scheme to a limit is proper, then
already the base change is proper at a finite level.
\end{slogan}
Assumptions and notation as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is proper, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ is proper.

\label{lemma-essentially-finite-type-criterion-separation}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a morphism of schemes locally of finite type over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ separated,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists at most one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking there to be at most one dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-essentially-finite-type-criterion-proper}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a quasi-compact morphism of schemes locally
of finite type over $S$. The following are equivalent
\begin{enumerate}
\item $f$ proper,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists exactly one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking for the existence and uniqueness of the dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-descend-quasi-finite}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a quasi-finite morphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is quasi-finite.

\label{lemma-eventually-relative-dimension}
Assumptions and notation as in Situation \ref{situation-descent-property}.
Let $d \geq 0$. If
\begin{enumerate}
\item $f$ has relative dimension $\leq d$
(Morphisms, Definition \ref{morphisms-definition-relative-dimension-d}), and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ has relative dimension $\leq d$.

\label{lemma-descend-dimension-d}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ has relative dimension $d$, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$
has relative dimension $d$.

\label{lemma-top-cohomology-functor}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$. Assume
\begin{enumerate}
\item $X$ and $Y$ are quasi-compact and quasi-separated, and
\item $R^if_*\mathcal{F} = 0$ for $i > d$ and
every quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$.
\end{enumerate}
Then we have
\begin{enumerate}
\item[(a)] for any base change diagram
$$
\xymatrix{
X' \ar[d]_{f'} \ar[r]_{g'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
we have $R^if'_*\mathcal{F}' = 0$ for $i > d$ and any quasi-coherent
$\mathcal{O}_{X'}$-module $\mathcal{F}'$,
\item[(b)]
$R^df'_*(\mathcal{F}' \otimes_{\mathcal{O}_{X'}} (f')^*\mathcal{G}') =
R^df'_*\mathcal{F}' \otimes_{\mathcal{O}_{Y'}} \mathcal{G}'$
for any quasi-coherent $\mathcal{O}_{Y'}$-module $\mathcal{G}'$,
\item[(c)] formation of $R^df'_*\mathcal{F}'$ commutes with arbitrary
further base change (see proof for explanation).
\end{enumerate}

\label{lemma-proper-top-cohomology-finite-type}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$. Let $\mathcal{F}$
be an $\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $f$ is a proper morphism all of whose fibres have dimension $\leq d$,
\item $\mathcal{F}$ is a quasi-coherent $\mathcal{O}_X$-module of finite type.
\end{enumerate}
Then $R^df_*\mathcal{F}$ is a quasi-coherent $\mathcal{O}_X$-module
of finite type.

\label{lemma-proper-top-cohomology-finite-presentation}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $f$ is a proper morphism of finite presentation
all of whose fibres have dimension $\leq d$,
\item $\mathcal{F}$ is an $\mathcal{O}_X$-module of finite presentation.
\end{enumerate}
Then $R^df_*\mathcal{F}$ is an $\mathcal{O}_X$-module
of finite presentation.

\label{lemma-glueing-near-closed-point}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\begin{matrix}
X \to S\text{ of finite presentation}
\end{matrix}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

\label{lemma-glueing-near-closed-point-modules}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\mathcal{O}_S\text{-modules }\mathcal{F}\text{ of finite presentation}
\right\}
\longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\right\}
$$
where on the right hand side we consider triples
consisting of a $\mathcal{O}_U$-module $\mathcal{G}$ of
finite presentation, a $\mathcal{O}_{\Spec(\mathcal{O}_{S, s})}$-module
$\mathcal{H}$ of finite presentation, and an isomorphism
$\alpha : \mathcal{G}|_V \to \mathcal{H}|_V$ of
$\mathcal{O}_V$-modules.

\label{lemma-glueing-near-point}
Let $S$ be a scheme. Let $U \subset S$ be a retrocompact open.
Let $s \in S$ be a point in the complement of $U$. With
$V = \Spec(\mathcal{O}_{S, s}) \cap U$ there is
an equivalence of categories
$$
\colim_{s \in U' \supset U\text{ open}}
\left\{
\vcenter{
\xymatrix{
X \ar[d] \\
U'
}
}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the left hand side the vertical arrow is of finite
presentation and on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

\label{lemma-modifications}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ the base change functor
$$
\left\{
\begin{matrix}
f : X \to S\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{S, s})\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{lemma-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to S$ be quasi-separated and of finite type.
Then there exists an $i \in I$ and a diagram
\begin{equation}
\label{equation-good-diagram}
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_i
}
}
\end{equation}
such that $W \to S_i$ is of finite type and such that
the induced morphism $X \to S \times_{S_i} W$ is a closed
immersion.

\label{lemma-limit-from-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to S$ be quasi-separated and of finite type.
Given $i \in I$ and a diagram
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_i
}
}
$$
as in (\ref{equation-good-diagram}) for $i' \geq i$ let
$X_{i'}$ be the scheme theoretic image of $X \to S_{i'} \times_{S_i} W$.
Then $X = \lim_{i' \geq i} X_{i'}$.

\label{lemma-morphism-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $f : X \to Y$ be a morphism of schemes quasi-separated
and of finite type over $S$. Let
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_{i_1}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
Y \ar[r] \ar[d] & V \ar[d] \\
S \ar[r] & S_{i_2}
}
}
$$
be diagrams as in (\ref{equation-good-diagram}). Let
$X = \lim_{i \geq i_1} X_i$ and
$Y = \lim_{i \geq i_2} Y_i$ be the corresponding
limit descriptions as in Lemma \ref{lemma-limit-from-good-diagram}.
Then there exists an $i_0 \geq \max(i_1, i_2)$ and a morphism
$$
(f_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}
$$
of inverse systems over $(S_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} f_i$.
If $(g_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}$
is a second morphism of inverse systems over $(S_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} g_i$
then $f_i = g_i$ for all $i \gg i_0$.

\label{lemma-depth-2-connected-punctured-spectrum}
\begin{reference}
\cite[Proposition 2.1]{Hartshorne-connectedness}
\end{reference}
\begin{slogan}
Hartshorne's connectedness
\end{slogan}
Let $A$ be a Noetherian local ring of depth $\geq 2$.
Then the punctured spectra of $A$, $A^h$, and $A^{sh}$ are connected.

\label{lemma-catenary-S2-equidimensional}
\begin{reference}
\cite[IV Corollary 5.10.9]{EGA}
\end{reference}
Let $A$ be a Noetherian local ring which is catenary and $(S_2)$.
Then $\Spec(A)$ is equidimensional.

\label{lemma-cd-sum}
Let $I, J \subset A$ be finitely generated ideals of a ring $A$.
Then $\text{cd}(A, I + J) \leq \text{cd}(A, I) + \text{cd}(A, J)$.

\label{lemma-cd-local}
Let $I \subset A$ be a finitely generated ideal of a ring $A$.
Then $\text{cd}(A, I) = \max \text{cd}(A_\mathfrak p, I_\mathfrak p)$.

\label{lemma-cd-is-one}
Let $I \subset A$ be a finitely generated ideal of a ring $A$. If
$\text{cd}(A, I) = 1$ then $\Spec(A) \setminus V(I)$ is nonempty affine.

\label{lemma-cd-maximal}
Let $(A, \mathfrak m)$ be a Noetherian local ring of dimension $d$.
Then $H^d_\mathfrak m(A)$ is nonzero and $\text{cd}(A, \mathfrak m) = d$.

\label{lemma-support}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. For an $A$-module $M$ the following are equivalent
\begin{enumerate}
\item $H^0_T(M) = M$, and
\item $\text{Supp}(M) \subset T$.
\end{enumerate}
The category of such $A$-modules is a Serre subcategory
of the category $A$-modules closed under direct sums.

\label{lemma-check-finiteness-local-cohomology-by-annihilator}
\begin{reference}
\cite[Lemma 3]{Faltings-annulators}
\end{reference}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $M$ be a finite $A$-module. Let $n \geq 0$.
The following are equivalent
\begin{enumerate}
\item $H^i_T(M)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(M)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(M)$ for $i \leq n$.
\end{enumerate}

\label{lemma-check-finiteness-local-cohomology-locally}
\begin{reference}
This is a special case of \cite[Satz 1]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring, $I \subset A$ an ideal, $M$ a finite
$A$-module, and $n \geq 0$ an integer. Let $Z = V(I)$.
The following are equivalent
\begin{enumerate}
\item the modules $H^i_Z(M)$ are finite for $i \leq n$, and
\item for all $\mathfrak p \in \Spec(A)$ the modules
$H^i_Z(M)_\mathfrak p$, $i \leq n$ are finite $A_\mathfrak p$-modules.
\end{enumerate}

[Koll\'ar]
\label{proposition-kollar}
\begin{reference}
See \cite{k-coherent} and see \cite[IV, Proposition 7.2.2]{EGA}
for a special case.
\end{reference}
\begin{slogan}
Weak analogue of Hartogs' Theorem: On Noetherian schemes, the
restriction of a coherent sheaf to an open set with complement
of codimension 2 in the sheaf's support, is coherent.
\end{slogan}
Let $j : U \to X$ be an open immersion of locally Noetherian schemes
with complement $Z$. Let $\mathcal{F}$ be a coherent $\mathcal{O}_U$-module.
The following are equivalent
\begin{enumerate}
\item $j_*\mathcal{F}$ is coherent,
\item for $x \in \text{Ass}(\mathcal{F})$ and
$z \in Z \cap \overline{\{x\}}$ and any associated prime
$\mathfrak p$ of the completion $\mathcal{O}_{\overline{\{x\}}, z}^\wedge$
we have $\dim(\mathcal{O}_{\overline{\{x\}}, z}^\wedge/\mathfrak p) \geq 2$.
\end{enumerate}

\label{lemma-local-annihilator}
\begin{reference}
This is a special case of
\cite[Satz 1]{Faltings-annulators}.
\end{reference}
Let $A$ be a Gorenstein Noetherian local ring. Let $I \subset A$
be an ideal and set $Z = V(I) \subset \Spec(A)$.
Let $M$ be a finite $A$-module. Let $s = s_{A, I}(M)$ as in
(\ref{equation-cutoff}). Then $H^i_Z(M)$ is finite for $i < s$,
but $H^s_Z(M)$ is not finite.

\label{theorem-finiteness}
\begin{reference}
This is a special case of \cite[Satz 2]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Set $Z = V(I) \subset \Spec(A)$. Let $M$ be a finite $A$-module.
Set $s = s_{A, I}(M)$ as in (\ref{equation-cutoff}).
Assume that
\begin{enumerate}
\item $A$ is universally catenary,
\item the formal fibres of the local rings of $A$ are Cohen-Macaulay.
\end{enumerate}
Then $H^i_Z(M)$ is finite for $0 \leq i < s$ and
$H^s_Z(M)$ is not finite.

\label{lemma-annihilate-Hp}
\begin{reference}
\cite[Lemma 1.9]{Bhatt-local}
\end{reference}
Let $A$ be a ring and let $J \subset I \subset A$ be finitely generated ideals.
Let $p \geq 0$ be an integer. Set $U = \Spec(A) \setminus V(I)$. If
$H^p(U, \mathcal{O}_U)$ is annihilated by $J^n$ for some $n$, then
$H^p(U, \mathcal{F})$ annihilated by $J^m$ for some $m = m(\mathcal{F})$
for every finite locally free $\mathcal{O}_U$-module $\mathcal{F}$.

\label{lemma-check-finiteness-local-cohomology-by-annihilator-complex}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $K$ be an object of $D_{\textit{Coh}}^+(A)$.
Let $n \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $H^i_T(K)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(K)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(K)$ for $i \leq n$.
\end{enumerate}

\label{proposition-Hartshorne-Lichtenbaum-vanishing}
\begin{reference}
\cite[Theorem 3.1]{CD}
\end{reference}
Let $A$ be a Noetherian local ring with completion $A^\wedge$.
Let $I \subset A$ be an ideal such that
$$
\dim V(IA^\wedge + \mathfrak p) \geq 1
$$
for every minimal prime $\mathfrak p \subset A^\wedge$ of dimension $\dim(A)$.
Then $\text{cd}(A, I) < \dim(A)$.

\label{lemma-1}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 1 page 299]{MatCA}.
\end{reference}
Let $A$ be a ring. If $f_1, \ldots, f_{r - 1}, f_rg_r$
are independent, then $f_1, \ldots, f_r$ are independent.

\label{lemma-2}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 2 page 300]{MatCA}.
\end{reference}
Let $A$ be a ring. If $f_1, \ldots, f_{r - 1}, f_rg_r$
are independent and if the $A$-module
$A/(f_1, \ldots, f_{r - 1}, f_rg_r)$ has finite length, then
\begin{align*}
& \text{length}_A(A/(f_1, \ldots, f_{r - 1}, f_rg_r)) \\
& =
\text{length}_A(A/(f_1, \ldots, f_{r - 1}, f_r)) +
\text{length}_A(A/(f_1, \ldots, f_{r - 1}, g_r))
\end{align*}

\label{lemma-3}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 3 page 300]{MatCA}.
\end{reference}
Let $(A, \mathfrak m)$ be a local ring. If $\mathfrak m = (x_1, \ldots, x_r)$
and $x_1^{e_1}, \ldots, x_r^{e_r}$ are independent for some $e_i > 0$,
then $\text{length}_A(A/(x_1^{e_1}, \ldots, x_r^{e_r})) = e_1\ldots e_r$.

[Kunz]
\label{lemma-frobenius-flat-regular}
\begin{reference}
\cite{Kunz-flat}
\end{reference}
Let $p$ be a prime number.
Let $A$ be a Noetherian ring with $p = 0$.
The following are equivalent
\begin{enumerate}
\item $A$ is regular, and
\item $F : A \to A$, $a \mapsto a^p$ is flat.
\end{enumerate}

\label{lemma-recurring}
\begin{reference}
\cite[Theorem I]{Taussky}
\end{reference}
Let $A = (a_{ij})$ be a complex $n \times n$ matrix.
\begin{enumerate}
\item If $|a_{ii}| > \sum_{j \not = i} |a_{ij}|$ for each $i$, then
$\det(A)$ is nonzero.
\item If there exists a real vector $m = (m_1, \ldots, m_n)$
with $m_i > 0$ such that $|a_{ii} m_i| > \sum_{j \not = i} |a_{ij}m_j|$
for each $i$, then $\det(A)$ is nonzero.
\end{enumerate}

\label{lemma-recurring-real}
Let $A = (a_{ij})$ be a real $n \times n$ matrix with
$a_{ij} \geq 0$ for $i \not = j$. Let $m = (m_1, \ldots, m_n)$ be a real
vector with $m_i > 0$. For $I \subset \{1, \ldots, n\}$ let
$x_I \in \mathbf{R}^n$
be the vector whose $i$th coordinate is $m_i$ if $i \in I$
and $0$ otherwise. If
\begin{equation}
\label{equation-ineq}
-a_{ii}m_i \geq \sum\nolimits_{j \not = i} a_{ij}m_j
\end{equation}
for each $i$, then $\Ker(A)$ is the vector space
spanned by the vectors $x_I$ such that
\begin{enumerate}
\item $a_{ij} = 0$ for $i \in I$, $j \not \in I$, and
\item equality holds in (\ref{equation-ineq}) for $i \in I$.
\end{enumerate}

\label{definition-genus}
We say $n, m_i, a_{ij}, w_i, g_i$ is a {\it numerical type of genus $g$}
if $g = 1 + \sum m_i(w_i(g_i - 1) - \frac{1}{2} a_{ii})$ is the integer
from Lemma \ref{lemma-genus}.

\label{lemma-diagonal-negative}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type of genus $g$.
If $n > 1$, then $a_{ii} < 0$ for all $i$.

\label{definition-type-minus-one}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type.
We say $i$ is a {\it $(-1)$-index} if $g_i = 0$ and $a_{ii} = -w_i$.

\label{lemma-non-irreducible-minimal-type-genus-at-least-one}
If $n, m_i, a_{ij}, w_i, g_i$ is a minimal numerical type
with $n > 1$, then $g \geq 1$.

\label{lemma-genus-nonnegative}
If $n, m_i, a_{ij}, w_i, g_i$ is a minimal numerical type
with $n > 1$, then $g \geq g_{top}$.

\label{definition-type-minus-two}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type of genus $g$.
We say $i$ is a {\it $(-2)$-index} if $g_i = 0$ and $a_{ii} = -2w_i$.

\label{lemma-picard-rank-1}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
The Picard group of $T$ is a finitely generated abelian group of rank $1$.

\label{lemma-picard-T-and-A}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
Then $\Pic(T) \subset \Coker(A)$ where $A = (a_{ij})$.

\label{lemma-picard-group-genus-nonpositive}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
If the genus $g$ of $T$ is $\leq 0$, then $\Pic(T) = \mathbf{Z}$.

\label{lemma-bound-wm}
Fix $g \geq 2$. For every minimal numerical type $n, m_i, a_{ij}, w_i, g_i$
of genus $g$ we have $m_i|a_{ij}| \leq 768g$.

\label{definition-minimal-model}
Let $C$ be a smooth projective curve over $K$ with
$H^0(C, \mathcal{O}_C) = K$. A {\it minimal model}
will be a regular, proper model $X$ for $C$ such that
$X$ does not contain an exceptional curve of the first kind
(Resolution of Surfaces, Section \ref{resolve-section-minus-one}).

\label{proposition-exists-minimal-model}
Let $C$ be a smooth projective curve over $K$ with
$H^0(C, \mathcal{O}_C) = K$. A minimal model exists.

\label{lemma-divisor-special-fiber}
Let $X$ be a regular model of a smooth curve $C$ over $K$.
\begin{enumerate}
\item the special fibre $X_k$ is an effective Cartier divisor on $X$,
\item each irreducible component $C_i$ of $X_k$ is an effective
Cartier divisor on $X$,
\item $X_k = \sum m_i C_i$ (sum of effective Cartier divisors)
where $m_i$ is the multiplicity of $C_i$ in $X_k$,
\item $\mathcal{O}_X(X_k) \cong \mathcal{O}_X$.
\end{enumerate}

\label{lemma-gorenstein}
Let $X$ be a regular model of a smooth curve $C$ over $K$. Then
\begin{enumerate}
\item $X \to \Spec(R)$ is a Gorenstein morphism of relative dimension $1$,
\item each of the irreducible components $C_i$ of $X_k$ is Gorenstein.
\end{enumerate}

\label{lemma-properties-form}
In Situation \ref{situation-regular-model} the symmetric bilinear form
(\ref{equation-form}) has the following properties
\begin{enumerate}
\item $(C_i \cdot C_j) \geq 0$ if $i \not = j$ with equality if and only
if $C_i \cap C_j = \emptyset$,
\item $(\sum m_i C_i \cdot C_j) = 0$,
\item there is no nonempty proper subset $I \subset \{1, \ldots, n\}$
such that $(C_i \cdot C_j) = 0$ for $i \in I$, $j \not \in I$.
\item $(\sum a_i C_i \cdot \sum a_i C_i) \leq 0$ with equality if and
only if there exists a $q \in \mathbf{Q}$ such that $a_i = qm_i$
for $i = 1, \ldots, n$,
\end{enumerate}

\label{lemma-regular-model-field}
\begin{reference}
\cite[Lemma 2.6]{Artin-Winters}
\end{reference}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
Let $D = \sum (m_i/d) C_i$ as an effective Cartier divisor. Then there exists
a sequence of effective Cartier divisors
$$
(X_k)_{red} = Z_0 \subset Z_1 \subset \ldots \subset Z_m = D
$$
such that $Z_j = Z_{j - 1} + C_{i_j}$ for some $i_j \in \{1, \ldots, n\}$
for $j = 1, \ldots, m$ and such that $H^0(Z_j, \mathcal{O}_{Z_j})$
is a field finite over $k$ for $j = 0, \ldots m$.

\label{lemma-regular-model-genus}
\begin{reference}
\cite[Lemma 2.6]{Artin-Winters}
\end{reference}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
Let $D = \sum (m_i/d) C_i$ as an effective Cartier divisor on $X$. Then
$$
1 - g_C = d [\kappa : k] (1 - g_D)
$$
where $g_C$ is the genus of $C$, $g_D$ is the genus of $D$, and
$\kappa = H^0(D, \mathcal{O}_D)$.

\label{lemma-numerical-type-minimal-model}
In Situation \ref{situation-regular-model}. The following
are equivalent
\begin{enumerate}
\item $X$ is a minimal model, and
\item the numerical type associated to $X$ is minimal.
\end{enumerate}

\label{lemma-equality-genus-reduction-bigger-than}
If equality holds in Lemma \ref{lemma-genus-reduction-bigger-than}
then
\begin{enumerate}
\item the unique irreducible component of $X_k$ containing
$x$ is a smooth projective geometrically irreducible curve
over $k$,
\item if $C \subset X_k$ is another irreducible component, then
$\kappa = H^0(C, \mathcal{O}_C)$ is a finite separable extension
of $k$, $C$ has a $\kappa$-rational point, and $C$ is smooth over $\kappa$
\end{enumerate}

\label{lemma-characterize-trivial}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
If $\mathcal{L}$ is an invertible $\mathcal{O}_X$-module which
\begin{enumerate}
\item restricts to the trivial invertible module on $C$, and
\item has degree $0$ on each $C_i$,
\end{enumerate}
then $\mathcal{L}^{\otimes d} \cong \mathcal{O}_X$.

\label{lemma-good}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$.
The following are equivalent
\begin{enumerate}
\item there exists a proper smooth model for $C$,
\item there exists a minimal model for $C$ which is smooth over $R$,
\item any minimal model is smooth over $R$.
\end{enumerate}

\label{lemma-tensor-product-globally-generated}
\begin{slogan}
The tensor product of globally generated sheaves of modules is
globally generated.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$, $\mathcal{G}$ be sheaves of $\mathcal{O}_X$-modules.
If $\mathcal{F}$ and $\mathcal{G}$ are generated by global sections
then so is $\mathcal{F} \otimes_{\mathcal{O}_X} \mathcal{G}$.

\label{lemma-support-sheaf-rings-closed}
Let $X$ be a topological space.
The support of a sheaf of rings is closed.

\label{lemma-support-finite-type-closed}
\begin{slogan}
Over any ringed space, sheaves of modules of finite type have closed support.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_X$-modules.
If $\mathcal{F}$ is of finite type then support of $\mathcal{F}$ is closed.

\label{definition-sheaf-associated}
In the situation of Lemma \ref{lemma-construct-quasi-coherent-sheaves}
we say $\mathcal{F}_M$ is the {\it sheaf associated to the module $M$
and the ring map $\alpha$}. If $R = \Gamma(X, \mathcal{O}_X)$
and $\alpha = \text{id}_R$ we simply say $\mathcal{F}_M$ is the
{\it sheaf associated to the module $M$}.

\label{lemma-kernel-surjection-finite-free-onto-finite-presentation}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module of finite presentation.
\begin{enumerate}
\item If $\psi : \mathcal{O}_X^{\oplus r} \to \mathcal{F}$ is a surjection,
then $\Ker(\psi)$ is of finite type.
\item If $\theta : \mathcal{G} \to \mathcal{F}$ is surjective with
$\mathcal{G}$ of finite type, then $\Ker(\theta)$ is of finite type.
\end{enumerate}

\label{definition-coherent}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_X$-modules.
We say that $\mathcal{F}$ is a {\it coherent $\mathcal{O}_X$-module}
if the following two conditions hold:
\begin{enumerate}
\item $\mathcal{F}$ is of finite type, and
\item for every open $U \subset X$ and every finite
collection $s_i \in \mathcal{F}(U)$, $i = 1, \ldots, n$
the kernel of the associated map
$\bigoplus_{i = 1, \ldots, n} \mathcal{O}_U \to \mathcal{F}|_U$
is of finite type.
\end{enumerate}
The category of coherent $\mathcal{O}_X$-modules is denoted
$\textit{Coh}(\mathcal{O}_X)$.

\label{lemma-module-quotient-flat}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item Any sheaf of $\mathcal{O}_X$-modules is a quotient of
a direct sum $\bigoplus j_{U_i!}\mathcal{O}_{U_i}$.
\item Any $\mathcal{O}_X$-module is a quotient of
a flat $\mathcal{O}_X$-module.
\end{enumerate}

\label{lemma-flat-eq}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $\mathcal{F}$ be a flat
$\mathcal{O}_X$-module. Let $U \subset X$ be open and let
$$
\mathcal{O}_U \xrightarrow{(f_1, \ldots, f_n)}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. For every $x \in U$ there
exists an open neighbourhood $V \subset U$ of $x$ and a factorization
$$
\mathcal{O}_V^{\oplus n}
\xrightarrow{A}
\mathcal{O}_V^{\oplus m} \xrightarrow{(t_1, \ldots, t_m)}
\mathcal{F}|_V
$$
of $(s_1, \ldots, s_n)|_V$ such that $A \circ (f_1, \ldots, f_n)|_V = 0$.

\label{lemma-filtered-colimit-constructibles}
Let $X$ be a topological space. Let $\mathcal{B}$ be a basis for the
topology of $X$ and assume that each $U \in \mathcal{B}$ is quasi-compact.
Then every sheaf of sets on $X$ is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible-sets}
\text{Coequalizer}\left(
\xymatrix{
\coprod\nolimits_{b = 1, \ldots, m} j_{V_b!}\underline{S_b}
\ar@<1ex>[r] \ar@<-1ex>[r] &
\coprod\nolimits_{a = 1, \ldots, n} j_{U_a!}\underline{S_a}
}
\right)
\end{equation}
with $U_a$ and $V_b$ in $\mathcal{B}$ and $S_a$ and $S_b$ finite sets.

\label{definition-flat-morphism}
Let $f : X \to Y$ be a morphism of ringed spaces.
Let $x \in X$. We say $f$ is {\it flat at $x$}
if the map of rings $\mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$ is flat.
We say $f$ is {\it flat} if $f$ is flat at every $x \in X$.

\label{definition-flat-module}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$ be a morphism of
ringed spaces. Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_X$-modules.
\begin{enumerate}
\item We say that $\mathcal{F}$ is {\it flat over $Y$ at a point $x \in X$}
if the stalk $\mathcal{F}_x$ is a flat $\mathcal{O}_{Y, f(x)}$-module.
\item We say that $\mathcal{F}$ is {\it flat over $Y$} if
$\mathcal{F}$ is flat over $Y$ at every point $x$ of $X$.
\end{enumerate}

\label{lemma-constructions-invertible}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item If $\mathcal{L}$, $\mathcal{N}$ are invertible
$\mathcal{O}_X$-modules, then so is
$\mathcal{L} \otimes_{\mathcal{O}_X} \mathcal{N}$.
\item If $\mathcal{L}$ is an invertible $\mathcal{O}_X$-module, then so is
$\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X)$ and the evaluation map
$\mathcal{L} \otimes_{\mathcal{O}_X}
\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X) \to \mathcal{O}_X$
is an isomorphism.
\end{enumerate}

\label{definition-differentials}
Let $(f, f^\sharp) : (X, \mathcal{O}_X) \to (S, \mathcal{O}_S)$
be a morphism of ringed spaces.
\begin{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_X$-module. An {\it $S$-derivation}
into $\mathcal{F}$ is a $f^{-1}\mathcal{O}_S$-derivation, or more
precisely a $f^\sharp$-derivation in the sense of
Definition \ref{definition-derivation}.
We denote $\text{Der}_S(\mathcal{O}_X, \mathcal{F})$
the set of $S$-derivations into $\mathcal{F}$.
\item The {\it sheaf of differentials $\Omega_{X/S}$ of $X$ over $S$}
is the module of differentials $\Omega_{\mathcal{O}_X/f^{-1}\mathcal{O}_S}$
endowed with its universal
$S$-derivation $\text{d}_{X/S} : \mathcal{O}_X \to \Omega_{X/S}$.
\end{enumerate}

\label{lemma-NL-up-to-qis}
In the situation above there is a canonical isomorphism
$\NL(\alpha) = \NL_{\mathcal{B}/\mathcal{A}}$ in $D(\mathcal{B})$.

\label{lemma-curves-diagonal-separated-fp}
The diagonal of $\Curvesstack$ is separated
and of finite presentation.

\label{lemma-curves-qs-lfp}
The morphism $\Curvesstack \to \Spec(\mathbf{Z})$ is quasi-separated and
locally of finite presentation.

\label{lemma-DM-curves}
There exist an open substack $\Curvesstack^{DM} \subset \Curvesstack$
with the following properties
\begin{enumerate}
\item $\Curvesstack^{DM} \subset \Curvesstack$ is the maximal
open substack which is DM,
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{DM}$,
\item the group algebraic space $\mathit{Aut}_S(X)$ is unramified over $S$,
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{DM}$,
\item $\mathit{Aut}(X)$ is geometrically reduced over $k$ and
has dimension $0$,
\item $\mathit{Aut}(X) \to \Spec(k)$ is unramified.
\end{enumerate}
\end{enumerate}

\label{lemma-CM-curves}
There exist an open substack $\Curvesstack^{CM} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item the morphism $X \to S$ is Cohen-Macaulay,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item $X$ is Cohen-Macaulay.
\end{enumerate}
\end{enumerate}

\label{lemma-CM-1-curves}
There exist an open substack $\Curvesstack^{CM, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item the morphism $X \to S$ is Cohen-Macaulay and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item $X$ is Cohen-Macaulay and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-pre-genus-curves}
There exist an open substack $\Curvesstack^{h0, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds
after arbitrary base change, and the fibres of $f$ have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $H^0(X, \mathcal{O}_X) = k$ and $\dim(X) = 1$.
\end{enumerate}
\end{enumerate}

\label{lemma-pre-genus-in-CM-1}
We have $\Curvesstack^{h0, 1} \subset \Curvesstack^{CM, 1}$
as open substacks of $\Curvesstack$.

\label{lemma-geometrically-reduced-curves}
There exist an open substack $\Curvesstack^{geomred} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item the fibres of the morphism $X \to S$ are geometrically reduced
(More on Morphisms of Spaces, Definition
\ref{spaces-more-morphisms-definition-geometrically-reduced-fibre}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item $X$ is geometrically reduced over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-geomred-in-CM}
We have $\Curvesstack^{geomred} \subset \Curvesstack^{CM}$
as open substacks of $\Curvesstack$.

\label{lemma-geometrically-reduced-connected-1-curves}
There exist an open substack $\Curvesstack^{grc, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item the geometric fibres of the morphism $X \to S$ are
reduced, connected, and have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item $X$ is geometrically reduced, geometrically connected,
and has dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-gorenstein-curves}
There exist an open substack $\Curvesstack^{Gorenstein} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item the morphism $X \to S$ is Gorenstein,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item $X$ is Gorenstein.
\end{enumerate}
\end{enumerate}

\label{lemma-gorenstein-1-curves}
There exist an open substack
$\Curvesstack^{Gorenstein, 1} \subset \Curvesstack$ such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item the morphism $X \to S$ is Gorenstein and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item $X$ is Gorenstein and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-lci-curves}
There exist an open substack $\Curvesstack^{lci} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{lci}$,
\item $X \to S$ is a local complete intersection morphism, and
\item $X \to S$ is a syntomic morphism.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{lci}$,
\item $X$ is a local complete intersection over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-isolated-sings-curves}
There exist an open substack
$\Curvesstack^{+} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{+}$,
\item the singular locus of $X \to S$ endowed
with any/some closed subspace structure is finite over $S$.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{+}$,
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
\end{enumerate}

\label{lemma-in-smooth-locus}
In the situation above the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through the open where $\Curvesstack \to \Spec(\mathbf{Z})$ is smooth,
\item the deformation category $\Deformationcategory_X$ is unobstructed.
\end{enumerate}

\label{lemma-smooth-curves}
There exist an open substacks
$$
\Curvesstack^{smooth, 1} \subset \Curvesstack^{smooth} \subset \Curvesstack
$$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{smooth}$, resp.\ $\Curvesstack^{smooth, 1}$,
\item $f$ is smooth, resp.\ smooth of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{smooth}$, resp.\ $\Curvesstack^{smooth, 1}$,
\item $X$ is smooth over $k$, resp.\ $X$ is smooth over $k$ and
$X$ is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-smooth-curves-h0}
There exist an open substack
$\Curvesstack^{smooth, h0} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{smooth}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds after any base change,
and $f$ is smooth of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{smooth, h0}$,
\item $X$ is smooth, $\dim(X) = 1$, and $k = H^0(X, \mathcal{O}_X)$,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically connected,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically integral, and
\item $X_{\overline{k}}$ is a smooth curve.
\end{enumerate}
\end{enumerate}

\label{definition-deligne-mumford-smooth}
\begin{reference}
\cite{DM}
\end{reference}
We denote $\mathcal{M}$ and we name it the
{\it moduli stack of smooth proper curves}
the algebraic stack
$\Curvesstack^{smooth, h0}$ parametrizing families of curves
introduced in Lemma \ref{lemma-smooth-curves-h0}.
For $g \geq 0$ we denote $\mathcal{M}_g$ and we name it the
{\it moduli stack of smooth proper curves of genus $g$}
the algebraic stack introduced in
Lemma \ref{lemma-smooth-one-piece-per-genus}.

\label{lemma-nodal-curves}
There exist an open substack $\Curvesstack^{nodal} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item $f$ is at-worst-nodal of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item the singularities of $X$ are at-worst-nodal and $X$
is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-prestable-curves}
There exist an open substack $\Curvesstack^{prestable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}$,
\item $X \to S$ is a prestable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
and $k = H^0(X, \mathcal{O}_X)$.
\end{enumerate}
\end{enumerate}

\label{lemma-prestable-one-piece-per-genus}
There is a decomposition into open and closed substacks
$$
\Curvesstack^{prestable} = \coprod\nolimits_{g \geq 0}
\Curvesstack^{prestable}_g
$$
where each $\Curvesstack^{prestable}_g$ is characterized as follows:
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}_g$,
\item $X \to S$ is a prestable family of curves and
$R^1f_*\mathcal{O}_X$ is a locally free $\mathcal{O}_S$-module of rank $g$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}_g$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and the genus of $X$ is $g$.
\end{enumerate}
\end{enumerate}

\label{lemma-semistable}
Let $f : X \to S$ be a prestable family of curves of genus $g \geq 1$.
Let $s \in S$ be a point of the base scheme. Let $m \geq 2$.
The following are equivalent
\begin{enumerate}
\item $X_s$ does not have a rational tail
(Algebraic Curves, Example \ref{curves-example-rational-tail}), and
\item $f^*f_*\omega_{X/S}^{\otimes m} \to \omega_{X/S}^{\otimes m}$,
is surjective over $f^{-1}(U)$ for some $s \in U \subset S$ open.
\end{enumerate}

\label{definition-semistable}
Let $f : X \to S$ be a family of curves.
We say $f$ is a {\it semistable family of curves} if
\begin{enumerate}
\item $X \to S$ is a prestable family of curves, and
\item $X_s$ has genus $\geq 1$ and
does not have a rational tail for all $s \in S$.
\end{enumerate}

\label{lemma-semistable-curves}
There exist an open substack $\Curvesstack^{semistable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{semistable}$,
\item $X \to S$ is a semistable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{semistable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, the genus of $X$ is $\geq 1$, and
$X$ has no rational tails,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and $\omega_{X_s}^{\otimes m}$ is
globally generated for $m \geq 2$.
\end{enumerate}
\end{enumerate}

\label{definition-stable}
Let $f : X \to S$ be a family of curves.
We say $f$ is a {\it stable family of curves} if
\begin{enumerate}
\item $X \to S$ is a prestable family of curves, and
\item $X_s$ has genus $\geq 2$ and does not have a rational tails
or bridges for all $s \in S$.
\end{enumerate}

\label{lemma-stable-curves}
There exist an open substack $\Curvesstack^{stable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{stable}$,
\item $X \to S$ is a stable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{stable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, the genus of $X$ is $\geq 2$, and
$X$ has no rational tails or bridges,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and $\omega_{X_s}$ is ample.
\end{enumerate}
\end{enumerate}

\label{definition-deligne-mumford}
\begin{reference}
\cite{DM}
\end{reference}
We denote $\overline{\mathcal{M}}$ and we name the
{\it moduli stack of stable curves} the algebraic stack
$\Curvesstack^{stable}$ parametrizing stable families of curves
introduced in Lemma \ref{lemma-stable-curves}.
For $g \geq 2$ we denote $\overline{\mathcal{M}}_g$ and we name the
{\it moduli stack of stable curves of genus $g$}
the algebraic stack introduced in Lemma \ref{lemma-stable-one-piece-per-genus}.

\label{lemma-stable-reduction}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with
$K = H^0(C, \mathcal{O}_C)$ having genus $g \geq 2$.
The following are equivalent
\begin{enumerate}
\item $C$ has semistable reduction
(Semistable Reduction, Definition \ref{models-definition-semistable}), or
\item there is a stable family of curves over $R$ with generic fibre $C$.
\end{enumerate}

\label{theorem-stable-reduction}
\begin{reference}
\cite[Corollary 2.7]{DM}
\end{reference}
Let $R$ be a discrete valuation ring with fraction field $K$. Let $C$ be a
smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$
and genus $g \geq 2$. Then
\begin{enumerate}
\item there exists an extension of discrete valuation rings $R \subset R'$
inducing a finite separable extension of fraction fields $K'/K$ and
a stable family of curves $Y \to \Spec(R')$ of genus $g$ with
$Y_{K'} \cong C_{K'}$ over $K'$, and
\item there exists a finite separable extension $L/K$ and a stable
family of curves $Y \to \Spec(A)$ of genus $g$ where $A \subset L$
is the integral closure of $R$ in $L$ such that
$Y_L \cong C_L$ over $L$.
\end{enumerate}

\label{lemma-coherent-diagonal-affine-fp}
The diagonal of $\Cohstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-coherent-qs-lfp}
The morphism $\Cohstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-hilb-diagonal-closed}
The diagonal of $\Hilbfunctor_{X/B} \to B$ is a closed immersion
of finite presentation.

\label{lemma-hilb-s-lfp}
The morphism $\Hilbfunctor_{X/B} \to B$ is separated
and locally of finite presentation.

\label{lemma-pic-diagonal-affine-fp}
The diagonal of $\Picardstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-pic-qs-lfp}
The morphism $\Picardstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-pic-gerbe-over-pic-functor}
The morphism $\Picardstack_{X/B} \to \Picardfunctor_{X/B}$
turns the Picard stack into a gerbe over the Picard functor.

\label{lemma-pic-functor-qs-lfp}
The morphism $\Picardfunctor_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-Mor-diagonal-closed}
The diagonal of $\mathit{Mor}_B(Y, X) \to B$ is a closed immersion
of finite presentation.

\label{lemma-Mor-s-lfp}
The morphism $\mathit{Mor}_B(Y, X) \to B$ is separated
and locally of finite presentation.

\label{lemma-polarized-diagonal-separated-fp}
The diagonal of $\Polarizedstack$ is separated
and of finite presentation.

\label{lemma-polarized-qs-lfp}
The morphism $\Polarizedstack \to \Spec(\mathbf{Z})$ is quasi-separated and
locally of finite presentation.

\label{lemma-complexes-diagonal-affine-fp}
The diagonal of $\Complexesstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-complexes-qs-lfp}
The morphism $\Complexesstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{definition-stably-free}
Let $R$ be a ring. 
\begin{enumerate}
\item Two modules $M$, $N$ over $R$ are said to be
{\it stably isomorphic} if there exist $n, m \geq 0$ such
that $M \oplus R^{\oplus m} \cong N \oplus R^{\oplus n}$
as $R$-modules.
\item A module $M$ is {\it stably free} if it is stably isomorphic
to a free module.
\end{enumerate}

\label{lemma-fibre-product-finite-type}
Let $R$ be a ring. Let $A \to B$ and $C \to B$ be $R$-algebra maps.
Assume
\begin{enumerate}
\item $R$ is Noetherian,
\item $A$, $B$, $C$ are of finite type over $R$,
\item $A \to B$ is surjective, and
\item $B$ is finite over $C$.
\end{enumerate}
Then $A \times_B C$ is of finite type over $R$.

\label{lemma-fibre-product-integral}
In Situation \ref{situation-module-over-fibre-product}
if $B \to A$ is integral, then $B' \to A'$ is integral.

\label{lemma-relative-surjection-ideals}
In Situation \ref{situation-relative-module-over-fibre-product}
the map $JD' \to IC'$ is surjective where $J = \Ker(B' \to B)$.

\label{lemma-relative-finitely-presented-module-over-fibre-product}
Let $A, A', B, B', C, C', D, D', I, M', M, N, \varphi$ be as in
Lemma \ref{lemma-relative-module-over-fibre-product}. If
\begin{enumerate}
\item $N$ is finitely presented over $D$ and flat over $B$,
\item $M'$ finitely presented over $C'$ and flat over $A'$, and
\item the ring map $B' \to D'$ factors as $B' \to D'' \to D'$
with $B' \to D''$ flat and $D'' \to D'$ of finite presentation,
\end{enumerate}
then $N' = N \times_M M'$ is finitely presented over $D'$.

\label{lemma-fitting-ideal-finite-locally-free}
Let $R$ be a ring. Let $M$ be a finite $R$-module. Let $r \geq 0$.
The following are equivalent
\begin{enumerate}
\item $M$ is finite locally free of rank $r$
(Algebra, Definition \ref{algebra-definition-locally-free}),
\item $\text{Fit}_{r - 1}(M) = 0$ and $\text{Fit}_r(M) = R$, and
\item $\text{Fit}_k(M) = 0$ for $k < r$ and $\text{Fit}_k(M) = R$
for $k \geq r$.
\end{enumerate}

\label{lemma-symmetric-algebra-smooth}
Let $A$ be a ring. Let $M$ be an $A$-module. Then $C = \text{Sym}_A^*(M)$
is smooth over $A$ if and only if $M$ is a finite projective $A$-module.

\label{definition-zariski-pair}
A {\it Zariski pair} is a pair $(A, I)$ such that
$I$ is contained in the Jacobson radical of $A$.

\label{lemma-idempotents-determined-modulo-radical}
Let $(A, I)$ be a Zariski pair. Then the map from
idempotents of $A$ to idempotents of $A/I$ is injective.

\label{lemma-helper-finite}
Let $(A, I)$ be a Zariski pair. Let $A \to B$ be a finite ring map.
Assume
\begin{enumerate}
\item $B/IB = B_1 \times B_2$ is a product of $A/I$-algebras
\item $A/I \to B_1/IB_1$ is surjective,
\item $b \in B$ maps to $(1, 0)$ in the product.
\end{enumerate}
Then there exists a monic $f \in A[x]$ with $f(b) = 0$ and
$f \bmod I = (x - 1)x^d$ for some $d \geq 1$.

\label{lemma-noetherian-zariski-jacobson-complement}
Let $(A, I)$ be a Zariski pair with $A$ Noetherian. Let $f \in I$.
Then $A_f$ is a Jacobson ring.

\label{definition-henselian-pair}
A {\it henselian pair} is a pair $(A, I)$ satisfying
\begin{enumerate}
\item $I$ is contained in the Jacobson radical of $A$, and
\item for any monic polynomial $f \in A[T]$ and factorization
$\overline{f} = g_0h_0$ with $g_0, h_0 \in A/I[T]$ monic
generating the unit ideal in $A/I[T]$, there
exists a factorization $f = gh$ in $A[T]$ with $g, h$ monic
and $g_0 = \overline{g}$ and $h_0 = \overline{h}$.
\end{enumerate}

\label{lemma-complete-henselian}
Let $(A, I)$ be a pair. If $A$ is $I$-adically complete, then
the pair is henselian.

\label{lemma-change-ideal-henselian-pair}
Let $A$ be a ring. Let $I, J \subset A$ be ideals with $V(I) = V(J)$.
Then $(A, I)$ is henselian if and only if $(A, J)$ is henselian.

\label{lemma-integral-over-henselian-pair}
Let $(A, I)$ be a henselian pair and let $A \to B$ be an integral ring
map. Then $(B, IB)$ is a henselian pair.

\label{lemma-henselian-henselian-pair}
Let $I \subset J \subset A$ be ideals of a ring $A$.
The following are equivalent
\begin{enumerate}
\item $(A, I)$ and $(A/I, J/I)$ are henselian pairs, and
\item $(A, J)$ is an henselian pair.
\end{enumerate}

\label{lemma-sum-henselian}
Let $A$ be a ring and let $(A, I)$ and $(A, I')$ be henselian pairs.
Then $(A, I + I')$ is an henselian pair.

\label{lemma-largest-ideal-henselian}
Let $A$ be a ring. There exists a largest ideal $I \subset A$ such that
$(A, I)$ is a henselian pair.

\label{lemma-irreducible-henselian-pair-connected}
Let $(A, I)$ be a henselian pair. Let $\mathfrak p \subset A$
be a prime ideal. Then $V(\mathfrak p + I)$ is connected.

\label{lemma-henselization}
The inclusion functor
$$
\text{category of henselian pairs}
\longrightarrow
\text{category of pairs}
$$
has a left adjoint $(A, I) \mapsto (A^h, I^h)$.

\label{lemma-henselization-local-ring}
\begin{slogan}
Compatibility henselization of pairs and of local rings.
\end{slogan}
The functor of Lemma \ref{lemma-henselization} associates to a local ring
$(A, \mathfrak m)$ its henselization.

\label{lemma-henselization-change-ideal}
\begin{slogan}
The henselization of a pair only depends on the radical of the ideal
\end{slogan}
Let $A$ be a ring with ideals $I$ and $J$. If $V(I) = V(J)$ then the functor
of Lemma \ref{lemma-henselization} produces the same ring for the pair
$(A, I)$ as for the pair $(A, J)$.

\label{lemma-henselization-integral}
\begin{slogan}
Henselization commutes with integral base change
\end{slogan}
Let $(A, I) \to (B, J)$ be a map of pairs such that $V(J) = V(IB)$.
Let $(A^h , I^h) \to (B^h, J^h)$ be the induced map
on henselizations (Lemma \ref{lemma-henselization}).
If $A \to B$ is integral, then the induced map
$A^h \otimes_A B \to B^h$ is an isomorphism.

\label{definition-absolutely-integrally-closed}
A ring $A$ is {\it absolutely integrally closed} if every
monic $f \in A[T]$ is a product of linear factors.

\label{lemma-absolutely-integrally-closed}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is absolutely integrally closed, and
\item any monic $f \in A[T]$ has a root in $A$.
\end{enumerate}

\label{lemma-absolutely-integrally-closed-quotient-localization}
Let $A$ be absolutely integrally closed.
\begin{enumerate}
\item Any quotient ring $A/I$ of $A$ is absolutely integrally closed.
\item Any localization $S^{-1}A$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-normal-domain-absolutely-integrally-closed}
Let $A$ be a normal domain. Then $A$ is absolutely integrally closed
if and only if its fraction field is algebraically closed.

\label{lemma-construct-absolute-integral-closure}
For any ring $A$ there exists an extension $A \subset B$ such that
\begin{enumerate}
\item $B$ is a filtered colimit of finite free $A$-algebras,
\item $B$ is free as an $A$-module, and
\item $B$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-absolutely-integrally-closed-strictly-henselian}
Let $A$ be absolutely integrally closed. Let $\mathfrak p \subset A$
be a prime. Then the local ring $A_\mathfrak p$ is strictly henselian.

\label{lemma-absolutely-integrally-closed-henselian-pair}
Let $A$ be absolutely integrally closed. Let $I \subset A$ be an ideal.
Then $(A, I)$ is a henselian pair if (and only if) the following
conditions hold
\begin{enumerate}
\item $I$ is contained in the Jacobson radical of $A$,
\item $A \to A/I$ induces a bijection on idempotents.
\end{enumerate}

\label{definition-auto-ass}
A ring $R$ is said to be {\it auto-associated} if $R$ is local and its
maximal ideal $\mathfrak m$ is weakly associated to $R$.

\label{lemma-exact-length-1}
Let $(R, \mathfrak m)$ be a local ring.
Suppose that $\varphi : R^m \to R^n$ is a map
of finite free modules. The following are equivalent
\begin{enumerate}
\item $\varphi$ is injective,
\item the rank of $\varphi$ is $m$ and the annihilator of
$I(\varphi)$ in $R$ is zero.
\end{enumerate}
If $R$ is Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] the rank of $\varphi$ is $m$ and
either $I(\varphi) = R$ or it contains a nonzerodivisor.
\end{enumerate}
Here the rank of $\varphi$ and $I(\varphi)$ are defined
as in Algebra, Definition \ref{algebra-definition-rank}.

\label{lemma-flat-descent-flat-at-primes}
In Situation \ref{situation-flattening-general}
let $R' \to R''$ be an $R$-algebra map.
Let $I' \subset R'$ and $I'R'' \subset I'' \subset R''$ be ideals.
Assume
\begin{enumerate}
\item the map $V(I'') \to V(I')$ induced by
$\Spec(R'') \to \Spec(R')$ is surjective, and
\item $R''_{\mathfrak p''}$ is flat over $R'$ for all primes
$\mathfrak p'' \in V(I'')$.
\end{enumerate}
If (\ref{equation-flat-at-primes}) holds for
$(R'', I'')$, then (\ref{equation-flat-at-primes}) holds for $(R', I')$.

\label{definition-torsion}
Let $R$ be a domain. Let $M$ be an $R$-module.
\begin{enumerate}
\item We say an element $x \in M$ is {\it torsion} if there exists
a nonzero $f \in R$ such that $fx = 0$.
\item We say $M$ is {\it torsion free} if the only torsion element of $M$
is $0$.
\item We say $M$ is a {\it torsion module} if every element of $M$
is torsion.
\end{enumerate}

\label{lemma-flat-pullback-torsion}
Let $R \to R'$ be a flat homomorphism of domains. If $M$ is a torsion
free $R$-module, then $M \otimes_R R'$ is a torsion free $R'$-module.

\label{lemma-torsion-free-finite-noetherian-domain}
Let $R$ be a Noetherian domain. Let $M$ be a nonzero finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is torsion free,
\item $M$ is a submodule of a finite free module,
\item $(0)$ is the only associated prime of $M$,
\item $(0)$ is in the support of $M$ and $M$ has property $(S_1)$, and
\item $(0)$ is in the support of $M$ and $M$ has no embedded associated prime.
\end{enumerate}

\label{lemma-valuation-ring-torsion-free-flat}
Let $A$ be a valuation ring.
An $A$-module $M$ is flat over $A$ if and only if $M$ is torsion free.

\label{lemma-dedekind-torsion-free-flat}
Let $A$ be a Dedekind domain (for example a discrete valuation ring
or more generally a PID).
\begin{enumerate}
\item An $A$-module is flat if and only if it is torsion free.
\item A finite torsion free $A$-module is finite locally free.
\item A finite torsion free $A$-module is finite free if
$A$ is a PID.
\end{enumerate}

\label{lemma-hom-into-torsion-free}
Let $R$ be a domain. Let $M$, $N$ be $R$-modules.
If $N$ is torsion free, so is $\Hom_R(M, N)$.

\label{definition-rank}
Let $R$ be a domain with fraction field $K$.
The {\it rank} of an $R$-module $M$ is $\dim_K(M \otimes_R K)$.

\label{lemma-rank-tensor}
Let $R$ be a domain. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item The rank of $M \otimes_R N$ is the product of the
ranks of $M$ and $N$.
\item If $M$ is a finitely presented $R$-module, then
the rank of $\Hom_R(M, N)$ is the product of the
ranks of $M$ and $N$.
\end{enumerate}

\label{lemma-reflexive-torsion-free}
Let $R$ be a domain and let $M$ be an $R$-module.
\begin{enumerate}
\item If $M$ is reflexive, then $M$ is torsion free.
\item If $M$ is finite, then the kernel and cokernel of
$j : M \to \Hom_R(\Hom_R(M, R), R)$ are torsion modules.
\item If $M$ is finite, then $j$ is injective
if and only if $M$ is torsion free.
\end{enumerate}

\label{lemma-cokernel-map-double-dual-dvr}
Let $R$ be a discrete valuation ring and let $M$ be a finite $R$-module.
Then the map $j : M \to \Hom_R(\Hom_R(M, R), R)$ is surjective.

\label{lemma-check-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent:
\begin{enumerate}
\item $M$ is reflexive,
\item $M_\mathfrak p$ is a reflexive $R_\mathfrak p$-module
for all primes $\mathfrak p \subset R$, and
\item $M_\mathfrak m$ is a reflexive $R_\mathfrak m$-module
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}

\label{lemma-characterize-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item there exists a short exact sequence $0 \to M \to F \to N \to 0$
with $F$ finite free and $N$ torsion free.
\end{enumerate}

\label{lemma-dual-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
Let $N$ be a finite reflexive $R$-module. Then $\Hom_R(M, N)$ is reflexive.

\label{lemma-hom-into-depth}
Let $R$ be a Noetherian local ring. Let $M$, $N$ be finite $R$-modules.
\begin{enumerate}
\item If $N$ has depth $\geq 1$, then $\Hom_R(M, N)$ has depth $\geq 1$.
\item If $N$ has depth $\geq 2$, then $\Hom_R(M, N)$ has depth $\geq 2$.
\end{enumerate}

\label{lemma-hom-into-S2}
Let $R$ be a Noetherian ring. Let $M$, $N$ be finite $R$-modules.
\begin{enumerate}
\item If $N$ has property $(S_1)$, then $\Hom_R(M, N)$ has property $(S_1)$.
\item If $N$ has property $(S_2)$, then $\Hom_R(M, N)$ has property $(S_2)$.
\item If $R$ is a domain, $N$ is torsion free and $(S_2)$, then
$\Hom_R(M, N)$ is torsion free and has property $(S_2)$.
\end{enumerate}

\label{lemma-check-injective-on-ass}
Let $R$ be a Noetherian ring. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume that for every prime $\mathfrak p$
of $R$ at least one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is injective, or
\item $\mathfrak p \not \in \text{Ass}(M)$.
\end{enumerate}
Then $\varphi$ is injective.

\label{lemma-check-isomorphism-via-depth-and-ass}
Let $R$ be a Noetherian ring. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume $M$ is finite and that for every prime $\mathfrak p$
of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is an isomorphism, or
\item $\text{depth}(M_\mathfrak p) \geq 2$ and
$\mathfrak p \not \in \text{Ass}(N)$.
\end{enumerate}
Then $\varphi$ is an isomorphism.

\label{lemma-isom-depth-2-torsion-free}
Let $R$ be a Noetherian domain. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume $M$ is finite, $N$ is torsion free, and
that for every prime $\mathfrak p$ of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is an isomorphism, or
\item $\text{depth}(M_\mathfrak p) \geq 2$.
\end{enumerate}
Then $\varphi$ is an isomorphism.

\label{lemma-reflexive-depth-2}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item for every prime $\mathfrak p$ of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p$ is a reflexive $R_\mathfrak p$-module, or
\item $\text{depth}(M_\mathfrak p) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-reflexive-S2}
Let $R$ be a Noetherian domain. Let $M$ be a finite reflexive $R$-module.
Let $\mathfrak p \subset R$ be a prime ideal.
\begin{enumerate}
\item If $\text{depth}(R_\mathfrak p) \geq 2$, then
$\text{depth}(M_\mathfrak p) \geq 2$.
\item If $R$ is $(S_2)$, then $M$ is $(S_2)$.
\end{enumerate}

\label{lemma-reflexive-over-normal}
Let $R$ be a Noetherian normal domain with fraction field $K$.
Let $M$ be a finite $R$-module. The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item $M$ is torsion free and has property $(S_2)$,
\item $M$ is torsion free and
$M = \bigcap_{\text{height}(\mathfrak p) = 1} M_{\mathfrak p}$
where the intersection happens in $M_K = M \otimes_R K$.
\end{enumerate}

\label{lemma-content-finitely-generated}
Let $A$ be a ring. Let $M$ be a flat $A$-module. Let $x \in M$.
The content ideal of $x$, if it exists, is finitely generated.

\label{lemma-content-exists-flat-Mittag-Leffler}
Let $A$ be a ring. Let $M$ be a flat Mittag-Leffler module.
Then every element of $M$ has a content ideal.

\label{lemma-flat-finite-type-valuation-ring-finite-presentation}
\begin{reference}
\cite[Theorem 3]{Nagata-Finitely}
\end{reference}
Let $A$ be a valuation ring. Let $A \to B$ be a ring map of finite type.
Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is a finitely presented $A$-algebra.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-valuation-ring-flat-essentially-finite-type}
Let $A$ be a valuation ring. Let $A \to B$ be a local homomorphism
which is essentially of finite type. Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is essentially of finite
presentation over $A$.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-tor-strictly-pro-zero}
\begin{reference}
This is \cite[Lemma 9.9]{quillenhomology}; note that
the author forgot the word ``strict'' in the statement
although it was clearly intended.
\end{reference}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$.
Let $M$ be a finite $A$-module. For every $p > 0$ there exists a $c > 0$
such that $\text{Tor}_p^A(M, A/I^n) \to \text{Tor}_p^A(M, A/I^{n - c})$
is zero for all $n \geq c$.

\label{lemma-limit-flat}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$. Let
$(M_n)$ be an inverse system of $A$-modules such that
\begin{enumerate}
\item $M_n$ is a flat $A/I^n$-module,
\item $M_{n + 1} \to M_n$ is surjective.
\end{enumerate}
Then $M = \lim M_n$ is a flat $A$-module and
$Q \otimes_A M = \lim Q \otimes_A M_n$ for every finite $A$-module $Q$.

\label{lemma-extended-alternating-is-complex}
The extended alternating {\v C}ech complexes defined above
are complexes of $R$-modules.

\label{lemma-extended-alternating-torsion}
Let $R$ be a ring. Let $f_1, \ldots, f_r \in R$. Let $M$ be an $R$-module.
Let $H^q$ be the $q$th cohomology module of the extended alternation
{\v C}ech complex of $M$. Then
\begin{enumerate}
\item $H^q = 0$ if $q \not \in [0, r]$,
\item for $x \in H^i$ there exists an $n \geq 1$ such that $f_i^n x = 0$
for $i = 1, \ldots, r$,
\item the support of $H^q$ is contained in $V(f_1, \ldots, f_r)$,
\item if there is an $f \in (f_1, \ldots, f_r)$ which acts invertibly
on $M$, then $H^q = 0$.
\end{enumerate}

\label{lemma-koszul-regular-H1-regular}
A $M$-Koszul-regular sequence is $M$-$H_1$-regular.
A Koszul-regular sequence is $H_1$-regular.

\label{lemma-independence-of-generators}
Let $R$ be a ring. Let $I$ be an ideal generated by $f_1, \ldots, f_r \in R$.
\begin{enumerate}
\item If $I$ can be generated by a quasi-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a quasi-regular sequence.
\item If $I$ can be generated by an $H_1$-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is an $H_1$-regular sequence.
\item If $I$ can be generated by a Koszul-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a Koszul-regular sequence.
\end{enumerate}

\label{lemma-make-nonzero-divisor}
\begin{reference}
This is a particular case of \cite[Corollary]{McCoy}
\end{reference}
Let $R$ be a ring. Let $a_1, \ldots, a_n \in R$ be elements such
that $R \to R^{\oplus n}$, $x \mapsto (xa_1, \ldots, xa_n)$ is injective.
Then the element $\sum a_i t_i$ of the polynomial ring $R[t_1, \ldots, t_n]$
is a nonzerodivisor.

\label{lemma-relative-regular-immersion-algebra}
Let $A \to B$ and $A \to A'$ be ring maps. Set $B' = B \otimes_A A'$.
Let $f_1, \ldots, f_r \in B$. Assume $B/(f_1, \ldots, f_r)B$ is flat over $A$
\begin{enumerate}
\item If $f_1, \ldots, f_r$ is a quasi-regular sequence, then
the image in $B'$ is a quasi-regular sequence.
\item If $f_1, \ldots, f_r$ is a $H_1$-regular sequence, then
the image in $B'$ is a $H_1$-regular sequence.
\end{enumerate}

\label{lemma-cut-by-koszul-flat}
Let $A' \to B'$ be a ring map. Let $I \subset A'$ be an ideal.
Set $A = A'/I$ and $B = B'/IB'$. Let $f'_1, \ldots, f'_r \in B'$. Assume
\begin{enumerate}
\item $A' \to B'$ is flat and of finite presentation,
\item $I$ is locally nilpotent,
\item the images $f_1, \ldots, f_r \in B$ form a quasi-regular sequence,
\item $B/(f_1, \ldots, f_r)$ is flat over $A$.
\end{enumerate}
Then $B'/(f'_1, \ldots, f'_r)$ is flat over $A'$.

\label{lemma-cut-by-koszul}
Let $A' \to B'$ be a ring map. Let $I \subset A'$ be an ideal.
Set $A = A'/I$ and $B = B'/IB'$. Let $f'_1, \ldots, f'_r \in B'$. Assume
\begin{enumerate}
\item $A' \to B'$ is flat and of finite presentation (for example smooth),
\item $I$ is locally nilpotent,
\item the images $f_1, \ldots, f_r \in B$ form a quasi-regular sequence,
\item $B/(f_1, \ldots, f_r)$ is smooth over $A$.
\end{enumerate}
Then $B'/(f'_1, \ldots, f'_r)$ is smooth over $A'$.

\label{lemma-quasi-regular-ideal-finite-projective}
Let $I \subset R$ be a quasi-regular ideal of a ring.
Then $I/I^2$ is a finite projective $R/I$-module.

\label{definition-local-complete-intersection}
A ring map $A \to B$ is called a {\it local complete intersection}
if it is of finite type and for some (equivalently any) presentation
$B = A[x_1, \ldots, x_n]/I$ the ideal $I$ is Koszul-regular.

\label{lemma-syntomic-lci}
Let $R \to S$ be a ring map. The following are equivalent
\begin{enumerate}
\item $R \to S$ is syntomic
(Algebra, Definition \ref{algebra-definition-lci}), and
\item $R \to S$ is flat and a local complete intersection.
\end{enumerate}

\label{lemma-transitive-colimit-lci-at-end}
Let $A \to B \to C$ be ring maps.
If $B \to C$ is a filtered colimit of local complete intersection
homomorphisms then the conclusion of
Lemma \ref{lemma-transitive-lci-at-end}
remains valid.

\label{lemma-consequence-baire-complete-module}
With same assumptions as Lemma \ref{lemma-baire-category-complete-module}
if $M = \bigcup_{n \geq 1} N_n$ for some closed subgroups $N_n$,
then $N_n$ is open for some $n$.

\label{lemma-compose-formally-smooth}
A composition of formally smooth continuous homomorphisms of linearly
topologized rings is formally smooth.

\label{lemma-descent-fs}
Let $R$, $S$ be rings. Let $\mathfrak n \subset S$ be an ideal.
Let $R \to R'$ be a ring map. Set $S' = S \otimes_R R'$ and
$\mathfrak n' = \mathfrak nS$. If
\begin{enumerate}
\item the map $R \to R'$ embeds $R$ as a direct summand of $R'$
as an $R$-module, and
\item $R' \to S'$ is formally smooth for the $\mathfrak n'$-adic topology,
\end{enumerate}
then $R \to S$ is formally smooth in the $\mathfrak n$-adic topology.

\label{lemma-fs-local}
Let $(R, \mathfrak m) \to (S, \mathfrak n)$ be a local homomorphism
of local rings. The following are equivalent
\begin{enumerate}
\item $R \to S$ is formally smooth in the $\mathfrak n$-adic topology,
\item for every solid commutative diagram
$$
\xymatrix{
S \ar[r] \ar@{-->}[rd] & A/J \\
R \ar[r] \ar[u] & A \ar[u]
}
$$
of local homomorphisms of local rings where $J \subset A$ is
an ideal of square zero, $\mathfrak m_A^n = 0$ for some $n > 0$, and
$S \to A/J$ induces an isomorphism on residue fields, a dotted
arrow exists which makes the diagram commute.
\end{enumerate}
If $S$ is Noetherian these conditions are also equivalent to
\begin{enumerate}
\item[(3)] same as in (2) but only for diagrams where in addition
$A \to A/J$ is a small extension
(Algebra, Definition \ref{algebra-definition-small-extension}).
\end{enumerate}

\label{lemma-formally-smooth-finite-type}
Let $A \to B$ be a finite type ring map with $A$ Noetherian.
Let $\mathfrak q \subset B$ be a prime ideal lying over
$\mathfrak p \subset A$. The following are equivalent
\begin{enumerate}
\item $A \to B$ is smooth at $\mathfrak q$, and
\item $A_\mathfrak p \to B_\mathfrak q$ is formally smooth in
the $\mathfrak q$-adic topology.
\end{enumerate}

\label{lemma-dominate-two-surjections}
Let $S \to R$ and $S' \to R$ be surjective maps of complete Noetherian local
rings. Then $S \times_R S'$ is a complete Noetherian local ring.

\label{lemma-regular-field-extension}
Let $K/k$ be a field extension. Then $k \to K$ is a regular
ring map if and only if $K$ is a separable field extension of $k$.

\label{lemma-regular-permanence}
Let $A \to B \to C$ be ring maps. If $A \to C$ is regular and $B \to C$
is flat and surjective on spectra, then $A \to B$ is regular.

\label{lemma-reduced-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and reduced.
\end{enumerate}
Then $S$ is reduced.

\label{lemma-normal-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and normal.
\end{enumerate}
Then $S$ is normal.

\label{lemma-regular-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and regular.
\end{enumerate}
Then $S$ is regular.

\label{lemma-CM-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and Cohen-Macaulay.
\end{enumerate}
Then $S$ is Cohen-Macaulay.

\label{lemma-completion-dimension}
Let $A$ be a Noetherian local ring.
Then $\dim(A) = \dim(A^\wedge)$.

\label{lemma-completion-depth}
Let $A$ be a Noetherian local ring. Then
$\text{depth}(A) = \text{depth}(A^\wedge)$.

\label{lemma-completion-CM}
Let $A$ be a Noetherian local ring.
Then $A$ is Cohen-Macaulay if and only if $A^\wedge$ is so.

\label{lemma-completion-regular}
Let $A$ be a Noetherian local ring.
Then $A$ is regular if and only if $A^\wedge$ is so.

\label{lemma-completion-dvr}
Let $A$ be a Noetherian local ring.
Then $A$ is a discrete valuation ring if and only if $A^\wedge$ is so.

\label{lemma-completion-reduced}
Let $A$ be a Noetherian local ring.
\begin{enumerate}
\item If $A^\wedge$ is reduced, then so is $A$.
\item In general $A$ reduced does not imply $A^\wedge$ is reduced.
\item If $A$ is Nagata, then $A$ is reduced if and only if $A^\wedge$
is reduced.
\end{enumerate}

\label{lemma-henselization-formally-smooth}
Let $(R, \mathfrak m, \kappa)$ be a local ring. Then
\begin{enumerate}
\item $R \to R^h$, $R^h \to R^{sh}$, and $R \to R^{sh}$ are formally \'etale,
\item $R \to R^h$, $R^h \to R^{sh}$, resp.\ $R \to R^{sh}$ are formally
smooth in the $\mathfrak m^h$, $\mathfrak m^{sh}$,
resp.\ $\mathfrak m^{sh}$-topology.
\end{enumerate}

\label{lemma-henselization-noetherian}
\begin{reference}
\cite[IV, Theorem 18.6.6 and Proposition 18.8.8]{EGA}
\end{reference}
Let $R$ be a local ring. The following are equivalent
\begin{enumerate}
\item $R$ is Noetherian,
\item $R^h$ is Noetherian, and
\item $R^{sh}$ is Noetherian.
\end{enumerate}
In this case we have
\begin{enumerate}
\item[(a)] $(R^h)^\wedge$ and $(R^{sh})^\wedge$ are Noetherian complete
local rings,
\item[(b)] $R^\wedge \to (R^h)^\wedge$ is an isomorphism,
\item[(c)] $R^h \to (R^h)^\wedge$ and $R^{sh} \to (R^{sh})^\wedge$ are flat,
\item[(d)] $R^\wedge \to (R^{sh})^\wedge$ is formally smooth in
the $\mathfrak m_{(R^{sh})^\wedge}$-adic topology,
\item[(e)] $(R^\wedge)^{sh} = R^\wedge \otimes_{R^h} R^{sh}$, and
\item[(f)] $((R^\wedge)^{sh})^\wedge = (R^{sh})^\wedge$.
\end{enumerate}

\label{lemma-henselization-reduced}
\begin{slogan}
Reducedness passes to the (strict) henselization.
\end{slogan}
Let $R$ be a local ring.
The following are equivalent: $R$ is reduced,
the henselization $R^h$ of $R$ is reduced, and
the strict henselization $R^{sh}$ of $R$ is reduced.

\label{lemma-henselization-depth}
Given a Noetherian local ring $R$ we have
$\text{depth}(R) = \text{depth}(R^h) = \text{depth}(R^{sh})$.

\label{lemma-p-basis}
Let $K/k$ be a field extension. Assume $k$ has characteristic
$p > 0$. Let $\{x_i\}$ be a subset of $K$. The following are equivalent
\begin{enumerate}
\item the elements $\{x_i\}$ are $p$-independent over $k$, and
\item the elements $\text{d}x_i$ are $K$-linearly independent
in $\Omega_{K/k}$.
\end{enumerate}
Any $p$-independent collection can be extended to a $p$-basis of $K$ over $k$.
In particular, the field $K$ has a $p$-basis over $k$.
Moreover, the following are equivalent:
\begin{enumerate}
\item[(a)] $\{x_i\}$ is a $p$-basis of $K$ over $k$, and
\item[(b)] $\text{d}x_i$ is a basis of the $K$-vector space $\Omega_{K/k}$.
\end{enumerate}

\label{lemma-intersection-subfields}
Let $K$ be a field of characteristic $p$. Let $\{K_\alpha\}_{\alpha \in A}$
be a collection of subfields of $K$ with the following properties
\begin{enumerate}
\item $K^p \subset K_\alpha$ for all $\alpha \in A$,
\item $K^p = \bigcap_{\alpha \in A} K_\alpha$,
\item for $\alpha, \alpha' \in A$ there exists an $\alpha'' \in A$
such that $K_{\alpha''} \subset K_\alpha \cap K_{\alpha'}$.
\end{enumerate}
Then
\begin{enumerate}
\item the intersection of the kernels of the maps
$\Omega_{K/\mathbf{F}_p} \to \Omega_{K/K_\alpha}$ is zero,
\item for any finite extension $L/K$ we have
$L^p = \bigcap_{\alpha \in A} L^pK_\alpha$.
\end{enumerate}

\label{definition-J}
\begin{reference}
\cite[(32.B)]{MatCA}
\end{reference}
Let $R$ be a Noetherian ring. Let $X = \Spec(R)$.
\begin{enumerate}
\item We say $R$ is {\it J-0} if $\text{Reg}(X)$ contains a nonempty open.
\item We say $R$ is {\it J-1} if $\text{Reg}(X)$ is open.
\item We say $R$ is {\it J-2} if any finite type $R$-algebra is J-1.
\end{enumerate}

\label{lemma-J-0-goes-down}
Let $R \to S$ be a ring map. Assume that
\begin{enumerate}
\item $R$ is a Noetherian domain,
\item $R \to S$ is injective and of finite type, and
\item $S$ is a domain and J-0.
\end{enumerate}
Then $R$ is J-0.

\label{lemma-J-0-goes-up}
Let $R \to S$ be a ring map. Assume that
\begin{enumerate}
\item $R$ is a Noetherian domain and J-0,
\item $R \to S$ is injective and of finite type, and
\item $S$ is a domain, and
\item the induced extension of fraction fields is separable.
\end{enumerate}
Then $S$ is J-0.

\label{lemma-quotient-regular}
\begin{slogan}
The Jacobian criterion for hypersurfaces, done right.
\end{slogan}
Let $R$ be a regular ring. Let $f \in R$. Assume there exists a
derivation $D : R \to R$ such that $D(f)$ is a unit of $R/(f)$.
Then $R/(f)$ is regular.

\label{proposition-finite-type-over-G-ring}
Let $R$ be a G-ring. If $R \to S$ is essentially of finite type
then $S$ is a G-ring.

\label{proposition-ubiquity-G-ring}
The following types of rings are G-rings:
\begin{enumerate}
\item fields,
\item Noetherian complete local rings,
\item $\mathbf{Z}$,
\item Dedekind domains with fraction field of characteristic zero,
\item finite type ring extensions of any of the above.
\end{enumerate}

\label{lemma-map-G-ring-to-completion-regular}
\begin{reference}
\cite[Theorem 79]{MatCA}
\end{reference}
Let $A$ be a G-ring. Let $I \subset A$ be an ideal
and let $A^\wedge$ be the completion of $A$ with respect to $I$.
Then $A \to A^\wedge$ is regular.

\label{lemma-henselization-pair-G-ring}
\begin{slogan}
Being a G-ring is stable under Henselizations along ideals
\end{slogan}
\begin{reference}
\cite[Theorem 5.3 i)]{Greco}
\end{reference}
Let $A$ be a G-ring. Let $I \subset A$ be an ideal.
Let $(A^h, I^h)$ be the henselization of the pair $(A, I)$, see
Lemma \ref{lemma-henselization}.
Then $A^h$ is a G-ring.

\label{proposition-finite-type-over-P-ring}
Let $R$ be a $P$-ring where $P$ satisfies (A), (B), (C), and (D).
If $R \to S$ is essentially of finite type then $S$ is a $P$-ring.

\label{lemma-henselization-pair-P-ring}
\begin{slogan}
Henselization of a ring inherits good properties of formal fibers
\end{slogan}
Let $A$ be a $P$-ring where $P$ satisfies (B), (C), (D), and (E).
Let $I \subset A$ be an ideal. Let $(A^h, I^h)$ be the henselization
of the pair $(A, I)$, see Lemma \ref{lemma-henselization}.
Then $A^h$ is a $P$-ring.

\label{lemma-formal-fibres-reduced}
Properties (A), (B), (C), (D), and (E) hold for
$P(k \to R) =$``$R$ is geometrically reduced over $k$''.

\label{lemma-formal-fibres-normal}
Properties (A), (B), (C), (D), and (E) hold for
$P(k \to R) =$``$R$ is geometrically normal over $k$''.

\label{lemma-formal-fibres-Sk}
Fix $n \geq 1$. Properties (A), (B), (C), (D), and (E) hold for
$P(k \to R) =$``$R$ has $(S_n)$''.

\label{lemma-formal-fibres-CM}
Properties (A), (B), (C), (D), and (E) hold for
$P(k \to R) =$``$R$ is Cohen-Macaulay''.

\label{definition-excellent}
Let $R$ be a ring.
\begin{enumerate}
\item We say $R$ is {\it quasi-excellent} if $R$ is Noetherian,
a G-ring, and J-2.
\item We say $R$ is {\it excellent} if $R$ is quasi-excellent
and universally catenary.
\end{enumerate}

\label{lemma-finite-type-over-excellent}
Any localization of a finite type ring over a (quasi-)excellent ring
is (quasi-)excellent.

\label{proposition-ubiquity-excellent}
The following types of rings are excellent:
\begin{enumerate}
\item fields,
\item Noetherian complete local rings,
\item $\mathbf{Z}$,
\item Dedekind domains with fraction field of characteristic zero,
\item finite type ring extensions of any of the above.
\end{enumerate}

\label{lemma-Nagata-local-ring}
Let $(A, \mathfrak m)$ be a Noetherian local ring.
The following are equivalent
\begin{enumerate}
\item $A$ is Nagata, and
\item the formal fibres of $A$ are geometrically reduced.
\end{enumerate}

\label{lemma-characterize-injective}
Let $R$ be a ring. Let $J$ be an $R$-module.
The following are equivalent
\begin{enumerate}
\item $J$ is injective,
\item $\Ext^1_R(M, J) = 0$ for every $R$-module $M$.
\end{enumerate}

\label{lemma-characterize-injective-bis}
Let $R$ be a ring. Let $J$ be an $R$-module.
The following are equivalent
\begin{enumerate}
\item $J$ is injective,
\item $\Ext^1_R(R/I, J) = 0$ for every ideal $I \subset R$, and
\item for an ideal $I \subset R$ and module map $I \to J$
there exists an extension $R \to J$.
\end{enumerate}

\label{lemma-vee-exact}
Let $R$ be a ring.
The functor $M \mapsto M^\vee$ is exact.

\label{lemma-ev-injective}
For any $R$-module $M$ the evaluation map
$ev : M \to (M^\vee)^\vee$ is injective.

\label{lemma-JM-injective}
Let $R$ be a ring. For every $R$-module $M$ the
$R$-module $J(M)$ is injective.

\label{definition-K-flat}
Let $R$ be a ring. A complex $K^\bullet$ is called {\it K-flat}
if for every acyclic complex $M^\bullet$ the total complex
$\text{Tot}(M^\bullet \otimes_R K^\bullet)$ is acyclic.

\label{lemma-derived-tor-quasi-isomorphism}
Let $R$ be a ring. Let $P^\bullet$ be a bounded above complex of
flat $R$-modules. Then $P^\bullet$ is K-flat.

\label{lemma-tensor-hom-adjoint}
Let $R \to A$ be a ring map. The functor
$D(R) \to D(A)$, $E \mapsto E \otimes_R^\mathbf{L} A$
of Lemma \ref{lemma-derived-base-change}
is left adjoint to the restriction functor
$D(A) \to D(R)$.

\label{lemma-base-change-comparison}
The comparison map (\ref{equation-comparison-map}) is an isomorphism
if $A' = A \otimes_R R'$ and $A$ and $R'$ are Tor independent over $R$.

\label{definition-pseudo-coherent}
Let $R$ be a ring. Denote $D(R)$ its derived category.
Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item An object $K^\bullet$ of $D(R)$ is {\it $m$-pseudo-coherent}
if there exists a bounded complex $E^\bullet$ of finite free $R$-modules
and a morphism $\alpha : E^\bullet \to K^\bullet$ such that
$H^i(\alpha)$ is an isomorphism for $i > m$ and $H^m(\alpha)$
is surjective.
\item An object $K^\bullet$ of $D(R)$ is {\it pseudo-coherent}
if it is quasi-isomorphic to a bounded above complex of finite
free $R$-modules.
\item An $R$-module $M$ is called {\it $m$-pseudo-coherent}
if $M[0]$ is an $m$-pseudo-coherent object of $D(R)$.
\item An $R$-module $M$ is called
{\it pseudo-coherent}\footnote{This clashes with what is meant by
a pseudo-coherent module in \cite{Bourbaki-CA}.}
if $M[0]$ is a pseudo-coherent object of $D(R)$.
\end{enumerate}

\label{lemma-finite-cohomology}
Let $R$ be a ring. Let $K^\bullet$ be a complex of $R$-modules.
Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item If $K^\bullet$ is $m$-pseudo-coherent and $H^i(K^\bullet) = 0$
for $i > m$, then $H^m(K^\bullet)$ is a finite type $R$-module.
\item If $K^\bullet$ is $m$-pseudo-coherent and $H^i(K^\bullet) = 0$
for $i > m + 1$, then $H^{m + 1}(K^\bullet)$ is a finitely presented
$R$-module.
\end{enumerate}

\label{lemma-tensor-pseudo-coherent}
Let $R$ be a ring. Let $K, L$ be objects of $D(R)$.
\begin{enumerate}
\item If $K$ is $n$-pseudo-coherent and $H^i(K) = 0$ for $i > a$
and $L$ is $m$-pseudo-coherent and $H^j(L) = 0$ for $j > b$, then
$K \otimes_R^\mathbf{L} L$ is $t$-pseudo-coherent with $t = \max(m + a, n + b)$.
\item If $K$ and $L$ are pseudo-coherent, then
$K \otimes_R^\mathbf{L} L$ is pseudo-coherent.
\end{enumerate}

\label{lemma-pseudo-coherence-and-ext}
Let $R$ be a ring. Let $L$, $M$, $N$ be $R$-modules.
\begin{enumerate}
\item If $M$ is finitely presented and $L$ is flat, then the canonical map
$\Hom_R(M, N) \otimes_R L \to \Hom_R(M, N \otimes_R L)$
is an isomorphism.
\item If $M$ is $(-m)$-pseudo-coherent and $L$ is flat, then the canonical map
$\Ext^i_R(M, N) \otimes_R L \to \Ext^i_R(M, N \otimes_R L)$
is an isomorphism for $i < m$.
\end{enumerate}

\label{definition-tor-amplitude}
Let $R$ be a ring. Denote $D(R)$ its derived category.
Let $a, b \in \mathbf{Z}$.
\begin{enumerate}
\item An object $K^\bullet$ of $D(R)$ has
{\it tor-amplitude in $[a, b]$}
if $H^i(K^\bullet \otimes_R^\mathbf{L} M) = 0$ for all $R$-modules
$M$ and all $i \not \in [a, b]$.
\item An object $K^\bullet$ of $D(R)$ has {\it finite tor dimension}
if it has tor-amplitude in $[a, b]$ for some $a, b$.
\item An $R$-module $M$ has {\it tor dimension $\leq d$}
if $M[0]$ as an object of $D(R)$ has tor-amplitude in $[-d, 0]$.
\item An $R$-module $M$ has {\it finite tor dimension}
if $M[0]$ as an object of $D(R)$ has finite tor dimension.
\end{enumerate}

\label{lemma-tor-amplitude}
Let $R$ be a ring. Let $K^\bullet$ be an object of $D(R)$.
Let $a, b \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $K^\bullet$ has tor-amplitude in $[a, b]$.
\item $K^\bullet$ is quasi-isomorphic to a complex
$E^\bullet$ of flat $R$-modules with $E^i = 0$ for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-bounded-below-tor-amplitude}
Let $R$ be a ring. Let $a \in \mathbf{Z}$ and let $K$ be an object of $D(R)$.
The following are equivalent
\begin{enumerate}
\item $K$ has tor-amplitude in $[a, \infty]$, and
\item $K$ is quasi-isomorphic to a K-flat complex
$E^\bullet$ whose terms are flat $R$-modules with
$E^i = 0$ for $i \not \in [a, \infty]$.
\end{enumerate}

\label{lemma-complex-finite-tor-dimension-modules}
Let $R$ be a ring. Let $K^\bullet$ be a bounded complex of $R$-modules
such that $K^i$ has tor amplitude in $[a - i, b - i]$ for all $i$.
Then $K^\bullet$ has tor amplitude in $[a, b]$. In particular
if $K^\bullet$ is a finite complex of $R$-modules of finite tor dimension,
then $K^\bullet$ has finite tor dimension.

\label{lemma-push-tor-amplitude}
Let $A \to B$ be a ring map. Let $K^\bullet$ and $L^\bullet$ be complexes
of $B$-modules. Let $a, b, c, d \in \mathbf{Z}$. If
\begin{enumerate}
\item $K^\bullet$ as a complex of $B$-modules has tor amplitude in $[a, b]$,
\item $L^\bullet$ as a complex of $A$-modules has tor amplitude in $[c, d]$,
\end{enumerate}
then $K^\bullet \otimes^\mathbf{L}_B L^\bullet$ as a complex of $A$-modules
has tor amplitude in $[a + c, b + d]$.

\label{lemma-finite-gl-dim-tor-dimension}
Let $R$ be a ring of finite global dimension $d$. Then
\begin{enumerate}
\item every module has tor dimension $\leq d$,
\item a complex of $R$-modules $K^\bullet$ with $H^i(K^\bullet) \not = 0$
only if $i \in [a, b]$ has tor amplitude in $[a - d, b]$, and
\item a complex of $R$-modules $K^\bullet$ has finite tor dimension if and only
if $K^\bullet \in D^b(R)$.
\end{enumerate}

\label{lemma-injective-amplitude}
Let $R$ be a ring. Let $K$ be an object of $D(R)$. Let $a, b \in \mathbf{Z}$.
The following are equivalent
\begin{enumerate}
\item $K$ has injective-amplitude in $[a, b]$,
\item $\Ext^i_R(N, K) = 0$ for all $R$-modules $N$ and all
$i \not \in [a, b]$,
\item $\Ext^i(R/I, K) = 0$ for all ideals $I \subset R$ and
all $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-finite-injective-dimension}
Let $R$ be a ring. Let $K \in D(R)$.
\begin{enumerate}
\item If $K$ is in $D^b(R)$ and $H^i(K)$ has finite injective dimension
for all $i$, then $K$ has finite injective dimension.
\item If $K^\bullet$ represents $K$, is a bounded complex of $R$-modules,
and $K^i$ has finite injective dimension for all $i$, then $K$ has finite
injective dimension.
\end{enumerate}

\label{lemma-finite-injective-dimension-Noetherian-radical}
Let $R$ be a Noetherian ring. Let $I \subset R$ be an ideal contained
in the Jacobson radical of $R$. Let $K \in D^+(R)$ have
finite cohomology modules. Then the following are equivalent
\begin{enumerate}
\item $K$ has finite injective dimension, and
\item there exists a $b$ such that $\Ext^i_R(R/J, K) = 0$ for $i > b$
and any ideal $J \supset I$.
\end{enumerate}

\label{lemma-finite-injective-dimension-Noetherian-local}
Let $(R, \mathfrak m, \kappa)$ be a local Noetherian ring.
Let $K \in D^+(R)$ have finite cohomology modules.
Then the following are equivalent
\begin{enumerate}
\item $K$ has finite injective dimension, and
\item $\Ext^i_R(\kappa, K) = 0$ for $i \gg 0$.
\end{enumerate}

\label{lemma-near-projective}
Let $R$ be a ring. Let $I \subset R$ be an ideal. Let $M$ be an $R$-module.
The following conditions are equivalent
\begin{enumerate}
\item for every $a \in I$ the map $a : M \to M$ factors through a projective
$R$-module,
\item for every $a \in I$ the map $a : M \to M$ factors through a free
$R$-module, and
\item $\Ext^1_R(M, N)$ is annihilated by $I$ for every $R$-module $N$.
\end{enumerate}

\label{definition-near-projective}
Let $R$ be a ring. Let $I \subset R$ be an ideal. Let $M$ be an $R$-module.
We say $M$ is {\it $I$-projective}\footnote{This is nonstandard notation.}
if the equivalent conditions of Lemma \ref{lemma-near-projective} hold.

\label{lemma-torsion-near-projective}
Let $R$ be a ring. Let $I \subset R$ be an ideal. Let $M$ be an $R$-module.
If $M$ is annihilated by $I$, then $M$ is $I$-projective.

\label{definition-perfect}
Let $R$ be a ring. Denote $D(R)$ the derived category of the abelian
category of $R$-modules.
\begin{enumerate}
\item An object $K$ of $D(R)$ is {\it perfect} if it is quasi-isomorphic
to a bounded complex of finite projective $R$-modules.
\item An $R$-module $M$ is {\it perfect} if $M[0]$ is a perfect object
in $D(R)$.
\end{enumerate}

\label{lemma-perfect}
Let $K^\bullet$ be an object of $D(R)$. The following are equivalent
\begin{enumerate}
\item $K^\bullet$ is perfect, and
\item $K^\bullet$ is pseudo-coherent and has finite tor dimension.
\end{enumerate}
If (1) and (2) hold and $K^\bullet$ has tor-amplitude
in $[a, b]$, then $K^\bullet$ is quasi-isomorphic to a complex
$E^\bullet$ of finite projective $R$-modules with $E^i = 0$
for $i \not \in [a, b]$.

\label{lemma-perfect-module}
Let $M$ be a module over a ring $R$. The following are equivalent
\begin{enumerate}
\item $M$ is a perfect module, and
\item there exists a resolution
$$
0 \to F_d \to \ldots \to F_1 \to F_0 \to M \to 0
$$
with each $F_i$ a finite projective $R$-module.
\end{enumerate}

\label{lemma-summands-perfect}
Let $R$ be a ring. If $K^\bullet \oplus L^\bullet$ is perfect, then
so are $K^\bullet$ and $L^\bullet$.

\label{lemma-complex-perfect-modules}
Let $R$ be a ring. Let $K^\bullet$ be a bounded complex of perfect
$R$-modules. Then $K^\bullet$ is a perfect complex.

\label{lemma-cohomology-perfect}
Let $R$ be a ring. If $K^\bullet \in D^b(R)$ and all its cohomology
modules are perfect, then $K^\bullet$ is perfect.

\label{lemma-flat-base-change-perfect}
Let $A \to B$ be a flat ring map. Let $M$ be a perfect $A$-module.
Then $M \otimes_A B$ is a perfect $B$-module.

\label{lemma-tensor-perfect}
Let $R$ be a ring. If $K$ and $L$ are perfect objects of $D(R)$, then
$K \otimes_R^\mathbf{L} L$ is a perfect object too.

\label{lemma-regular-perfect}
Let $R$ be a regular ring. Then
\begin{enumerate}
\item an $R$-module is perfect if and only if it is a finite $R$-module, and
\item a complex of $R$-modules $K^\bullet$ is perfect if and only
if $K^\bullet \in D^b(R)$ and each $H^i(K^\bullet)$ is a finite $R$-module.
\end{enumerate}

\label{proposition-perfect-is-compact}
Let $R$ be a ring. For an object $K$ of $D(R)$ the following are equivalent
\begin{enumerate}
\item $K$ is perfect, and
\item $K$ is a compact object of $D(R)$.
\end{enumerate}

\label{lemma-perfect-modulo-nilpotent-ideal}
Let $R$ be a ring. Let $I \subset R$ be an ideal.
Let $K$ be an object of $D(R)$. Assume that
\begin{enumerate}
\item $K \otimes_R^\mathbf{L} R/I$ is perfect in $D(R/I)$, and
\item $I$ is a nilpotent ideal.
\end{enumerate}
Then $K$ is perfect in $D(R)$.

\label{lemma-perfect-modulo-two-ideals}
Let $R$ be a ring. Let $I, J \subset R$ be ideals.
Let $K$ be an object of $D(R)$. Assume that
\begin{enumerate}
\item $K \otimes_R^\mathbf{L} R/I$ is perfect in $D(R/I)$, and
\item $K \otimes_R^\mathbf{L} R/J$ is perfect in $D(R/J)$.
\end{enumerate}
Then $K \otimes_R^\mathbf{L} R/IJ$ is perfect in $D(R/IJ)$.

\label{lemma-ghost-lemma}
\begin{reference}
\cite{Kelly}
\end{reference}
Let $R$ be a ring. Let $n \geq 1$. Let $K \in \langle R \rangle_n$ with
notation as in Derived Categories, Section \ref{derived-section-generators}.
Consider maps
$$
K \xrightarrow{f_1} K_1 \xrightarrow{f_2} K_2
\xrightarrow{f_3} \ldots \xrightarrow{f_n} K_n
$$
in $D(R)$. If $H^i(f_j) = 0$ for all $i, j$, then
$f_n \circ \ldots \circ f_1 = 0$.

\label{proposition-regular-strong-generator}
Let $R$ be a Noetherian ring. The following are equivalent
\begin{enumerate}
\item $R$ is regular of finite dimension,
\item $D_{perf}(R)$ has a strong generator, and
\item $R$ is a strong generator for $D_{perf}(R)$.
\end{enumerate}

\label{definition-relatively-finitely-presented}
Let $R \to A$ be a finite type ring map. Let $M$ be an $A$-module.
We say $M$ is an $A$-module {\it finitely presented relative to $R$}
if the equivalent conditions of
Lemma \ref{lemma-relatively-finitely-presented}
hold.

\label{lemma-glue-relative-finite-presentation}
Let $R \to A$ be a finite type ring map. Let $M$ be an $A$-module.
Let $f_1, \ldots, f_r \in A$ generate the unit ideal.
The following are equivalent
\begin{enumerate}
\item each $M_{f_i}$ is finitely presented relative to $R$, and
\item $M$ is finitely presented relative to $R$.
\end{enumerate}

\label{lemma-ses-relatively-finite-presentation}
Let $R \to A$ be a finite type ring map. Let $0 \to M' \to M \to M'' \to 0$
be a short exact sequence of $A$-modules.
\begin{enumerate}
\item If $M', M''$ are finitely presented relative to $R$, then so is $M$.
\item If $M'$ is a finite type $A$-module and $M$ is finitely presented
relative to $R$, then $M''$ is finitely presented relative to $R$.
\end{enumerate}

\label{definition-relatively-pseudo-coherent}
Let $R \to A$ be a finite type ring map.
Let $K^\bullet$ be a complex of $A$-modules.
Let $M$ be an $A$-module.
Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item We say $K^\bullet$ is {\it $m$-pseudo-coherent relative to $R$}
if the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
hold.
\item We say $K^\bullet$ is {\it pseudo-coherent relative to $R$}
if $K^\bullet$ is $m$-pseudo-coherent relative to $R$ for all
$m \in \mathbf{Z}$.
\item We say $M$ is {\it $m$-pseudo-coherent relative to $R$}
if $M[0]$ is $m$-pseudo-coherent relative to $R$.
\item We say $M$ is {\it pseudo-coherent relative to $R$}
if $M[0]$ is pseudo-coherent relative to $R$.
\end{enumerate}

\label{definition-pseudo-coherent-perfect}
Let $A \to B$ be a ring map.
\begin{enumerate}
\item We say $A \to B$ is a {\it pseudo-coherent ring map} if it is of finite
type and $B$, as a $B$-module, is pseudo-coherent relative to $A$.
\item We say $A \to B$ is a {\it perfect ring map} if it is a
pseudo-coherent ring map such that $B$ as an $A$-module has finite
tor dimension.
\end{enumerate}

\label{lemma-regular-perfect-ring-map}
Let $A \to B$ be a finite type ring map with $A$ a regular ring
of finite dimension. Then $A \to B$ is perfect.

\label{lemma-relative-pseudo-coherent-is-moot}
Let $R \to A$ be a pseudo-coherent ring map. Let $K \in D(A)$.
The following are equivalent
\begin{enumerate}
\item $K$ is $m$-pseudo-coherent (resp.\ pseudo-coherent) relative to $R$, and
\item $K$ is $m$-pseudo-coherent (resp.\ pseudo-coherent) in $D(A)$.
\end{enumerate}

\label{lemma-structure-relatively-perfect}
Let $R \to A$ be a flat ring map of finite presentation.
Let $K \in D(A)$. The following are equivalent
\begin{enumerate}
\item $K$ is $R$-perfect, and
\item $K$ is isomorphic to a finite complex of $R$-flat,
finitely presented $A$-modules.
\end{enumerate}

\label{lemma-bounded-on-fibres-relatively-perfect}
Let $R \to A$ be a ring map which is flat and of finite presentation.
Let $K \in D(A)$ be pseudo-coherent. The following are equivalent
\begin{enumerate}
\item $K$ is $R$-perfect, and
\item $K$ is bounded below and for every prime ideal $\mathfrak p \subset R$
the object $K \otimes_R^\mathbf{L} \kappa(\mathfrak p)$ is bounded below.
\end{enumerate}

\label{lemma-ext-1-zero}
Let $R$ be a ring. Let $K \in D(R)$ with $H^i(K) = 0$ for
$i \not \in \{-1, 0\}$. The following are equivalent
\begin{enumerate}
\item $H^{-1}(K) = 0$ and $H^0(K)$ is a projective module and
\item $\Ext^1_R(K, M) = 0$ for every $R$-module $M$.
\end{enumerate}
If $R$ is Noetherian and $H^i(K)$ is a finite $R$-module for
$i = -1, 0$, then these are also equivalent to
\begin{enumerate}
\item[(3)] $\Ext^1_R(K, M) = 0$ for every finite $R$-module $M$.
\end{enumerate}

\label{lemma-represent-two-term-complex}
Let $R$ be a ring. Let $K$ be an object of $D(R)$ with $H^i(K) = 0$
for $i \not \in \{-1, 0\}$. Then
\begin{enumerate}
\item $K$ can be represented by a two term complex
$K^{-1} \to K^0$ with $K^0$ a free module, and
\item if $R$ is Noetherian and $H^i(K)$ is a finite $R$-module for
$i = -1, 0$, then $K$ can be represented by a two term complex
$K^{-1} \to K^0$ with $K^0$ a finite free module and $K^{-1}$ finite.
\end{enumerate}

\label{lemma-two-term-surjection-map-zero}
Let $R$ be a ring. Let $\alpha : K \to K'$ be a morphism of $D(R)$. Assume
\begin{enumerate}
\item $H^i(K) = H^i(K') = 0$ for $i \not \in \{-1, 0\}$
\item $H^0(\alpha)$ is an isomorphism and $H^{-1}(\alpha)$ is surjective.
\end{enumerate}
For any $f \in R$ if $f : K \to K$ is $0$, then $f : K' \to K'$ is $0$.

\label{lemma-surjection-property-ext-1-annihilated}
Let $I$ be an ideal of a ring $R$. Let $\alpha : K \to K'$
be a morphism of $D(R)$. Assume
\begin{enumerate}
\item $H^i(K) = H^i(K') = 0$ for $i \not \in \{-1, 0\}$
\item $H^0(\alpha)$ is an isomorphism and $H^{-1}(\alpha)$ is surjective.
\end{enumerate}
If $K$ satisfies the equivalent conditions (1), (2), and (3)
of Lemma \ref{lemma-ext-1-annihilated-definite},
then $K'$ does too.

[Emmanouil]
\label{lemma-emmanouil}
\begin{reference}
Taken from \cite{Emmanouil}.
\end{reference}
Let $(A_n)$ be an inverse system of abelian groups.
The following are equivalent
\begin{enumerate}
\item $(A_n)$ is Mittag-Leffler,
\item $R^1\lim A_n = 0$ and
the same holds for $\bigoplus_{i \in \mathbf{N}} (A_n)$.
\end{enumerate}

\label{lemma-Rlim-zero-of-direct-sums}
Let $(A_n)$ be an inverse system of abelian groups.
The following are equivalent
\begin{enumerate}
\item $(A_n)$ is zero as a pro-object,
\item $\lim A_n = 0$ and $R^1\lim A_n = 0$ and
the same holds for $\bigoplus_{i \in \mathbf{N}} (A_n)$.
\end{enumerate}

\label{definition-f-power-torsion}
Let $R$ be a ring. Let $M$ be an $R$-module.
\begin{enumerate}
\item Let $I \subset R$ be an ideal. We say $M$ is an
{\it $I$-power torsion module} if for every $m \in M$ there exists an $n > 0$
such that $I^n m = 0$.
\item Let $f \in R$. We say $M$ is
{\it an $f$-power torsion module} if for each
$m \in M$, there exists an $n > 0$ such that $f^n m = 0$.
\end{enumerate}

\label{lemma-torsion-free}
Let $R$ be a ring. Let $I$ be an ideal of $R$.
For any $R$-module $M$ set $M[I^n] = \{m \in M \mid I^nm = 0\}$.
If $I$ is finitely generated then the following are equivalent
\begin{enumerate}
\item $M[I] = 0$,
\item $M[I^n] = 0$ for all $n \geq 1$, and
\item if $I = (f_1, \ldots, f_t)$, then the map
$M \to \bigoplus M_{f_i}$ is injective.
\end{enumerate}

\label{lemma-divide-by-torsion}
Let $R$ be a ring. Let $I$ be a finitely generated ideal of $R$.
\begin{enumerate}
\item For any $R$-module $M$ we have $(M/M[I^\infty])[I] = 0$.
\item An extension of $I$-power torsion modules is $I$-power torsion.
\end{enumerate}

\label{lemma-derived-vanishing-mod-I}
Let $R$ be a ring. Let $I \subset R$ be an ideal. Let $K$ be an object of
$D(R)$ such that $K \otimes_R^\mathbf{L} R/I = 0$ in $D(R)$. Then
\begin{enumerate}
\item $K \otimes_R^\mathbf{L} R/I^n = 0$ for all $n \geq 1$,
\item $K \otimes_R^\mathbf{L} N = 0$ for any $I$-power torsion
$R$-module $N$,
\item $K \otimes_R^\mathbf{L} M = 0$ for any $M \in D^b(R)$ whose
cohomology modules are $I$-power torsion.
\end{enumerate}

\label{lemma-torsion-completion}
\begin{reference}
Slight generalization of \cite[Lemme~1]{Beauville-Laszlo}.
\end{reference}
Let $R \to R'$ be a ring map. Let $I \subset R$ be an ideal such that
$R/I^n \to R'/I^nR'$ is an isomorphism for $n > 0$.
For any $I$-power torsion $R$-module $M$ the map $M \to M \otimes_R R'$
is an isomorphism.
For example, if $I$ is finitely generated and $R^\wedge$ is the completion
of $R$ with respect to $I$, then we have $M \cong M \otimes_R R^\wedge$.

\label{lemma-neighbourhood-isomorphism}
Assume $(\varphi : R \to S, I)$ satisfies the equivalent conditions of
Lemma \ref{lemma-characterize-flatness-on-torsion}.
The following are equivalent
\begin{enumerate}
\item for any $I$-power torsion module $M$, the natural map
$M \to M \otimes_R S$ is an isomorphism, and
\item $R/I \to S/IS$ is an isomorphism.
\end{enumerate}

\label{lemma-map-identifies-koszul-and-cech-complexes}
Assume $\varphi : R \to S$ is a flat ring map and $I \subset R$ is a
finitely generated ideal such that $R/I \to S/IS$ is an isomorphism.
For any $f_1, \ldots, f_r \in R$ such that $V(f_1, \ldots, f_r) = V(I)$
\begin{enumerate}
\item the map of Koszul complexes
$K(R, f_1, \ldots, f_r) \to K(S, f_1, \ldots, f_r)$ is a quasi-isomorphism, and
\item The map of extended alternating {\v C}ech complexes
$$
\xymatrix{
R \to \prod_{i_0} R_{f_{i_0}} \to \prod_{i_0 < i_1} R_{f_{i_0}f_{i_1}}
\to \ldots \to R_{f_1\ldots f_r} \ar[d] \\
S \to \prod_{i_0} S_{f_{i_0}} \to \prod_{i_0 < i_1} S_{f_{i_0}f_{i_1}}
\to \ldots \to S_{f_1\ldots f_r}
}
$$
is a quasi-isomorphism.
\end{enumerate}

\label{lemma-koszul-homology-annihilated}
Let $R$ be a ring. Let $I = (f_1, \ldots, f_n)$ be a finitely generated ideal
of $R$. For any $R$-module $N$ the Koszul homology group
$H_1(N, f_\bullet)$ defined in
Lemma \ref{lemma-explicit-ext}
is annihilated by $I$.

\label{proposition-formal-glueing}
Let $R$ be a Noetherian ring.
Let $f \in R$ be an element.
Let $R^\wedge$ be the $f$-adic completion of $R$.
Then the functor $M \mapsto (M^\wedge, M_f, \text{can})$
defines an equivalence
$$
\text{Mod}^{fg}_R
\longrightarrow
\text{Mod}^{fg}_{R^\wedge}
\times_{\text{Mod}^{fg}_{(R^\wedge)_f}}
\text{Mod}^{fg}_{R_f}
$$

\label{lemma-same-quotients}
Let $R$ be a ring and let $f \in R$. For every positive integer $n$ the map
$R/f^nR \to R^\wedge/f^n R^\wedge$ is an isomorphism.

\label{lemma-first-tor}
Let $(R \to R', f)$ be a glueing pair. Then
$\text{Tor}^R_1(R', f^n R) = 0$ for each $n > 0$.

\label{lemma-first-tor-total}
Let $(R \to R',f)$ be a glueing pair.
Then $\text{Tor}^R_1(R', R/R[f^\infty]) = 0$.

\label{lemma-BL3}
\begin{reference}
Slight generalization of \cite[Lemme 3(a)]{Beauville-Laszlo}
\end{reference}
Let $(R \to R', f)$ be a glueing pair. For every $R$-module $M$, we have
$\text{Tor}^R_1(R', \Coker(M \to M_f)) = 0$.

\label{theorem-BL-glueing}
\begin{reference}
Slight generalization of the main theorem of \cite{Beauville-Laszlo}.
\end{reference}
Let $(R \to R',f)$ be a glueing pair. The functor
$\text{Can} : \text{Mod}_R \longrightarrow \text{Glue}(R \to R', f)$
determines an equivalence of the category of $R$-modules glueable
for $(R \to R', f)$ and the category $\text{Glue}(R \to R', f)$
of glueing data.

\label{lemma-ideal-of-elements-complete-wrt}
Let $A$ be a ring. Let $K \in D(A)$. The set $I$ of $f \in A$ such that
$T(K, f) = 0$ is a radical ideal of $A$.

\label{lemma-complete-derived-complete}
Let $A$ be a ring. Let $I \subset A$ be an ideal. Let $M$ be an $A$-module.
\begin{enumerate}
\item If $M$ is $I$-adically complete, then $T(M, f) = 0$ for all $f \in I$.
\item Conversely, if $T(M, f) = 0$ for all $f \in I$ and $I$ is finitely
generated, then $M \to \lim M/I^nM$ is surjective.
\end{enumerate}

\label{definition-derived-complete}
Let $A$ be a ring. Let $K \in D(A)$. Let $I \subset A$ be an ideal.
We say $K$ is {\it derived complete with respect to $I$}
if for every $f \in I$ we have $T(K, f) = 0$.
If $M$ is an $A$-module, then we say $M$ is
{\it derived complete with respect to $I$}
if $M[0] \in D(A)$ is derived complete with respect to $I$.

\label{proposition-derived-complete-modules}
Let $I \subset A$ be a finitely generated ideal of a ring $A$.
Let $M$ be an $A$-module. The following are equivalent
\begin{enumerate}
\item $M$ is $I$-adically complete, and
\item $M$ is derived complete with respect to $I$ and $\bigcap I^nM = 0$.
\end{enumerate}

\label{lemma-serre-subcategory}
Let $I$ be an ideal of a ring $A$.
\begin{enumerate}
\item The derived complete $A$-modules form a weak Serre
subcategory $\mathcal{C}$ of $\text{Mod}_A$.
\item $D_\mathcal{C}(A) \subset D(A)$ is the full subcategory
of derived complete objects.
\end{enumerate}

\label{lemma-double-localize}
Let $A$ be a ring. Let $f, g \in A$. Then for $K \in D(A)$ we have
$R\Hom_A(A_f, R\Hom_A(A_g, K)) = R\Hom_A(A_{fg}, K)$.

\label{lemma-characterize-derived-complete-Koszul}
In Situation \ref{situation-koszul}. Let $K \in D(A)$.
The following are equivalent
\begin{enumerate}
\item $K$ is derived complete with respect to $I$, and
\item the canonical map $K \to R\lim (K \otimes_A^\mathbf{L} K_n^\bullet)$
is an isomorphism of $D(A)$.
\end{enumerate}

\label{lemma-derived-complete-bounded}
Let $I = (f_1, \ldots, f_r)$ be a finitely generated ideal of a ring $A$.
Let $K$ be a derived complete object of $D(A)$. The following are equivalent
\begin{enumerate}
\item $H^i(K) = 0$ for $i > 0$,
\item $H^i(K \otimes_A^\mathbf{L} A/I) = 0$ for $i > 0$,
\item $H^i(K \otimes_A^\mathbf{L} K_1^\bullet) = 0$ for $i > 0$
where $K_1^\bullet$ is as in Situation \ref{situation-koszul}.
\end{enumerate}

\label{lemma-derived-complete-zero-bis}
\begin{slogan}
Derived Nakayama
\end{slogan}
\begin{reference}
A related result is \cite[Proposition 6.5]{Dwyer-Greenlees}.
The derived Nakayama lemma can for example be found in Bhatt's 3rd lecture
on Prismatic cohomology at Columbia University in Fall 2018
as Section 2 property (2). Leonid Positselski proposed a proof in
\url{https://mathoverflow.net/a/331501}. However, we follow the proof
suggested by Anonymous in the comments.
\end{reference}
Let $I$ be a finitely generated ideal of a ring $A$.
Let $K$ be a derived complete object of $D(A)$.
If $K \otimes_A^\mathbf{L} A/I = 0$, then $K = 0$.

\label{lemma-derived-complete-henselian}
Let $A$ be a ring derived complete with respect to an ideal $I$.
Then $(A, I)$ is a henselian pair.

\label{lemma-reduced-derived-complete-complete}
Let $A$ be a reduced ring derived complete with respect to
a finitely generated ideal $I$. Then $A$ is $I$-adically complete.

\label{lemma-when-derived-completion-is-completion}
Let $I$ be an ideal in a Noetherian ring $A$.
\begin{enumerate}
\item If $M$ is a finite $A$-module and $N$ is a flat $A$-module, then the
derived $I$-adic completion of $M \otimes_A N$ is the usual
$I$-adic completion of $M \otimes_A N$.
\item If $M$ is a finite $A$-module and $f \in A$, then the derived
$I$-adic completion of $M_f$ is the usual $I$-adic completion
of $M_f$.
\end{enumerate}

\label{lemma-derived-completion-tensor-finite}
Let $I$ be an ideal in a Noetherian ring $A$.
Let ${}^\wedge$ denote derived completion with respect to $I$.
Let $K \in D^-(A)$.
\begin{enumerate}
\item If $M$ is a finite $A$-module, then
$(K \otimes_A^\mathbf{L} M)^\wedge = K^\wedge \otimes_A^\mathbf{L} M$.
\item If $L \in D(A)$ is pseudo-coherent, then
$(K \otimes_A^\mathbf{L} L)^\wedge = K^\wedge \otimes_A^\mathbf{L} L$.
\end{enumerate}

\label{lemma-Rlim-perfect-gives-perfect}
\begin{reference}
\cite[Lemma 4.2]{Bhatt-Algebraize}
\end{reference}
Let $A = \lim A_n$ be a limit of an inverse system $(A_n)$ of rings.
Suppose given $K_n \in D(A_n)$ and maps $K_{n + 1} \to K_n$
in $D(A_{n + 1})$. Assume
\begin{enumerate}
\item the transition maps $A_{n + 1} \to A_n$ are surjective with
locally nilpotent kernels,
\item either all $K_n$ are perfect or there exists an integer $n_0$
such that $K_{n_0}$ is perfect and the kernels $A_{n + 1} \to A_n$
are nilpotent for $n \geq n_0$, and
\item the maps induce isomorphisms
$K_{n + 1} \otimes_{A_{n + 1}}^\mathbf{L} A_n \to K_n$.
\end{enumerate}
Then $K = R\lim K_n$ is a perfect object of $D(A)$
and $K \otimes_A^\mathbf{L} A_n \to K_n$ is an isomorphism for all $n$.

[Koll\'ar-Kov\'acs]
\label{lemma-kollar-kovacs}
\begin{reference}
Email from Kovacs of 23/02/2018.
\end{reference}
Let $I$ be an ideal of a Noetherian ring $A$. Let $K \in D(A)$.
Set $K_n = K \otimes_A^\mathbf{L} A/I^n$. Assume for all
$i \in \mathbf{Z}$ we have
\begin{enumerate}
\item $H^i(K)$ is a finite $A$-module, and
\item the system $H^i(K_n)$ satisfies Mittag-Leffler.
\end{enumerate}
Then $\lim H^i(K)/I^nH^i(K)$ is equal to $\lim H^i(K_n)$ for all
$i \in \mathbf{Z}$.

\label{lemma-kollar-kovacs-pseudo-coherent}
\begin{reference}
Email from Kovacs of 23/02/2018.
\end{reference}
Let $I$ be an ideal of a Noetherian ring $A$. Let $K \in D(A)$
be pseudo-coherent. Set $K_n = K \otimes_A^\mathbf{L} A/I^n$.
Then for all $i \in \mathbf{Z}$ the system $H^i(K_n)$
satisfies Mittag-Leffler and $\lim H^i(K)/I^nH^i(K)$ is equal to
$\lim H^i(K_n)$.

\label{lemma-dejong-kollar-kovacs}
\begin{reference}
Email correspondence between Janos Kollar, Sandor Kovacs, and
Johan de Jong of 23/02/2018.
\end{reference}
Let $I$ be an ideal of the Noetherian ring $A$. Let $M$ and $N$
be finite $A$-modules. Write $A_n = A/I^n$, $M_n = M/I^nM$, and
$N_n = N/I^nN$.
For every $i \geq 0$ the objects
$$
\{\Ext^i_A(M, N)/I^n\Ext^i_A(M, N)\}_{n \geq 1}
\quad\text{and}\quad
\{\Ext^i_{A_n}(M_n, N_n)\}_{n \geq 1}
$$
are isomorphic in the category $\mathcal{C}$ of
Remark \ref{remark-weird-systems}.

\label{lemma-f-flat}
Let $R$ be a ring and $f \in R$. Let $M \in D(R)$. Assume
\begin{enumerate}
\item $H^i(M) = 0$ for $i > 0$,
\item $M \otimes_R^\mathbf{L} R_f$ is isomorphic to a flat $R_f$-module
placed in degree $0$,
\item $M \otimes_R^\mathbf{L} R/fR$ is isomorphic to a flat $R/fR$-module
placed in degree $0$.
\end{enumerate}
Then $M$ is isomorphic to a flat $R$-module placed in degree $0$.

\label{definition-weakly-etale}
A ring $A$ is called {\it absolutely flat} if every $A$-module is flat over
$A$. A ring map $A \to B$ is {\it weakly \'etale} or {\it absolutely flat}
if both $A \to B$ and $B \otimes_A B \to B$ are flat.

\label{definition-weak-dimension}
Let $A$ be a ring. Let $d \geq 0$ be an integer.
We say that $A$ has {\it weak dimension $\leq d$}
if every $A$-module has tor dimension $\leq d$.

\label{lemma-weak-dimension-goes-up}
Let $A \to B$ be a weakly \'etale ring map.
If $A$ has weak dimension at most $d$, then so does $B$.

\label{lemma-absolutely-flat}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ has weak dimension $\leq 0$,
\item $A$ is absolutely flat,
\item $A$ is reduced and every prime is maximal, and
\item every local ring of $A$ is a field.
\end{enumerate}

\label{lemma-base-change-weakly-etale}
Let $A \to B$ and $A \to A'$ be ring maps. Let $B' = B \otimes_A A'$
be the base change of $B$.
\begin{enumerate}
\item If $B \otimes_A B \to B$ is flat, then $B' \otimes_{A'} B' \to B'$
is flat.
\item If $A \to B$ is weakly \'etale, then $A' \to B'$ is weakly \'etale.
\end{enumerate}

\label{lemma-absolutely-flat-over-absolutely-flat}
Let $A \to B$ be a ring map such that $B \otimes_A B \to B$ is flat.
\begin{enumerate}
\item If $A$ is an absolutely flat ring, then so is $B$.
\item If $A$ is reduced and $A \to B$ is weakly \'etale, then $B$ is reduced.
\end{enumerate}

\label{lemma-composition-weakly-etale}
Let $A \to B$ and $B \to C$ be ring maps.
\begin{enumerate}
\item If $B \otimes_A B \to B$ and $C \otimes_B C \to C$
are flat, then $C \otimes_A C \to C$ is flat.
\item If $A \to B$ and $B \to C$ are weakly \'etale, then $A \to C$
is weakly \'etale.
\end{enumerate}

\label{lemma-go-down}
Let $A \to B \to C$ be ring maps.
\begin{enumerate}
\item If $B \to C$ is faithfully flat and $C \otimes_A C \to C$ is flat,
then $B \otimes_A B \to B$ is flat.
\item If $B \to C$ is faithfully flat and $A \to C$ is weakly \'etale,
then $A \to B$ is weakly \'etale.
\end{enumerate}

\label{lemma-weakly-etale-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra map of weakly \'etale
$A$-algebras. Then $B \to C$ is weakly \'etale.

\label{lemma-formally-unramified}
Let $A \to B$ be a ring map such that $B \otimes_A B \to B$ is flat.
Then $\Omega_{B/A} = 0$, i.e., $B$ is formally unramified over $A$.

\label{lemma-weakly-etale-finite-type}
Let $A \to B$ be a ring map such that $B \otimes_A B \to B$ is flat.
\begin{enumerate}
\item If $A \to B$ is of finite type, then $A \to B$ is unramified.
\item If $A \to B$ is of finite presentation and flat, then
$A \to B$ is \'etale.
\end{enumerate}
In particular a weakly \'etale ring map of finite presentation is \'etale.

\label{lemma-when-weakly-etale}
Let $A \to B$ be a ring map. Then $A \to B$ is weakly \'etale in each
of the following cases
\begin{enumerate}
\item $B = S^{-1}A$ is a localization of $A$,
\item $A \to B$ is \'etale,
\item $B$ is a filtered colimit of weakly \'etale $A$-algebras.
\end{enumerate}

\label{lemma-absolutely-flat-fields}
Let $L/K$ be an extension of fields. If $L \otimes_K L \to L$
is flat, then $L$ is an algebraic separable extension of $K$.

\label{lemma-absolutely-flat-over-field}
Let $B$ be an algebra over a field $K$. The following are
equivalent
\begin{enumerate}
\item $B \otimes_K B \to B$ is flat,
\item $K \to B$ is weakly \'etale, and
\item $B$ is a filtered colimit of \'etale $K$-algebras.
\end{enumerate}
Moreover, every finitely generated $K$-subalgebra of $B$
is \'etale over $K$.

\label{lemma-weakly-etale-residue-field-extensions}
Let $A \to B$ be a ring map. If $A \to B$ is weakly \'etale, then
$A \to B$ induces separable algebraic residue field extensions.

\label{lemma-weak-dimension-at-most-1}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ has weak dimension $\leq 1$,
\item every ideal of $A$ is flat,
\item every finitely generated ideal of $A$ is flat,
\item every submodule of a flat $A$-module is flat, and
\item every local ring of $A$ is a valuation ring.
\end{enumerate}

\label{lemma-max-weakly-etale-subalgebra}
Let $K$ be a field. Let $A$ be a $K$-algebra. There exists
a maximal weakly \'etale $K$-subalgebra $B_{max} \subset A$.

\label{definition-unibranch}
\begin{reference}
\cite[Chapter 0 (23.2.1)]{EGA4}
\end{reference}
Let $A$ be a local ring. We say $A$ is {\it unibranch}
if the reduction $A_{red}$ is a domain and if the integral closure
$A'$ of $A_{red}$ in its field of fractions is local.
We say $A$ is {\it geometrically unibranch} if $A$ is unibranch
and moreover the residue field of $A'$ is purely inseparable over
the residue field of $A$.

\label{lemma-unibranch}
\begin{reference}
\cite[Chapter IV Proposition 18.6.12]{EGA4}
\end{reference}
Let $A$ be a local ring. Let $A^h$ be the henselization of $A$.
The following are equivalent
\begin{enumerate}
\item $A$ is unibranch, and
\item $A^h$ has a unique minimal prime.
\end{enumerate}

\label{lemma-geometrically-unibranch}
\begin{reference}
\cite[Lemma 2.2]{Etale-coverings} and
\cite[Chapter IV Proposition 18.8.15]{EGA4}
\end{reference}
Let $A$ be a local ring. Let $A^{sh}$ be a strict henselization of $A$.
The following are equivalent
\begin{enumerate}
\item $A$ is geometrically unibranch, and
\item $A^{sh}$ has a unique minimal prime.
\end{enumerate}

\label{definition-number-of-branches}
Let $A$ be a local ring with henselization $A^h$ and
strict henselization $A^{sh}$. The {\it number of branches of $A$}
is the number of minimal primes of $A^h$ if finite and $\infty$
otherwise. The {\it number of geometric branches of $A$}
is the number of minimal primes of $A^{sh}$ if finite and $\infty$
otherwise.

\label{lemma-invariance-number-branches-smooth}
Let $A \to B$ be a local homomorphism of local rings which
is the localization of a smooth ring map.
\begin{enumerate}
\item The number of geometric branches of $A$ is equal to the number
of geometric branches of $B$.
\item If $A \to B$ induces a purely inseparable extension of residue fields,
then the number of branches of $A$ is the number of branches of $B$.
\end{enumerate}

\label{lemma-unramified-extension-unibranch-domain-is-etale}
\begin{reference}
Generalization of \cite[Expose I, Theorem 9.5 part (ii)]{SGA1}
\end{reference}
Let $(A, \mathfrak m)$ be a geometrically unibranch local domain. Let
$A \to B$ be an injective local homomorphism of local rings,
which is essentially of finite type. If $\mathfrak m B$
is the maximal ideal of $B$ and the induced extension of
residue fields is separable, then $A \to B$ is the localization
of an \'etale ring map.

\label{lemma-nr-branches-completion}
Let $(A, \mathfrak m)$ be a Noetherian local ring.
\begin{enumerate}
\item The map $A^h \to A^\wedge$ defines a surjective map from minimal
primes of $A^\wedge$ to minimal primes of $A^h$.
\item The number of branches of $A$ is at most the number of branches
of $A^\wedge$.
\item The number of geometric branches of $A$ is at most the number
of geometric branches of $A^\wedge$.
\end{enumerate}

\label{lemma-one-dimensional-number-of-branches}
Let $(A, \mathfrak m)$ be a Noetherian local ring of dimension $1$.
Then the number of (geometric) branches of $A$ and $A^\wedge$ is the same.

\label{lemma-geometrically-normal-formal-fibres-number-of-branches}
\begin{reference}
\cite[Theorem 2.3]{Beddani}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian local ring. If the formal
fibres of $A$ are geometrically normal (for example if $A$ is
excellent or quasi-excellent), then $A$ is Nagata
and the number of (geometric) branches of $A$ and $A^\wedge$ is the same.

\label{definition-formally-catenary}
A Noetherian local ring $A$ is {\it formally catenary}
if for every minimal prime $\mathfrak p \subset A$ the spectrum of
$A^\wedge/\mathfrak p A^\wedge$ is equidimensional.

\label{lemma-not-formally-catenary}
Let $(A, \mathfrak m)$ be a Noetherian local ring which is not
formally catenary. Then $A$ is not universally catenary.

\label{lemma-flat-under-catenary-equidimensional}
Let $A \to B$ be a flat local ring map of local Noetherian rings.
Assume $B$ is catenary and is $\Spec(B)$ equidimensional. Then
\begin{enumerate}
\item $\Spec(B/\mathfrak p B)$ is equidimensional for all
$\mathfrak p \subset A$ and
\item $A$ is catenary and $\Spec(A)$ is equidimensional.
\end{enumerate}

\label{lemma-formally-catenary}
Let $A$ be a formally catenary Noetherian local ring.
Then $A$ is universally catenary.

[Ratliff]
\label{proposition-ratliff}
\begin{reference}
\cite{Ratliff}
\end{reference}
A Noetherian local ring is universally catenary if and only if
it is formally catenary.

\label{lemma-geometrically-normal-fibres-universally-catenary}
\begin{reference}
\cite[Corollary 2.3]{Heinzer-Rotthaus-Wiegand}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian local ring with
geometrically normal formal fibres. Then
\begin{enumerate}
\item $A^h$ is universally catenary, and
\item if $A$ is unibranch (for example normal), then
$A$ is universally catenary.
\end{enumerate}

\label{lemma-functor-invariants-tensor}
Let $R$ be a ring. Let $G$ be a finite group of order $n$ acting on $R$.
Let $A$ be an $R^G$-algebra.
\begin{enumerate}
\item for $b \in (A \otimes_{R^G} R)^G$ there exists a monic polynomial
$P \in A[T]$ whose image in $(A \otimes_{R^G} R)^G[T]$ is $(T - b)^n$,
\item for $a \in \Ker(A \to (A \otimes_{R^G} R)^G)$ we have
$(T - a)^n = T^n$ in $A[T]$.
\end{enumerate}

\label{lemma-extension-dvrs-formally-smooth}
Let $A \subset B$ be an extension of discrete valuation rings.
The following are equivalent
\begin{enumerate}
\item $A \to B$ is formally smooth in the $\mathfrak m_B$-adic topology, and
\item $A \to B$ is weakly unramified and $\kappa_B/\kappa_A$
is a separable field extension.
\end{enumerate}

\label{lemma-galois}
Let $A$ be a discrete valuation ring with fraction field $K$.
Let $L/K$ be a finite Galois extension with Galois group $G$.
Then $G$ acts on the ring $B$ of Remark \ref{remark-finite-separable-extension}
and acts transitively on the set of maximal ideals of $B$.

\label{definition-decomposition-inertia}
Let $A$ be a discrete valuation ring with fraction field $K$.
Let $L/K$ be a finite Galois extension with Galois group $G$.
Let $B$ be the integral closure of $A$ in $L$.
Let $\mathfrak m \subset B$ be a maximal ideal.
\begin{enumerate}
\item The {\it decomposition group of $\mathfrak m$}
is the subgroup $D = \{\sigma \in G \mid \sigma(\mathfrak m) = \mathfrak m\}$.
\item The {\it inertia group of $\mathfrak m$} is the kernel $I$ of the map
$D \to \text{Aut}(\kappa(\mathfrak m)/\kappa_A)$.
\end{enumerate}

\label{lemma-galois-galois}
Let $A$ be a discrete valuation ring with fraction field $K$ and residue field
$\kappa$. Let $L/K$ be a finite Galois extension with Galois group $G$.
Let $B$ be the integral closure of $A$ in $L$. Let $\mathfrak m$ be a maximal
ideal of $B$. Then
\begin{enumerate}
\item the field extension $\kappa(\mathfrak m)/\kappa$ is normal, and
\item $D \to \text{Aut}(\kappa(\mathfrak m)/\kappa)$ is surjective.
\end{enumerate}
If for some (equivalently all) maximal ideal(s) $\mathfrak m \subset B$
the field extension $\kappa(\mathfrak m)/\kappa$ is separable, then
\begin{enumerate}
\item[(3)] $\kappa(\mathfrak m)/\kappa$ is Galois, and
\item[(4)] $D \to \text{Gal}(\kappa(\mathfrak m)/\kappa)$ is surjective.
\end{enumerate}
Here $D \subset G$ is the decomposition group of $\mathfrak m$.

\label{definition-wild-inertia}
With assumptions and notation as in Lemma \ref{lemma-galois-inertia}.
\begin{enumerate}
\item The {\it wild inertia group of $\mathfrak m$} is the subgroup $P$.
\item The {\it tame inertia group of $\mathfrak m$} is the
quotient $I \to I_t$.
\end{enumerate}
We denote $\theta : I \to \mu_e(\kappa(\mathfrak m))$ the surjective map
(\ref{equation-inertia-character}) whose kernel is $P$ and which
induces the isomorphism $I_t \to \mu_e(\kappa(\mathfrak m))$.

\label{definition-mixed}
Let $A$ be a discrete valuation ring. We say $A$ has {\it mixed characteristic}
if the characteristic of the residue field of $A$ is $p > 0$ and the
characteristic of the fraction field of $A$ is $0$.
In this case we obtain an extension of discrete valuation rings
$\mathbf{Z}_{(p)} \subset A$ and the {\it absolute ramification index}
of $A$ is the ramification index of this extension.

\label{lemma-solutions-go-down}
Let $A \to B \to C$ be extensions of discrete valuation rings with fraction
fields $K \subset L \subset M$. Let $K_1/K$ be a finite extension.
\begin{enumerate}
\item If $K_1$ is a (weak) solution for $A \to C$, then $K_1$ is a (weak)
solution for $A \to B$.
\item If $K_1$ is a (weak) solution for $A \to B$ and
$L_1 = (L \otimes_K K_1)_{red}$ is a product of fields which are
(weak) solutions for $B \to C$, then $K_1$ is a (weak) solution for $A \to C$.
\end{enumerate}

\label{lemma-galois-relative}
Let $A \to B$ be an extension of discrete valuation rings with fraction fields
$K \subset L$. Let $K_1/K$ be a normal extension. Say
$G = \text{Aut}(K_1/K)$. Then $G$ acts on the rings $K_1$, $L_1$,
$A_1$ and $B_1$ of Remark \ref{remark-construction}
and acts transitively on the set of maximal ideals of $B_1$.

\label{lemma-separable-solution-separable-solution}
Let $A \subset B$ be an extension of discrete valuation rings.
Assume
\begin{enumerate}
\item the extension $L/K$ of fraction fields is separable,
\item $B$ is Nagata, and
\item there exists a solution for $A \subset B$.
\end{enumerate}
Then there exists a separable solution for $A \subset B$.

\label{proposition-epp-essentially-finite-type}
\begin{reference}
See \cite[Lemma 2.13]{alterations} for a special case.
\end{reference}
Let $A \to B$ be an extension of discrete valuation rings with fraction
fields $K \subset L$. If $B$ is essentially of finite type over $A$, then
there exists a finite extension $K_1/K$ which is a solution for
$A \to B$ as defined in
Definition \ref{definition-solution}.

\label{lemma-epp-essentially-finite-type-separable}
Let $A \to B$ be an extension of discrete valuation rings with fraction
fields $K \subset L$. Assume
\begin{enumerate}
\item $B$ is essentially of finite type over $A$,
\item either $A$ or $B$ is a Nagata ring, and
\item $L/K$ is separable.
\end{enumerate}
Then there exists a separable solution for $A \to B$
(Definition \ref{definition-solution}).

\label{lemma-invertible}
Let $R$ be a ring. Let $M$ be an $R$-module. Equivalent are
\begin{enumerate}
\item $M$ is finite locally free module of rank $1$,
\item $M$ is invertible, and
\item there exists an $R$-module $N$ such that $M \otimes_R N \cong R$.
\end{enumerate}
Moreover, in this case the module $N$ in (3) is isomorphic
to $\Hom_R(M, R)$.

\label{lemma-regular-local-Pic-zero}
Let $R$ be a regular local ring. Let $f \in R$.
Then $\Pic(R_f) = 0$.

\label{lemma-picard-group-generic-fibre-regular}
Let $R$ be a valuation ring with fraction field $K$
and residue field $\kappa$. Let $R \to A$ be a
homomorphism of rings such that
\begin{enumerate}
\item $A$ is local and $R \to A$ is local,
\item $A$ is flat and essentially of finite type over $R$,
\item $A \otimes_R \kappa$ regular.
\end{enumerate}
Then $\Pic(A \otimes_R K) = 0$.

\label{lemma-determinant-two-term-complexes}
Let $R$ be a ring. The constructions above determine a functor
$$
\det :
\left\{
\begin{matrix}
\text{category of perfect complexes} \\
\text{with tor amplitude in }[-1, 0] \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of invertible modules} \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
$$
Moreover, given a rank $0$ perfect object $L$ of $D(R)$ with
tor-amplitude in $[-1, 0]$ there is a canonical element
$\delta(L) \in \det(L)$ such that for any isomorphism
$a : L \to K$ in $D(R)$ we have $\det(a)(\delta(L)) = \delta(K)$.

\label{lemma-characterize-PD-modules}
\begin{reference}
\cite[Corollary 1]{Warfield-Purity}
\end{reference}
Let $P$ be a module over a ring $R$. The following are equivalent
\begin{enumerate}
\item $P$ is a direct summand of a direct sum of modules of the
form $R/fR$, for $f \in R$ varying.
\item for every short exact sequence $0 \to A \to B \to C \to 0$
of $R$-modules such that $fA = A \cap fB$ for all $f \in R$
the map $\Hom_R(P, B) \to \Hom_R(P, C)$ is surjective.
\end{enumerate}

[Generalized valuation rings]
\label{lemma-generalized-valuation-ring}
\begin{reference}
\cite{Warfield-Decomposition}
\end{reference}
Let $R$ be a nonzero ring. The following are equivalent
\begin{enumerate}
\item For $a, b \in R$ either $a$ divides $b$ or $b$ divides $a$.
\item Every finitely generated ideal is principal and $R$ is local.
\item The set of ideals of $R$ is linearly ordered by inclusion.
\end{enumerate}
This holds in particular if $R$ is a valuation ring.

\label{lemma-generalized-valuation-ring-modules}
\begin{reference}
\cite[Theorem 1]{Warfield-Decomposition}
\end{reference}
Let $R$ be a ring satisfying the equivalent conditions of
Lemma \ref{lemma-generalized-valuation-ring}.
Then every finitely presented $R$-module
is isomorphic to a finite direct sum of modules of the form $R/fR$.

\label{lemma-warfield}
\begin{reference}
\cite[Theorem 3]{Warfield-Decomposition}
\end{reference}
Let $R$ be a ring such that every local ring of $R$ at a maximal
ideal satisfies the equivalent conditions of
Lemma \ref{lemma-generalized-valuation-ring}.
Then every finitely presented $R$-module is a summand of a 
finite direct sum of modules of the form $R/fR$ for $f$ in $R$ varying.

\label{lemma-split-off-free-part}
Let $R$ be a B\'ezout domain.
\begin{enumerate}
\item Every finite submodule of a free module is finite free.
\item Every finitely presented $R$-module $M$ is a direct sum of a
finite free module and a torsion module $M_{tors}$ which is a
summand of a module of the form $\bigoplus_{i = 1, \ldots, n} R/f_iR$
with $f_1, \ldots, f_n \in R$ nonzero.
\end{enumerate}

\label{lemma-polypoly}
Let $(R,\mathfrak m)$ be a Noetherian local ring of dimension one, and
let $x\in\mathfrak m$ be an element not contained in any minimal prime
of $R$. Then
\begin{enumerate}
\item the function $P : n \mapsto \text{length}_R(R/x^n R)$
satisfies $P(n) \leq n P(1)$ for $n \geq 0$,
\item if $x$ is a nonzerodivisor, then $P(n) = nP(1)$ for $n \geq 0$.
\end{enumerate}

\label{proposition-propdimd}
\begin{reference}
\cite[Lemma 3.14]{Artin-Lipman} has this result without the
assumption that the ring is catenary
\end{reference}
Let $R$ be a catenary Noetherian local normal domain.
Let $J \subset R$ be a radical ideal.
Then there exists a nonzero element $f \in J$
such that $R/fR$ is reduced.

\label{lemma-have-dual-derived}
Let $R$ be a ring. Let $M$ be an object of $D(R)$. The following
are equivalent
\begin{enumerate}
\item $M$ has a left dual in $D(R)$ as in
Categories, Definition \ref{categories-definition-dual},
\item $M$ is a perfect object of $D(R)$.
\end{enumerate}
Moreover, in this case the left dual of $M$ is the object
$M^\vee$ of Lemma \ref{lemma-dual-perfect-complex}.

\label{proposition-splitting}
\begin{reference}
\cite[Theorem 2]{Serre-projective}
\end{reference}
In Situation \ref{situation-splitting} assume $\Omega$ is
a Noetherian topological space. Let $s_1, \ldots, s_h \in M$.
Let $Z(s_1, \ldots, s_h) \subset F \subset \Omega$ be closed.
Let $x_1, \ldots, x_n \in F$ be pairwise distinct.
Let $v_i  \in V(x_i)$.
Let $k \geq 0$ be an integer such that
$$
(*)\quad h + k \leq \dim_{\kappa(x)} V(x)\text{ for all }x \in \Omega
$$
Then there exist $s \in M$ and $F' \subset \Omega$ closed such that
\begin{enumerate}
\item[(a)] $s(x_i)$ maps to $v_i$,
\item[(b)] $Z(s_1, \ldots, s_h, s) \subset F \cup F'$, and
\item[(c)] every irreducible component of $F'$ has
codimension $\geq k$ in $\Omega$.
\end{enumerate}

\label{theorem-splitting}
\begin{reference}
\cite[Theorem 1]{Serre-projective}
\end{reference}
Let $R$ be a ring whose max spectrum $\Omega \subset \Spec(R)$
is a Noetherian topological space of dimension $d < \infty$.
Let $M$ be a finitely presented $R$-module such that
for all $\mathfrak m \in \Omega$ the $R_\mathfrak m$-module
$M_\mathfrak m$ has a free direct summand of rank $> d$.
Then $M \cong R \oplus M'$.

[Eilenberg's lemma]
\label{lemma-eilenberg-swindle}
\begin{slogan}
Eilenberg swindle
\end{slogan}
\begin{history}
In \cite{Bass} we find: ``...is an elegant little swindle,
observed several years ago by Eilenberg, and which
might well have sprung from the brow of Barry Mazur.''
\end{history}
\begin{reference}
\cite[Eilenberg's lemma]{Bass}
\end{reference}
If $P \oplus Q \cong F$ with $F$ a nonfinitely generated free module,
then $P \oplus F \cong F$.

\label{lemma-projective-plus-free-is-free}
Let $R$ be a ring. Let $P$ be a projective module.
There exists a free module $F$ such that $P \oplus F$ is free.

\label{theorem-countable-free}
\begin{reference}
Commutative case of \cite[Theorem 3.1]{Bass}
\end{reference}
Let $R$ be a ring with Jacobson radical $J$ such that $R/J$ is Noetherian.
Let $P$ be a countably generated projective $R$-module such that
$P_\mathfrak m$ has infinite rank for all maximal ideals
$\mathfrak m$ of $R$. Then $P$ is free.

\label{lemma-proper-f-shriek}
Let $f : X \to Y$ be a proper morphism of schemes.
Then $f_! = f_*$.

\label{lemma-proper-compact-support}
Let $X$ be a proper scheme over a field $k$. Then
$H^0_c(X, \mathcal{F}) = H^0(X, \mathcal{F})$.

\label{lemma-f-shriek-separated-direct-sums}
Let $f : X \to Y$ be a morphism of schemes which is separated and
locally of finite type. Then functor $f_!$ commutes with direct sums.

\label{lemma-lqf-f-shriek-separated-colimits}
Let $f : X \to Y$ be a morphism of schemes which is separated and
locally quasi-finite. Then
\begin{enumerate}
\item for $\mathcal{F}$ in $\textit{Ab}(X_\etale)$ and a geometric
point $\overline{y} : \Spec(k) \to Y$ we have
$$
(f_!\mathcal{F})_{\overline{y}} =
\bigoplus\nolimits_{f(\overline{x}) = \overline{y}} \mathcal{F}_{\overline{x}}
$$
functorially in $\mathcal{F}$, and
\item the functor $f_!$ is exact.
\end{enumerate}

\label{lemma-finite-support-f-shriek-separated}
Let $f : X \to Y$ be a separated and locally quasi-finite morphism
of schemes. Functorially in $\mathcal{F} \in \textit{Ab}(X_\etale)$
there is a canonical isomorphism(!)
$$
f_{p!}\mathcal{F} \longrightarrow f_!\mathcal{F}
$$
of abelian presheaves which identifies the sheaf
$f_!\mathcal{F}$ of Definition \ref{definition-f-shriek-separated}
with the presheaf $f_{p!}\mathcal{F}$ constructed above.

\label{lemma-lqf-f-shriek-stalk}
Let $f : X \to Y$ be a locally quasi-finite morphism of schemes. Then
\begin{enumerate}
\item for $\mathcal{F}$ in $\textit{Ab}(X_\etale)$ and a geometric
point $\overline{y} : \Spec(k) \to Y$ we have
$$
(f_!\mathcal{F})_{\overline{y}} =
\bigoplus\nolimits_{f(\overline{x}) = \overline{y}} \mathcal{F}_{\overline{x}}
$$
functorially in $\mathcal{F}$, and
\item the functor $f_! : \textit{Ab}(X_\etale) \to \textit{Ab}(Y_\etale)$
is exact and commutes with direct sums.
\end{enumerate}

\label{lemma-lqf-base-change-f-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of schemes with $f$ locally quasi-finite. There is an isomorphism
$g^{-1}f_!\mathcal{F} \to f'_!(g')^{-1}\mathcal{F}$ functorial for
$\mathcal{F}$ in $\textit{Ab}(X_\etale)$ which is compatible with
the descriptions of stalks given in Lemma \ref{lemma-lqf-f-shriek-stalk}
(see proof for the precise statement).

\label{lemma-lqf-separated-shriek-composition}
Let $f' : X \to Y'$ and $g : Y' \to Y$ be composable morphisms of schemes
with $f'$ and $f = g \circ f'$ locally quasi-finite and $g$ separated and
locally of finite type. Then there is a canonical isomorphism of functors
$g_! \circ f'_! = f_!$. This isomorphism is compatible with
\begin{enumerate}
\item[(a)] covariance with respect to open embeddings as in
Remarks \ref{remark-covariance-f-shriek-separated} and
\ref{remark-covariance-lqf-f-shriek},
\item[(b)] the base change isomorphisms of
Lemmas \ref{lemma-lqf-base-change-f-shriek}
and \ref{lemma-base-change-f-shriek-separated}, and
\item[(c)] equal to the isomorphism of Lemma \ref{lemma-f-shriek-composition}
via the identifications of Lemma \ref{lemma-finite-support-f-shriek-separated}
in case $f'$ is separated.
\end{enumerate}

\label{lemma-upper-shriek-restriction-etale}
Let $j : U \to X$ and $j' : V \to U$ be \'etale morphisms.
The isomorphism $(j \circ j')^{-1} = (j')^{-1} \circ j^{-1}$
and the isomorphism $(j \circ j')^! = (j')^! \circ j^!$ of
Lemma \ref{lemma-upper-shriek-restriction}
agree via the isomorphism of Lemma \ref{lemma-etale-upper-shriek}.

\label{lemma-lqf-base-change-upper-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of schemes with $f$ locally quasi-finite. For any abelian sheaf $\mathcal{F}$
on $Y'_\etale$ we have $(g')_*(f')^!\mathcal{F} = f^!g_*\mathcal{F}$.

\label{lemma-shriek-proper-and-open-base-change}
Let $b : Y_1 \to Y$ be a morphism of schemes. Consider a commutative diagram
of schemes
$$
\vcenter{
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
}
\quad\text{and let}\quad
\vcenter{
\xymatrix{
X'_1 \ar[r]_{g'_1} \ar[d]_{f'_1} & X_1 \ar[d]^{f_1} \\
Y'_1 \ar[r]^{g_1} & Y_1
}
}
$$
be the base change by $b$. Assume $f$ and $f'$ proper and
$g$ and $g'$ separated and locally quasi-finite.
For a ring $\Lambda$ and $K$ in $D(X'_\etale, \Lambda)$
there is commutative diagram
$$
\xymatrix{
b^{-1}g_!Rf'_*K \ar[d] \ar[r] &
g_{1, !}(b')^{-1}Rf'_*K \ar[r] &
g_{1, !}Rf'_{1, *}(a')^{-1}K \ar[d] \\
b^{-1}Rf_*g'_!K \ar[r] &
Rf_{1, *}a^{-1}g'_!K \ar[r] &
Rf_{1, *}g'_{1, !}(a')^{-1}K
}
$$
in $D(Y_{1, \etale}, \Lambda)$ where $a : X_1 \to X$, $a' : X'_1 \to X'$,
$b' : Y'_1 \to Y'$ are the projections, the vertical maps are the arrows
of Lemma \ref{lemma-shriek-proper-and-open}
and the horizontal arrows are the base change map
(from \'Etale Cohomology, Section
\ref{etale-cohomology-section-base-change-preliminaries})
and the base change map of Lemma \ref{lemma-base-change-f-shriek-separated}.

\label{lemma-derived-lower-shriek-bounded}
Let $f : X \to Y$ be a finite type separated morphism of quasi-compact
and quasi-separated schemes. Let $\Lambda$ be a ring. The functors $Rf_!$
constructed in Section \ref{section-derived-lower-shriek-compactification}
are bounded in the following sense: There exists an integer $N$ such that
for $E \in D^+_{tors}(X_\etale, \Lambda)$ or $E \in D(X_\etale, \Lambda)$
if $\Lambda$ is torsion, we have
\begin{enumerate}
\item $H^i(Rf_!(\tau_{\leq a}E) \to H^i(Rf_!(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(Rf_!(E)) \to H^i(Rf_!(\tau_{\geq b - N}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(Rf_!(E)) = 0$
for $i \not \in [a, b + N]$.
\end{enumerate}

\label{lemma-Rf-shriek-for-quasi-finite}
Let $f : X \to Y$ be a quasi-finite separated morphism of quasi-compact and
quasi-separated schemes. Then the functors $Rf_!$ constructed in
Section \ref{section-derived-lower-shriek-compactification}
agree with the restriction of the functor
$f_! : D(X_\etale, \Lambda) \to D(Y_\etale, \Lambda)$
constructed in Section \ref{section-derived-duality-locally-quasi-finite}
to their common domains of definition.

\label{lemma-cartesian-square-Rf-upper-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of quasi-compact and quasi-separated schemes with $f$ separated and
of finite type. Then we have $Rf^! \circ Rg_* = Rg'_* \circ R(f')^!$.

\label{lemma-compact-support-h0}
Let $X$ be a separated scheme of finite type over a field $k$.
If $\mathcal{F}$ is a torsion abelian sheaf, then the abelian group
$H^0_c(X, \mathcal{F})$ defined in Definition \ref{definition-compact-support}
agrees with the abelian group $H^0_c(X, \mathcal{F})$ defined in
Definition \ref{definition-cohomology-compact-support}.

\label{lemma-qf-f-shriek-constructible}
Let $f : X \to Y$ be a morphism of schemes which is
locally quasi-finite and of finite presentation.
The functor $f_! : D(X_\etale, \Lambda) \to D(Y_\etale, \Lambda)$
of Lemma \ref{lemma-lqf-shriek-derived}
sends $D_c(X_\etale, \Lambda)$ into $D_c(Y_\etale, \Lambda)$.

\label{lemma-groupoid-on-field-explain-points}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume $U = \Spec(k)$ with $k$ a field.
For any point $r \in R$ there exist
\begin{enumerate}
\item a field extension $k'/k$ with $k'$ algebraically closed,
\item a point $r' \in R'$ where $(U', R', s', t', c')$ is the
restriction of $(U, R, s, t, c)$ via $\Spec(k') \to \Spec(k)$
\end{enumerate}
such that
\begin{enumerate}
\item the point $r'$ maps to $r$ under the morphism $R' \to R$, and
\item the maps $s', t' : R' \to \Spec(k')$ induce isomorphisms
$k' \to \kappa(r')$.
\end{enumerate}

\label{lemma-groupoid-characteristic-zero-smooth}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume
\begin{enumerate}
\item $U = \Spec(k)$ with $k$ a field,
\item $s, t$ are locally of finite type, and
\item the characteristic of $k$ is zero.
\end{enumerate}
Then $s, t : R \to U$ are smooth.

\label{lemma-reduced-group-scheme-perfect-field-characteristic-p-smooth}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume
\begin{enumerate}
\item $U = \Spec(k)$ with $k$ a field,
\item $s, t$ are locally of finite type,
\item $R$ is reduced, and
\item $k$ is perfect.
\end{enumerate}
Then $s, t : R \to U$ are smooth.

\label{lemma-quasi-finite-over-base-j-proper}
Let $S$ be a scheme.
Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
Let $p \in S$ be a point, and let $u \in U$ be a point lying over $p$.
Assume assumptions (1) -- (6) of
Lemma \ref{lemma-quasi-finite-over-base}
hold as well as
\begin{enumerate}
\item[(7)] $j : R \to U \times_S U$ is universally closed\footnote{In view of
the other conditions this is equivalent to requiring $j$ to be proper.}.
\end{enumerate}
Then we can choose $(S', p') \to (S, p)$ and decompositions
$S' \times_S U = U' \amalg W$ and $S' \times_S R = R' \amalg W'$
and $u' \in U'$ such that (a) -- (g) of
Lemma \ref{lemma-quasi-finite-over-base}
hold as well as
\begin{enumerate}
\item[(h)] $R'$ is the restriction of $S' \times_S R$ to $U'$.
\end{enumerate}

\label{lemma-finite-flat-over-almost-dense-subscheme-addendum}
In Lemma \ref{lemma-finite-flat-over-almost-dense-subscheme}
assume in addition that $s$ and $t$ are of finite presentation.
Then
\begin{enumerate}
\item the morphism $W' \to W$ is of finite presentation, and
\item if $u \in U$ is a point whose $R$-orbit consists of
generic points of irreducible components of $U$, then $u \in W$.
\end{enumerate}

\label{lemma-find-affine-codimension-1}
Let $(U, R, s, t, c)$ be a groupoid scheme. Let $u \in U$. Assume
\begin{enumerate}
\item $s, t$ are finite morphisms,
\item $U$ is separated and locally Noetherian,
\item $\dim(\mathcal{O}_{U, u'}) \leq 1$ for every point $u'$
in the orbit of $u$.
\end{enumerate}
Then $u$ is contained in an $R$-invariant affine open of $U$.

\label{lemma-thickening-affine-scheme}
\begin{slogan}
Affineness is insensitive to thickenings
\end{slogan}
\begin{reference}
The case of a finite order thickening is \cite[Proposition 5.1.9]{EGA1}.
\end{reference}
Any thickening of an affine scheme is affine.

\label{lemma-composition-thickening}
\begin{slogan}
Compositions of thickenings are thickenings
\end{slogan}
If $S \subset S'$ and $S' \subset S''$ are thickenings, then so is
$S \subset S''$.

\label{lemma-descending-property-thickening}
The property of being a thickening is fpqc local.
Similarly for first order thickenings.

\label{definition-first-order-infinitesimal-neighbourhood}
Let $i : Z \to X$ be an immersion of schemes.
\begin{enumerate}
\item The {\it first order infinitesimal neighbourhood} of $Z$ in $X$ is
the first order thickening $Z \subset Z_1$ over $X$ described above.
\item The {\it $n$th order infinitesimal neighbourhood} of $Z$ in $X$ is
the $n$th order thickening $Z \subset Z_n$ over $X$ described above.
\end{enumerate}

\label{lemma-formally-unramified-differentials}
Let $f : X \to S$ be a morphism of schemes.
Then $f$ is formally unramified if and only if $\Omega_{X/S} = 0$.

\label{lemma-unramified-formally-unramified}
\begin{slogan}
Unramified morphisms are the same as formally unramified morphism that
are locally of finite type.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is unramified (resp.\ G-unramified), and
\item the morphism $f$ is locally of finite type (resp.\ locally of finite
presentation) and formally unramified.
\end{enumerate}

\label{definition-universal-thickening}
Let $h : Z \to X$ be a formally unramified morphism of schemes.
\begin{enumerate}
\item The {\it universal first order thickening} of $Z$ over $X$
is the thickening $Z \subset Z'$ constructed in
Lemma \ref{lemma-universal-thickening}.
\item The {\it conormal sheaf of $Z$ over $X$} is the conormal sheaf
of $Z$ in its universal first order thickening $Z'$ over $X$.
\end{enumerate}
We often denote the conormal sheaf $\mathcal{C}_{Z/X}$ in this situation.

\label{lemma-immersion-universal-thickening}
Let $i : Z \to X$ be an immersion of schemes. Then
\begin{enumerate}
\item $i$ is formally unramified,
\item the universal first order thickening of $Z$ over $X$ is the first order
infinitesimal neighbourhood of $Z$ in $X$ of
Definition \ref{definition-first-order-infinitesimal-neighbourhood}, and
\item the conormal sheaf of $i$ in the sense of
Morphisms, Definition \ref{morphisms-definition-conormal-sheaf}
agrees with the conormal sheaf of $i$ in the sense of
Definition \ref{definition-universal-thickening}.
\end{enumerate}

\label{lemma-characterize-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is formally \'etale,
\item $f$ is formally unramified and the universal first order thickening
of $X$ over $S$ is equal to $X$,
\item $f$ is formally unramified and $\mathcal{C}_{X/S} = 0$, and
\item $\Omega_{X/S} = 0$ and $\mathcal{C}_{X/S} = 0$.
\end{enumerate}

\label{lemma-etale-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is \'etale, and
\item the morphism $f$ is locally of finite presentation and
formally \'etale.
\end{enumerate}

\label{lemma-sheaf}
Let $S$ be a scheme.
Let $X \subset X'$ and $Y \subset Y'$ be first order thickenings
over $S$. Assume given a morphism $a : X \to Y$ and a map
$A : a^*\mathcal{C}_{Y/Y'} \to \mathcal{C}_{X/X'}$ of
$\mathcal{O}_X$-modules. For an open subscheme $U' \subset X'$
consider morphisms $a' : U' \to Y'$ such that
\begin{enumerate}
\item $a'$ is a morphism over $S$,
\item $a'|_U = a|_U$, and
\item the induced map
$a^*\mathcal{C}_{Y/Y'}|_U \to \mathcal{C}_{X/X'}|_U$
is the restriction of $A$ to $U$.
\end{enumerate}
Here $U = X \cap U'$. Then the rule
\begin{equation}
\label{equation-sheaf}
U' \mapsto
\{a' : U' \to Y'\text{ such that (1), (2), (3) hold.}\}
\end{equation}
defines a sheaf of sets on $X'$.

\label{lemma-sheaf-differentials-etale-localization}
Let
$$
\xymatrix{
X_1 \ar[d] & X_2 \ar[l]^f \ar[d] \\
S_1 & S_2 \ar[l]
}
$$
be a commutative diagram of schemes with $X_2 \to X_1$ and $S_2 \to S_1$
\'etale. Then the map $c_f : f^*\Omega_{X_1/S_1} \to \Omega_{X_2/S_2}$ of
Morphisms, Lemma \ref{morphisms-lemma-functoriality-differentials}
is an isomorphism.

\label{lemma-action-by-derivations-etale-localization}
Consider a commutative diagram of first order thickenings
$$
\vcenter{
\xymatrix{
(T_2 \subset T_2') \ar[d]_{(h, h')} \ar[rr]_{(a_2, a_2')} & &
(X_2 \subset X_2') \ar[d]^{(f, f')} \\
(T_1 \subset T_1') \ar[rr]^{(a_1, a_1')} & &
(X_1 \subset X_1')
}
}
\quad
\begin{matrix}
\text{and a commutative} \\
\text{diagram of schemes}
\end{matrix}
\quad
\vcenter{
\xymatrix{
X_2' \ar[r] \ar[d] & S_2 \ar[d] \\
X_1' \ar[r] & S_1
}
}
$$
with $X_2 \to X_1$ and $S_2 \to S_1$ \'etale.
For any $\mathcal{O}_{T_1}$-linear map
$\theta_1 : a_1^*\Omega_{X_1/S_1} \to \mathcal{C}_{T_1/T'_1}$ let
$\theta_2$ be the composition
$$
\xymatrix{
a_2^*\Omega_{X_2/S_2} \ar@{=}[r] &
h^*a_1^*\Omega_{X_1/S_1} \ar[r]^-{h^*\theta_1} &
h^*\mathcal{C}_{T_1/T'_1} \ar[r] &
\mathcal{C}_{T_2/T'_2}
}
$$
(equality sign is explained in the proof). Then the diagram
$$
\xymatrix{
T_2' \ar[rr]_{\theta_2 \cdot a_2'} \ar[d] & & X'_2 \ar[d] \\
T_1' \ar[rr]^{\theta_1 \cdot a_1'} & & X'_1
}
$$
commutes where the actions $\theta_2 \cdot a_2'$ and $\theta_1 \cdot a_1'$
are as in Remark \ref{remark-action-by-derivations}.

\label{lemma-deform}
Let $(f, f') : (X \subset X') \to (S \subset S')$ be a morphism
of first order thickenings. Assume that $f$ is flat.
Then the following are equivalent
\begin{enumerate}
\item $f'$ is flat and $X = S \times_{S'} X'$, and
\item the canonical map $f^*\mathcal{C}_{S/S'} \to \mathcal{C}_{X/X'}$
is an isomorphism.
\end{enumerate}

\label{lemma-deform-property}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $S \subset S'$ is a finite order thickening,
$X'$ flat over $S'$, $X = S \times_{S'} X'$, and
$Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine}
\item
\label{item-finite-type}
$f$ is locally of finite type if and only if $f'$ is locally of finite type,
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite}
\item
\label{item-finite-presentation}
$f$ is locally of finite presentation if and only if $f'$ is locally of
finite presentation,
\item
\label{item-relative-dimension-d}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper}
\item $f$ is integral if and only if $f'$ is integral,
\label{item-integral}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite}
\item
\label{item-finite-locally-free}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-deform-property-fp-over-ft}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $Y' \to S'$ locally of finite type,
$X' \to S'$ flat and locally of finite presentation,
$X = S \times_{S'} X'$, and $Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact-fp-over-ft}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed-fp-over-ft}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective-fp-over-ft}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective-fp-over-ft}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item
\label{item-relative-dimension-d-fp-over-ft}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite-fp-over-ft}
\item
\label{item-finite-locally-free-fp-over-ft}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

[Infinitesimal lifting criterion]
\label{lemma-smooth-formally-smooth}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth, and
\item the morphism $f$ is locally of finite presentation and
formally smooth.
\end{enumerate}

\label{lemma-formally-smooth-sheaf-differentials}
Let $f : X \to Y$ be a formally smooth morphism of schemes.
Then $\Omega_{X/Y}$ is locally projective on $X$.

\label{lemma-check-smoothness-on-infinitesimal-nbhds}
Let $f : X \to S$ be a finite type morphism of locally Noetherian schemes.
Let $Z \subset S$ be a closed subscheme with $n$th infinitesimal
neighbourhood $Z_n \subset S$. Set $X_n = Z_n \times_S X$.
\begin{enumerate}
\item If $X_n \to Z_n$ is smooth for all $n$, then $f$
is smooth at every point of $f^{-1}(Z)$.
\item If $X_n \to Z_n$ is \'etale for all $n$, then $f$
is \'etale at every point of $f^{-1}(Z)$.
\end{enumerate}

\label{definition-netherlander}
Let $f : X \to Y$ be a morphism of schemes.
The {\it naive cotangent complex of $f$}
is the complex defined in Modules, Definition
\ref{modules-definition-cotangent-complex-morphism-ringed-topoi}.
Notation: $\NL_f$ or $\NL_{X/Y}$.

\label{lemma-NL-formally-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item $H^{-1}(\NL_{X/Y}) = 0$ and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is locally projective.
\end{enumerate}

\label{lemma-NL-formally-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally \'etale,
\item $H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-NL-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is smooth, and
\item $f$ is locally of finite presentation,
$H^{-1}(\NL_{X/Y}) = 0$, and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is finite locally free.
\end{enumerate}

\label{lemma-NL-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation and
$H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-smooth-etale-permanence}
Let $X \to Y \to Z$ be morphisms of schemes. Assume $X \to Z$ smooth
and $Y \to Z$ \'etale. Then $X \to Y$ is smooth.

\label{lemma-base-change-NL}
Consider a cartesian diagram of schemes
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d] & X \ar[d] \\
Y' \ar[r] & Y
}
$$
The canonical map $(g')^*\NL_{X/Y} \to \NL_{X'/Y'}$ induces
an isomorphism on $H^0$ and a surjection on $H^{-1}$.

\label{lemma-flat-base-change-NL}
Consider a cartesian diagram of schemes
$$
\xymatrix{
X' \ar[d] \ar[r]_{g'} & X \ar[d] \\
Y' \ar[r] & Y
}
$$
If $Y' \to Y$ is flat, then the canonical map
$(g')^*\NL_{X/Y} \to \NL_{X'/Y'}$ is a quasi-isomorphism.

\label{lemma-basic-example-pushout}
Let $A' \to A$ be a surjection of rings and let $B \to A$ be a ring map.
Let $B' = B \times_A A'$ be the fibre product of rings. Set
$S = \Spec(A)$, $S' = \Spec(A')$, $T = \Spec(B)$, and $T' = \Spec(B')$.
Then
$$
\vcenter{
\xymatrix{
S \ar[r]_i \ar[d]_f & S' \ar[d]^{f'} \\
T \ar[r]^{i'} & T'
}
}
\quad\text{corresponding to}\quad
\vcenter{
\xymatrix{
A & A' \ar[l] \\
B \ar[u] & B' \ar[l] \ar[u]
}
}
$$
is a pushout of schemes.

\label{theorem-openness-flatness}
\begin{reference}
\cite[IV Theorem 11.3.1]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $f : X \to S$ be a morphism which is locally of finite presentation.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module which is
locally of finite presentation. Then
$$
U = \{x \in X \mid \mathcal{F}\text{ is flat over }S\text{ at }x\}
$$
is open in $X$.

\label{definition-normal}
Let $f : X \to Y$ be a morphism of schemes.
Assume that all the fibres $X_y$ are locally Noetherian schemes.
\begin{enumerate}
\item Let $x \in X$, and $y = f(x)$. We say that $f$ is {\it normal at $x$}
if $f$ is flat at $x$, and the scheme $X_y$ is geometrically
normal at $x$ over $\kappa(y)$ (see
Varieties, Definition \ref{varieties-definition-geometrically-normal}).
\item We say $f$ is a {\it normal morphism} if $f$ is normal
at every point of $X$.
\end{enumerate}

\label{lemma-normal}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is normal, and
\item $f$ is flat and its fibres are geometrically normal schemes.
\end{enumerate}

\label{lemma-locally-Noetherian-fibres-fppf-local-source-and-target}
The property $\mathcal{P}(f)=$``the fibres of $f$ are locally Noetherian''
is local in the fppf topology on the source and the target.

\label{definition-regular}
Let $f : X \to Y$ be a morphism of schemes.
Assume that all the fibres $X_y$ are locally Noetherian schemes.
\begin{enumerate}
\item Let $x \in X$, and $y = f(x)$. We say that $f$ is {\it regular at $x$}
if $f$ is flat at $x$, and the scheme $X_y$ is geometrically
regular at $x$ over $\kappa(y)$ (see
Varieties, Definition \ref{varieties-definition-geometrically-regular}).
\item We say $f$ is a {\it regular morphism} if $f$ is regular
at every point of $X$.
\end{enumerate}

\label{definition-CM}
Let $f : X \to Y$ be a morphism of schemes.
Assume that all the fibres $X_y$ are locally Noetherian schemes.
\begin{enumerate}
\item Let $x \in X$, and $y = f(x)$. We say that $f$ is
{\it Cohen-Macaulay at $x$} if $f$ is flat at $x$, and the
local ring of the scheme $X_y$ at $x$ is Cohen-Macaulay.
\item We say $f$ is a {\it Cohen-Macaulay morphism} if $f$ is
Cohen-Macaulay at every point of $X$.
\end{enumerate}

\label{lemma-CM}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Cohen-Macaulay, and
\item $f$ is flat and its fibres are Cohen-Macaulay schemes.
\end{enumerate}

\label{lemma-flat-finite-presentation-CM-open}
\begin{reference}
\cite[IV Corollary 12.1.7(iii)]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. Let
$$
W = \{x \in X \mid f\text{ is Cohen-Macaulay at }x\}
$$
Then
\begin{enumerate}
\item $W = \{x \in X \mid \mathcal{O}_{X_{f(x)}, x}\text{ is Cohen-Macaulay}\}$,
\item $W$ is open in $X$,
\item $W$ is dense in every fibre of $X \to S$,
\item the formation of $W$ commutes with arbitrary base change of $f$:
For any morphism $g : S' \to S$, consider
the base change $f' : X' \to S'$ of $f$ and the
projection $g' : X' \to X$. Then the corresponding
set $W'$ for the morphism $f'$ is equal to $W' = (g')^{-1}(W)$.
\end{enumerate}

\label{lemma-flat-finite-presentation-CM-pieces}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. For $d \geq 0$ there exist opens $U_d \subset X$
with the following properties
\begin{enumerate}
\item $W = \bigcup_{d \geq 0} U_d$ is dense in every fibre of $f$, and
\item $U_d \to S$ is of relative dimension $d$ (see
Morphisms, Definition \ref{morphisms-definition-relative-dimension-d}).
\end{enumerate}

\label{lemma-slice-CM}
\begin{reference}
\cite[IV Proposition 17.16.1]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point with image $s \in S$.
Assume
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $f$ is Cohen-Macaulay at $x$, and
\item $x$ is a closed point of $X_s$.
\end{enumerate}
Then there exists a regular immersion $Z \to X$ containing $x$ such that
\begin{enumerate}
\item[(a)] $Z \to S$ is flat and locally of finite presentation,
\item[(b)] $Z \to S$ is locally quasi-finite, and
\item[(c)] $Z_s = \{x\}$ set theoretically.
\end{enumerate}

\label{lemma-base-change-fibres-geometrically-reduced}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically reduced}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically reduced}\}).
\end{align*}

\label{lemma-geometrically-reduced-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically reduced, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically reduced fibres.

\label{lemma-base-change-fibres-geometrically-irreducible}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically irreducible}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically irreducible}\}).
\end{align*}

\label{lemma-geom-irreducible-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically irreducible, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically irreducible fibres.

\label{lemma-base-change-fibres-geometrically-connected}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically connected}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically connected}\}).
\end{align*}

\label{lemma-geometrically-connected-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically connected, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically connected fibres.

\label{lemma-connected-flat-over-dvr}
\begin{slogan}
A flat degeneration of a disconnected scheme is either disconnected
or nonreduced.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $S$ is the spectrum of a discrete valuation ring,
\item $f$ is flat,
\item $X$ is connected,
\item the closed fibre $X_s$ is reduced.
\end{enumerate}
Then the generic fibre $X_\eta$ is connected.

\label{lemma-connected-along-section-open-neighbourhood}
Let $f : X \to Y$, $s : Y \to X$ be as in
Situation \ref{situation-connected-along-section}.
Let $y \in Y$ be a point.
Assume
\begin{enumerate}
\item $f$ is of finite presentation and flat, and
\item the fibre $X_y$ is geometrically reduced.
\end{enumerate}
Then $X^0$ is a neighbourhood of $X^0_y$ in $X$.

\label{lemma-connected-along-section-open}
Let $f : X \to Y$, $s : Y \to X$ be as in
Situation \ref{situation-connected-along-section}.
Assume
\begin{enumerate}
\item $f$ is of finite presentation and flat, and
\item all fibres of $f$ are geometrically reduced.
\end{enumerate}
Then $X^0$ is open in $X$.

\label{lemma-bertini-irreducible}
\begin{reference}
\cite[Theorem 6.3 part 4)]{Jou}
\end{reference}
In Varieties, Situation \ref{varieties-situation-family-divisors} assume
\begin{enumerate}
\item $X$ is of finite type over $k$,
\item $X$ is geometrically irreducible over $k$,
\item there exist $v_1, v_2, v_3 \in V$ and an irreducible component
$Z$ of $H_{v_2} \cap H_{v_3}$ such that $Z \not \subset H_{v_1}$ and
$\text{codim}(Z, X) = 2$, and
\item every irreducible component $Y$ of $\bigcap_{v \in V} H_v$
has $\text{codim}(Y, X) \geq 2$.
\end{enumerate}
Then for general $v \in V \otimes_k k'$
the scheme $H_v$ is geometrically irreducible over $k'$.

\label{lemma-get-a-closed}
Let $f : X \to S$ and $\mathcal{E}$ be as in
Lemma \ref{lemma-diagonal-picard-flat-proper}
and in addition assume $\mathcal{E}$ is an invertible $\mathcal{O}_X$-module.
If moreover the geometric fibres of $f$ are
integral, then $Z$ is closed in $S$.

\label{lemma-Noetherian-approximation}
Let $f : X \to S$ be a morphism of affine schemes, which is of finite
presentation. Then there exists a cartesian diagram
$$
\xymatrix{
X_0 \ar[d]_{f_0} & X \ar[l]^g \ar[d]^f \\
S_0 & S \ar[l]
}
$$
such that
\begin{enumerate}
\item $X_0$, $S_0$ are affine schemes,
\item $S_0$ is of finite type over $\mathbf{Z}$,
\item $f_0$ is of finite type.
\end{enumerate}

\label{lemma-Noetherian-approximation-flat}
Let $f : X \to S$ be a morphism of affine schemes, which is of finite
presentation and flat. Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ is flat.

\label{lemma-Noetherian-approximation-smooth}
Let $f : X \to S$ be a morphism of affine schemes, which is smooth.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ is smooth.

\label{lemma-Noetherian-approximation-geometrically-reduced}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically reduced fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically reduced fibres.

\label{lemma-Noetherian-approximation-geometrically-irreducible}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically irreducible fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically irreducible fibres.

\label{lemma-Noetherian-approximation-geometrically-connected}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically connected fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically connected fibres.

\label{lemma-Noetherian-approximation-combine}
(Noetherian approximation and combining properties.)
Let $P$, $Q$ be properties of morphisms of schemes which are stable
under base change. Let $f : X \to S$ be a morphism of finite presentation
of affine schemes. Assume we can find cartesian diagrams
$$
\vcenter{
\xymatrix{
X_1 \ar[d]_{f_1} & X \ar[l] \ar[d]^f \\
S_1 & S \ar[l]
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
X_2 \ar[d]_{f_2} & X \ar[l] \ar[d]^f \\
S_2 & S \ar[l]
}
}
$$
of affine schemes, with $S_1$, $S_2$ of finite type over $\mathbf{Z}$
and $f_1$, $f_2$ of finite type such that $f_1$ has property $P$
and $f_2$ has property $Q$. Then we can find a cartesian diagram
$$
\xymatrix{
X_0 \ar[d]_{f_0} & X \ar[l] \ar[d]^f \\
S_0 & S \ar[l]
}
$$
of affine schemes with $S_0$ of finite type over $\mathbf{Z}$
and $f_0$ of finite type such that $f_0$ has both property $P$ and
property $Q$.

\label{lemma-lift-etale-neighbourhood-fibre}
\begin{slogan}
Lift \'etale neighbourhood of point on fibre to total space.
\end{slogan}
Let $X \to S$ be a morphism of schemes. Let $x \in X$ with image $s \in S$.
Let $(V, v) \to (X_s, x)$ be an \'etale neighbourhood.
Then there exists an \'etale neighbourhood $(U, u) \to (X, x)$
such that there exists a morphism $(U_s, u) \to (V, v)$
of \'etale neighbourhoods of $(X_s, x)$ which is an open immersion.

\label{lemma-number-of-branches-and-smooth}
Let $X \to S$ be a smooth morphism of schemes.
Let $x \in X$ with image $s \in S$.
Then
\begin{enumerate}
\item The number of geometric branches of $X$ at $x$
is equal to the number of geometric branches of $S$ at $s$.
\item If $\kappa(x)/\kappa(s)$ is a purely inseparable\footnote{In fact,
it would suffice if $\kappa(x)$ is geometrically irreducible over
$\kappa(s)$. If we ever need this we will add a detailed proof.}
extension of fields, then number of branches of $X$ at $x$
is equal to the number of branches of $S$ at $s$.
\end{enumerate}

\label{lemma-global-unramified-dominant-unibranch-is-etale}
\begin{reference}
\cite[Expose I, Corollary 9.11]{SGA1}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch,
\item at least one irreducible component of $X$ dominates $Y$,
\item $f$ is unramified, and
\item $X$ is connected.
\end{enumerate}
Then $f$ is \'etale and $X$ is irreducible.

\label{lemma-weird-permanence-etale}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
Let $x \in X$ with image $y \in Y$. Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch at $y$,
\item $g \circ f$ is \'etale at $x$,
\item there is a specialization $x' \leadsto x$ such that $f(x')$
is the generic point of $Y$.
\end{enumerate}
Then $f$ is \'etale at $x$ and $g$ is \'etale at $y$.

\label{lemma-global-weird-permanence-etale}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch,
\item $g \circ f$ is \'etale,
\item every irreducible component of $X$ dominates $Y$.
\end{enumerate}
Then $f$ is \'etale and $g$ is \'etale at every point in
the image of $f$.

\label{lemma-slice-smooth}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point with image $s \in S$.
Assume
\begin{enumerate}
\item $f$ is smooth at $x$, and
\item $x$ is a closed point of $X_s$ and $\kappa(s) \subset \kappa(x)$
is separable.
\end{enumerate}
Then there exists an immersion $Z \to X$ containing $x$ such that
\begin{enumerate}
\item $Z \to S$ is \'etale, and
\item $Z_s = \{x\}$ set theoretically.
\end{enumerate}

\label{lemma-etale-nbhd-dominates-smooth}
\begin{slogan}
Smooth morphisms admit \'etale local sections.
\end{slogan}
\begin{reference}
See \cite[Corollaire 17.16.3 (ii)]{EGA4}.
\end{reference}
Let $f : X \to S$ be a smooth morphism of schemes.
Let $s \in S$ be a point in the image of $f$.
Then there exists an \'etale neighbourhood $(S', s') \to (S, s)$
and a $S$-morphism $S' \to X$.

\label{lemma-relative-isomorphism-approximation}
With notation an assumptions as in Lemma \ref{lemma-relative-map-approximation}
assume that $\varphi$ induces an isomorphism on completions.
Then we can choose our diagram such that $f$ is \'etale.

\label{lemma-etale-makes-quasi-finite-finite-multiple-points}
Let $f : X \to S$ be a morphism of schemes.
Let $x_1, \ldots, x_n \in X$ be points having the same image $s$ in $S$.
Assume that
\begin{enumerate}
\item $f$ is locally of finite type, and
\item $x_i \in X_s$ is isolated for $i = 1, \ldots, n$.
\end{enumerate}
Then there exist
\begin{enumerate}
\item[(a)] an elementary \'etale neighbourhood $(U, u) \to (S, s)$,
\item[(b)] for each $i$ an open subscheme $V_i \subset X_U$,
\end{enumerate}
such that for each $i$ we have
\begin{enumerate}
\item[(\romannumeral1)] $V_i \to U$ is a finite morphism,
\item[(\romannumeral2)] there is a unique point $v_i$ of $V_i$
mapping to $u$ in $U$, and
\item[(\romannumeral3)] the point $v_i$ maps to $x_i$ in $X$ and
$\kappa(x_i) = \kappa(v_i)$.
\end{enumerate}

[Zariski's Main Theorem]
\label{lemma-quasi-finite-separated-pass-through-finite}
\begin{reference}
\cite[IV Corollary 18.12.13]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is quasi-finite and separated and assume that
$S$ is quasi-compact and quasi-separated. Then there exists
a factorization
$$
\xymatrix{
X \ar[rd]_f \ar[rr]_j & & T \ar[ld]^\pi \\
& S &
}
$$
where $j$ is a quasi-compact open immersion and $\pi$ is finite.

\label{lemma-characterize-finite}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite,
\item $f$ is proper with finite fibres,
\item $f$ is proper and locally quasi-finite,
\item $f$ is universally closed, separated, locally of finite type
and has finite fibres.
\end{enumerate}

\label{lemma-normal-morphism-irreducible}
Let $h : Y \to S$ be a morphism of schemes.
Let $s \in S$ be a point.
Let $T \subset Y_s$ be an open subscheme.
Assume
\begin{enumerate}
\item $h$ is of finite presentation,
\item $h$ is normal, and
\item $T$ is geometrically irreducible over $\kappa(s)$.
\end{enumerate}
Then we can find an affine elementary \'etale neighbourhood
$(S', s') \to (S, s)$ and a quasi-compact open $V \subset Y_{S'}$ such that
\begin{enumerate}
\item[(a)] all fibres of $V \to S'$ are geometrically integral,
\item[(b)] $V_{s'} = T \times_s s'$.
\end{enumerate}

\label{lemma-local-local-structure-finite-type-affine}
Assumption and notation as in
Lemma \ref{lemma-local-local-structure-finite-type}.
In addition to properties (1) -- (6) we may also arrange it so that
\begin{enumerate}
\item[(7)] $S'$, $Y'$, $X'$ are affine.
\end{enumerate}

\label{lemma-dominate-fppf-etale-locally}
Let $S$ be a scheme. Let $\{S_i \to S\}_{i \in I}$ be an fppf covering.
Then there exist
\begin{enumerate}
\item an \'etale covering $\{S'_a \to S\}$,
\item surjective finite locally free morphisms $V_a \to S'_a$,
\end{enumerate}
such that the fppf covering $\{V_a \to S\}$ refines the given
covering $\{S_i \to S\}$.

\label{lemma-integral-over-quasi-affine}
Let $X$ be a quasi-affine scheme. Let $f : U \to X$ be an integral
morphism. Then $U$ is quasi-affine and the diagram
$$
\xymatrix{
U \ar[r] \ar[d] & \Spec(\Gamma(U, \mathcal{O}_U)) \ar[d] \\
X \ar[r] & \Spec(\Gamma(X, \mathcal{O}_X))
}
$$
is cartesian.

\label{lemma-ample-in-neighbourhood}
\begin{reference}
\cite[IV Corollary 9.6.4]{EGA}
\end{reference}
Let $f : X \to Y$ be a proper morphism of schemes.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $y \in Y$ be a point such that $\mathcal{L}_y$ is ample
on $X_y$. Then there is an open neighbourhood $V \subset Y$
of $y$ such that $\mathcal{L}|_{f^{-1}(V)}$ is ample on $f^{-1}(V)/V$.

\label{lemma-closed-point-nearby-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $x \leadsto x'$ be a specialization of points in $X$.
Set $s = f(x)$ and $s' = f(x')$.
Assume
\begin{enumerate}
\item $x'$ is a closed point of $X_{s'}$, and
\item $f$ is locally of finite type.
\end{enumerate}
Then the set
$$
\{x_1 \in X
\text{ such that }
f(x_1) = s
\text{ and }
x_1\text{ is closed in }X_s
\text{ and }
x \leadsto x_1 \leadsto x'
\}
$$
is dense in the closure of $x$ in $X_s$.

\label{lemma-proper-flat-geom-red}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is proper, flat, and of finite presentation, and
\item the geometric fibres of $f$ are reduced.
\end{enumerate}
Then the function $n_{X/S} : S \to \mathbf{Z}$
counting the numbers of geometric connected components
of fibres of $f$ is locally constant.

\label{lemma-split-off-proper-part-henselian}
\begin{reference}
A reference for the case of an adic Noetherian base is
\cite[III, Proposition 5.5.1]{EGA}
\end{reference}
Let $(A, I)$ be a henselian pair. Let $X \to \Spec(A)$
be separated and of finite type. Set $X_0 = X \times_{\Spec(A)} \Spec(A/I)$.
Let $Y \subset X_0$ be an open and closed subscheme such that
$Y \to \Spec(A/I)$ is proper. Then there exists an open and closed
subscheme $W \subset X$ which is proper over $A$ with
$W \times_{\Spec(A)} \Spec(A/I) = Y$.

\label{lemma-relative-finite-presentation}
Let $f : X \to S$ be a morphism of schemes which is locally of finite
type. Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $f$ is locally of finite presentation, then $\mathcal{F}$
is of finite presentation relative to $S$ if and only if $\mathcal{F}$
is of finite presentation.
\item The morphism $f$ is locally of finite presentation if and only
if $\mathcal{O}_X$ is of finite presentation relative to $S$.
\end{enumerate}

\label{lemma-sum-relatively-finite-presentation}
\begin{slogan}
A direct summand of a module inherits the property of being finitely
presented relative to a base.
\end{slogan}
Let $X \to S$ be a morphism of schemes which is locally of finite type.
Let $\mathcal{F}, \mathcal{F}'$ be quasi-coherent $\mathcal{O}_X$-modules.
If $\mathcal{F} \oplus \mathcal{F}'$ is finitely presented relative to $S$,
then so are $\mathcal{F}$ and $\mathcal{F}'$.

\label{definition-relative-pseudo-coherence}
Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
Let $E$ be an object of $D(\mathcal{O}_X)$. Let $\mathcal{F}$ be an
$\mathcal{O}_X$-module. Fix $m \in \mathbf{Z}$.
\begin{enumerate}
\item We say $E$ is {\it $m$-pseudo-coherent relative to $S$}
if there exists an affine open covering $S = \bigcup V_i$ and
for each $i$ an affine open covering $f^{-1}(V_i) = \bigcup U_{ij}$
such that the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
are satisfied for each of the pairs $(U_{ij} \to V_i, E|_{U_{ij}})$.
\item We say $E$ is {\it pseudo-coherent relative to $S$}
if $E$ is $m$-pseudo-coherent relative to $S$ for all $m \in \mathbf{Z}$.
\item We say $\mathcal{F}$ is {\it $m$-pseudo-coherent relative to $S$} if
$\mathcal{F}$ viewed as an object of $D(\mathcal{O}_X)$ is
$m$-pseudo-coherent relative to $S$.
\item We say $\mathcal{F}$ is {\it pseudo-coherent relative to $S$} if
$\mathcal{F}$ viewed as an object of $D(\mathcal{O}_X)$ is
pseudo-coherent relative to $S$.
\end{enumerate}

\label{lemma-localize-relative-pseudo-coherent}
Let $S$ be an affine scheme. Let $V \subset S$ be a standard open.
Let $X \to V$ be a finite type morphism of affine schemes.
Let $U \subset X$ be an affine open. Let $E$ be an object of
$D(\mathcal{O}_X)$. If the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
are satisfied for the pair $(X \to V, E)$, then
the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
are satisfied for the pair $(U \to S, E|_U)$.

\label{lemma-glue-relative-pseudo-coherent}
Let $X \to S$ be a finite type morphism of affine schemes. Let $E$ be an
object of $D(\mathcal{O}_X)$. Let $m \in \mathbf{Z}$.
Let $X = \bigcup U_i$ be a standard affine open covering.
The following are equivalent
\begin{enumerate}
\item the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
hold for the pairs $(U_i \to S, E|_{U_i})$,
\item the equivalent conditions of
Lemma \ref{lemma-relatively-pseudo-coherent}
hold for the pair $(X \to S, E)$.
\end{enumerate}

\label{lemma-rel-n-pseudo-module}
Let $X \to S$ be a morphism of schemes which is locally of finite type.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $\mathcal{F}$ is $m$-pseudo-coherent relative to $S$ for all $m > 0$,
\item $\mathcal{F}$ is $0$-pseudo-coherent relative to $S$ if and only if
$\mathcal{F}$ is a finite type $\mathcal{O}_X$-module,
\item $\mathcal{F}$ is $(-1)$-pseudo-coherent relative to $S$ if and only if
$\mathcal{F}$ is quasi-coherent and finitely presented relative to $S$.
\end{enumerate}

\label{definition-pseudo-coherent}
A morphism of schemes $f : X \to S$ is called {\it pseudo-coherent}
if the equivalent conditions of
Lemma \ref{lemma-pseudo-coherent}
are satisfied. In this case we also say that $X$ is pseudo-coherent
over $S$.

\label{lemma-composition-pseudo-coherent}
A composition of pseudo-coherent morphisms of schemes is
pseudo-coherent.

\label{lemma-permanence-pseudo-coherent}
Let $f : X \to Y$ be a morphism of schemes pseudo-coherent
over a base scheme $S$. Then $f$ is pseudo-coherent.

\label{lemma-descending-property-pseudo-coherent}
The property $\mathcal{P}(f) =$``$f$ is pseudo-coherent''
is fpqc local on the base.

\label{lemma-pseudo-coherent-syntomic-local-source}
The property $\mathcal{P}(f) =$``$f$ is pseudo-coherent''
is syntomic local on the source.

\label{lemma-pseudo-coherent-fppf-local-source}
The property $\mathcal{P}(f) =$``$f$ is pseudo-coherent''
is fppf local on the source.

\label{definition-perfect}
A morphism of schemes $f : X \to S$ is called {\it perfect}
if the equivalent conditions of
Lemma \ref{lemma-perfect}
are satisfied. In this case we also say that $X$ is perfect
over $S$.

\label{lemma-flat-finite-presentation-perfect}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is flat and perfect, and
\item $f$ is flat and locally of finite presentation.
\end{enumerate}

\label{lemma-regular-immersion-perfect}
A regular immersion of schemes is perfect.
A Koszul-regular immersion of schemes is perfect.

\label{lemma-perfect-permanence}
Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd] & & Y \ar[ld] \\
& S
}
$$
be a commutative diagram of morphisms of schemes. Assume $Y \to S$
smooth and $X \to S$ perfect. Then $f : X \to Y$ is perfect.

\label{lemma-descending-property-perfect}
The property $\mathcal{P}(f) =$``$f$ is perfect''
is fpqc local on the base.

\label{lemma-check-perfect-stalks}
Let $f : X \to S$ be a pseudo-coherent morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is perfect,
\item $\mathcal{O}_X$ locally has finite tor dimension as a
sheaf of $f^{-1}\mathcal{O}_S$-modules, and
\item for all $x \in X$ the ring $\mathcal{O}_{X, x}$ has finite tor
dimension as an $\mathcal{O}_{S, f(x)}$-module.
\end{enumerate}

\label{lemma-perfect-fppf-local-source}
The property $\mathcal{P}(f) =$``$f$ is perfect''
is fppf local on the source.

\label{lemma-factor-regular-immersion}
Let $i : Z \to Y$ and $j : Y \to X$ be immersions of schemes.
Assume
\begin{enumerate}
\item $X$ is locally Noetherian,
\item $j \circ i$ is a regular immersion, and
\item $i$ is perfect.
\end{enumerate}
Then $i$ and $j$ are regular immersions.

\label{lemma-koszul-independence-factorization}
Let $S$ be a scheme. Let $U$, $P$, $P'$ be schemes over $S$.
Let $u \in U$. Let $i : U \to P$, $i' : U \to P'$ be immersions over $S$.
Assume $P$ and $P'$ smooth over $S$. Then the following are equivalent
\begin{enumerate}
\item $i$ is a Koszul-regular immersion in a neighbourhood of $u$, and
\item $i'$ is a Koszul-regular immersion in a neighbourhood of $u$.
\end{enumerate}

\label{definition-lci}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item Let $x \in X$. We say that $f$ is {\it Koszul at $x$} if $f$
is of finite type at $x$ and there exists an open neighbourhood
and a factorization of $f|_U$ as $\pi \circ i$ where $i : U \to P$
is a Koszul-regular immersion and $\pi : P \to S$ is smooth.
\item We say $f$ is a {\it Koszul morphism}, or that
$f$ is a {\it local complete intersection morphism}
if $f$ is Koszul at every point.
\end{enumerate}

\label{lemma-lci-properties}
Let $f : X \to S$ be a local complete intersection morphism.
Then
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $f$ is pseudo-coherent, and
\item $f$ is perfect.
\end{enumerate}

\label{lemma-flat-base-change-lci}
A flat base change of a local complete intersection morphism is a
local complete intersection morphism.

\label{lemma-composition-lci}
A composition of local complete intersection morphisms
is a local complete intersection morphism.

\label{lemma-flat-lci}
\begin{slogan}
A morphism is flat and lci if and only if it is syntomic.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is flat and a local complete intersection morphism, and
\item $f$ is syntomic.
\end{enumerate}

\label{lemma-perfect-conormal-free-lci}
Let $i : X \to Y$ be an immersion. If
\begin{enumerate}
\item $i$ is perfect,
\item $Y$ is locally Noetherian, and
\item the conormal sheaf $\mathcal{C}_{X/Y}$ is finite locally free,
\end{enumerate}
then $i$ is a regular immersion.

\label{lemma-perfect-NL-lci}
Let $f : X \to Y$ be a perfect morphism of locally Noetherian schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is a local complete intersection morphism,
\item $\NL_{X/Y}$ has tor-amplitude in $[-1, 0]$, and
\item $\NL_{X/Y}$ is perfect with tor-amplitude in $[-1, 0]$.
\end{enumerate}

\label{lemma-flat-fp-NL-lci}
Let $f : X \to Y$ be a flat morphism of finite presentation.
The following are equivalent
\begin{enumerate}
\item $f$ is a local complete intersection morphism,
\item $f$ is syntomic,
\item $\NL_{X/Y}$ has tor-amplitude in $[-1, 0]$, and
\item $\NL_{X/Y}$ is perfect with tor-amplitude in $[-1, 0]$.
\end{enumerate}

\label{lemma-descending-property-lci}
The property $\mathcal{P}(f) =$``$f$ is a local complete intersection
morphism'' is fpqc local on the base.

\label{lemma-lci-syntomic-local-source}
The property $\mathcal{P}(f) =$``$f$ is a local complete intersection
morphism'' is syntomic local on the source.

\label{lemma-check-weakly-etale-stalks}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $X \to Y$ is weakly \'etale, and
\item for every $x \in X$ the ring map
$\mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$ is weakly \'etale.
\end{enumerate}

\label{lemma-composition-weakly-etale}
Let $X \to Y \to Z$ be morphisms of schemes.
\begin{enumerate}
\item If $X \to X \times_Y X$ and $Y \to Y \times_Z Y$ are flat,
then $X \to X \times_Z X$ is flat.
\item If $X \to Y$ and $Y \to Z$ are weakly \'etale, then
$X \to Z$ is weakly \'etale.
\end{enumerate}

\label{lemma-base-change-weakly-etale}
Let $X \to Y$ and $Y' \to Y$ be morphisms of schemes and let
$X' = Y' \times_Y X$ be the base change of $X$.
\begin{enumerate}
\item If $X \to X \times_Y X$ is flat, then $X' \to X' \times_{Y'} X'$
is flat.
\item If $X \to Y$ is weakly \'etale, then $X' \to Y'$ is weakly \'etale.
\end{enumerate}

\label{lemma-weakly-etale-formally-unramified}
Let $f : X \to Y$ be a weakly \'etale morphism of schemes.
Then $f$ is formally unramified, i.e., $\Omega_{X/Y} = 0$.

\label{lemma-when-weakly-etale}
Let $f : X \to Y$ be a morphism of schemes. Then $X \to Y$ is weakly \'etale
in each of the following cases
\begin{enumerate}
\item $X \to Y$ is a flat monomorphism,
\item $X \to Y$ is an open immersion,
\item $X \to Y$ is flat and unramified,
\item $X \to Y$ is \'etale.
\end{enumerate}

\label{lemma-reduced-goes-up}
Let $f : X \to Y$ be a morphism of schemes.
If $Y$ is reduced and $f$ weakly \'etale, then $X$ is reduced.

\label{lemma-weakly-etale-strictly-henselian-local-rings}
Let $f : X \to Y$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is weakly \'etale, and
\item for $x \in X$ the local ring map
$\mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$ induces an isomorphism
on strict henselizations.
\end{enumerate}

\label{lemma-normal-goes-up}
Let $f : X \to Y$ be a morphism of schemes. If $Y$ is a normal scheme
and $f$ weakly \'etale, then $X$ is a normal scheme.

\label{lemma-weakly-etale-permanence}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of schemes over $S$.
If $X$, $Y$ are weakly \'etale over $S$, then $f$ is weakly \'etale.

\label{lemma-weakly-etale-universal-homeomorphism}
Let $f : X \to Y$ be a morphism of schemes. If $f$ is weakly \'etale and
a universal homeomorphism, it is an isomorphism.

\label{lemma-ind-quasi-affine-examples}
Any quasi-affine morphism is ind-quasi-affine.
Any immersion is ind-quasi-affine.

\label{lemma-ind-quasi-affine-permanence}
If $f : X \to Y$ and $g : Y \to Z$ are morphisms of schemes
such that $g \circ f$ is ind-quasi-affine, then $f$ is ind-quasi-affine.

\label{lemma-prepare-pushout-along-closed-immersion-and-integral}
In Situation \ref{situation-pushout-along-closed-immersion-and-integral}
then for $y \in Y$ there exist affine opens $U \subset X$ and
$V \subset Y$ with $i^{-1}(U) = j^{-1}(V)$ and $y \in V$.

\label{proposition-pushout-along-closed-immersion-and-integral}
\begin{reference}
\cite[Theorem 7.1 part iii]{Ferrand-Conducteur}
\end{reference}
In Situation \ref{situation-pushout-along-closed-immersion-and-integral}
the pushout $Y \amalg_Z X$ exists in the category of schemes. Picture
$$
\xymatrix{
Z \ar[r]_i \ar[d]_j & X \ar[d]^a \\
Y \ar[r]^-b & Y \amalg_Z X
}
$$
The diagram is a fibre square, the morphism $a$ is integral,
the morphism $b$ is a closed immersion, and
$$
\mathcal{O}_{Y \amalg_Z X} =
b_*\mathcal{O}_Y \times_{c_*\mathcal{O}_Z} a_*\mathcal{O}_X
$$
as sheaves of rings where $c = a \circ i = b \circ j$.

\label{lemma-pushout-finite-type}
In Situation \ref{situation-pushout-along-closed-immersion-and-integral}
assume $S$ is a locally Noetherian scheme and $X$, $Y$, and $Z$
are locally of finite type over $S$. Then the pushout $Y \amalg_Z X$
(Proposition \ref{proposition-pushout-along-closed-immersion-and-integral})
is locally of finite type over $S$.

\label{lemma-pushout-functor}
In Situation \ref{situation-pushout-along-closed-immersion-and-integral}
suppose given a commutative diagram
$$
\xymatrix{
Y' \ar[d]^g & Z' \ar[l]^{j'} \ar[r]_{i'} \ar[d]^h & X' \ar[d]^f \\
Y & Z \ar[l] \ar[r] & X
}
$$
with cartesian squares and $f, g, h$ separated and locally quasi-finite. Then
\begin{enumerate}
\item the pushouts $Y \amalg_Z X$ and $Y' \amalg_{Z'} X'$ exist,
\item $Y' \amalg_{Z'} X' \to Y \amalg_Z X$ is
separated and locally quasi-finite, and
\item the squares
$$
\xymatrix{
Y' \ar[r] \ar[d] & Y' \amalg_{Z'} X' \ar[d] & X' \ar[l] \ar[d] \\
Y \ar[r] & Y \amalg_Z X & X \ar[l]
}
$$
are cartesian.
\end{enumerate}

\label{lemma-pushout-functor-equivalence-flat}
In Situation \ref{situation-pushout-along-closed-immersion-and-integral}
the category of schemes flat, separated, and locally quasi-finite
over the pushout $Y \amalg_Z X$ is equivalent to the category of
$(X', Y', Z', i', j', f, g, h)$ as in Lemma \ref{lemma-pushout-functor}
with $f, g, h$ flat. Similarly with ``flat'' replaced with
``\'etale''.

\label{lemma-hom-from-finite-locally-free-representable}
Let $Z \to S$ and $X \to S$ be morphisms of schemes.
Assume
\begin{enumerate}
\item $Z \to S$ is finite locally free, and
\item for all $(s, x_1, \ldots, x_d)$ where $s \in S$ and
$x_1, \ldots, x_d \in X_s$ there exists an affine open $U \subset X$
with $x_1, \ldots, x_d \in U$.
\end{enumerate}
Then $\mathit{Mor}_S(Z, X)$ is representable by a scheme.

\label{lemma-check-h1-fibre-zero}
Let $f : X \to Y$ be a proper morphism of schemes. Let $y \in Y$
be a point with $\dim(X_y) \leq 1$. If
\begin{enumerate}
\item $R^1f_*\mathcal{O}_X = 0$, or more generally
\item there is a morphism $g : Y' \to Y$ such that $y$ is in the image
of $g$ and such that $R^1f'_*\mathcal{O}_{X'} = 0$ where $f' : X' \to Y'$
is the base change of $f$ by $g$.
\end{enumerate}
Then $H^1(X_y, \mathcal{O}_{X_y}) = 0$.

\label{lemma-globally-generated-vanishing}
Let $f : X \to Y$ be a proper morphism of schemes such
that $\dim(X_y) \leq 1$ and $H^1(X_y, \mathcal{O}_{X_y}) = 0$
for all $y \in Y$. Let $\mathcal{F}$ be quasi-coherent on $X$. Then
\begin{enumerate}
\item $R^pf_*\mathcal{F} = 0$ for $p > 1$, and
\item $R^1f_*\mathcal{F} = 0$ if there is a surjection
$f^*\mathcal{G} \to \mathcal{F}$ with $\mathcal{G}$ quasi-coherent
on $Y$.
\end{enumerate}
If $Y$ is affine, then we also have
\begin{enumerate}
\item[(3)] $H^p(X, \mathcal{F}) = 0$ for $p \not \in \{0, 1\}$, and
\item[(4)] $H^1(X, \mathcal{F}) = 0$ if $\mathcal{F}$ is globally generated.
\end{enumerate}

\label{lemma-h1-fibre-zero-check-h0-kappa}
Let $f : X \to Y$ be a proper morphism of schemes. Assume
\begin{enumerate}
\item for all $y \in Y$ we have $\dim(X_y) \leq 1$ and
$H^1(X_y, \mathcal{O}_{X_y}) = 0$, and
\item $\mathcal{O}_Y \to f_*\mathcal{O}_X$ is surjective.
\end{enumerate}
Then $\mathcal{O}_{Y'} \to f'_*\mathcal{O}_{X'}$ is surjective
for any base change $f' : X' \to Y'$ of $f$.

\label{lemma-qc-affine-stratification}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ has a finite affine stratification, and
\item $X$ is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-affine-stratification-number-bound-Noetherian}
Let $X$ be a Noetherian scheme of dimension $\infty > d \geq 0$.
Then the affine stratification number of $X$ is at most $d$.

\label{lemma-quasi-finite-Noetherian-universally-open}
Let $f : X \to Y$ be a morphism of schemes. If
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item $Y$ is geometrically unibranch and locally Noetherian, and
\item every irreducible component of $X$ dominates
an irreducible component of $Y$,
\end{enumerate}
then $f$ is universally open.

\label{lemma-count-geometric-fibres}
Let $f : X \to Y$ be a locally quasi-finite morphism. Then
\begin{enumerate}
\item the functions $n_{X/Y}$ of
Lemmas \ref{lemma-base-change-fibres-nr-geometrically-irreducible-components}
and \ref{lemma-base-change-fibres-nr-geometrically-connected-components}
agree,
\item if $X$ is quasi-compact, then $n_{X/Y}$ attains a maximum $d < \infty$.
\end{enumerate}

\label{lemma-weighting-quasi-finite-Noetherian}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is locally quasi-finite, and
\item $Y$ is geometrically unibranch and locally Noetherian.
\end{enumerate}
Then there is a weighting $w : X \to \mathbf{Z}_{\geq 0}$ given by
the rule that sends $x \in X$ lying over $y \in Y$ to the
``generic separable degree''
of $\mathcal{O}_{X, x}^{sh}$ over $\mathcal{O}_{Y, y}^{sh}$.

\label{definition-cd-morphism}
A morphism $f : X \to Y$ of schemes is said to be
{\it completely decomposed}\footnote{This may be nonstandard terminology.}
if for all points $y \in Y$ there
is a point $x \in X$ with $f(x) = y$ such that the field
extension $\kappa(x)/\kappa(y)$ is trivial.
A family of morphisms $\{f_i : X_i \to Y\}_{i \in I}$ of
schemes with fixed target is said to be {\it completely decomposed}
if $\coprod f_i : \coprod Y_i \to X$ is completely decomposed.

\label{lemma-decompose}
\begin{reference}
\cite[Lemma 2.1.2]{EHIK}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes. Assume
$f$ is completely decomposed,
$f$ is locally of finite presentation, and
$Y$ is quasi-compact and quasi-separated.
Then there exist $n \geq 0$ and morphisms
$Z_i \to Y$, $i = 1, \ldots, n$ with the following properties
\begin{enumerate}
\item $\coprod Z_i \to Y$ is surjective,
\item $Z_i \to Y$ is an immersion for all $i$,
\item $Z_i \to Y$ is of finite presentation for all $i$, and
\item the base change $X \times_Y Z_i \to Z_i$ has a section
for all $i$.
\end{enumerate}

\label{lemma-ample-family-ample-relative}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $Y$ has an ample family of invertible modules,
\item there exists an $f$-ample invertible module on $X$.
\end{enumerate}
Then $X$ has an ample family of invertible modules.

\label{lemma-resolution-property-goes-up-affine}
Let $f : X \to Y$ be an affine or quasi-affine morphism of schemes.
If $Y$ has an ample family of invertible modules, so does $X$.

\label{lemma-blow-up-ample-family}
\begin{reference}
\cite[Proposition 1.3.1]{Gross-thesis}
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme with finitely
many irreducible components. There exists a quasi-compact dense open
$U \subset X$ and a $U$-admissible blowing up $X' \to X$ such that the
scheme $X'$ has an ample family of invertible modules.

\label{lemma-scheme-affine-if-aff-is-split-mono}
Let $X$ be a scheme.
If the canonical morphism $X \to \Spec(\Gamma(X, \mathcal{O}_X))$
of Schemes, Lemma \ref{schemes-lemma-morphism-into-affine}
has a retraction, then $X$ is an affine scheme.

\label{lemma-immersion-permanence}
Let $Z \to Y \to X$ be morphisms of schemes.
\begin{enumerate}
\item If $Z \to X$ is an immersion, then $Z \to Y$ is an immersion.
\item If $Z \to X$ is a quasi-compact immersion and $Y \to X$ is
quasi-separated, then $Z \to Y$ is a quasi-compact immersion.
\item If $Z \to X$ is a closed immersion and $Y \to X$ is separated,
then $Z \to Y$ is a closed immersion.
\end{enumerate}

\label{lemma-i-upper-shriek}
Let $i : Z \to X$ be a closed immersion of schemes.
There is a functor\footnote{This is likely nonstandard notation.}
$i^! : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Z)$
which is a right adjoint to $i_*$. (Compare
Modules, Lemma \ref{modules-lemma-i-star-right-adjoint}.)

\label{lemma-support-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is in the support of $M$, and
\item $x$ is in the support of $\mathcal{F}$.
\end{enumerate}

\label{definition-scheme-theoretic-image}
Let $f : X \to Y$ be a morphism of schemes. The {\it scheme theoretic image}
of $f$ is the smallest closed subscheme $Z \subset Y$ through which $f$
factors, see Lemma \ref{lemma-scheme-theoretic-image} above.

\label{definition-scheme-theoretically-dense}
Let $X$ be a scheme. Let $U \subset X$ be an open subscheme.
\begin{enumerate}
\item The scheme theoretic image of the morphism $U \to X$
is called the {\it scheme theoretic closure of $U$ in $X$}.
\item We say $U$ is {\it scheme theoretically dense in $X$}
if for every open $V \subset X$ the scheme theoretic closure
of $U \cap V$ in $V$ is equal to $V$.
\end{enumerate}

\label{lemma-intersection-scheme-theoretically-dense}
Let $X$ be a scheme. If $U$, $V$ are scheme theoretically dense
open subschemes of $X$, then so is $U \cap V$.

\label{lemma-reduced-scheme-theoretically-dense}
Let $X$ be a reduced scheme and let $U \subset X$ be an open subscheme.
Then the following are equivalent
\begin{enumerate}
\item $U$ is topologically dense in $X$,
\item the scheme theoretic closure of $U$ in $X$ is $X$, and
\item $U$ is scheme theoretically dense in $X$.
\end{enumerate}

\label{lemma-reduced-subscheme-closure}
Let $X$ be a scheme and let $U \subset X$ be a reduced open subscheme.
Then the following are equivalent
\begin{enumerate}
\item the scheme theoretic closure of $U$ in $X$ is $X$, and
\item $U$ is scheme theoretically dense in $X$.
\end{enumerate}
If this holds then $X$ is a reduced scheme.

\label{definition-dominant}
A morphism $f : X \to S$ of schemes is called {\it dominant} if the
image of $f$ is a dense subset of $S$.

\label{lemma-quasi-compact-dominant}
\begin{slogan}
Morphisms whose image contains the generic points are dominant
\end{slogan}
Let $f : X \to S$ be a quasi-compact morphism of schemes.
Then $f$ is dominant if and only if for every irreducible
component $Z \subset S$ the generic point of $Z$ is in the
image of $f$.

\label{definition-surjective}
A morphism of schemes is said to be {\it surjective}
if it is surjective on underlying topological
spaces.

\label{definition-universally-injective}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item We say that $f$ is {\it universally injective} if and only
if for any morphism of schemes $S' \to S$ the base change
$f' : X_{S'} \to S'$ is injective (on underlying topological spaces).
\item We say $f$ is {\it radicial} if $f$ is injective as a
map of topological spaces, and for every $x \in X$ the field
extension $\kappa(x)/\kappa(f(x))$ is purely inseparable.
\end{enumerate}

\label{lemma-universally-injective}
\begin{reference}
\cite[Proposition 3.7.1]{EGA1-second}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item For every field $K$ the induced map
$\Mor(\Spec(K), X) \to \Mor(\Spec(K), S)$
is injective.
\item The morphism $f$ is universally injective.
\item The morphism $f$ is radicial.
\item The diagonal morphism $\Delta_{X/S} : X \longrightarrow X \times_S X$
is surjective.
\end{enumerate}

\label{lemma-composition-universally-injective}
A composition of radicial morphisms is radicial, and so the same holds
for the equivalent condition of being universally injective.

\label{lemma-characterize-affine}
\begin{reference}
\cite[II, Corollary 1.3.2]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is affine.
\item There exists an affine open covering $S = \bigcup W_j$
such that each $f^{-1}(W_j)$ is affine.
\item There exists a quasi-coherent sheaf of $\mathcal{O}_S$-algebras
$\mathcal{A}$ and an isomorphism
$X \cong \underline{\Spec}_S(\mathcal{A})$
of schemes over $S$. See
Constructions, Section \ref{constructions-section-spec} for notation.
\end{enumerate}
Moreover, in this case $X = \underline{\Spec}_S(f_*\mathcal{O}_X)$.

\label{lemma-affine-equivalence-algebras}
Let $S$ be a scheme. There is an anti-equivalence of categories
$$
\begin{matrix}
\text{Schemes affine} \\
\text{over }S
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{quasi-coherent sheaves} \\
\text{of }\mathcal{O}_S\text{-algebras}
\end{matrix}
$$
which associates to $f : X \to S$ the sheaf $f_*\mathcal{O}_X$.
Moreover, this equivalence is compatible with arbitrary base change.

\label{lemma-quasi-coherence-scalar-restriction}
\begin{reference}
\cite[I, Proposition 9.6.1]{EGA}
\end{reference}
Let $S$ be a scheme and let $\mathcal{A}$ be a quasi-coherent
$\mathcal{O}_S$-algebra. An $\mathcal{A}$-module is
quasi-coherent as an $\mathcal{O}_S$-module if and only if
it is quasi-coherent as an $\mathcal{A}$-module.

\label{lemma-affine-equivalence-modules}
Let $f : X \to S$ be an affine morphism of schemes.
Let $\mathcal{A} = f_*\mathcal{O}_X$.
The functor $\mathcal{F} \mapsto f_*\mathcal{F}$ induces
an equivalence of categories
$$
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{O}_X\text{-modules}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{A}\text{-modules}
\end{matrix}
\right\}
$$
Moreover, an $\mathcal{A}$-module is
quasi-coherent as an $\mathcal{O}_S$-module if and only if
it is quasi-coherent as an $\mathcal{A}$-module.

\label{lemma-get-affine}
Let $j : Y \to X$ be an immersion of schemes.
Assume there exists an open $U \subset X$ with complement
$Z = X \setminus U$ such that
\begin{enumerate}
\item $U \to X$ is affine,
\item $j^{-1}(U) \to U$ is affine, and
\item $j(Y) \cap Z$ is closed.
\end{enumerate}
Then $j$ is affine. In particular, if $X$ is affine, so is $Y$.

\label{definition-family-ample-invertible-modules}
\begin{reference}
\cite[II Definition 2.2.4]{SGA6}
\end{reference}
Let $X$ be a scheme. Let $\{\mathcal{L}_i\}_{i \in I}$
be a family of invertible $\mathcal{O}_X$-modules. We say
$\{\mathcal{L}_i\}_{i \in I}$ is an
{\it ample family of invertible modules on $X$} if
\begin{enumerate}
\item $X$ is quasi-compact, and
\item for every $x \in X$ there exists an $i \in I$, an $n \geq 1$,
and $s \in \Gamma(X, \mathcal{L}_i^{\otimes n})$ such
that $x \in X_s$ and $X_s$ is affine.
\end{enumerate}

\label{definition-quasi-affine}
A morphism of schemes $f : X \to S$ is called {\it quasi-affine} if the
inverse image of every affine open of $S$ is a quasi-affine scheme.

\label{lemma-composition-finite-type}
The composition of two morphisms which are locally of finite type is
locally of finite type. The same is true for morphisms of finite type.

\label{lemma-immersion-locally-finite-type}
A closed immersion is of finite type.
An immersion is locally of finite type.

\label{lemma-finite-type-Noetherian-quasi-separated}
Let $f : X \to S$ be locally of finite type with $S$ locally Noetherian.
Then $f$ is quasi-separated.

\label{definition-finite-type-point}
Let $S$ be a scheme.
Let us say that a point $s$ of $S$ is a {\it finite type point}
if the canonical morphism $\Spec(\kappa(s)) \to S$ is of finite type.
We denote $S_{\text{ft-pts}}$ the set of finite type points of $S$.

\label{lemma-Jacobson-universally-Jacobson}
Let $S$ be a Jacobson scheme.
Any scheme locally of finite type over $S$ is Jacobson.

\label{lemma-universally-catenary-local-rings-universally-catenary}
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is universally catenary, and
\item all local rings $\mathcal{O}_{S, s}$ of $S$ are universally catenary.
\end{enumerate}

\label{lemma-catenary-check-irreducible}
Let $S$ be a locally Noetherian scheme. Then $S$ is universally catenary
if and only if the irreducible components of $S$ are universally catenary.

\label{lemma-ubiquity-uc}
The following types of schemes are universally catenary.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Cohen-Macaulay scheme.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a $1$-dimensional
Noetherian domain.
\item And so on.
\end{enumerate}

\label{lemma-ubiquity-nagata}
The following types of schemes are Nagata.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\item And so on.
\end{enumerate}

\label{definition-J}
Let $X$ be a locally Noetherian scheme. We say $X$ is {\it J-2}
if for every morphism $Y \to X$ which is locally of finite type
the regular locus $\text{Reg}(Y)$ is open in $Y$.

\label{lemma-characterize-quasi-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-excellent, and
\item $X$ is a G-scheme and J-2.
\end{enumerate}

\label{lemma-characterize-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is excellent, and
\item $X$ is quasi-excellent and universally catenary.
\end{enumerate}

\label{lemma-ubiquity-excellent}
The following types of schemes are excellent.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\end{enumerate}

\label{definition-quasi-finite}
\begin{reference}
\cite[II Definition 6.2.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item We say that $f$ is {\it quasi-finite at a point $x \in X$}
if there exist an affine neighbourhood $\Spec(A) = U \subset X$
of $x$ and an affine open $\Spec(R) = V \subset S$ such that
$f(U) \subset V$, the ring map $R \to A$ is of finite type,
and $R \to A$ is quasi-finite at the prime of $A$ corresponding to $x$
(see above).
\item We say $f$ is {\it locally quasi-finite} if $f$ is
quasi-finite at every point $x$ of $X$.
\item We say that $f$ is {\it quasi-finite} if $f$ is of finite type
and every point $x$ is an isolated point of its fibre.
\end{enumerate}

\label{lemma-algebraic-residue-field-extension-closed-point-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point. Set $s = f(x)$.
If $\kappa(x)/\kappa(s)$
is an algebraic field extension, then
\begin{enumerate}
\item $x$ is a closed point of its fibre, and
\item if in addition $s$ is a closed point of $S$, then
$x$ is a closed point of $X$.
\end{enumerate}

\label{lemma-finite-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $s \in S$. Assume that
\begin{enumerate}
\item $f$ is locally of finite type, and
\item $f^{-1}(\{s\})$ is a finite set.
\end{enumerate}
Then $X_s$ is a finite discrete topological space, and
$f$ is quasi-finite at each point of $X$ lying over $s$.

\label{lemma-locally-quasi-finite-fibres}
\begin{slogan}
Finite type morphisms with discrete fibers are quasi-finite.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is locally of finite type.
Then the following are equivalent
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item for every $s \in S$ the fibre $X_s$ is a discrete topological space, and
\item for every morphism $\Spec(k) \to S$ where $k$ is a field
the base change $X_k$ has an underlying discrete topological space.
\end{enumerate}

\label{lemma-quasi-finite}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is quasi-finite, and
\item $f$ is locally of finite type, quasi-compact, and has finite fibres.
\end{enumerate}

\label{lemma-composition-quasi-finite}
The composition of two morphisms which are locally quasi-finite is
locally quasi-finite. The same is true for quasi-finite morphisms.

\label{lemma-quasi-compact-open-immersion-finite-presentation}
Any open immersion is of finite presentation if and only if
it is quasi-compact.

\label{lemma-closed-immersion-finite-presentation}
\begin{slogan}
Closed immersions of finite presentation correspond
to quasi-coherent sheaves of ideals of finite type.
\end{slogan}
A closed immersion $i : Z \to X$ is of finite presentation if and only if
the associated quasi-coherent sheaf of ideals
$\mathcal{I} = \Ker(\mathcal{O}_X \to i_*\mathcal{O}_Z)$
is of finite type (as an $\mathcal{O}_X$-module).

\label{lemma-finite-presentation-finite-type}
A morphism which is locally of finite presentation is locally of finite type.
A morphism of finite presentation is of finite type.

\label{lemma-noetherian-finite-type-finite-presentation}
\begin{slogan}
Over a locally Noetherian base, finite type is finite presentation.
\end{slogan}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $S$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $S$ is locally Noetherian and $f$ of finite type
then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-finite-presentation-permanence}
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is locally of finite presentation over $S$ and
$Y$ is locally of finite type over $S$, then $f$ is locally
of finite presentation.
\item If $X$ is of finite presentation over $S$ and $Y$ is quasi-separated
and locally of finite type over $S$, then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-chevalley}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $f$ is quasi-compact and locally of finite presentation, and
\item $Y$ is quasi-compact and quasi-separated.
\end{enumerate}
Then the image of every constructible subset of $X$ is constructible in $Y$.

[Chevalley's Theorem]
\label{theorem-chevalley}
\begin{reference}
\cite[IV, Theorem 1.8.4]{EGA}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes.
Assume $f$ is quasi-compact and locally of finite presentation.
Then the image of every locally constructible subset is locally constructible.

\label{definition-open}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item We say $f$ is {\it open} if the map on underlying
topological spaces is open.
\item We say $f$ is {\it universally open} if for any morphism of
schemes $S' \to S$ the base change $f' : X_{S'} \to S'$ is open.
\end{enumerate}

\label{lemma-locally-finite-presentation-universally-open}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is locally of finite presentation and generalizations lift
along $f$, then $f$ is open.
\item If $f$ is locally of finite presentation and generalizations lift
along every base change of $f$, then $f$ is universally open.
\end{enumerate}

\label{lemma-scheme-over-field-universally-open}
Let $k$ be a field. Let $X$ be a scheme over $k$.
The structure morphism $X \to \Spec(k)$ is universally open.

\label{lemma-open-generizing}
\begin{reference}
Follows from the implication (a) $\Rightarrow$ (b) in
\cite[IV, Corollary 1.10.4]{EGA}
\end{reference}
Let $\varphi : X \to Y$ be a morphism of schemes.
If $\varphi$ is open, then $\varphi$ is generizing
(i.e., generalizations lift along $\varphi$).
If $\varphi$ is universally open, then $\varphi$ is
universally generizing.

\label{definition-submersive}
Let $f : X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item We say $f$ is {\it submersive}\footnote{This is very different
from the notion of a submersion of differential manifolds.}
if the continuous map of underlying topological spaces is submersive, see
Topology, Definition \ref{topology-definition-submersive}.
\item We say $f$ is {\it universally submersive} if for every
morphism of schemes $Y' \to Y$ the base change
$Y' \times_Y X \to Y'$ is submersive.
\end{enumerate}

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of schemes
by any morphism of schemes is universally submersive.

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
schemes is (universally) submersive.

\label{definition-flat}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent sheaf of $\mathcal{O}_X$-modules.
\begin{enumerate}
\item We say $f$ is {\it flat at a point $x \in X$} if the
local ring $\mathcal{O}_{X, x}$ is flat over the local ring
$\mathcal{O}_{S, f(x)}$.
\item We say that $\mathcal{F}$ is {\it flat over $S$ at a point $x \in X$}
if the stalk $\mathcal{F}_x$ is a flat $\mathcal{O}_{S, f(x)}$-module.
\item We say $f$ is {\it flat} if $f$ is flat at every point of $X$.
\item We say that $\mathcal{F}$ is {\it flat over $S$} if
$\mathcal{F}$ is flat over $S$ at every point $x$ of $X$.
\end{enumerate}

\label{lemma-fpqc-quotient-topology}
\begin{reference}
\cite[Expose VIII, Corollaire 4.3]{SGA1} and
\cite[IV, Corollaire 2.3.12]{EGA}
\end{reference}
Let $f : X \to Y$ be a quasi-compact, surjective, flat morphism.
A subset $T \subset Y$ is open (resp.\ closed) if and only
$f^{-1}(T)$ is open (resp.\ closed). In other words, $f$ is
a submersive morphism.

\label{lemma-flat-base-change-scheme-theoretic-image}
\begin{slogan}
Taking scheme theoretic images commutes with flat base change
in the quasi-compact case
\end{slogan}
Let $f : X \to Y$ be a flat morphism of schemes. Let $g : V \to Y$ be a
quasi-compact morphism of schemes. Let $Z \subset Y$ be the scheme theoretic
image of $g$ and let $Z' \subset X$ be the scheme theoretic image of the
base change $V \times_Y X \to X$. Then $Z' = f^{-1}Z$.

\label{lemma-characterize-flat-closed-immersions}
Let $X$ be a scheme. The rule which associates to a closed subscheme
of $X$ its underlying closed subset defines a bijection
$$
\left\{
\begin{matrix}
\text{closed subschemes }Z \subset X \\
\text{such that }Z \to X\text{ is flat}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{closed subsets }Z \subset X \\
\text{closed under generalizations}
\end{matrix}
\right\}
$$
If $Z \subset X$ is such a closed subscheme, every morphism of schemes
$g : Y \to X$ with $g(Y) \subset Z$ set theoretically factors (scheme
theoretically) through $Z$.

\label{lemma-flat-closed-immersions-finite-presentation}
A flat closed immersion of finite presentation
is the open immersion of an open and closed subscheme.

\label{lemma-finite-flat-is-finite-locally-free}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item every finite flat quasi-coherent $\mathcal{O}_X$-module is
finite locally free, and
\item every closed subset $Z \subset X$ which is closed under generalizations
is open.
\end{enumerate}

\label{lemma-openness-bounded-dimension-fibres}
\begin{reference}
\cite[IV Theorem 13.1.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $n \geq 0$. Assume $f$ is locally of finite type.
The set
$$
U_n = \{x \in X \mid \dim_x X_{f(x)} \leq n\}
$$
is open in $X$.

\label{lemma-morphism-finite-type-bounded-dimension}
Let $f : X \to Y$ be a morphism of finite type with $Y$ quasi-compact.
Then the dimension of the fibres of $f$ is bounded.

\label{lemma-flat-finite-presentation-CM-fibres-relative-dimension}
\begin{slogan}
Cohen-Macaulay morphisms decompose into clopens of pure relative dimension
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $f$ is flat,
\item $f$ is locally of finite presentation, and
\item for all $s \in S$ the fibre $X_s$ is Cohen-Macaulay
(Properties, Definition \ref{properties-definition-Cohen-Macaulay})
\end{enumerate}
Then there exist open and closed subschemes $X_d \subset X$
such that $X = \coprod_{d \geq 0} X_d$ and $f|_{X_d} : X_d \to S$
has relative dimension $d$.

\label{lemma-syntomic-relative-dimension}
Let $f : X \to S$ be a syntomic morphism. The function
$x \mapsto \dim_x(X_{f(x)})$ is locally constant on $X$.

\label{definition-conormal-sheaf}
Let $i : Z \to X$ be an immersion. The {\it conormal sheaf
$\mathcal{C}_{Z/X}$ of $Z$ in $X$} or the {\it conormal sheaf of $i$}
is the quasi-coherent $\mathcal{O}_Z$-module $\mathcal{I}/\mathcal{I}^2$
described above.

\label{lemma-conormal-functorial-flat}
Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a fibre product diagram in the category of schemes with
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X'} \to \mathcal{C}_{Z/X}$ of
Lemma \ref{lemma-conormal-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{lemma-differential-product}
Let $f : X \to S$ and $g : Y \to S$ be morphisms of schemes with the same
target. Let $p : X \times_S Y \to X$ and $q : X \times_S Y \to Y$ be the
projection morphisms. The maps from
Lemma \ref{lemma-functoriality-differentials}
$$
p^*\Omega_{X/S} \oplus q^*\Omega_{Y/S}
\longrightarrow
\Omega_{X \times_S Y/S}
$$
give an isomorphism.

\label{lemma-immersion-differentials}
If $X \to S$ is an immersion, or more generally a monomorphism, then
$\Omega_{X/S}$ is zero.

\label{lemma-smooth-locally-standard-smooth}
\begin{slogan}
Smooth morphisms are locally standard smooth.
\end{slogan}
Let $f : X  \to S$ be a morphism of schemes.
Let $x \in X$ be a point.
Let $V \subset S$ be an affine open neighbourhood of $f(x)$.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is smooth at $x$.
\item There exists an affine open $U \subset X$,
with $x \in U$ and $f(U) \subset V$ such that the
induced morphism $f|_U : U \to V$ is standard smooth.
\end{enumerate}

\label{lemma-set-points-where-fibres-smooth}
Let
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
S' \ar[r]^g & S
}
$$
be a cartesian diagram of schemes. Let $W \subset X$, resp.\ $W' \subset X'$
be the open subscheme of points where $f$, resp.\ $f'$ is smooth.
Then $W' = (g')^{-1}(W)$ if
\begin{enumerate}
\item $f$ is flat and locally of finite presentation, or
\item $f$ is locally of finite presentation and $g$ is flat.
\end{enumerate}

\label{lemma-unramified-omega-zero}
Let $f : X \to S$ be a morphism of schemes. Then
\begin{enumerate}
\item $f$ is unramified if and only if $f$ is locally of finite type
and $\Omega_{X/S} = 0$, and
\item $f$ is G-unramified if and only if $f$ is locally of finite presentation
and $\Omega_{X/S} = 0$.
\end{enumerate}

\label{lemma-composition-unramified}
The composition of two morphisms which are unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-base-change-unramified}
The base change of a morphism which is unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-noetherian-unramified}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian.
Then $f$ is unramified if and only if $f$ is G-unramified.

\label{lemma-unramified-locally-finite-type}
An unramified morphism is locally of finite type.
A G-unramified morphism is locally of finite presentation.

\label{lemma-diagonal-unramified-morphism}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is unramified, then the diagonal morphism
$\Delta : X \to X \times_S X$ is an open immersion.
\item If $f$ is locally of finite type
and $\Delta$ is an open immersion, then $f$ is unramified.
\item If $f$ is locally of finite presentation and $\Delta$ is an open
immersion, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-unramified-permanence}
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is unramified over $S$, then $f$ is unramified.
\item If $X$ is G-unramified over $S$ and $Y$ is locally of finite type
over $S$, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-etale-over-field}
\begin{slogan}
Description of the \'etale schemes over fields and fibres
of \'etale morphisms.
\end{slogan}
Fibres of \'etale morphisms.
\begin{enumerate}
\item Let $X$ be a scheme over a field $k$.
The structure morphism $X \to \Spec(k)$ is \'etale if
and only if $X$ is a disjoint union of spectra of finite separable
field extensions of $k$.
\item If $f : X \to S$ is an \'etale morphism, then for every $s \in S$ the
fibre $X_s$ is a disjoint union of spectra of finite separable field
extensions of $\kappa(s)$.
\end{enumerate}

\label{lemma-set-points-where-fibres-etale}
Let
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
S' \ar[r]^g & S
}
$$
be a cartesian diagram of schemes. Let $W \subset X$, resp.\ $W' \subset X'$
be the open subscheme of points where $f$, resp.\ $f'$ is \'etale.
Then $W' = (g')^{-1}(W)$ if
\begin{enumerate}
\item $f$ is flat and locally of finite presentation, or
\item $f$ is locally of finite presentation and $g$ is flat.
\end{enumerate}

\label{lemma-etale-permanence-better}
\begin{reference}
See for example \cite[Remark 18.30 (2).]{GWII}.
\end{reference}
Let $f : X \to Y$ be a morphism of schemes over $S$.
If $X$ is \'etale over $S$ and $Y$ is unramified over $S$, then
$f$ is \'etale.

\label{lemma-etale-permanence}
\begin{slogan}
Cancellation law for \'etale morphisms
\end{slogan}
Let $f : X \to Y$ be a morphism of schemes over $S$.
If $X$ and $Y$ are \'etale over $S$, then
$f$ is \'etale.

\label{lemma-smooth-etale-over-affine-space}
\begin{slogan}
Smooth schemes are \'etale-locally like affine spaces.
\end{slogan}
Let $\varphi : X \to Y$ be a morphism of schemes. Let $x \in X$.
Let $V \subset Y$ be an affine open neighbourhood of $\varphi(x)$.
If $\varphi$ is smooth at $x$, then there exists an integer $d \geq 0$
and an affine open $U \subset X$ with $x \in U$ and
$\varphi(U) \subset V$ such that there exists a commutative diagram
$$
\xymatrix{
X \ar[d] & U \ar[l] \ar[d] \ar[r]_-\pi & \mathbf{A}^d_V \ar[ld] \\
Y & V \ar[l]
}
$$
where $\pi$ is \'etale.

\label{definition-relatively-ample}
\begin{reference}
\cite[II Definition 4.6.1]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
We say $\mathcal{L}$ is {\it relatively ample}, or {\it $f$-relatively ample},
or {\it ample on $X/S$}, or {\it $f$-ample} if $f : X \to S$
is quasi-compact, and if for every affine open $V \subset S$
the restriction of $\mathcal{L}$ to the open subscheme
$f^{-1}(V)$ of $X$ is ample.

\label{lemma-ample-over-affine}
\begin{reference}
\cite[II Corollary 4.6.6]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Assume $S$ affine.
Then $\mathcal{L}$ is $f$-relatively ample if and only
if $\mathcal{L}$ is ample on $X$.

\label{lemma-quasi-affine-O-ample}
\begin{reference}
\cite[II Proposition 5.1.6]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes. Then $f$ is quasi-affine
if and only if $\mathcal{O}_X$ is $f$-relatively ample.

\label{lemma-ample-very-ample}
\begin{reference}
\cite[II, Proposition 4.6.2]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
If $f$ is quasi-compact and $\mathcal{L}$ is a relatively
very ample invertible sheaf, then $\mathcal{L}$ is a relatively
ample invertible sheaf.

\label{lemma-finite-type-ample-very-ample}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Assume $S$ quasi-compact and $f$ of finite type.
The following are equivalent
\begin{enumerate}
\item $\mathcal{L}$ is $f$-ample,
\item $\mathcal{L}^{\otimes d}$ is $f$-very ample for some $d \geq 1$,
\item $\mathcal{L}^{\otimes d}$ is $f$-very ample for all $d \gg 1$.
\end{enumerate}

\label{definition-quasi-projective}
\begin{reference}
\cite[II, Definition 5.3.1]{EGA} and \cite[page 103]{H}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item We say $f$ is {\it quasi-projective} if $f$ is of finite type
and there exists an $f$-relatively ample invertible $\mathcal{O}_X$-module.
\item We say $f$ is {\it H-quasi-projective} if there exists
a quasi-compact immersion $X \to \mathbf{P}^n_S$ over $S$ for some
$n$.\footnote{This is not exactly the same as the definition in Hartshorne.
Namely, the definition in Hartshorne (8th corrected printing, 1997) is that
$f$ should be the composition of an open immersion followed by a H-projective
morphism (see Definition \ref{definition-projective}), which does not imply
$f$ is quasi-compact. See
Lemma \ref{lemma-H-quasi-projective-open-H-projective} for
the implication in the other direction.}
\item We say $f$ is {\it locally quasi-projective} if there exists
an open covering $S = \bigcup V_j$ such that each $f^{-1}(V_j) \to V_j$
is quasi-projective.
\end{enumerate}

\label{lemma-characterize-locally-quasi-projective}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is locally quasi-projective.
\item There exists an open covering $S = \bigcup V_j$ such
that each $f^{-1}(V_j) \to V_j$ is H-quasi-projective.
\end{enumerate}

\label{lemma-quasi-affine-finite-type-quasi-projective}
\begin{reference}
\cite[II, Proposition 5.3.4 (i)]{EGA}
\end{reference}
A quasi-affine morphism of finite type is quasi-projective.

\label{lemma-universally-closed-local-on-the-base}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is universally closed.
\item There exists an open covering $S = \bigcup V_j$ such
that $f^{-1}(V_j) \to V_j$ is universally closed for all indices $j$.
\end{enumerate}

\label{lemma-proper-local-on-the-base}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is proper.
\item There exists an open covering $S = \bigcup V_j$ such
that $f^{-1}(V_j) \to V_j$ is proper for all indices $j$.
\end{enumerate}

\label{lemma-composition-proper}
The composition of proper morphisms is proper.
The same is true for universally closed morphisms.

\label{lemma-base-change-proper}
The base change of a proper morphism is proper.
The same is true for universally closed morphisms.

\label{lemma-image-proper-scheme-closed}
Suppose given a commutative diagram of schemes
$$
\xymatrix{
X \ar[rr] \ar[rd] & &
Y \ar[ld] \\
& S &
}
$$
with $Y$ separated over $S$.
\begin{enumerate}
\item If $X \to S$ is universally closed, then the morphism
$X \to Y$ is universally closed.
\item If $X$ is proper over $S$, then the morphism $X \to Y$ is proper.
\end{enumerate}
In particular, in both cases the image of $X$ in $Y$ is closed.

\label{lemma-universally-closed-quasi-compact}
\begin{reference}
Due to Bjorn Poonen.
\end{reference}
A universally closed morphism of schemes is quasi-compact.

\label{lemma-scheme-theoretic-image-is-proper}
Suppose given a commutative diagram of schemes
$$
\xymatrix{
X \ar[rr]_h \ar[rd]_f & & Y \ar[ld]^g \\
& S
}
$$
Assume
\begin{enumerate}
\item $X \to S$ is a universally closed (for example proper) morphism, and
\item $Y \to S$ is separated and locally of finite type.
\end{enumerate}
Then the scheme theoretic image $Z \subset Y$ of $h$
is proper over $S$ and $X \to Z$ is surjective.

\label{lemma-image-universally-closed-separated}
Let $S$ be a scheme. Let $f : X \to Y$ be a surjective universally closed
morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is quasi-separated, then $Y$ is quasi-separated.
\item If $X$ is separated, then $Y$ is separated.
\item If $X$ is quasi-separated over $S$, then $Y$ is quasi-separated over $S$.
\item If $X$ is separated over $S$, then $Y$ is separated over $S$.
\end{enumerate}

[Valuative criterion for properness]
\label{lemma-characterize-proper}
\begin{reference}
\cite[II Theorem 7.3.8]{EGA}
\end{reference}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of schemes
over $S$. Assume $f$ is of finite type and quasi-separated.
Then the following are equivalent
\begin{enumerate}
\item $f$ is proper,
\item $f$ satisfies the valuative criterion
(Schemes, Definition \ref{schemes-definition-valuative-criterion}),
\item given any commutative solid diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d] \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $A$ is a valuation ring with field of fractions $K$, there exists
a unique dotted arrow making the diagram commute.
\end{enumerate}

\label{lemma-H-projective}
An H-projective morphism is H-quasi-projective.
An H-projective morphism is projective.

\label{lemma-characterize-locally-projective}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is locally projective.
\item There exists an open covering $S = \bigcup U_i$ such
that each $f^{-1}(U_i) \to U_i$ is H-projective.
\end{enumerate}

\label{lemma-proper-ample-locally-projective}
Let $f : X \to S$ be a proper morphism of schemes. If there exists
an $f$-ample invertible sheaf on $X$, then $f$ is locally projective.

\label{lemma-projective-is-quasi-projective-proper}
Let $S$ be a quasi-compact and quasi-separated scheme.
Let $f : X \to S$ be a morphism of schemes. Then
\begin{enumerate}
\item $f$ is projective if and only if $f$ is quasi-projective and proper, and
\item $f$ is H-projective if and only if $f$ is H-quasi-projective and proper.
\end{enumerate}

\label{lemma-projective-over-quasi-projective-is-H-projective}
Let $S$ be a scheme which admits an ample invertible sheaf. Then
\begin{enumerate}
\item any projective morphism $X \to S$ is H-projective, and
\item any quasi-projective morphism $X \to S$ is H-quasi-projective.
\end{enumerate}

\label{lemma-finite-integral}
A finite morphism is integral.
An integral morphism which is locally of finite type is finite.

\label{lemma-composition-finite}
A composition of finite morphisms is finite.
Same is true for integral morphisms.

\label{lemma-base-change-finite}
A base change of a finite morphism is finite.
Same is true for integral morphisms.

\label{lemma-integral-universally-closed}
\begin{slogan}
integral $=$ affine $+$ universally closed
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f$ is integral, and
\item $f$ is affine and universally closed.
\end{enumerate}

\label{lemma-integral-fibres}
Let $f : X \to S$ be an integral morphism.
Then every point of $X$ is closed in its fibre.

\label{lemma-integral-dimension}
Let $f : X \to Y$ be an integral morphism. Then $\dim(X) \leq \dim(Y)$.
If $f$ is surjective then $\dim(X) = \dim(Y)$.

\label{lemma-finite-proper}
Let $f : X \to S$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is finite, and
\item $f$ is affine and proper.
\end{enumerate}

\label{lemma-finite-union-finite}
Let $X_i \to Y$, $i = 1, \ldots, n$ be finite morphisms of schemes.
Then $X_1 \amalg \ldots \amalg X_n \to Y$ is finite too.

\label{lemma-finite-permanence}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms.
\begin{enumerate}
\item If $g \circ f$ is finite and $g$ separated then $f$ is finite.
\item If $g \circ f$ is integral and $g$ separated then $f$ is integral.
\end{enumerate}

\label{lemma-finite-monomorphism-closed}
Let $f : X \to Y$ be a morphism of schemes.
If $f$ is finite and a monomorphism, then $f$ is a closed immersion.

\label{definition-universal-homeomorphism}
A morphism $f : X \to Y$ of schemes is called a {\it universal homeomorphism}
if the base change $f' : Y' \times_Y X \to Y'$ is a homeomorphism for
every morphism $Y' \to Y$.

\label{lemma-base-change-universal-homeomorphism}
The base change of a universal homeomorphism of schemes
by any morphism of schemes is a universal homeomorphism.

\label{lemma-composition-universal-homeomorphism}
The composition of a pair of universal homeomorphisms of
schemes is a universal homeomorphism.

\label{lemma-homeomorphism-affine}
Let $f : X \to Y$ be a morphism of schemes. If $f$ is a homeomorphism
onto a closed subset of $Y$ then $f$ is affine.

\label{lemma-universal-homeomorphism}
Let $f : X \to Y$ be a morphism of schemes. The following are
equivalent:
\begin{enumerate}
\item $f$ is a universal homeomorphism, and
\item $f$ is integral, universally injective and surjective.
\end{enumerate}

\label{lemma-check-closed-infinitesimally}
Let $f : X \to S$ and $S' \to S$ be morphisms of schemes.
Assume
\begin{enumerate}
\item $S' \to S$ is a closed immersion,
\item $S' \to S$ is bijective on points,
\item $X \times_S S' \to S'$ is a closed immersion, and
\item $X \to S$ is of finite type or $S' \to S$ is of finite presentation.
\end{enumerate}
Then $f : X \to S$ is a closed immersion.

\label{proposition-universal-homeomorphism}
Let $A \subset B$ be a ring extension. The following are equivalent
\begin{enumerate}
\item $\Spec(B) \to \Spec(A)$ is a universal homeomorphism, and
\item every finite subset $E \subset B$ is contained in an extension
$$
A[b_1, \ldots, b_n] \subset B
$$
such that for $i = 1, \ldots, n$ we have
\begin{enumerate}
\item $b_i^2, b_i^3 \in A[b_1, \ldots, b_{i - 1}]$, or
\item there exists a prime number $p$ with
$pb_i, b_i^p \in A[b_1, \ldots, b_{i - 1}]$.
\end{enumerate}
\end{enumerate}

\label{lemma-make-universal-homeo}
Let $A$ be a ring. Let $x, y \in A$.
\begin{enumerate}
\item If $x^3 = y^2$ in $A$, then $A \to B = A[t]/(t^2 - x, t^3 - y)$
induces bijections on residue fields and a
universal homeomorphism on spectra.
\item If there is a prime number $p$ such that $p^px = y^p$ in $A$, then
$A \to B = A[t]/(t^p - x, pt - y)$ induces a universal
homeomorphism on spectra.
\end{enumerate}

\label{definition-seminormal}
Let $X$ be a scheme.
\begin{enumerate}
\item We say $X$ is {\it seminormal} if every $x \in X$ has
an affine open neighbourhood $\Spec(R) = U \subset X$
such that the ring $R$ is seminormal.
\item We say $X$ is {\it absolutely weakly normal} if every $x \in X$ has
an affine open neighbourhood $\Spec(R) = U \subset X$
such that the ring $R$ is absolutely weakly normal.
\end{enumerate}

\label{lemma-seminormal-reduced}
A seminormal scheme or ring is reduced. A fortiori the same
is true for absolutely weakly normal schemes or rings.

\label{definition-seminormalization}
Let $X$ be a scheme.
\begin{enumerate}
\item The morphism $X^{sn} \to X$ constructed in
Lemma \ref{lemma-seminormalization}
is the {\it seminormalization} of $X$.
\item The morphism $X^{awn} \to X$ constructed in
Lemma \ref{lemma-seminormalization}
is the {\it absolute weak normalization} of $X$.
\end{enumerate}

\label{lemma-characterize-seminormal}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is seminormal,
\item $X$ is equal to its own seminormalization, i.e., the morphism
$X^{sn} \to X$ is an isomorphism,
\item if $\pi : Y \to X$ is a universal homeomorphism inducing isomorphisms
on residue fields with $Y$ reduced, then $\pi$ is an isomorphism.
\end{enumerate}

\label{lemma-characterize-absolutely-weakly-normal}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is absolutely weakly normal,
\item $X$ is equal to its own absolute weak normalization, i.e., the morphism
$X^{awn} \to X$ is an isomorphism,
\item if $\pi : Y \to X$ is a universal homeomorphism with $Y$ reduced, then
$\pi$ is an isomorphism.
\end{enumerate}

\label{lemma-finite-flat}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite locally free,
\item $f$ is finite, flat, and locally of finite presentation.
\end{enumerate}
If $S$ is locally Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] $f$ is finite and flat.
\end{enumerate}

\label{lemma-rational-map-finite-presentation}
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$. Assume $X$ has
finitely many irreducible components with generic points
$x_1, \ldots, x_n$. Let $s_i \in S$ be the image of $x_i$.
Consider the map
$$
\left\{
\begin{matrix}
S\text{-rational maps} \\
\text{from }X\text{ to }Y
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(y_1, \varphi_1, \ldots, y_n, \varphi_n)\text{ where }
y_i \in Y\text{ lies over }s_i\text{ and}\\
\varphi_i : \mathcal{O}_{Y, y_i} \to \mathcal{O}_{X, x_i}
\text{ is a local }\mathcal{O}_{S, s_i}\text{-algebra map}
\end{matrix}
\right\}
$$
which sends $f : U \to Y$ to the $2n$-tuple with
$y_i = f(x_i)$ and $\varphi_i = f^\sharp_{x_i}$. Then
\begin{enumerate}
\item If $Y \to S$ is locally of finite type, then the map is injective.
\item If $Y \to S$ is locally of finite presentation, then the map is bijective.
\item If $Y \to S$ is locally of finite type and $X$ reduced,
then the map is bijective.
\end{enumerate}

\label{definition-rational-function}
Let $X$ be a scheme. A {\it rational function on $X$} is a rational map
from $X$ to $\mathbf{A}^1_{\mathbf{Z}}$.

\label{definition-ring-of-rational-functions}
Let $X$ be a scheme. The {\it ring of rational functions on $X$}
is the ring $R(X)$ whose elements are rational functions with
addition and multiplication as just described.

\label{definition-function-field}
Let $X$ be an integral scheme.
The {\it function field}, or the {\it field of rational functions}
of $X$ is the field $R(X)$.

\label{definition-birational-schemes}
Let $X$ and $Y$ be irreducible schemes.
\begin{enumerate}
\item We say $X$ and $Y$ are {\it birational} if $X$ and $Y$ are isomorphic
in the category of irreducible schemes and dominant rational maps.
\item Assume $X$ and $Y$ are schemes over a base scheme $S$.
We say $X$ and $Y$ are {\it $S$-birational} if $X$ and $Y$ are
isomorphic in the category of irreducible schemes over $S$ and
dominant $S$-rational maps.
\end{enumerate}

\label{lemma-birational-integral}
Let $X$ and $Y$ be irreducible schemes.
\begin{enumerate}
\item The schemes $X$ and $Y$ are birational if and only if they have
isomorphic nonempty opens.
\item Assume $X$ and $Y$ are schemes over a base scheme $S$. Then
$X$ and $Y$ are $S$-birational if and only if there are nonempty
opens $U \subset X$ and $V \subset Y$ which are $S$-isomorphic.
\end{enumerate}

\label{definition-birational}
\begin{reference}
\cite[(2.2.9)]{EGA1}
\end{reference}
Let $X$, $Y$ be schemes. Assume $X$ and $Y$ have finitely many
irreducible components. We say a morphism $f : X \to Y$ is
{\it birational} if
\begin{enumerate}
\item $f$ induces a bijection between the set of generic points
of irreducible components of $X$ and the set of generic points
of the irreducible components of $Y$, and
\item for every generic point $\eta \in X$ of an irreducible component
of $X$ the local ring map
$\mathcal{O}_{Y, f(\eta)} \to \mathcal{O}_{X, \eta}$
is an isomorphism.
\end{enumerate}

\label{lemma-common-open}
Let $S$ be a scheme. Let $X$ and $Y$ be integral schemes locally
of finite type over $S$. Let $x \in X$ and $y \in Y$ be the generic points.
The following are equivalent
\begin{enumerate}
\item $X$ and $Y$ are $S$-birational,
\item there exist nonempty opens of $X$ and $Y$ which are $S$-isomorphic, and
\item $x$ and $y$ map to the same point $s \in S$ and
$\kappa(x) \cong \kappa(y)$ as $\kappa(s)$-extensions.
\end{enumerate}

\label{lemma-quasi-finiteness-over-generic-point}
Let $X$, $Y$ be schemes. Let $f : X \to Y$ be locally of finite type.
Let $X^0$, resp.\ $Y^0$ denote the set of generic points of irreducible
components of $X$, resp.\ $Y$. Let $\eta \in Y^0$. The following are
equivalent
\begin{enumerate}
\item $f^{-1}(\{\eta\}) \subset X^0$,
\item $f$ is quasi-finite at all points lying over $\eta$,
\item $f$ is quasi-finite at all $\xi \in X^0$ lying over $\eta$.
\end{enumerate}

\label{lemma-finite-over-dense-open}
Let $X$, $Y$ be schemes. Let $f : X \to Y$ be locally of finite type.
Let $X^0$, resp.\ $Y^0$ denote the set of generic points of irreducible
components of $X$, resp.\ $Y$. Assume
\begin{enumerate}
\item $X^0$ and $Y^0$ are finite and $f^{-1}(Y^0) = X^0$,
\item either $f$ is quasi-compact or $f$ is separated.
\end{enumerate}
Then there exists a dense open $V \subset Y$
such that $f^{-1}(V) \to V$ is finite.

\label{definition-modification}
Let $X$ be an integral scheme. A {\it modification of $X$}
is a birational proper morphism $f : X' \to X$ with $X'$
integral.

\label{definition-alteration}
\begin{reference}
\cite[Definition 2.20]{alterations}
\end{reference}
Let $X$ be an integral scheme. An {\it alteration of $X$}
is a proper dominant morphism $f : Y \to X$ with $Y$ integral such
that $f^{-1}(U) \to U$ is finite for some nonempty open $U \subset X$.

\label{lemma-dimension-formula}
Let $S$ be a scheme.
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$, and set $s = f(x)$.
Assume
\begin{enumerate}
\item $S$ is locally Noetherian,
\item $f$ is locally of finite type,
\item $X$ and $S$ integral, and
\item $f$ dominant.
\end{enumerate}
We have
\begin{equation}
\label{equation-dimension-formula}
\dim(\mathcal{O}_{X, x})
\leq
\dim(\mathcal{O}_{S, s}) + \text{trdeg}_{R(S)}R(X)
- \text{trdeg}_{\kappa(s)} \kappa(x).
\end{equation}
Moreover, equality holds if $S$ is universally catenary.

\label{lemma-normalization-in-integral}
Let $f : Y \to X$ be an integral morphism.
Then the normalization of $X$ in $Y$ is equal to $Y$.

\label{lemma-normal-normalization}
Let $f : Y \to X$ be a quasi-compact and quasi-separated morphism
of schemes. Let $X'$ be the normalization of $X$ in $Y$. Assume
\begin{enumerate}
\item $Y$ is a normal scheme,
\item quasi-compact opens of $Y$ have finitely many irreducible components.
\end{enumerate}
Then $X'$ is a disjoint union of integral normal schemes. Moreover,
the morphism $Y \to X'$ is dominant and induces a bijection of
irreducible components.

\label{lemma-nagata-normalization-finite}
Let $f : X \to S$ be a morphism. Assume that
\begin{enumerate}
\item $S$ is a Nagata scheme,
\item $f$ is of finite type,
\item $X$ is reduced.
\end{enumerate}
Then the normalization $\nu : S' \to S$ of $S$ in $X$ is finite.

\label{lemma-relative-normalization-normal-codim-1}
Let $f : Y \to X$ be a finite type morphism of schemes with $Y$ reduced
and $X$ Nagata. Let $X'$ be the normalization of $X$ in $Y$.
Let $x' \in X'$ be a point such that
\begin{enumerate}
\item $\dim(\mathcal{O}_{X', x'}) = 1$, and
\item the fibre of $Y \to X'$ over $x'$ is empty.
\end{enumerate}
Then $\mathcal{O}_{X', x'}$ is a discrete valuation ring.

\label{lemma-normalization-birational}
Let $X$ be a reduced scheme with finitely many irreducible components.
Then the normalization morphism $X^\nu \to X$ is birational.

\label{lemma-finite-birational-over-normal}
A finite (or even integral) birational morphism $f : X \to Y$
of integral schemes with $Y$ normal is an isomorphism.

\label{lemma-Japanese-normalization}
Let $X$ be an integral, Japanese scheme.
The normalization $\nu : X^\nu \to X$ is a finite morphism.

\label{lemma-nagata-normalization}
Let $X$ be a Nagata scheme.
The normalization $\nu : X^\nu \to X$ is a finite morphism.

\label{lemma-relative-weak-normalization-algebra}
Let $A \to B$ be a ring map inducing a dominant morphism
$\Spec(B) \to \Spec(A)$ of spectra. There exists an $A$-subalgebra
$B' \subset B$ such that
\begin{enumerate}
\item $\Spec(B') \to \Spec(A)$ is a universal homeomorphism,
\item given a factorization $A \to C \to B$ such that
$\Spec(C) \to \Spec(A)$ is a universal homeomorphism, the
image of $C \to B$ is contained in $B'$.
\end{enumerate}

\label{lemma-relative-weak-normalization-localization}
Let $A \to B$ be a ring map inducing a dominant morphism
$\Spec(B) \to \Spec(A)$ of spectra. Formation of the $A$-subalgebra
$B' \subset B$ in Lemma \ref{lemma-relative-weak-normalization-algebra}
commutes with localization (see proof for explanation).

\label{lemma-relative-seminormalization-localization}
Let $A \to B$ be a ring map inducing a dominant morphism
$\Spec(B) \to \Spec(A)$ of spectra. Formation of the $A$-subalgebra
$B' \subset B$ in Lemma \ref{lemma-relative-seminormalization-algebra}
commutes with localization (see proof for explanation).

\label{definition-weakly-normal}
Let $X$ be a scheme such that every quasi-compact open has
finitely many irreducible components. We say $X$ is {\it weakly normal}
if the weak normalization $X^{wn} \to X$ is an isomorphism
(Definition \ref{definition-weak-normalization}).

\label{lemma-affine-weakly-normal}
Let $X = \Spec(A)$ be an affine scheme which has finitely many
irreducible components. Then $X$ is weakly normal if and only if
\begin{enumerate}
\item $A$ is seminormal (Definition \ref{definition-seminormal-ring}),
\item for a prime number $p$ and $z, w \in A$ such that
(a) $z$ is a nonzerodivisor, (b) $w^p$ is divisible by $z^p$, and
(c) $pw$ is divisible by $z$, then $w$ is divisible by $z$.
\end{enumerate}

\label{lemma-quasi-finite-points-open}
\begin{slogan}
The locally quasi-finite locus of a morphism is open
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The set of points of $X$ where $f$ is quasi-finite is an open
$U \subset X$. The induced morphism $U \to S$ is locally quasi-finite.

\label{lemma-quasi-finite-affine}
Let $f : Y \to X$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $X$ and $Y$ are affine, and
\item $f$ is quasi-finite.
\end{enumerate}
Then there exists a diagram
$$
\xymatrix{
Y \ar[rd]_f \ar[rr]_j & & Z \ar[ld]^\pi \\
& X &
}
$$
with $Z$ affine, $\pi$ finite and $j$ an open immersion.

\label{definition-universally-bounded}
Let $f : X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item We say the integer $n$ {\it bounds the degrees of the fibres
of $f$} if for all $y \in Y$
the fibre $X_y$ is a finite scheme over $\kappa(y)$ whose
degree over $\kappa(y)$ is $\leq n$.
\item We say the {\it fibres of $f$ are universally bounded}\footnote{This is
probably nonstandard notation.}
if there exists an integer $n$ which bounds the degrees of the fibres
of $f$.
\end{enumerate}

\label{lemma-finite-locally-free-universally-bounded}
If $f$ is a finite locally free morphism of degree $d$, then
$d$ bounds the degree of the fibres of $f$.

\label{lemma-locally-quasi-finite-qc-source-universally-bounded}
Let $f : X \to Y$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $f$ is locally quasi-finite, and
\item $X$ is quasi-compact.
\end{enumerate}
Then $f$ has universally bounded fibres.

\label{lemma-finite-type-flat-over-integral-algebra}
Let $A \to B$ be a finite type, flat ring map with $A$ an integral
domain. Then $B$ is a finitely presented $A$-algebra.

\label{lemma-relative-effective-cartier-algebra}
Let $A \to B$ be a ring map. Let $f \in B$. Assume that
\begin{enumerate}
\item $A \to B$ is flat,
\item $f$ is a nonzerodivisor, and
\item $A \to B/fB$ is flat.
\end{enumerate}
Then for every ideal $I \subset A$ the map
$f : B/IB \to B/IB$ is injective.

\label{lemma-faithfully-flat-injective}
If $R \to S$ is a faithfully flat ring map then for every $R$-module
$M$ the map $M \to S \otimes_R M$, $x \mapsto 1 \otimes x$ is injective.

\label{lemma-flat-over-gorenstein-gorenstein-fibre}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
If $A$ and $B/\mathfrak m_A B$ are Gorenstein, then $B$ is Gorenstein.

\label{lemma-combine-one}
In Algebraic and Formal Geometry, Situation
\ref{algebraization-situation-bootstrap}
we have $H^s_\mathfrak a(M) = \lim H^s_\mathfrak a(M/I^nM)$.

\label{lemma-lqf-f-upper-shriek-stalk}
Let $f : X \to Y$ be a morphism of schemes which is locally quasi-finite.
For an abelian group $A$ and a geometric point
$\overline{y} : \Spec(k) \to Y$ we have
$f^!(\overline{y}_*A) = \prod\nolimits_{f(\overline{x}) = \overline{y}}
\overline{x}_*A$.

\label{lemma-trace-map}
\begin{reference}
The proof given here follows the argument given in
\cite[Remark 3.4]{MS}
\end{reference}
Let $f : X' \to X$ be a proper birational morphism of integral Noetherian
schemes with $X$ regular. The map $\mathcal{O}_X \to Rf_*\mathcal{O}_{X'}$
canonically splits in $D(\mathcal{O}_X)$.

\label{lemma-characterize-dbcoh-proper-regular}
Let $X$ be a proper scheme over a field $k$ which is regular. Let
$K \in \Ob(D_\QCoh(\mathcal{O}_X))$. The following are equivalent
\begin{enumerate}
\item $K \in D^b_{\textit{Coh}}(\mathcal{O}_X) = D_{perf}(\mathcal{O}_X)$, and
\item $\sum_{i \in \mathbf{Z}} \dim_k \Ext^i_X(E, K) < \infty$
for all perfect $E$ in $D(\mathcal{O}_X)$.
\end{enumerate}

\label{lemma-quasi-separated-very-reasonable}
An algebraic space which is Zariski locally quasi-separated is very reasonable.
In particular any quasi-separated algebraic space is very reasonable.

\label{lemma-vanishing-surjective}
In Cohomology of Spaces, Situation \ref{spaces-cohomology-situation-vanishing}
the morphism $p : X \to \Spec(A)$ is surjective.

\label{lemma-vanishing-universally-closed}
In Cohomology of Spaces, Situation \ref{spaces-cohomology-situation-vanishing}
the morphism $p : X \to \Spec(A)$ is universally closed.

\label{lemma-category-fibred}
Let $X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item The category $\mathcal{C}_{X/Y}$ is fibred over $X_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over $Y_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over the
category of pairs $(U, V)$ where $U \subset X$, $V \subset Y$ are
open and $f(U) \subset V$.
\end{enumerate}

\label{lemma-equivalence}
Notation and assumptions as above. Let $p : X_A \to X$ denote the projection.
Given $A'$ denote $p' : X_{A'} \to X$ the projection. The functor $p'_*$
induces an equivalence of categories between
\begin{enumerate}
\item the category $\textit{Lift}(\mathcal{F}, A')$, and
\item the category $\textit{Lift}(p_*\mathcal{F}, A')$.
\end{enumerate}

\label{lemma-second-equivalence}
Notation and assumptions as above.
The functor $\pi_!$ induces an equivalence of categories between
\begin{enumerate}
\item the category
$\textit{Lift}_\mathcal{O}(i_*\underline{\mathcal{G}}, A')$, and
\item the category $\textit{Lift}(\mathcal{G}, A')$.
\end{enumerate}

\label{lemma-dualizing-components}
In Semistable Reduction, Situation \ref{models-situation-regular-model}
the dualizing module of $C_i$ over $k$ is
$$
\omega_{C_i} = \omega_X(C_i)|_{C_i}
$$
where $\omega_X$ is as above.

\label{lemma-points-monomorphism}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The map $\{\Spec(k) \to X \text{ monomorphism}\} \to |X|$ is injective.

\label{lemma-locally-ringed-space-direct-summand-free}
Let $X$ be a locally ringed space. A direct summand of a finite free
$\mathcal{O}_X$-module is finite locally free.

\label{lemma-characterize-injective}
Let $R$ be a ring. Let $E$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $E$ is an injective $R$-module, and
\item given an ideal $I \subset R$ and a module map $\varphi : I \to E$
there exists an extension of $\varphi$ to an $R$-module map $R \to E$.
\end{enumerate}

\label{lemma-quasi-coherence-direct-sums}
Let $X$ be a scheme. Then $D_\QCoh(\mathcal{O}_X)$
has direct sums.

\label{lemma-application-nice-K-injective}
Let $X$ be a scheme. Let $F : \textit{Mod}(\mathcal{O}_X) \to \textit{Ab}$
be an additive functor and $N \geq 0$ an integer. Assume that
\begin{enumerate}
\item $F$ commutes with countable direct products,
\item $R^pF(\mathcal{F}) = 0$ for all $p \geq N$ and $\mathcal{F}$
quasi-coherent.
\end{enumerate}
Then for $E \in D_\QCoh(\mathcal{O}_X)$
\begin{enumerate}
\item $H^i(RF(\tau_{\leq a}E)) \to H^i(RF(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(RF(E)) \to H^i(RF(\tau_{\geq b - N + 1}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(RF(E)) = 0$
for $i \not \in [a, b + N - 1]$.
\end{enumerate}

\label{lemma-affine-compare-bounded}
Let $X = \Spec(A)$ be an affine scheme. All the functors in the diagram
$$
\xymatrix{
D(\QCoh(\mathcal{O}_X)) \ar[rr]_{(\ref{equation-compare})}
& &
D_\QCoh(\mathcal{O}_X) \ar[ld]^{R\Gamma(X, -)} \\
& D(A) \ar[lu]^{\widetilde{\ \ }}
}
$$
are equivalences of triangulated categories. Moreover, for $E$ in
$D_\QCoh(\mathcal{O}_X)$ we have $H^0(X, E) = H^0(X, H^0(E))$.

\label{lemma-quasi-coherence-pushforward}
If $f : X \to Y$ is a morphism of affine schemes given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[d] \ar[r] & D_\QCoh(\mathcal{O}_X) \ar[d]^{Rf_*} \\
D(A) \ar[r] & D_\QCoh(\mathcal{O}_Y)
}
$$
commutes.

\label{lemma-quasi-coherence-pullback}
Let $f : Y \to X$ be a morphism of schemes.
\begin{enumerate}
\item The functor $Lf^*$ sends $D_\QCoh(\mathcal{O}_X)$
into $D_\QCoh(\mathcal{O}_Y)$.
\item If $X$ and $Y$ are affine and $f$ is given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[r] & D_\QCoh(\mathcal{O}_Y) \\
D(A) \ar[r] \ar[u]^{- \otimes_A^\mathbf{L} B} &
D_\QCoh(\mathcal{O}_X) \ar[u]_{Lf^*}
}
$$
commutes.
\end{enumerate}

\label{lemma-quasi-coherence-tensor-product}
Let $X$ be a scheme.
\begin{enumerate}
\item For objects $K, L$ of $D_\QCoh(\mathcal{O}_X)$
the derived tensor product $K \otimes^\mathbf{L}_{\mathcal{O}_X} L$ is in
$D_\QCoh(\mathcal{O}_X)$.
\item If $X = \Spec(A)$ is affine then
$$
\widetilde{M^\bullet} \otimes_{\mathcal{O}_X}^\mathbf{L} \widetilde{K^\bullet}
=
\widetilde{M^\bullet \otimes_A^\mathbf{L} K^\bullet}
$$
for any pair of complexes of $A$-modules $K^\bullet$, $M^\bullet$.
\end{enumerate}

\label{lemma-extended-alternating-zero}
With $X$, $f_1, \ldots, f_c \in \Gamma(X, \mathcal{O}_X)$, and
$\mathcal{F}$ as in Remark \ref{remark-support-c-equations}
the complex (\ref{equation-extended-alternating}) restricts to an acyclic
complex over $X \setminus Z$.

\label{lemma-identify-pseudo-coherent-noetherian}
Let $X$ be a Noetherian scheme. Let $E$ be an object of
$D_\QCoh(\mathcal{O}_X)$. For $m \in \mathbf{Z}$ the
following are equivalent
\begin{enumerate}
\item $H^i(E)$ is coherent for $i \geq m$ and zero for $i \gg 0$, and
\item $E$ is $m$-pseudo-coherent.
\end{enumerate}
In particular, $E$ is pseudo-coherent if and only if $E$ is an object
of $D^-_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-tor-dimension-affine}
Let $X = \Spec(A)$ be an affine scheme. Let $M^\bullet$ be a
complex of $A$-modules and let $E$ be the corresponding object
of $D(\mathcal{O}_X)$. Then
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$ if and only if $M^\bullet$
has tor amplitude in $[a, b]$.
\item $E$ has finite tor dimension if and only if $M^\bullet$
has finite tor dimension.
\end{enumerate}

\label{lemma-tor-qc-qs}
Let $X$ be a quasi-separated scheme. Let $E$ be an object
of $D_\QCoh(\mathcal{O}_X)$. Let $a \leq b$. The
following are equivalent
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$, and
\item for all $\mathcal{F}$ in $\QCoh(\mathcal{O}_X)$
we have $H^i(E \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{F}) = 0$
for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-ext-from-perfect-into-bounded-QCoh}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $K$ be a perfect object of $D(\mathcal{O}_X)$. Then
\begin{enumerate}
\item there exist integers $a \leq b$ such that for any
$L \in D_\QCoh(\mathcal{O}_X)$ with $H^i(L) = 0$ for $i \in [a, b]$
we have $\Hom_{D(\mathcal{O}_X)}(K, L) = 0$, and
\item if $L$ is bounded, then $\Ext^n_{D(\mathcal{O}_X)}(K, L)$
is zero for all but finitely many $n$.
\end{enumerate}

\label{lemma-perfect-into-support-on-T}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $f \in \Gamma(X, \mathcal{O}_X)$.
For any morphism $\alpha : E \to E'$ in
$D_\QCoh(\mathcal{O}_X)$ such that
\begin{enumerate}
\item $E$ is perfect, and
\item $E'$ is supported on $T = V(f)$
\end{enumerate}
there exists an $n \geq 0$ such that $f^n \alpha  = 0$.

\label{definition-approximation}
Let $X$ be a scheme. We say {\it approximation by perfect complexes holds}
on $X$ if for any closed subset $T \subset X$ with $X \setminus T$
retro-compact in $X$ there exists an integer $r$ such that
for every triple $(T, E, m)$ as in
Definition \ref{definition-approximation-holds} with
\begin{enumerate}
\item $E$ is $(m - r)$-pseudo-coherent, and
\item $H^i(E)$ is supported on $T$ for $i \geq m - r$
\end{enumerate}
approximation holds.

\label{lemma-approximation-affine}
Let $X$ be an affine scheme. Then approximation holds for every
triple $(T, E, m)$ as in Definition \ref{definition-approximation-holds}
such that there exists an integer $r \geq 0$ with
\begin{enumerate}
\item $E$ is $m$-pseudo-coherent,
\item $H^i(E)$ is supported on $T$ for $i \geq m - r + 1$,
\item $X \setminus T$ is the union of $r$ affine opens.
\end{enumerate}
In particular, approximation by perfect complexes holds for affine schemes.

\label{theorem-approximation}
Let $X$ be a quasi-compact and quasi-separated scheme.
Then approximation by perfect complexes holds on $X$.

\label{lemma-orthogonal-koszul-complex}
\begin{reference}
\cite[Proposition 6.1]{Bokstedt-Neeman}
\end{reference}
In Situation \ref{situation-complex} denote $j : U \to X$ the open
immersion and let $K$ be the perfect object of $D(\mathcal{O}_X)$
corresponding to the Koszul complex on $f_1, \ldots, f_r$ over $A$.
For $E \in D_\QCoh(\mathcal{O}_X)$ the following are equivalent
\begin{enumerate}
\item $E = Rj_*(E|_U)$, and
\item $\Hom_{D(\mathcal{O}_X)}(K[n], E) = 0$ for all $n \in \mathbf{Z}$.
\end{enumerate}

\label{theorem-bondal-van-den-Bergh}
Let $X$ be a quasi-compact and quasi-separated scheme. The category
$D_\QCoh(\mathcal{O}_X)$ can be generated by a single
perfect object. More precisely, there exists a perfect object
$P$ of $D(\mathcal{O}_X)$ such that for 
$E \in D_\QCoh(\mathcal{O}_X)$ the following are equivalent
\begin{enumerate}
\item $E = 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[n], E) = 0$ for all $n \in \mathbf{Z}$.
\end{enumerate}

\label{lemma-generator-with-support}
\begin{reference}
\cite[Theorem 6.8]{Rouquier-dimensions}
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme. Let $T \subset X$ be a
closed subset such that $X \setminus T$ is quasi-compact. With notation
as above, the category $D_{\QCoh, T}(\mathcal{O}_X)$ is generated by a
single perfect object.

\label{lemma-pseudo-coherent-hocolim}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $K \in D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $K$ is pseudo-coherent, and
\item $K = \text{hocolim} K_n$ where
$K_n$ is perfect and $\tau_{\geq -n}K_n \to \tau_{\geq -n}K$
is an isomorphism for all $n$.
\end{enumerate}

\label{lemma-perfect-direct-image}
Let $S$ be a Noetherian scheme. Let $f : X \to S$ be a morphism of schemes
which is locally of finite type. Let $E \in D(\mathcal{O}_X)$ such that
\begin{enumerate}
\item $E \in D^b_{\textit{Coh}}(\mathcal{O}_X)$,
\item the support of $H^i(E)$ is proper over $S$ for all $i$, and
\item $E$ has finite tor dimension as an object of $D(f^{-1}\mathcal{O}_S)$.
\end{enumerate}
Then $Rf_*E$ is a perfect object of $D(\mathcal{O}_S)$.

\label{lemma-locally-closed-where-H0-locally-free}
Let $X$ be a scheme. Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subscheme $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$
if and only if for all morphisms $g : Y' \to Y$ the
$\mathcal{O}_{Y'}$-module $H^a(L(f \circ g)^*E)$ is locally free
of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in X$, then
$j$ is a closed immersion and given $f : Y \to X$ the following
are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^a(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^a(Lf^*E), H^a(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}

\label{lemma-proper-flat-geom-red-connected}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is proper, flat, and of finite presentation, and
\item the geometric fibres of $f$ are reduced and connected.
\end{enumerate}
Then $f_*\mathcal{O}_X = \mathcal{O}_S$ and this holds
after any base change.

\label{lemma-compute-ext-rel-perfect}
Let $f : X \to S$ be a morphism of schemes. Let $E, K \in D(\mathcal{O}_X)$.
Assume
\begin{enumerate}
\item $S$ is quasi-compact and quasi-separated,
\item $f$ is proper, flat, and of finite presentation,
\item $E$ is $S$-perfect,
\item $K$ is pseudo-coherent.
\end{enumerate}
Then there exists a pseudo-coherent $L \in D(\mathcal{O}_S)$ such that
$$
Rf_*R\SheafHom(K, E) = R\SheafHom(L, \mathcal{O}_S)
$$
and the same is true after arbitrary base change: given
$$
\vcenter{
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} &
X \ar[d]^f \\
S' \ar[r]^g &
S
}
}
\quad\quad
\begin{matrix}
\text{cartesian, then we have } \\
Rf'_*R\SheafHom(L(g')^*K, L(g')^*E) \\
= R\SheafHom(Lg^*L, \mathcal{O}_{S'})
\end{matrix}
$$

\label{lemma-bounded-on-fibres}
Let $f : X \to S$ be a morphism of schemes which is flat and
locally of finite presentation. Let $E$ be a pseudo-coherent
object of $D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $E$ is $S$-perfect, and
\item $E$ is locally bounded below and for every point $s \in S$
the object $L(X_s \to X)^*E$ of $D(\mathcal{O}_{X_s})$
is locally bounded below.
\end{enumerate}

\label{definition-resolution-property}
Let $X$ be a scheme. We say $X$ has the {\it resolution property}
if every quasi-coherent $\mathcal{O}_X$-module of finite type
is the quotient of a finite locally free $\mathcal{O}_X$-module.

\label{lemma-resolution-property-ample}
Let $X$ be a scheme. If $X$ has an ample invertible $\mathcal{O}_X$-module,
then $X$ has the resolution property.

\label{lemma-resolution-property-ample-relative}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $Y$ is quasi-compact and quasi-separated and has the resolution property,
\item there exists an $f$-ample invertible module on $X$.
\end{enumerate}
Then $X$ has the resolution property.

\label{lemma-resolution-property-goes-down-finite-flat}
Let $f : X \to Y$ be a surjective finite locally free morphism of schemes.
If $X$ has the resolution property, so does $Y$.

\label{lemma-resolution-property-finite-number}
Let $X$ be a scheme. Suppose given
\begin{enumerate}
\item a finite affine open covering $X = U_1 \cup \ldots \cup U_m$
\item finite type quasi-coherent ideals $\mathcal{I}_j$
with $V(\mathcal{I}_j) = X \setminus U_j$
\end{enumerate}
Then $X$ has the resolution property if and only if $\mathcal{I}_j$
is the quotient of a finite locally free $\mathcal{O}_X$-module
for $j = 1, \ldots, m$.

\label{lemma-regular-resolution-property}
Let $X$ be a quasi-compact, regular scheme with affine diagonal.
Then $X$ has the resolution property.

\label{lemma-resolution-property-affine-diagonal}
\begin{reference}
Special case of \cite[Proposition 1.3]{totaro_resolution}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme with
the resolution property. Then $X$ has affine diagonal.

\label{lemma-K-agrees-affine}
Let $X = \Spec(R)$ be an affine scheme. Then $K_0(X) = K_0(R)$
and if $R$ is Noetherian then $K'_0(X) = K'_0(R)$.

\label{lemma-Kprime-K}
Let $X$ be a Noetherian regular scheme. Then
the map $K_0(X) \to K'_0(X)$ is an isomorphism.

\label{lemma-determinant-two-term-complexes}
Let $X$ be a scheme. There is a functor
$$
\det :
\left\{
\begin{matrix}
\text{category of perfect complexes} \\
\text{with tor amplitude in }[-1, 0] \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of invertible modules} \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
$$
In addition, given a rank $0$ perfect object $L$ of $D(\mathcal{O}_X)$ with
tor-amplitude in $[-1, 0]$ there is a canonical element
$\delta(L) \in \Gamma(X, \det(L))$ such that for any isomorphism
$a : L \to K$ in $D(\mathcal{O}_X)$ we have $\det(a)(\delta(L)) = \delta(K)$.
Moreover, the construction is affine locally given by the construction
of More on Algebra, Section \ref{more-algebra-section-determinants-complexes}.

\label{lemma-bounded-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$. 
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \gg 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\geq a} E) = 0$ for $i \gg 0$.
\end{enumerate}

\label{lemma-bounded-below-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme. Let
$P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \ll 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\leq a} E) = 0$ for $i \ll 0$.
\end{enumerate}

\label{lemma-DQCoh-alternative-small}
In the situation above there are canonical exact equivalences between
the following triangulated categories
\begin{enumerate}
\item $D_\QCoh(\mathcal{O}_X)$,
\item $D_\QCoh(X_{Zar}, \mathcal{O})$,
\item $D_\QCoh(X_{affine, Zar}, \mathcal{O})$,
\item $D_\QCoh(X_{affine}, \mathcal{O}_X)$, and
\item $\mathit{QC}(X_{affine}, \mathcal{O})$.
\end{enumerate}

\label{lemma-hilb-d-An}
Let $X \to S$ be a morphism of affine schemes. Let $d \geq 0$. Then
$\Hilbfunctor^d_{X/S}$ is representable.

\label{proposition-hilb-d}
Let $X$ be a geometrically irreducible smooth proper curve over a field $k$.
\begin{enumerate}
\item The functors $\Hilbfunctor^d_{X/k}$ are representable by smooth
proper varieties $\underline{\Hilbfunctor}^d_{X/k}$ of dimension
$d$ over $k$.
\item For a field extension $k'/k$ the $k'$-rational points
of $\underline{\Hilbfunctor}^d_{X/k}$ are in $1$-to-$1$ bijection
with effective Cartier divisors of degree $d$ on $X_{k'}$.
\item For $d_1, d_2 \geq 0$ there is a morphism
$$
\underline{\Hilbfunctor}^{d_1}_{X/k}
\times_k
\underline{\Hilbfunctor}^{d_2}_{X/k}
\longrightarrow
\underline{\Hilbfunctor}^{d_1 + d_2}_{X/k}
$$
which is finite locally free of degree ${d_1 + d_2 \choose d_1}$.
\end{enumerate}

\label{lemma-criterion}
Let $k$ be a field. Let $G : (\Sch/k)^{opp} \to \textit{Groups}$ be a
functor. With terminology as in
Schemes, Definition \ref{schemes-definition-representable-by-open-immersions},
assume that
\begin{enumerate}
\item $G$ satisfies the sheaf property for the Zariski topology,
\item there exists a subfunctor $F \subset G$ such that
\begin{enumerate}
\item $F$ is representable,
\item $F \subset G$ is representable by open immersion,
\item for every field extension $K$ of $k$ and $g \in G(K)$
there exists a $g' \in G(k)$ such that $g'g \in F(K)$.
\end{enumerate}
\end{enumerate}
Then $G$ is representable by a group scheme over $k$.

\label{lemma-check-conditions}
Let $k$ be a field. Let $X$ be a smooth projective curve over $k$
which has a $k$-rational point. Then the hypotheses of
Lemma \ref{lemma-flat-geometrically-connected-fibres-with-section}
are satisfied.

\label{definition-genus}
Let $k$ be a field. Let $X$ be a smooth projective geometrically irreducible
curve over $k$. The {\it genus} of $X$ is $g = \dim_k H^1(X, \mathcal{O}_X)$.

\label{proposition-pic-curve}
Let $k$ be a separably closed field. Let $X$ be a smooth projective
curve over $k$. The Picard functor $\Picardfunctor_{X/k}$ is representable.

\label{lemma-galois}
Let $(\mathcal{C}, F)$ be a Galois category. For any connected object $X$
of $\mathcal{C}$ there exists a Galois object $Y$ and a morphism $Y \to X$.

\label{lemma-tame}
\begin{reference}
Compare with \cite[Definition 7.2.4]{BS}.
\end{reference}
Let $(\mathcal{C}, F)$ be a Galois category. Let $G = \text{Aut}(F)$
be as in Example \ref{example-from-C-F-to-G-sets}. For any connected
$X$ in $\mathcal{C}$ the action of $G$ on $F(X)$ is transitive.

\label{proposition-galois}
\begin{reference}
This is a weak version of \cite[Expos\'e V]{SGA1}.
The proof is borrowed from \cite[Theorem 7.2.5]{BS}.
\end{reference}
Let $(\mathcal{C}, F)$ be a Galois category. Let $G = \text{Aut}(F)$
be as in Example \ref{example-from-C-F-to-G-sets}. The functor
$F : \mathcal{C} \to \textit{Finite-}G\textit{-Sets}$
(\ref{equation-remember}) an equivalence.

\label{lemma-composition-trivial}
In diagram (\ref{equation-translation}) the following are equivalent
\begin{enumerate}
\item $h \circ h'$ is trivial, and
\item the image of $H' \circ H$ consists of objects isomorphic to finite
coproducts of final objects.
\end{enumerate}

\label{lemma-functoriality-galois-normal}
In diagram (\ref{equation-translation}) the following are equivalent
\begin{enumerate}
\item the image of $h'$ is normal, and
\item for every connected object $X'$ of $\mathcal{C}'$ such that
there is a morphism from the final object of $\mathcal{C}''$
to $H'(X')$ we have that $H'(X')$ is isomorphic to a finite coproduct
of final objects.
\end{enumerate}

\label{lemma-what-equivalence-gives}
Let $f : X \to Y$ be a morphism of quasi-compact and quasi-separated schemes
such that the base change functor $\textit{F\'Et}_Y \to \textit{F\'Et}_X$
is an equivalence of categories. In this case
\begin{enumerate}
\item $f$ induces a homeomorphism $\pi_0(X) \to \pi_0(Y)$,
\item if $X$ or equivalently $Y$ is connected, then
$\pi_1(X, \overline{x}) = \pi_1(Y, \overline{y})$.
\end{enumerate}

\label{lemma-quasi-compact-dense-open-connected-at-infinity-Noetherian}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item the underlying topological space of $X$ is Noetherian, and
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-retrocompact-dense-open-connected-at-infinity-closed}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item $U \to X$ is quasi-compact,
\item every point of $X \setminus U$ is closed, and
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-quasi-compact-dense-open-connected-at-infinity}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item every quasi-compact open of $X$ has finitely many
irreducible components,
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-unramified-in-L}
In the situation above the following are equivalent
\begin{enumerate}
\item $X$ is unramified in $L$,
\item $Y \to X$ is \'etale, and
\item $Y \to X$ is finite \'etale.
\end{enumerate}

\label{lemma-normal-local-domain-separablly-closed-fraction-field}
A normal local ring with separably closed fraction field is
strictly henselian.

\label{lemma-inertia-base-change}
Let $G$ be a finite group acting on a ring $R$. Let $R^G \to A$ be a ring
map. Let $\mathfrak q' \subset A \otimes_{R^G} R$ be a prime lying
over the prime $\mathfrak q \subset R$. Then
$$
I_\mathfrak q = \{\sigma \in G \mid
\sigma(\mathfrak q) = \mathfrak q\text{ and }
\sigma \bmod \mathfrak q = \text{id}_{\kappa(\mathfrak q)}\}
$$
is equal to
$$
I_{\mathfrak q'} = \{\sigma \in G \mid
\sigma(\mathfrak q') = \mathfrak q'\text{ and }
\sigma \bmod \mathfrak q' = \text{id}_{\kappa(\mathfrak q')}\}
$$

\label{lemma-stein-factorization-etale}
\begin{reference}
\cite[Expose X, Proposition 1.2, p. 262]{SGA1}.
\end{reference}
Let $f : X \to S$ be a proper morphism of schemes.
Let $X \to S' \to S$ be the Stein factorization of $f$, see
More on Morphisms, Theorem
\ref{more-morphisms-theorem-stein-factorization-general}.
If $f$ is of finite presentation, flat, with geometrically
reduced fibres, then $S' \to S$ is finite \'etale.

\label{lemma-pushout-along-closed-immersion-and-integral}
In More on Morphisms, Situation
\ref{more-morphisms-situation-pushout-along-closed-immersion-and-integral},
for example if $Z \to Y$ and $Z \to X$ are closed immersions of schemes,
there is an equivalence of categories
$$
\textit{F\'Et}_{Y \amalg_Z X}
\longrightarrow
\textit{F\'Et}_Y
\times_{\textit{F\'Et}_Z}
\textit{F\'Et}_X
$$

\label{lemma-fully-faithful-minimal}
\begin{reference}
\cite[Corollary 1.11]{Bhatt-local}
\end{reference}
In Situation \ref{situation-local-lefschetz}. Assume
\begin{enumerate}
\item $H^1_\mathfrak m(A)$ and $H^2_\mathfrak m(A)$ are
annihilated by a power of $f$, and
\item $A$ is henselian or more generally $(A, (f))$ is a henselian pair.
\end{enumerate}
Then the restriction functor
$\textit{F\'Et}_U \longrightarrow \textit{F\'Et}_{U_0}$
is fully faithful.

\label{lemma-reformulate-purity}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Set $X = \Spec(A)$
and let $U = X \setminus \{\mathfrak m\}$.
Let $V$ be finite \'etale
over $U$. Assume $A$ has depth $\geq 2$. The following are equivalent
\begin{enumerate}
\item $V = Y \times_X U$ for some $Y \to X$ finite \'etale,
\item $B = \Gamma(V, \mathcal{O}_V)$ is finite \'etale over $A$.
\end{enumerate}

\label{lemma-lift-purity-general}
In Situation \ref{situation-local-lefschetz}.
Let $V$ be finite \'etale over $U$. Assume
\begin{enumerate}
\item $H^1_\mathfrak m(A)$ and $H^2_\mathfrak m(A)$
are annihilated by a power of $f$,
\item $V_0 = V \times_U U_0$ is equal to $Y_0 \times_{X_0} U_0$
for some $Y_0 \to X_0$ finite \'etale.
\end{enumerate}
Then $V = Y \times_X U$ for some $Y \to X$ finite \'etale.

\label{lemma-lift-purity}
In Situation \ref{situation-local-lefschetz}.
Let $V$ be finite \'etale over $U$. Assume
\begin{enumerate}
\item $A$ has depth $\geq 3$,
\item $V_0 = V \times_U U_0$ is equal to $Y_0 \times_{X_0} U_0$
for some $Y_0 \to X_0$ finite \'etale.
\end{enumerate}
Then $V = Y \times_X U$ for some $Y \to X$ finite \'etale.

\label{lemma-local-purity}
Let $(A, \mathfrak m)$ be a regular local ring of dimension $d \geq 2$.
Set $X = \Spec(A)$ and $U = X \setminus \{\mathfrak m\}$. Then
\begin{enumerate}
\item the functor $\textit{F\'Et}_X \to \textit{F\'Et}_U$
is essentially surjective, i.e., purity holds for $A$,
\item any finite $A \to B$ with $B$ normal which
induces a finite \'etale morphism on punctured spectra is \'etale.
\end{enumerate}

\label{lemma-fully-faithful-general-better}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ has a dualizing complex and is $f$-adically complete,
\item every irreducible component of $X$ not contained in $X_0$
has dimension $\geq 3$.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is fully faithful.

\label{lemma-fully-faithful-general}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ is $f$-adically complete,
\item $f$ is a nonzerodivisor.
\item $H^1_\mathfrak m(A/fA)$ is a finite $A$-module.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is fully faithful.

\label{lemma-essentially-surjective-general-better}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ has a dualizing complex and is $f$-adically complete,
\item one of the following is true
\begin{enumerate}
\item $A_f$ is $(S_2)$ and every irreducible component of $X$
not contained in $X_0$ has dimension $\geq 4$, or
\item if $\mathfrak p \not \in V(f)$ and
$V(\mathfrak p) \cap V(f) \not = \{\mathfrak m\}$, then
$\text{depth}(A_\mathfrak p) + \dim(A/\mathfrak p) > 3$.
\end{enumerate}
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is an equivalence.

\label{lemma-essentially-surjective-general}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ is $f$-adically complete,
\item $f$ is a nonzerodivisor,
\item $H^1_\mathfrak m(A/fA)$ and $H^2_\mathfrak m(A/fA)$
are finite $A$-modules.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is an equivalence.

\label{lemma-key-purity-ramification}
Let $f : X \to \Spec(A)$ be a finite type morphism.
Let $x \in X$ be a point. Assume
\begin{enumerate}
\item $A$ is an excellent regular local ring,
\item $\mathcal{O}_{X, x}$ is normal of dimension $2$,
\item $f$ is \'etale outside of $\overline{\{x\}}$.
\end{enumerate}
Then $f$ is \'etale at $x$.

[Purity of ramification locus]
\label{lemma-purity-ramification}
\begin{reference}
This result for complex spaces can be found on page 170 of \cite{Fischer}.
In general this is \cite[Theorem 2.4]{Zong} attributed to Gabber.
\end{reference}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes.
Let $x \in X$ and set $y = f(x)$. Assume
\begin{enumerate}
\item $\mathcal{O}_{X, x}$ is normal of dimension $\geq 1$,
\item $\mathcal{O}_{Y, y}$ is regular,
\item $f$ is locally of finite type, and
\item for specializations $x' \leadsto x$ with
$\dim(\mathcal{O}_{X, x'}) = 1$ our $f$ is \'etale at $x'$.
\end{enumerate}
Then $f$ is \'etale at $x$.

\label{lemma-conclude}
In the situation of Lemma \ref{lemma-structure-cohomology}
assume that $H^i(V, \mathcal{O}_V) = 0$ for $i \geq \dim(A) - 1$.
Then $V$ is affine.

\label{lemma-purity-one-divisor-general}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be open and dense.
Let $Y \to U$ be a finite \'etale morphism. Assume
\begin{enumerate}
\item $Y$ is unramified over $X$ in codimension $1$, and
\item $\mathcal{O}_{X, x}$ is regular for all $x \in X \setminus U$.
\end{enumerate}
Then there exists a finite \'etale morphism $Y' \to X$
whose restriction to $U$ is $Y$.

\label{definition-w-local}
A spectral space $X$ is {\it w-local} if the set of closed points $X_0$
is closed and every point of $X$ specializes to a unique closed point.
A continuous map $f : X \to Y$ of w-local spaces is {\it w-local}
if it is spectral and maps any closed point of $X$ to a closed point of $Y$.

\label{lemma-closed-subspace-w-local}
Let $X$ be a w-local spectral space. If $Y \subset X$ is closed,
then $Y$ is w-local.

\label{definition-local-isomorphism}
Let $\varphi : A \to B$ be a ring map.
\begin{enumerate}
\item We say $A \to B$ is a {\it local isomorphism} if for every prime
$\mathfrak q \subset B$ there exists a $g \in B$, $g \not \in \mathfrak q$
such that $A \to B_g$ induces an open immersion $\Spec(B_g) \to \Spec(A)$.
\item We say $A \to B$ {\it identifies local rings} if for every prime
$\mathfrak q \subset B$ the canonical map
$A_{\varphi^{-1}(\mathfrak q)} \to B_\mathfrak q$ is an isomorphism.
\end{enumerate}

\label{lemma-base-change-local-isomorphism}
Let $A \to B$ and $A \to A'$ be ring maps. Let $B' = B \otimes_A A'$
be the base change of $B$.
\begin{enumerate}
\item If $A \to B$ is a local isomorphism, then $A' \to B'$ is a
local isomorphism.
\item If $A \to B$ identifies local rings, then $A' \to B'$
identifies local rings.
\end{enumerate}

\label{lemma-composition-local-isomorphism}
Let $A \to B$ and $B \to C$ be ring maps.
\begin{enumerate}
\item If $A \to B$ and $B \to C$ are local isomorphisms, then $A \to C$
is a local isomorphism.
\item If $A \to B$ and $B \to C$ identify local rings, then $A \to C$
identifies local rings.
\end{enumerate}

\label{lemma-local-isomorphism-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra homomorphism.
\begin{enumerate}
\item If $A \to B$ and $A \to C$ are local isomorphisms, then $B \to C$
is a local isomorphism.
\item If $A \to B$ and $A \to C$ identify local rings, then $B \to C$
identifies local rings.
\end{enumerate}

\label{lemma-local-isomorphism-implies}
Let $A \to B$ be a local isomorphism. Then
\begin{enumerate}
\item $A \to B$ is \'etale,
\item $A \to B$ identifies local rings,
\item $A \to B$ is quasi-finite.
\end{enumerate}

\label{lemma-composition-ind-zariski}
Let $A \to B$ and $B \to C$ be ring maps. If $A \to B$ and $B \to C$
are ind-Zariski, then $A \to C$ is ind-Zariski.

\label{lemma-w-local-algebraic-residue-field-extensions}
Let $A$ be a ring such that $X = \Spec(A)$ is w-local. Let $I \subset A$
be the radical ideal cutting out the set $X_0$ of closed points in $X$.
Let $A \to B$ be a ring map inducing algebraic extensions on residue
fields at primes. Then
\begin{enumerate}
\item every point of $Z = V(IB)$ is a closed point of $\Spec(B)$,
\item there exists an ind-Zariski ring map $B \to C$ such that
\begin{enumerate}
\item $B/IB \to C/IC$ is an isomorphism,
\item the space $Y = \Spec(C)$ is w-local,
\item the induced map $p : Y \to X$ is w-local, and
\item $p^{-1}(X_0)$ is the set of closed points of $Y$.
\end{enumerate}
\end{enumerate}

\label{lemma-w-local-morphism-equal-points-stalks-is-iso}
Let $A \to B$ be ring map such that
\begin{enumerate}
\item $A \to B$ identifies local rings,
\item the topological spaces $\Spec(B)$, $\Spec(A)$ are w-local,
\item $\Spec(B) \to \Spec(A)$ is w-local, and
\item $\pi_0(\Spec(B)) \to \pi_0(\Spec(A))$ is bijective.
\end{enumerate}
Then $A \to B$ is an isomorphism

\label{lemma-w-local-morphism-equal-stalks-is-ind-zariski}
Let $A \to B$ be ring map such that
\begin{enumerate}
\item $A \to B$ identifies local rings,
\item the topological spaces $\Spec(B)$, $\Spec(A)$ are w-local, and
\item $\Spec(B) \to \Spec(A)$ is w-local.
\end{enumerate}
Then $A \to B$ is ind-Zariski.

\label{lemma-w-local-extremally-disconnected}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item every faithfully flat ring map $A \to B$ identifying local rings
has a retraction,
\item every faithfully flat ind-Zariski ring map $A \to B$ has a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local, and
\item $\pi_0(\Spec(A))$ is extremally disconnected.
\end{enumerate}
\end{enumerate}

\label{definition-ind-etale}
A ring map $A \to B$ is said to be {\it ind-\'etale} if $B$ can be written
as a filtered colimit of \'etale $A$-algebras.

\label{lemma-composition-ind-etale}
Let $A \to B$ and $B \to C$ be ring maps. If $A \to B$ and $B \to C$
are ind-\'etale, then $A \to C$ is ind-\'etale.

\label{lemma-ind-etale-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra map of ind-\'etale
$A$-algebras. Then $C$ is an ind-\'etale $B$-algebra.

\label{lemma-ind-etale-implies}
Let $A \to B$ be ind-\'etale. Then $A \to B$ is weakly \'etale
(More on Algebra, Definition \ref{more-algebra-definition-weakly-etale}).

\label{lemma-first-construction}
Given a ring $A$ there exists a faithfully flat ind-\'etale $A$-algebra $C$
such that every faithfully flat \'etale ring map $C \to B$ has a retraction.

\label{lemma-pro-V-V}
Let $Y$ be an affine scheme. Let $X = \lim X_i$ be a directed limit
of affine schemes over $Y$. The following are equivalent
\begin{enumerate}
\item $\{X \to Y\}$ is a standard V covering
(Topologies, Definition \ref{topologies-definition-standard-V-covering}), and
\item $\{X_i \to Y\}$ is a standard V covering for all $i$.
\end{enumerate}

\label{lemma-pro-h-V}
Let $X \to Y$ be a morphism of affine schemes. The following are equivalent
\begin{enumerate}
\item $\{X \to Y\}$ is a standard V covering
(Topologies, Definition \ref{topologies-definition-standard-V-covering}),
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is a ph covering for each $i$, and
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is an h covering for each $i$.
\end{enumerate}

\label{lemma-h-limit-preserving}
Let $S$ be a scheme. Let $F$ be a contravariant functor defined
on the category of all schemes over $S$. If
\begin{enumerate}
\item $F$ satisfies the sheaf property for the h topology, and
\item $F$ is limit preserving
(Limits, Remark \ref{limits-remark-limit-preserving}),
\end{enumerate}
then $F$ satisfies the sheaf property for the V topology.

\label{definition-w-contractible}
Let $A$ be a ring. We say $A$ is {\it w-contractible} if every
faithfully flat weakly \'etale ring map $A \to B$ has a retraction.

\label{lemma-w-local-strictly-henselian-extremally-disconnected}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible,
\item every faithfully flat, ind-\'etale ring map $A \to B$ has
a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local,
\item $\pi_0(\Spec(A))$ is extremally disconnected, and
\item for every maximal ideal $\mathfrak m \subset A$ the
local ring $A_\mathfrak m$ is strictly henselian.
\end{enumerate}
\end{enumerate}

\label{proposition-find-w-contractible}
For every ring $A$ there exists a faithfully flat, ind-\'etale ring
map $A \to D$ such that $D$ is w-contractible.

\label{lemma-finite-finitely-presented-over-w-contractible}
Let $A \to B$ be a finite and finitely presented ring map.
If $A$ is w-contractible, so is $B$.

\label{definition-standard-proetale}
Let $T$ be an affine scheme. A {\it standard pro-\'etale covering}
of $T$ is a family $\{f_i : T_i \to T\}_{i = 1, \ldots, n}$
where each $T_j$ is affine, each $f_i$ is weakly \'etale, and
$T = \bigcup f_i(T_i)$.

\label{lemma-verify-site-proetale}
Let $S$ be a scheme. Let $\Sch_\proetale$ be a big pro-\'etale site
containing $S$. Both $S_\proetale$ and $(\textit{Aff}/S)_\proetale$ are sites.

\label{lemma-w-contractible-proetale-cover}
Let $T = \Spec(A)$ be an affine scheme. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible, and
\item every pro-\'etale covering of $T$ can be refined by
a Zariski covering of the form $T = \coprod_{i = 1, \ldots, n} U_i$.
\end{enumerate}

\label{lemma-enough-compact-proetale}
Let $S$ be a scheme. Let $\Lambda$ be a ring.
\begin{enumerate}
\item $D(S_\proetale)$ is compactly generated,
\item $D(S_\proetale, \Lambda)$ is compactly generated,
\item $D(S_\proetale, \mathcal{A})$ is compactly generated
for any sheaf of rings $\mathcal{A}$ on $S_\proetale$,
\item $D((\Sch/S)_\proetale)$ is compactly generated,
\item $D((\Sch/S)_\proetale, \Lambda)$ is compactly generated, and
\item $D((\Sch/S)_\proetale, \mathcal{A})$ is compactly generated
for any sheaf of rings $\mathcal{A}$ on $(\Sch/S)_\proetale$,
\end{enumerate}

\label{lemma-compare-injectives}
Let $S$ be a scheme. Let $T$ be an object of $(\Sch/S)_\proetale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}|_{S_\proetale}$ is injective in $\textit{Ab}(S_\proetale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}^\bullet|_{S_\proetale}$ is a K-injective complex in
$\textit{Ab}(S_\proetale)$,
\end{enumerate}
\end{enumerate}

\label{lemma-relative-comparison}
Let $X$ be a scheme.
\begin{enumerate}
\item For an abelian sheaf $\mathcal{F}$ on $X_\etale$
we have $R\epsilon_*(\epsilon^{-1}\mathcal{F}) = \mathcal{F}$.
\item For $K \in D^+(X_\etale)$ the map $K \to R\epsilon_*\epsilon^{-1}K$
is an isomorphism.
\end{enumerate}

\label{lemma-compare-locally-constant}
Let $X$ be a scheme. Let $\Lambda$ be a ring.
The functor $\epsilon^{-1}$ defines an equivalence of categories
$$
\left\{
\begin{matrix}
\text{locally constant sheaves}\\
\text{of }\Lambda\text{-modules on }X_\etale\\
\text{of finite presentation}
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{locally constant sheaves}\\
\text{of }\Lambda\text{-modules on }X_\proetale\\
\text{of finite presentation}
\end{matrix}
\right\}
$$

\label{lemma-closed-immersion}
Let $i : Z \to X$ be a closed immersion of schemes. Then
\begin{enumerate}
\item $i_\proetale^{-1}$ commutes with limits,
\item $i_{\proetale, *}$ is fully faithful, and
\item $i_\proetale^{-1}i_{\proetale, *} \cong \text{id}_{\Sh(Z_\proetale)}$.
\end{enumerate}

\label{lemma-compute-i-star}
Let $i : Z \to X$ be a closed immersion of schemes.
Let $U \to X$ be an object of $X_\proetale$ such that
\begin{enumerate}
\item $U$ is affine and weakly contractible, and
\item every point of $U$ specializes to a point of $U \times_X Z$.
\end{enumerate}
Then $i_\proetale^{-1}\mathcal{F}(U \times_X Z) = \mathcal{F}(U)$
for all abelian sheaves on $X_\proetale$.

\label{lemma-compare-constructible}
Let $X$ be a scheme. Let $\Lambda$ be a Noetherian ring.
The functor $\epsilon^{-1}$ defines an equivalence of categories
$$
\left\{
\begin{matrix}
\text{constructible sheaves of}\\
\Lambda\text{-modules on }X_\etale\\
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{constructible sheaves of}\\
\Lambda\text{-modules on }X_\proetale\\
\end{matrix}
\right\}
$$
between constructible sheaves of $\Lambda$-modules on $X_\etale$
and constructible sheaves of $\Lambda$-modules on $X_\proetale$.

\label{lemma-generic-point-in-constructible}
Let $X$ be a scheme and let $E \subset X$ be a locally constructible subset.
Let $\xi \in X$ be a generic point of an irreducible component of $X$.
\begin{enumerate}
\item If $\xi \in E$, then an open neighbourhood of
$\xi$ is contained in $E$.
\item If $\xi \not \in E$, then an open neighbourhood
of $\xi$ is disjoint from $E$.
\end{enumerate}

\label{lemma-quasi-compact-quasi-separated-spectral}
Let $X$ be a quasi-compact and quasi-separated scheme.
Then the underlying topological space of $X$ is a spectral space.

\label{lemma-constructible-quasi-compact-quasi-separated}
Let $X$ be a quasi-compact and quasi-separated scheme.
Any locally constructible subset of $X$ is constructible.

\label{lemma-retrocompact}
Let $X$ be a scheme. A subset $E$ of $X$ is retrocompact in $X$ if and only if
$E \cap U$ is quasi-compact for every affine open $U$ of $X$.

\label{definition-property-local}
Let $P$ be a property of rings.
We say that $P$ is {\it local} if the following hold:
\begin{enumerate}
\item For any ring $R$, and any $f \in R$ we have
$P(R) \Rightarrow P(R_f)$.
\item For any ring $R$, and $f_i \in R$ such that
$(f_1, \ldots, f_n) = R$ then
$\forall i, P(R_{f_i}) \Rightarrow P(R)$.
\end{enumerate}

\label{lemma-reduced-is-locally-reduced}
Let $X$ be a scheme. Then $X$ is reduced if and only if $X$ is
``locally reduced'' in the sense of Definition \ref{definition-locally-P}.

\label{definition-noetherian}
Let $X$ be a scheme.
\begin{enumerate}
\item We say $X$ is {\it locally Noetherian} if every
$x \in X$ has an affine open neighbourhood
$\Spec(R) = U \subset X$ such that the ring $R$ is Noetherian.
\item We say $X$ is {\it Noetherian} if $X$ is locally Noetherian
and quasi-compact.
\end{enumerate}

\label{lemma-locally-closed-in-Noetherian}
Any locally closed subscheme of a (locally) Noetherian
scheme is (locally) Noetherian.

\label{lemma-morphism-Noetherian-schemes-quasi-compact}
Any morphism of schemes $f : X \to Y$ with $X$ Noetherian
is quasi-compact.

\label{lemma-countable-dense-subset}
Let $S$ be a Noetherian scheme. Let $T \subset S$ be an infinite dense subset.
Then there exist a countable subset $E \subset T$ which is dense in $S$.

\label{definition-jacobson}
A scheme $S$ is said to be {\it Jacobson} if its underlying topological
space is Jacobson.

\label{lemma-affine-jacobson}
An affine scheme $\Spec(R)$ is Jacobson if and only if
the ring $R$ is Jacobson.

\label{definition-normal}
A scheme $X$ is {\it normal} if and only if for all $x \in X$ the local ring
$\mathcal{O}_{X, x}$ is a normal domain.

\label{lemma-normal-locally-finite-nr-irreducibles}
Let $X$ be a scheme such that any quasi-compact open has a finite number
of irreducible components. The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of normal integral schemes.
\end{enumerate}

\label{lemma-normal-Noetherian}
Let $X$ be a Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a finite disjoint union of normal integral schemes.
\end{enumerate}

\label{lemma-normal-locally-Noetherian}
Let $X$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of integral normal schemes.
\end{enumerate}

\label{lemma-normal-integral-sections}
\begin{slogan}
The ring of functions on a normal scheme is normal.
\end{slogan}
Let $X$ be an integral normal scheme.
Then $\Gamma(X, \mathcal{O}_X)$ is a normal domain.

\label{lemma-characterize-Cohen-Macaulay}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is Cohen-Macaulay,
\item $X$ is locally Noetherian and all of its local rings are Cohen-Macaulay,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is Cohen-Macaulay.
\end{enumerate}

\label{lemma-characterize-regular}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is regular,
\item $X$ is locally Noetherian and all of its local rings are regular,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is regular.
\end{enumerate}

\label{lemma-dimension}
Let $X$ be a scheme. The following are equal
\begin{enumerate}
\item The dimension of $X$.
\item The supremum of the dimensions of the local rings of $X$.
\item The supremum of $\dim_x(X)$ for $x \in X$.
\end{enumerate}

\label{lemma-generic-point}
Let $X$ be a scheme. Let $x \in X$. Then $x$ is a generic point of
an irreducible component of $X$ if and only if $\dim(\mathcal{O}_{X, x}) = 0$.

\label{lemma-locally-Noetherian-dimension-0}
A locally Noetherian scheme of dimension $0$ is a disjoint
union of spectra of Artinian local rings.

\label{lemma-dimension-zero}
\begin{reference}
Email from Ofer Gabber dated June 4, 2016
\end{reference}
Let $X$ be a scheme of dimension zero. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-separated,
\item $X$ is separated,
\item $X$ is Hausdorff,
\item every affine open is closed.
\end{enumerate}
In this case the connected components of $X$ are points and every
quasi-compact open of $X$ is affine. In particular, if $X$
is quasi-compact, then $X$ is affine.

\label{lemma-isolated-dim-0-locally-noetherian}
Let $x$ be a point of a locally Noetherian scheme $X$.
Then $\dim_x(X) = 0$ if and only if $x$ is an isolated point of $X$.

\label{definition-catenary}
Let $S$ be a scheme. We say $S$ is {\it catenary} if the
underlying topological space of $S$ is catenary.

\label{lemma-catenary-dimension-function}
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is catenary, and
\item locally in the Zariski topology there exists a dimension function
on $S$ (see Topology, Definition \ref{topology-definition-dimension-function}).
\end{enumerate}

\label{lemma-catenary-local-rings-catenary}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is catenary, and
\item for any $x \in X$ the local ring $\mathcal{O}_{X, x}$ is
catenary.
\end{enumerate}

\label{lemma-scheme-regular-iff-all-Rk}
Let $X$ be a locally Noetherian scheme.
Then $X$ is regular if and only if $X$ has $(R_k)$ for all $k \geq 0$.

\label{lemma-scheme-CM-iff-all-Sk}
Let $X$ be a locally Noetherian scheme.
Then $X$ is Cohen-Macaulay if and only if $X$ has $(S_k)$ for all $k \geq 0$.

\label{lemma-criterion-reduced}
Let $X$ be a locally Noetherian scheme.
Then $X$ is reduced if and only if $X$ has properties $(S_1)$ and $(R_0)$.

\label{lemma-criterion-normal}
Let $X$ be a locally Noetherian scheme.
Then $X$ is normal if and only if $X$ has properties $(S_2)$ and $(R_1)$.

\label{lemma-normal-dimension-1-regular}
Let $X$ be a locally Noetherian scheme which is normal and
has dimension $\leq 1$. Then $X$ is regular.

\label{lemma-normal-dimension-2-Cohen-Macaulay}
Let $X$ be a locally Noetherian scheme which is normal and
has dimension $\leq 2$. Then $X$ is Cohen-Macaulay.

\label{lemma-nagata-universally-Japanese}
Let $X$ be a scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is Nagata, and
\item $X$ is locally Noetherian and universally Japanese.
\end{enumerate}

\label{lemma-characterize-G-scheme}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is a G-scheme,
\item $X$ is locally Noetherian and for all $x \in X$ the ring
map $\mathcal{O}_{X, x} \to \mathcal{O}_{X, x}^\wedge$ is regular, and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the ring map $\mathcal{O}_{X, x} \to \mathcal{O}_{X, x}^\wedge$ is regular.
\end{enumerate}

\label{definition-singular-locus}
Let $X$ be a locally Noetherian scheme. The {\it regular locus}
$\text{Reg}(X)$ of $X$ is the set of $x \in X$ such that $\mathcal{O}_{X, x}$
is a regular local ring. The {\it singular locus} $\text{Sing}(X)$ is the
complement $X \setminus \text{Reg}(X)$, i.e., the set of points $x \in X$
such that $\mathcal{O}_{X, x}$ is not a regular local ring.

\label{definition-unibranch}
\begin{reference}
\cite[Chapter IV (6.15.1)]{EGA4}
\end{reference}
Let $X$ be a scheme. Let $x \in X$. We say $X$ is {\it unibranch at $x$}
if the local ring $\mathcal{O}_{X, x}$ is unibranch. We say $X$ is
{\it geometrically unibranch at $x$}
if the local ring $\mathcal{O}_{X, x}$ is geometrically unibranch.
We say $X$ is {\it unibranch} if $X$ is unibranch at all of its points.
We say $X$ is {\it geometrically unibranch} if $X$ is
geometrically unibranch at all of its points.

\label{lemma-geometrically-unibranch}
\begin{reference}
Compare with \cite[Proposition 2.3]{Etale-coverings}
\end{reference}
Let $X$ be a Noetherian scheme. The following are equivalent
\begin{enumerate}
\item $X$ is geometrically unibranch (Definition \ref{definition-unibranch}),
\item for every point $x \in X$ which is not the generic point of
an irreducible component of $X$, the punctured spectrum of the
strict henselization $\mathcal{O}_{X, x}^{sh}$ is connected.
\end{enumerate}

\label{lemma-number-of-branches-1}
Let $X$ be a scheme. Let $x \in X$.
\begin{enumerate}
\item The number of branches of $X$ at $x$ is $1$ if and only if
$X$ is unibranch at $x$.
\item The number of geometric branches of $X$ at $x$ is $1$ if and only if
$X$ is geometrically unibranch at $x$.
\end{enumerate}

\label{lemma-invert-s-sections}
\begin{reference}
\cite[Section 6.8]{EGA1-second}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible sheaf on $X$.
Let $s \in \Gamma(X, \mathcal{L})$. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module.
\begin{enumerate}
\item If $X$ is quasi-compact, then (\ref{equation-module-invert-s})
is injective, and
\item if $X$ is quasi-compact and quasi-separated, then
(\ref{equation-module-invert-s}) is an isomorphism.
\end{enumerate}
In particular, the canonical map
$$
\Gamma_*(X, \mathcal{L})_{(s)}
\longrightarrow
\Gamma(X_s, \mathcal{O}_X),\quad
a/s^n \longmapsto a \otimes s^{-n}
$$
is an isomorphism if $X$ is quasi-compact and quasi-separated.

\label{definition-quasi-affine}
A scheme $X$ is called {\it quasi-affine} if it is quasi-compact
and isomorphic to an open subscheme of an affine scheme.

\label{lemma-cartesian-diagram-quasi-affine}
Let $U \to V$ be an open immersion of quasi-affine schemes. Then
$$
\xymatrix{
U \ar[d] \ar[rr]_-j & & \Spec(\Gamma(U, \mathcal{O}_U)) \ar[d] \\
U \ar[r] & V \ar[r]^-{j'} & \Spec(\Gamma(V, \mathcal{O}_V))
}
$$
is cartesian.

\label{lemma-flat-module}
\begin{slogan}
Flatness is the same for modules and sheaves.
\end{slogan}
Let $X = \Spec(R)$ be an affine scheme.
Let $\mathcal{F} = \widetilde{M}$ for some $R$-module $M$.
The quasi-coherent sheaf $\mathcal{F}$ is a flat
$\mathcal{O}_X$-module if and only if $M$ is a flat $R$-module.

\label{definition-locally-projective}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. We say $\mathcal{F}$ is {\it locally projective}
if for every affine open $U \subset X$ the $\mathcal{O}_X(U)$-module
$\mathcal{F}(U)$ is projective.

\label{lemma-integral-algebra-directed-colimit-finite}
Let $X$ be a scheme. Assume $X$ is quasi-compact and quasi-separated.
Let $\mathcal{A}$ be an integral quasi-coherent $\mathcal{O}_X$-algebra.
Then
\begin{enumerate}
\item $\mathcal{A}$ is the directed colimit of its finite
quasi-coherent $\mathcal{O}_X$-subalgebras, and
\item $\mathcal{A}$ is a direct colimit of finite and finitely
presented quasi-coherent $\mathcal{O}_X$-algebras.
\end{enumerate}

\label{definition-ample}
\begin{reference}
\cite[II Definition 4.5.3]{EGA}
\end{reference}
Let $X$ be a scheme.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
We say $\mathcal{L}$ is {\it ample} if
\begin{enumerate}
\item $X$ is quasi-compact, and
\item for every $x \in X$ there exists an $n \geq 1$
and $s \in \Gamma(X, \mathcal{L}^{\otimes n})$ such
that $x \in X_s$ and $X_s$ is affine.
\end{enumerate}

\label{lemma-ample-power-ample}
\begin{reference}
\cite[II Proposition 4.5.6(i)]{EGA}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $n \geq 1$. Then $\mathcal{L}$ is ample if and only if
$\mathcal{L}^{\otimes n}$ is ample.

\label{lemma-ample-tensor-globally-generated}
\begin{reference}
\cite[II Proposition 4.5.6(ii)]{EGA}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ and $\mathcal{M}$
be invertible $\mathcal{O}_X$-modules. If
\begin{enumerate}
\item $\mathcal{L}$ is ample, and
\item the open sets $X_t$ where $t \in \Gamma(X, \mathcal{M}^{\otimes m})$
for $m > 0$ cover $X$,
\end{enumerate}
then $\mathcal{L} \otimes \mathcal{M}$ is ample.

\label{lemma-ample-separated}
Let $X$ be a scheme. If there exists an ample invertible sheaf on $X$
then $X$ is separated.

\label{lemma-ample-immersion-into-proj}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Set $S = \Gamma_*(X, \mathcal{L})$.
Assume $\mathcal{L}$ is ample. Then the canonical morphism of schemes
$f : X \longrightarrow \text{Proj}(S)$ of Lemma \ref{lemma-map-into-proj}
is an open immersion with dense image.

\label{lemma-quasi-affine-O-ample}
Let $X$ be a scheme.
Then $X$ is quasi-affine if and only if $\mathcal{O}_X$ is ample.

\label{lemma-quasi-affine-locally-closed}
Let $X$ be a quasi-affine scheme. For any quasi-compact immersion
$i : X' \to X$ the scheme $X'$ is quasi-affine.

\label{lemma-characterize-affine}
Let $X$ be a scheme. Suppose that there exist finitely many elements
$f_1, \ldots, f_n \in \Gamma(X, \mathcal{O}_X)$ such that
\begin{enumerate}
\item each $X_{f_i}$ is an affine open of $X$, and
\item the ideal generated by $f_1, \ldots, f_n$ in
$\Gamma(X, \mathcal{O}_X)$ is equal to the unit ideal.
\end{enumerate}
Then $X$ is affine.

\label{lemma-quasi-compact-dense-open-separated}
Let $X$ be a quasi-compact scheme.
There exists a dense open $V \subset X$ which is separated.

\label{lemma-ring-affine-open-injective-local-ring}
Let $X$ be a scheme and $x \in X$ a point. There exists an affine open
neighbourhood $U \subset X$ of $x$ such that the canonical map
$\mathcal{O}_X(U) \to \mathcal{O}_{X, x}$ is injective in each of
the following cases:
\begin{enumerate}
\item $X$ is integral,
\item $X$ is locally Noetherian,
\item $X$ is reduced and has a finite number of irreducible components.
\end{enumerate}

\label{proposition-isom}
In Situation \ref{situation-hom} assume that
\begin{enumerate}
\item $f$ is of finite presentation, and
\item $\mathcal{F}$ and $\mathcal{G}$ are finitely presented
$\mathcal{O}_X$-modules, flat over $B$, with support proper over $B$.
\end{enumerate}
Then the functor $\mathit{Isom}(\mathcal{F}, \mathcal{G})$ is
an algebraic space affine of finite presentation over $B$.

\label{lemma-extend-q-to-spaces}
In Situation \ref{situation-q}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \text{Q}_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is quasi-coherent and flat over }T
\end{matrix}
\right\}
$$
where $\mathcal{F}_T$ denotes the pullback of $\mathcal{F}$
to the algebraic space $X \times_{B, h} T$. Similarly, we have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \text{Q}^{fp}_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is of finite presentation and flat over }T
\end{matrix}
\right\}
$$

\label{lemma-quot-sheaf}
In Situation \ref{situation-quot}. The functor $\Quotfunctor_{\mathcal{F}/X/B}$
satisfies the sheaf property for the fpqc topology.

\label{lemma-extend-quot-to-spaces}
In Situation \ref{situation-quot}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \Quotfunctor_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is of finite presentation and}\\
\text{flat over }T\text{ with support proper over }T
\end{matrix}
\right\}
$$
where $\mathcal{F}_T$ denotes the pullback of $\mathcal{F}$
to the algebraic space $X \times_{B, h} T$.

\label{lemma-hilb-is-quot}
In Situation \ref{situation-hilb} we have
$\Hilbfunctor_{X/B} = \Quotfunctor_{\mathcal{O}_X/X/B}$.

\label{lemma-extend-hilb-to-spaces}
In Situation \ref{situation-hilb}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T, \Hilbfunctor_{X/B}) =
\left\{
\begin{matrix}
(h, Z)\text{ where }h : T \to B,\ Z \subset X_T \\
\text{finite presentation, flat, proper over }T
\end{matrix}
\right\}
$$
where $X_T = X \times_{B, h} T$.

\label{lemma-pic-over-pic}
In Situation \ref{situation-pic}
the functor $\Picardfunctor_{X/B}$ is the sheafification of
the functor $T \mapsto \Ob(\Picardstack_{X/B, T})/\cong$.

\label{proposition-pic-functor}
Let $S$ be a scheme. Let $f : X \to B$ be a morphism of algebraic
spaces over $S$. Assume that
\begin{enumerate}
\item $f$ is flat, of finite presentation, and proper, and
\item $\mathcal{O}_T \to f_{T, *}\mathcal{O}_{X_T}$ is an isomorphism
for all schemes $T$ over $B$.
\end{enumerate}
Then $\Picardfunctor_{X/B}$ is an algebraic space.

\label{lemma-extend-spaces-to-spaces}
Let $T$ be an algebraic space over $\mathbf{Z}$. Let $\mathcal{S}_T$
denote the corresponding algebraic stack (Algebraic Stacks, Sections
\ref{algebraic-section-split},
\ref{algebraic-section-representable-by-algebraic-spaces}, and
\ref{algebraic-section-stacks-spaces}).
We have an equivalence of categories
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces }\\
X \to T\text{ of finite type}
\end{matrix}
\right\}
\longrightarrow
\Mor_{\textit{Cat}/\Sch_{fppf}}(\mathcal{S}_T, \Spacesstack'_{ft})
$$
and an equivalence of categories
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces }X \to T\\
\text{of finite presentation, flat, and proper}
\end{matrix}
\right\}
\longrightarrow
\Mor_{\textit{Cat}/\Sch_{fppf}}(\mathcal{S}_T,
\Spacesstack'_{fp, flat, proper})
$$

\label{lemma-spaces-RS-star}
Let
$$
\xymatrix{
T \ar[r] \ar[d] & T' \ar[d] \\
S \ar[r] & S'
}
$$
be a pushout in the category of schemes where
$T \to T'$ is a thickening and $T \to S$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\begin{matrix}
\Spacesstack'_{fp, flat, proper, S'} \\
\downarrow \\
\Spacesstack'_{fp, flat, proper, S}
\times_{\Spacesstack'_{fp, flat, proper, T}}
\Spacesstack'_{fp, flat, proper, T'}
\end{matrix}
$$
is an equivalence.

\label{lemma-polarized-limits}
The stack in groupoids $\Polarizedstack$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-polarized-existence}
Consider the stack $\Polarizedstack$ over the base
scheme $\Spec(\mathbf{Z})$. Then every formal object is effective.

\label{lemma-curves-limits}
The stack $\Curvesstack \to \Sch_{fppf}$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-curves-RS-star}
Let
$$
\xymatrix{
T \ar[r] \ar[d] & T' \ar[d] \\
S \ar[r] & S'
}
$$
be a pushout in the category of schemes where
$T \to T'$ is a thickening and $T \to S$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\Curvesstack_{S'}
\longrightarrow
\Curvesstack_S
\times_{\Curvesstack_T}
\Curvesstack_{T'}
$$
is an equivalence.

\label{lemma-curves-existence}
Consider the stack $\Curvesstack$ over the base
scheme $\Spec(\mathbf{Z})$. Then every formal object is effective.

[Algebraicity of the stack of curves]
\label{theorem-curves-algebraic}
\begin{reference}
See \cite[Proposition 3.3, page 8]{dJHS} and
\cite[Appendix B by Jack Hall, Theorem B.1]{Smyth}.
\end{reference}
The stack $\Curvesstack$ (Situation \ref{situation-curves})
is algebraic. In fact, for any algebraic space $B$ the stack
$B\text{-}\Curvesstack$ (Remark \ref{remark-curves-base-change})
is algebraic.

\label{lemma-curves-open-and-closed-in-spaces}
The $1$-morphism (\ref{equation-curves-over-proper-spaces})
$$
\Curvesstack \longrightarrow \Spacesstack'_{fp, flat, proper}
$$
is representable by open and closed immersions.

\label{lemma-complexes-RS-star}
In Situation \ref{situation-complexes}. Let
$$
\xymatrix{
Z \ar[r] \ar[d] & Z' \ar[d] \\
Y \ar[r] & Y'
}
$$
be a pushout in the category of schemes over $S$ where
$Z \to Z'$ is a finite order thickening and $Z \to Y$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\Complexesstack_{X/B, Y'}
\longrightarrow
\Complexesstack_{X/B, Y}
\times_{\Complexesstack_{X/B, Z}}
\Complexesstack_{X/B, Z'}
$$
is an equivalence.

\label{lemma-complexes-strong-effectiveness}
In Situation \ref{situation-complexes} assume $B = S$ is locally Noetherian.
Then strong formal effectiveness in the sense of
Artin's Axioms, Remark \ref{artin-remark-strong-effectiveness}
holds for $p : \Complexesstack_{X/S} \to (\Sch/S)_{fppf}$.

[Algebraicity of moduli of complexes on a proper morphism]
\label{theorem-complexes-algebraic}
\begin{reference}
\cite{lieblich-complexes}
\end{reference}
Let $S$ be a scheme. Let $f : X \to B$ be morphism of algebraic spaces
over $S$. Assume that $f$ is proper, flat, and of finite presentation.
Then $\Complexesstack_{X/B}$ is an algebraic stack over $S$.

\label{lemma-family-associated-module}
The construction in Example \ref{example-family-associated-module}
is compatible with base change, restriction, and flat pullback.

\label{lemma-family-associated-closed}
The construction in Example \ref{example-family-associated-closed}
is compatible with base change, restriction, and flat pullback.

\label{lemma-support-family}
Taking the support as in Remark \ref{remark-supports-family}
is compatible with base change, restriction, and flat pullback.

\label{lemma-uniqueness-extension}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian
and $f$ locally of finite type. Let $r \geq 0$. Let $\alpha$ and $\beta$
be relative $r$-cycles on $X/S$. The following are equivalent
\begin{enumerate}
\item $\alpha = \beta$, and
\item $\alpha_\eta = \beta_\eta$ for any generic point $\eta \in S$
of an irreducible component of $S$.
\end{enumerate}

\label{lemma-family-associated-module-specialization}
In the situation of Example \ref{example-family-associated-module}
assume $S$ is locally Noetherian and
$\mathcal{F}$ is flat over $S$ in dimensions $\geq r$
(More on Flatness, Definition \ref{flat-definition-flat-dimension-n}).
Then $[\mathcal{F}/X/S]_r$ is a relative $r$-cycle on $X/S$.

\label{lemma-family-associated-closed-specialization}
In the situation of Example \ref{example-family-associated-closed}
assume $S$ is locally Noetherian and $Z$ is flat over $S$ in dimensions
$\geq r$. Then $[Z/X/S]_r$ is a relative $r$-cycle on $X/S$.

\label{definition-proper}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian
and $f$ is locally of finite type. Let $r \geq 0$ be an integer. We say a
relative $r$-cycle $\alpha$ on $X/S$ is a {\it proper relative cycle}
if the support of $\alpha$ (Remark \ref{remark-supports-family})
is contained in a closed subset $W \subset X$ proper over $S$
(Cohomology of Schemes, Definition \ref{coherent-definition-proper-over-base}).
The group of all proper relative $r$-cycles on $X/S$ is
denoted $c(X/S, r)$.

\label{lemma-action-opens}
If $U \subset X$ and $V \subset Y$ are open and $f(U) \subset V$, then
$(\alpha \cap \beta)|_U$ is equal to $\alpha|_U \cap \beta|_V$.

\label{lemma-action-base-change}
Forming $\alpha \cap \beta$ is compatible with flat base change
and flat pullback (see proof for elucidation).

\label{lemma-construction-opens}
If $U \subset X$ and $V \subset Y$ are open and $f(U) \subset V$, then
$(\alpha \circ \beta)|_U$ is equal to $\alpha|_U \circ \beta|_V$.

\label{lemma-trace-well-defined}
Let $\varphi : R[x]/(x^p - a) \to R[y]/(y^p - b)$ be an $R$-algebra
homomorphism. Then $\text{Tr}_x = \text{Tr}_y \circ \varphi$.

\label{lemma-dominate-by-scheme-modification}
In Situation \ref{situation-vanishing} there exists a $U$-admissible
blowup $X' \to S$ which dominates $X$.

\label{lemma-nice-meromorphic-function}
In Situation \ref{situation-vanishing} there exists a nonzero
$f \in \mathfrak m$ such that for every $i = 1, \ldots, r$ there exist
\begin{enumerate}
\item a closed point $x_i \in C_i$ with $x_i \not \in C_j$ for $j \not = i$,
\item a factorization $f = g_i f_i$ of $f$ in $\mathcal{O}_{X, x_i}$
such that $g_i \in \mathfrak m_{x_i}$ maps to a nonzero element
of $\mathcal{O}_{C_i, x_i}$.
\end{enumerate}

[Grauert-Riemenschneider]
\label{proposition-Grauert-Riemenschneider}
In Situation \ref{situation-vanishing} assume
\begin{enumerate}
\item $X$ is a normal scheme,
\item $A$ is Nagata and has a dualizing complex $\omega_A^\bullet$.
\end{enumerate}
Let $\omega_X$ be the dualizing module of $X$
(Remark \ref{remark-dualizing-setup}). Then $R^1f_*\omega_X = 0$.

\label{lemma-regular-rational}
Let $A$ be a Nagata regular local ring of dimension $2$. Then $A$ defines
a rational singularity.

\label{lemma-globally-generated}
In Situation \ref{situation-rational}.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $H^p(X, \mathcal{F}) = 0$ for $p \not \in \{0, 1\}$, and
\item $H^1(X, \mathcal{F}) = 0$ if $\mathcal{F}$ is globally generated.
\end{enumerate}

\label{lemma-blow-up-normal-rational}
In Situation \ref{situation-rational}
the blowup of $\Spec(A)$ in $\mathfrak m$ is normal.

\label{lemma-blowup-still-good}
Let $(A, \mathfrak m, \kappa)$ be a Nagata local normal domain of
dimension $2$. Assume $A$ defines a rational singularity and that
the completion $A^\wedge$ of $A$ is normal. Then
\begin{enumerate}
\item $A^\wedge$ defines a rational singularity, and
\item if $X \to \Spec(A)$ is the blowing up in $\mathfrak m$, then
for a closed point $x \in X$ the completion $\mathcal{O}_{X, x}$ is normal.
\end{enumerate}

\label{definition-resolution}
Let $Y$ be a Noetherian integral scheme. A {\it resolution of singularities}
of $Y$ is a modification $f : X \to Y$ such that $X$ is regular.

[Lipman]
\label{theorem-resolve}
\begin{reference}
\cite[Theorem on page 151]{Lipman}
\end{reference}
Let $Y$ be a two dimensional integral Noetherian scheme. The following are
equivalent
\begin{enumerate}
\item there exists an alteration $X \to Y$ with $X$ regular,
\item there exists a resolution of singularities of $Y$,
\item $Y$ has a resolution of singularities by normalized blowups,
\item the normalization $Y^\nu \to Y$ is finite, $Y^\nu$ has
finitely many singular points $y_1, \ldots, y_m$, and for each
$y_i$ the completion of $\mathcal{O}_{Y^\nu, y_i}$ is normal.
\end{enumerate}

\label{lemma-blowup-nonsingular-curves-meeting-at-point}
In the situation above let $X' \to X$ be the blowing up of $X$ in $p$.
Let $Y', Z' \subset X'$ be the strict transforms of $Y, Z$.
If $\mathcal{O}_{Y, p}$ is regular, then
\begin{enumerate}
\item $Y' \to Y$ is an isomorphism,
\item $Y'$ meets the exceptional fibre $E \subset X'$ in one point
$q$ and $m_q(Y \cap E) = 1$,
\item if $q \in Z'$ too, then $m_q(Y \cap Z') < m_p(Y \cap Z)$.
\end{enumerate}

\label{lemma-contract-when-quasi-projective}
Let $S$ be a Noetherian scheme. Let $f : X \to S$ be a morphism of finite type.
Let $E \subset X$ be an exceptional curve of the first kind which is in a
fibre of $f$.
\begin{enumerate}
\item If $X$ is projective over $S$, then there exists a contraction
$X \to X'$ of $E$ and $X'$ is projective over $S$.
\item If $X$ is quasi-projective over $S$, then there exists a contraction
$X \to X'$ of $E$ and $X'$ is quasi-projective over $S$.
\end{enumerate}

\label{lemma-topologically-finite-type-Noetherian}
\begin{reference}
\cite[Proposition 7.5.5]{EGA1}
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal. Then
\begin{enumerate}
\item every object of the category $\mathcal{C}'$
(\ref{equation-C-prime}) is Noetherian,
\item if $B \in \Ob(\mathcal{C}')$ and $J \subset B$ is an ideal,
then $B/J$ is an object of $\mathcal{C}'$,
\item for a finite type $A$-algebra $C$ the $I$-adic completion
$C^\wedge$ is in $\mathcal{C}'$,
\item in particular the completion $A[x_1, \ldots, x_r]^\wedge$
is in $\mathcal{C}'$.
\end{enumerate}

\label{lemma-NL-is-limit}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Let $B$ be an object of (\ref{equation-C-prime}). Then
\begin{enumerate}
\item the pro-objects
$\{\NL_{B/A}^\wedge \otimes_B B/I^nB\}$ and $\{\NL_{B_n/A_n}\}$
of $D(B)$ are strictly isomorphic (see proof for elucidation),
\item $\NL_{B/A}^\wedge = R\lim \NL_{B_n/A_n}$ in $D(B)$.
\end{enumerate}
Here $B_n$ and $A_n$ are as in Section \ref{section-two-categories}.

\label{lemma-transitive-lci-at-end}
With assumptions as in Lemma \ref{lemma-exact-sequence-NL}
assume that $B/I^nB \to C/I^nC$ is a local complete intersection
homomorphism for all $n$. Then
$H^{-1}(\NL_{B/A}^\wedge \otimes_B C) \to H^{-1}(\NL_{C/A}^\wedge)$
is injective.

\label{lemma-rig-smooth}
Let $A$ be a Noetherian ring and let $I$ be an ideal.
Let $B$ be a finite type $A$-algebra.
\begin{enumerate}
\item If $\Spec(B) \to \Spec(A)$ is smooth over $\Spec(A) \setminus V(I)$,
then $B^\wedge$ is rig-smooth over $(A, I)$.
\item If $B^\wedge$ is rig-smooth over $(A, I)$,
then there exists $g \in 1 + IB$ such that $\Spec(B_g)$ is smooth
over $\Spec(A) \setminus V(I)$.
\end{enumerate}

\label{lemma-presentation-rig-smooth}
Let $A$ be a ring. Let $f_1, \ldots, f_m \in A[x_1, \ldots, x_n]$
and set $B = A[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$. Assume $m \leq n$
and set $g = \det_{1 \leq i, j \leq m}(\partial f_j/\partial x_i)$.
Then
\begin{enumerate}
\item $g$ annihilates $\Ext^1_B(\NL_{B/A}, N)$ for every $B$-module $N$,
\item if $n = m$, then multiplication by $g$ on $\NL_{B/A}$ is $0$ in $D(B)$.
\end{enumerate}

\label{lemma-approximate-principal}
\begin{reference}
The rig-\'etale case of \cite[III Theorem 7]{Elkik}
\end{reference}
Let $A$ be a Noetherian ring and $I = (a)$ a principal ideal.
Let $B$ be an object of (\ref{equation-C-prime}) which is
rig-\'etale over $(A, I)$.
Then there exists a finite type $A$-algebra $C$ and an
isomorphism $B \cong C^\wedge$.

\label{lemma-approximate-by-etale-over-complement}
Let $A$ be a Noetherian ring. Let $I \subset A$ be an ideal.
Let $B$ be an $I$-adically complete $A$-algebra with $A/I \to B/IB$
of finite type. The equivalent conditions of
Lemma \ref{lemma-equivalent-with-artin} are also equivalent to
\begin{enumerate}
\item[(8)]
\label{item-algebraize}
there exists a finite type $A$-algebra $C$ such that
$\Spec(C) \to \Spec(A)$ is \'etale over $\Spec(A) \setminus V(I)$
and such that $B \cong C^\wedge$.
\end{enumerate}

\label{lemma-Noetherian-adic-finite-type-red}
Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$.
If $\varphi$ is adic the following are equivalent
\begin{enumerate}
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type-red} and
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type}.
\end{enumerate}

\label{lemma-base-change-flat-continuous}
Denote $P$ the property of arrows of $\textit{WAdm}^{Noeth}$
defined in Lemma \ref{lemma-flat-axioms}.
Denote $Q$ the property defined in Lemma \ref{lemma-finite-type-red}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$.
Denote $R$ the property defined in Lemma \ref{lemma-finite-type}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$. Then
\begin{enumerate}
\item $P$ is stable under base change by $Q$
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-variant-Noetherian}), and
\item $P + R$ is stable under base change
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-Noetherian}).
\end{enumerate}

\label{lemma-base-change-flat}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Z \to Y$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is flat and $g_{red} : Z_{red} \to Y_{red}$ is
locally of finite type, then the base change
$X \times_Y Z \to Z$ is flat.
\item If $f$ is flat and locally of finite type, then
the base change $X \times_Y Z \to Z$ is flat and locally of finite type.
\end{enumerate}

\label{definition-completed-principal-localization}
Let $A$ be an adic topological ring which has a finitely generated ideal
of definition. Let $f \in A$. The {\it completed principal localization}
$A_{\{f\}}$ of $A$ is the completion of $A_f = A[1/f]$
of the principal localization of $A$ at $f$ with respect to any
ideal of definition of $A$.

\label{lemma-rig-closed-point-after-localization}
Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$
which is adic and topologically of finite type.
Let $\mathfrak q \subset B$ be rig-closed.
There exists an $f \in A$ which maps to a unit in
$B/\mathfrak q$ such that we obtain a diagram
$$
\vcenter{
\xymatrix{
B \ar[r] &
B_{\{f\}} \\
A \ar[r] \ar[u]_\varphi &
A_{\{f\}} \ar[u]_{\varphi_{\{f\}}}
}
}
\quad\text{with primes}\quad
\vcenter{
\xymatrix{
\mathfrak q \ar@{-}[r] \ar@{-}[d] &
\mathfrak q' \ar@{-}[d] \ar@{=}[r] &
\mathfrak q B_{\{f\}} \\
\mathfrak p \ar@{-}[r] &
\mathfrak p'
}
}
$$
such that $\mathfrak p'$ is rig-closed, i.e.,
the map $A_{\{f\}} \to B_{\{f\}}$ and the prime ideals
$\mathfrak q'$ and $\mathfrak p'$ satisfy
the equivalent conditions of Lemma \ref{lemma-rig-closed-point-relative}.

\label{lemma-rig-flat-local-etale}
Consider a commutative diagram
$$
\xymatrix{
B \ar[r] & B' \\
A \ar[r] \ar[u]^\varphi & A' \ar[u]_{\varphi'}
}
$$
in $\textit{WAdm}^{Noeth}$ with all arrows adic and topologically
of finite type. Assume $A \to A'$ and $B \to B'$ are flat.
Let $I \subset A$ be an ideal of definition.
If $\varphi$ is rig-flat and $A/I \to A'/IA'$
is \'etale, then $\varphi'$ is rig-flat.

\label{lemma-rig-flat-local-down}
Consider a commutative diagram
$$
\xymatrix{
B \ar[r] & B' \\
A \ar[r] \ar[u]^\varphi & A' \ar[u]_{\varphi'}
}
$$
in $\textit{WAdm}^{Noeth}$ with all arrows adic and topologically
of finite type. Assume $A \to A'$ flat and $B \to B'$ faithfully flat.
If $\varphi'$ is rig-flat, then $\varphi$ is rig-flat.

\label{lemma-rig-etale-finite-type}
A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is locally of finite type.

\label{lemma-rig-etale-rig-smooth-morphism}
A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is rig-smooth.

\label{lemma-composition-rig-surjective}
\begin{slogan}
Rig-surjectivity of locally finite type morphisms is preserved under
composition
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of formal
algebraic spaces over $S$. Assume $X$, $Y$, $Z$ are locally Noetherian and
$f$ and $g$ locally of finite type. Then if $f$ and $g$ are rig-surjective,
so is $g \circ f$.

\label{lemma-flat-rig-surjective}
Let $A$ be a Noetherian ring complete with respect to an ideal $I$.
Let $B$ be an $I$-adically complete $A$-algebra. Assume that
\begin{enumerate}
\item the $I$-torsion in $A$ is $0$,
\item $A/I^n \to B/I^nB$ is flat and of finite type for all $n$.
\end{enumerate}
Then $\text{Spf}(B) \to \text{Spf}(A)$ is rig-surjective if and only
if $A/I \to B/IB$ is faithfully flat.

\label{lemma-rig-etale-descent}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Y \to Z$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
Assume
\begin{enumerate}
\item $g$ is locally of finite type,
\item $f$ is rig-smooth (resp.\ rig-\'etale) and rig-surjective,
\item $g \circ f$ is rig-smooth (resp.\ rig-\'etale)
\end{enumerate}
then $g$ is rig-smooth (resp.\ rig-\'etale).

\label{lemma-map-completions-finite-type}
In the situation above. If $f$ is locally of finite type, then
$f_{/T}$ is locally of finite type.

\label{lemma-closed-immersion-gives-closed-immersion}
In the situation above. If $f$ is a closed immersion, then
$f_{/T}$ is a closed immersion.

\label{lemma-quasi-compact-gives-quasi-compact}
In the situation above. If $f$ is quasi-compact, then
$f_{/T}$ is quasi-compact.

\label{lemma-quasi-separated-gives-quasi-separated}
In the situation above. If $f$ is (quasi-)separated, then
$f_{/T}$ is too.

\label{lemma-completion-proper-surjective-rig-surjective}
In the situation above. If $X$ is locally Noetherian,
$f$ is proper, and $U' \to U$ is surjective, then $f_{/T}$ is rig-surjective.

\label{lemma-dilatations-affine}
In the situation above. Assume $X$ is affine. Then the functor
(\ref{equation-completion-functor}) is an equivalence.

\label{theorem-dilatations-general}
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $U \subset X$ be the open subspace
with $|U| = |X| \setminus T$. The completion functor
(\ref{equation-completion-functor})
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces}\\
f : X' \to X\text{ which are locally}\\
\text{of finite type and such that}\\
f^{-1}U \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{morphisms }g : W \to X_{/T}\\
\text{of formal algebraic spaces}\\
\text{with }W\text{ locally Noetherian}\\
\text{and }g\text{ rig-\'etale}
\end{matrix}
\right\}
$$
sending $f : X' \to X$ to $f_{/T} : X'_{/T'} \to X_{/T}$ is an equivalence.

\label{lemma-output-quasi-compact}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-compact if and only if $g$ is quasi-compact.

\label{lemma-output-quasi-separated}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-separated if and only if $g$ is so.

\label{lemma-output-separated}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is separated $\Leftrightarrow$ $g$ is
separated and $\Delta_g : W \to W \times_{X_{/T}} W$ is rig-surjective.

\label{lemma-output-proper}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is proper if and only if $g$ is a formal modification
(Definition \ref{definition-formal-modification}).

\label{lemma-output-etale}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is \'etale if and only if $g$ is \'etale.

\label{lemma-isomorphism-locally-ringed}
\begin{slogan}
An isomorphism of ringed spaces between locally ringed spaces is an
isomorphism of locally ringed spaces.
\end{slogan}
Let $X$, $Y$ be locally ringed spaces.
If $f : X \to Y$ is an isomorphism of
ringed spaces, then $f$ is an isomorphism
of locally ringed spaces.

\label{definition-closed-immersion-locally-ringed-spaces}
Let $i : Z \to X$ be a morphism of locally ringed spaces.
We say that $i$ is a {\it closed immersion} if:
\begin{enumerate}
\item The map $i$ is a homeomorphism of $Z$ onto a closed subset of $X$.
\item The map $\mathcal{O}_X \to i_*\mathcal{O}_Z$ is surjective;
let $\mathcal{I}$ denote the kernel.
\item The $\mathcal{O}_X$-module $\mathcal{I}$
is locally generated by sections.
\end{enumerate}

\label{lemma-standard-open}
Let $R$ be a ring. Let $f \in R$.
\begin{enumerate}
\item If $g\in R$ and $D(g) \subset D(f)$, then
\begin{enumerate}
\item $f$ is invertible in $R_g$,
\item $g^e = af$ for some $e \geq 1$ and $a \in R$,
\item there is a canonical ring map $R_f \to R_g$, and
\item there is a canonical $R_f$-module map
$M_f \to M_g$ for any $R$-module $M$.
\end{enumerate}
\item Any open covering of $D(f)$ can be refined to a finite
open covering of the form $D(f) = \bigcup_{i = 1}^n D(g_i)$.
\item If $g_1, \ldots, g_n \in R$, then $D(f) \subset \bigcup D(g_i)$
if and only if $g_1, \ldots, g_n$ generate the unit ideal in $R_f$.
\end{enumerate}

\label{lemma-closed-immersion-affine-case}
\begin{slogan}
For affine schemes, closed immersions correspond to ideals.
\end{slogan}
Let $(X, \mathcal{O}_X) = (\Spec(R), \mathcal{O}_{\Spec(R)})$
be an affine scheme. Let $i : Z \to X$ be any closed immersion
of locally ringed spaces. Then there exists a unique ideal
$I \subset R$ such that the morphism $i : Z \to X$ can be identified
with the closed immersion $\Spec(R/I) \to \Spec(R)$
constructed in Example \ref{example-closed-immersion-affines} above.

\label{lemma-immersion-when-closed}
Let $f : Y \to X$ be an immersion of schemes. Then $f$ is a closed
immersion if and only if $f(Y) \subset X$ is a closed subset.

\label{lemma-basis-affine-opens}
Let $X$ be a scheme. The collection of affine opens
of $X$ forms a basis for the topology on $X$.

\label{definition-reduced}
Let $X$ be a scheme. We say $X$ is {\it reduced} if every local ring
$\mathcal{O}_{X, x}$ is reduced.

\label{lemma-reduced}
A scheme $X$ is reduced if and only if $\mathcal{O}_X(U)$
is a reduced ring for all $U \subset X$ open.

\label{lemma-affine-reduced}
An affine scheme $\Spec(R)$ is reduced
if and only if $R$ is reduced.

\label{lemma-glue}
\begin{slogan}
If you have two locally ringed spaces, and a subspace of the first one
is isomorphic to a subspace of the other, then you can glue them together
into one big locally ringed space.
\end{slogan}
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

\label{lemma-glue-schemes}
\begin{slogan}
Schemes can be glued to give new schemes.
\end{slogan}
In Lemma \ref{lemma-glue} above, assume that all
$X_i$ are schemes. Then the resulting locally ringed
space $X$ is a scheme.

\label{lemma-glue-functors}
Let $F$ be a contravariant functor on the category of schemes
with values in the category of sets. Suppose that
\begin{enumerate}
\item $F$ satisfies the sheaf property for the Zariski topology,
\item there exists a set $I$ and a collection of subfunctors
$F_i \subset F$ such that
\begin{enumerate}
\item each $F_i$ is representable,
\item each $F_i \subset F$ is representable by open immersions, and
\item the collection $(F_i)_{i \in I}$ covers $F$.
\end{enumerate}
\end{enumerate}
Then $F$ is representable.

\label{lemma-fibre-topological}
Let $f : X \to S$ be a morphism of schemes.
Consider the diagrams
$$
\vcenter{
\xymatrix{
X_s \ar[r] \ar[d] & X \ar[d] \\
\Spec(\kappa(s)) \ar[r] & S
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Spec(\mathcal{O}_{S, s}) \times_S X \ar[r] \ar[d] & X \ar[d] \\
\Spec(\mathcal{O}_{S, s}) \ar[r] & S
}
}
$$
In both cases these diagrams induce fibre squares of topological
spaces and in particular, the top horizontal arrow is a homeomorphism
onto its image.

\label{definition-quasi-compact}
A morphism of schemes is called {\it quasi-compact}
if the underlying map of topological spaces is
quasi-compact, see
Topology, Definition \ref{topology-definition-quasi-compact}.

\label{lemma-quasi-compact-affine}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f : X \to S$ is quasi-compact,
\item the inverse image of every affine open is quasi-compact, and
\item there exists some affine open covering $S = \bigcup_{i \in I} U_i$
such that $f^{-1}(U_i)$ is quasi-compact for all $i$.
\end{enumerate}

\label{lemma-quasi-compact-preserved-base-change}
Being quasi-compact is a property of morphisms of schemes
over a base which is preserved under arbitrary base change.

\label{lemma-image-quasi-compact-closed}
Let $f : X \to S$ be a quasi-compact morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f(X) \subset S$ is closed, and
\item $f(X) \subset S$ is stable under specialization.
\end{enumerate}

\label{lemma-specializations-lift}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item If $f$ is universally closed then specializations lift
along any base change of $f$, see
Topology, Definition \ref{topology-definition-lift-specializations}.
\item If $f$ is quasi-compact and specializations lift
along any base change of $f$, then $f$ is universally closed.
\end{enumerate}

\label{lemma-points-specialize}
\begin{slogan}
Specializations are witnessed by valuation rings.
\end{slogan}
Let $S$ be a scheme. Let $s' \leadsto s$ be a specialization of points of $S$.
Then
\begin{enumerate}
\item there exists a valuation ring $A$ and a morphism
$f : \Spec(A) \to S$ such that the generic point $\eta$ of
$\Spec(A)$ maps to $s'$ and the special point maps to $s$, and
\item given a field extension $K/\kappa(s')$
we may arrange it so that the extension
$\kappa(\eta)/\kappa(s')$ induced by $f$
is isomorphic to the given extension.
\end{enumerate}

\label{lemma-lift-specializations-valuative}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item Specializations lift along any base change of $f$
\item The morphism $f$ satisfies the existence part of the
valuative criterion.
\end{enumerate}

\label{lemma-diagonal-immersion}
\begin{slogan}
The diagonal morphism for relative schemes is an immersion.
\end{slogan}
Let $X$ be a scheme over $S$.
The diagonal morphism $\Delta_{X/S}$ is an immersion.

\label{lemma-separated-permanence}
Permanence properties.
\begin{enumerate}
\item A composition of separated morphisms is separated.
\item A composition of quasi-separated morphisms is quasi-separated.
\item The base change of a separated morphism is separated.
\item The base change of a quasi-separated morphism is quasi-separated.
\item A (fibre) product of separated morphisms is separated.
\item A (fibre) product of quasi-separated morphisms is quasi-separated.
\end{enumerate}

\label{lemma-compose-after-separated}
\begin{slogan}
Separated and quasi-separated morphisms satisfy cancellation.
\end{slogan}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
If $g \circ f$ is separated then so is $f$.
If $g \circ f$ is quasi-separated then so is $f$.

\label{lemma-affine-separated}
An affine scheme is separated. A morphism from an affine scheme
to another scheme is separated.

[Valuative criterion separatedness]
\label{lemma-valuative-criterion-separatedness}
\begin{reference}
\cite[II Proposition 7.2.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism.
Assume
\begin{enumerate}
\item the morphism $f$ is quasi-separated, and
\item the morphism $f$ satisfies the uniqueness
part of the valuative criterion.
\end{enumerate}
Then $f$ is separated.

\label{lemma-monomorphism}
\begin{slogan}
A scheme morphism is a monomorphism iff its diagonal is an isomorphism.
\end{slogan}
Let $j : X \to Y$ be a morphism of schemes.
Then $j$ is a monomorphism if and only if the
diagonal morphism $\Delta_{X/Y} : X \to X \times_Y X$ is
an isomorphism.

\label{lemma-injective-points}
Let $j : X \to Y$ be a morphism of schemes.
If $j$ is injective on points, then $j$ is separated.

\label{lemma-injective-points-surjective-stalks}
Let $j : X \to Y$ be a morphism of schemes.
If
\begin{enumerate}
\item $j$ is injective on points, and
\item for any $x \in X$ the ring map
$j^\sharp_x : \mathcal{O}_{Y, j(x)} \to \mathcal{O}_{X, x}$
is surjective,
\end{enumerate}
then $j$ is a monomorphism.

\label{lemma-immersions-monomorphisms}
An immersion of schemes is a monomorphism.
In particular, any immersion is separated.

\label{lemma-subscheme-of-separated-scheme}
Let $f : X \to S$ be a separated morphism.
Any locally closed subscheme $Z \subset X$ is separated over $S$.

\label{lemma-characterize-closed-immersions}
Let $f : X \to Y$ be a morphism of schemes.
Suppose that
\begin{enumerate}
\item $f$ induces a homeomorphism of $X$ with a
closed subset of $Y$, and
\item $f^\sharp : \mathcal{O}_Y \to f_*\mathcal{O}_X$
is surjective.
\end{enumerate}
Then $f$ is a closed immersion of schemes.

\label{lemma-dg-hull-acyclic}
The functors $F, G$ of Lemma \ref{lemma-dg-hull} have
the following properties. Given a graded $\mathcal{A}$-module
$\mathcal{N}$ we have
\begin{enumerate}
\item the counit $\mathcal{N} \to F(G(\mathcal{N}))$ is injective,
\item the map $\overline{\text{d}} : \mathcal{N} \to
\Coker(\mathcal{N} \to F(G(\mathcal{N})))[1]$ is an isomorphism, and
\item $G(\mathcal{N})$ is an acyclic differential graded $\mathcal{A}$-module.
\end{enumerate}

\label{lemma-kernel-localization}
In Definition \ref{definition-derived-category}
the kernel of the localization functor
$Q : K(\textit{Mod}(\mathcal{A}, \text{d})) \to D(\mathcal{A}, \text{d})$
is the category $\text{Ac}$ of Lemma \ref{lemma-acyclics}.

\label{proposition-exist-ordinals-large-cofinality}
Let $\kappa$ be a cardinal. Then there exists an ordinal
whose cofinality is bigger than $\kappa$.

\label{lemma-what-is-in-it-G-sets}
Let $\alpha$ be an ordinal as in Lemma \ref{lemma-sets-with-group-action}
above. The category $G\textit{-Sets}_\alpha$ satisfies the following
properties:
\begin{enumerate}
\item The $G$-set ${}_GG$ is an object of $G\textit{-Sets}_\alpha$.
\item (Co)Products, fibre products, and pushouts
exist in $G\textit{-Sets}_\alpha$
and are the same as their counterparts in $G\textit{-Sets}$.
\item Given an object $U$ of $G\textit{-Sets}_\alpha$,
any $G$-stable subset $O \subset U$  is isomorphic to an object
of $G\textit{-Sets}_\alpha$.
\end{enumerate}

\label{definition-abelian-sheaf}
Let $X$ be a topological space.
\begin{enumerate}
\item An {\it abelian sheaf on $X$} or
{\it sheaf of abelian groups on $X$}
is an abelian presheaf on $X$ such that the underlying presheaf of
sets is a sheaf.
\item The category of sheaves of abelian groups
is denoted $\textit{Ab}(X)$.
\end{enumerate}

\label{definition-sheaf-values-in-category}
Let $X$ be a topological space. Let $\mathcal{C}$ be
a category with products. A presheaf $\mathcal{F}$ with
values in $\mathcal{C}$ on $X$ is a {\it sheaf}
if for every open covering the diagram
$$
\xymatrix{
\mathcal{F}(U) \ar[r]
&
\prod\nolimits_{i\in I}
\mathcal{F}(U_i)
\ar@<1ex>[r] \ar@<-1ex>[r]
&
\prod\nolimits_{(i_0, i_1) \in I \times I}
\mathcal{F}(U_{i_0} \cap U_{i_1})
}
$$
is an equalizer diagram in the category $\mathcal{C}$.

\label{definition-separated}
Let $X$ be a topological space.
A presheaf of sets $\mathcal{F}$ on $X$ is {\it separated}
if for every open $U \subset X$ the map
$\mathcal{F}(U) \to \prod_{x \in U} \mathcal{F}_x$ is
injective.

\label{definition-algebraic-structure}
A {\it type of algebraic structure} is given by a category $\mathcal{C}$
and a functor $F : \mathcal{C} \to \textit{Sets}$ with the
following properties
\begin{enumerate}
\item $F$ is faithful,
\item $\mathcal{C}$ has limits and $F$ commutes with limits,
\item $\mathcal{C}$ has filtered colimits and $F$ commutes with them, and
\item $F$ reflects isomorphisms.
\end{enumerate}

\label{lemma-compose-f-maps-stalks}
Suppose that $f : X \to Y$ and $g : Y \to Z$ are continuous
maps of topological spaces. Suppose that $\mathcal{F}$ is
a sheaf on $X$, $\mathcal{G}$ is a sheaf on $Y$, and
$\mathcal{H}$ is a sheaf on $Z$.
Let $\varphi : \mathcal{G} \to \mathcal{F}$ be an $f$-map.
Let $\psi : \mathcal{H} \to \mathcal{G}$ be an $g$-map.
Let $x \in X$ be a point. The map on stalks
$(\varphi \circ \psi)_x : \mathcal{H}_{g(f(x))}
\to \mathcal{F}_x$ is the composition
$$
\mathcal{H}_{g(f(x))}
\xrightarrow{\psi_{f(x)}}
\mathcal{G}_{f(x)}
\xrightarrow{\varphi_x}
\mathcal{F}_x
$$

\label{lemma-stalk-pullback-modules}
Let $(f, f^\sharp) : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$
be a morphism of ringed spaces.
Let $\mathcal{G}$ be a sheaf of $\mathcal{O}_Y$-modules.
Let $x \in X$. Then
$$
(f^*\mathcal{G})_x =
\mathcal{G}_{f(x)}
\otimes_{\mathcal{O}_{Y, f(x)}}
\mathcal{O}_{X, x}
$$
as $\mathcal{O}_{X, x}$-modules where the tensor product on the right
uses $f^\sharp_x : \mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$.

\label{lemma-skyscraper-stalks}
Let $X$ be a topological space, $x \in X$ a point, and
$A$ a set. For any point $x' \in X$ the stalk of the
skyscraper sheaf at $x$ with value $A$ at $x'$ is
$$
(i_{x, *}A)_{x'} =
\left\{
\begin{matrix}
A & \text{if} & x' \in \overline{\{x\}} \\
\{*\} & \text{if} & x' \not\in \overline{\{x\}}
\end{matrix}
\right.
$$
A similar description holds for the case of
abelian groups, algebraic structures and
sheaves of modules.

\label{definition-j-shriek}
Let $X$ be a topological space.
Let $j : U \to X$ be the inclusion of an open subset.
\begin{enumerate}
\item Let $\mathcal{F}$ be a presheaf of sets on $U$. We define
the {\it extension of $\mathcal{F}$ by the empty set $j_{p!}\mathcal{F}$}
to be the presheaf of sets on $X$ defined by the rule
$$
j_{p!}\mathcal{F}(V) =
\left\{
\begin{matrix}
\emptyset & \text{if} & V \not \subset U \\
\mathcal{F}(V) & \text{if} & V \subset U
\end{matrix}
\right.
$$
with obvious restriction mappings.
\item Let $\mathcal{F}$ be a sheaf of sets on $U$. We define
the {\it extension of $\mathcal{F}$ by the empty set $j_!\mathcal{F}$}
to be the sheafification of the presheaf $j_{p!}\mathcal{F}$.
\end{enumerate}

\label{definition-face-degeneracy}
For any integer $n\geq 1$, and any $0\leq j \leq n$ we let
{\it $\delta^n_j : [n-1] \to [n]$}
denote the injective order preserving map skipping $j$. For any
integer $n\geq 0$, and any $0\leq j \leq n$ we denote
{\it $\sigma^n_j : [n + 1]  \to [n]$}
the surjective order preserving map with
$(\sigma^n_j)^{-1}(\{j\}) = \{j, j + 1\}$.

\label{lemma-face-degeneracy}
Any morphism in $\Delta$ can be written as a composition
of the morphisms $\delta^n_j$ and $\sigma^n_j$.

\label{definition-simplicial-object}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item A {\it simplicial object $U$ of $\mathcal{C}$}
is a contravariant functor $U$ from $\Delta$ to
$\mathcal{C}$, in a formula:
$$
U : \Delta^{opp} \longrightarrow \mathcal{C}
$$
\item If $\mathcal{C}$ is the category of sets, then we call
$U$ a {\it simplicial set}.
\item If $\mathcal{C}$ is the category of abelian groups,
then we call $U$ a {\it simplicial abelian group}.
\item A {\it morphism of simplicial objects $U \to U'$}
is a transformation of functors.
\item The {\it category of simplicial objects of $\mathcal{C}$}
is denoted $\text{Simp}(\mathcal{C})$.
\end{enumerate}

\label{definition-cosimplicial-object}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item A {\it cosimplicial object $U$ of $\mathcal{C}$}
is a covariant functor $U$ from $\Delta$ to
$\mathcal{C}$, in a formula:
$$
U : \Delta \longrightarrow \mathcal{C}
$$
\item If $\mathcal{C}$ is the category of sets, then we call
$U$ a {\it cosimplicial set}.
\item If $\mathcal{C}$ is the category of abelian groups,
then we call $U$ a {\it cosimplicial abelian group}.
\item A {\it morphism of cosimplicial objects $U \to U'$}
is a transformation of functors.
\item The {\it category of cosimplicial objects of $\mathcal{C}$}
is denoted $\text{CoSimp}(\mathcal{C})$.
\end{enumerate}

\label{definition-split}
Let $\mathcal{C}$ be a category which admits finite nonempty coproducts.
We say a simplicial object $U$ of $\mathcal{C}$ is {\it split}
if there exist subobjects $N(U_m)$ of $U_m$, $m \geq 0$
with the property that
\begin{equation}
\label{equation-splitting}
\coprod\nolimits_{\varphi : [n] \to [m]\text{ surjective}}
N(U_m)
\longrightarrow
U_n
\end{equation}
is an isomorphism for all $n \geq 0$. If $U$ is an $r$-truncated
simplicial object of $\mathcal{C}$ then we say $U$ is {\it split}
if there exist subobjects $N(U_m)$ of $U_m$, $r \geq m \geq 0$
with the property that (\ref{equation-splitting})
is an isomorphism for $r \geq n \geq 0$.

\label{lemma-splitting-simplicial-sets}
Let $U$ be a simplicial set. Then $U$ has a unique splitting
with $N(U_m)$ equal to the set of nondegenerate $m$-simplices.

\label{lemma-imshriek-sets}
If $U$ is an $m$-truncated simplicial set and $n > m$
then all $n$-simplices of $i_{m!}U$ are degenerate.

\label{lemma-products-homotopy}
Let $\mathcal{C}$ be a category. Let $T$ be a set. For $t \in T$
let $X_t$, $Y_t$ be simplicial objects of $\mathcal{C}$. Assume
$X = \prod_{t \in T} X_t$ and $Y = \prod_{t \in T} Y_t$ exist.
\begin{enumerate}
\item If $X_t$ and $Y_t$ are homotopy equivalent for all $t \in T$
and $T$ is finite, then $X$ and $Y$ are homotopy equivalent.
\end{enumerate}
For $t \in T$ let $a_t, b_t : X_t \to Y_t$ be morphisms.
Set $a = \prod a_t : X \to Y$ and $b = \prod b_t : X \to Y$.
\begin{enumerate}
\item[(2)] If there exists a homotopy from $a_t$ to $b_t$ for
all $t \in T$, then there exists a homotopy from $a$ to $b$.
\item[(3)] If $T$ is finite and $a_t, b_t : X_t \to Y_t$ for $t \in T$
are homotopic, then $a$ and $b$ are homotopic.
\end{enumerate}

\label{lemma-homotopy-s-Q}
\begin{slogan}
The (cosimplicial) Dold-Kan functor carries homotopic maps to homotopic maps.
\end{slogan}
Let $\mathcal{A}$ be an additive category. Let $a, b : U \to V$ be morphisms
of cosimplicial objects of $\mathcal{A}$. If $a$, $b$ are homotopic,
then $s(a), s(b) : s(U) \to s(V)$ are homotopic maps of cochain complexes.
If in addition $\mathcal{A}$ is abelian, then $Q(a), Q(b) : Q(U) \to Q(V)$
are homotopic maps of cochain complexes.

\label{definition-trivial-kan}
A map $X \to Y$ of simplicial sets is called a {\it trivial Kan fibration}
if $X_0 \to Y_0$ is surjective and for all $n \geq 1$ and any commutative
solid diagram
$$
\xymatrix{
\partial \Delta[n] \ar[r] \ar[d] & X \ar[d] \\
\Delta[n] \ar[r] \ar@{-->}[ru] & Y
}
$$
a dotted arrow exists making the diagram commute.

\label{lemma-product-trivial-kan}
\begin{slogan}
Products of trivial Kan fibrations are trivial Kan fibrations.
\end{slogan}
Let $X_i \to Y_i$ be a set of trivial Kan fibrations. Then
$\prod X_i \to \prod Y_i$ is a trivial Kan fibration.

\label{lemma-trivial-kan-homotopy}
Let $f : X \to Y$ be a trivial Kan fibration of simplicial sets.
Then $f$ is a homotopy equivalence.

\label{definition-kan}
A map $X \to Y$ of simplicial sets is called a {\it Kan fibration}
if for all $k, n$ with $1 \leq n$, $0 \leq k \leq n$ and any commutative
solid diagram
$$
\xymatrix{
\Lambda_k[n] \ar[r] \ar[d] & X \ar[d] \\
\Delta[n] \ar[r] \ar@{-->}[ru] & Y
}
$$
a dotted arrow exists making the diagram commute. A {\it Kan complex}
is a simplicial set $X$ such that $X \to *$ is a Kan fibration, where
$*$ is the constant simplicial set on a singleton.

\label{lemma-product-kan}
Let $X_i \to Y_i$ be a set of Kan fibrations. Then
$\prod X_i \to \prod Y_i$ is a Kan fibration.

\label{lemma-standard-simplicial}
In Situation \ref{situation-adjoint-functors}
the system $X = (X_n, d^n_j, s^n_j)$
is a simplicial object of $\text{Fun}(\mathcal{A}, \mathcal{A})$
and $\epsilon_0$ defines an augmentation $\epsilon$ from $X$
to the constant simplicial object with value $X_{-1} = \text{id}_\mathcal{A}$.

\label{lemma-cohomology-of-open}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $U$ be an object of $\mathcal{C}$.
\begin{enumerate}
\item If $\mathcal{I}$ is an injective $\mathcal{O}$-module
then $\mathcal{I}|_U$ is an injective $\mathcal{O}_U$-module.
\item For any sheaf of $\mathcal{O}$-modules $\mathcal{F}$ we have
$H^p(U, \mathcal{F}) = H^p(\mathcal{C}/U, \mathcal{F}|_U)$.
\end{enumerate}

\label{lemma-cech-exact-presheaves}
The functor given by Equation (\ref{equation-cech-functor})
is an exact functor (see Homology, Lemma \ref{homology-lemma-exact-functor}).

\label{lemma-complex-tensored-still-exact}
\begin{slogan}
The integral presheaf {\v C}ech complex is a flat resolution of the
constant presheaf of integers.
\end{slogan}
Let $\mathcal{C}$ be a category. Let
$\mathcal{U} = \{f_i : U_i \to U\}_{i \in I}$ be a family of morphisms
with fixed target such that all fibre products
$U_{i_0} \times_U \ldots \times_U U_{i_p}$ exist in $\mathcal{C}$.
Let $\mathcal{O}$ be a presheaf of rings on $\mathcal{C}$.
The chain complex
$$
\mathbf{Z}_{\mathcal{U}, \bullet}
\otimes_{p, \mathbf{Z}}
\mathcal{O}
$$
is exact in positive degrees. Here $\mathbf{Z}_{\mathcal{U}, \bullet}$
is the chain complex of Lemma \ref{lemma-cech-map-into}, and
the tensor product is over the constant presheaf of rings
with value $\mathbf{Z}$.

\label{lemma-injective-abelian-sheaf-injective-presheaf}
Let $\mathcal{C}$ be a site. An injective abelian sheaf is also injective as an
object in the category $\textit{PAb}(\mathcal{C})$.

\label{lemma-bounded-flat-K-flat}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. A bounded above complex
of flat $\mathcal{O}$-modules is K-flat.

\label{lemma-flat-tor-zero}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $\mathcal{F}$ be an $\mathcal{O}$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}$-module, and
\item $\text{Tor}_1^\mathcal{O}(\mathcal{F}, \mathcal{G}) = 0$
for every $\mathcal{O}$-module $\mathcal{G}$.
\end{enumerate}

\label{lemma-check-K-flat-stalks}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $\mathcal{K}^\bullet$ be a complex of $\mathcal{O}$-modules.
\begin{enumerate}
\item If $\mathcal{K}^\bullet$ is K-flat, then for every point $p$
of the site $\mathcal{C}$ the complex of $\mathcal{O}_p$-modules
$\mathcal{K}_p^\bullet$ is K-flat in the sense of
More on Algebra, Definition \ref{more-algebra-definition-K-flat}
\item If $\mathcal{C}$ has enough points, then the converse is true.
\end{enumerate}

\label{lemma-tensor-pull-compatibility}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $\mathcal{K}^\bullet$ and $\mathcal{M}^\bullet$
be complexes of $\mathcal{O}_\mathcal{D}$-modules.
The diagram
$$
\xymatrix{
Lf^*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
\mathcal{M}^\bullet) \ar[r] \ar[d] &
Lf^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
\mathcal{M}^\bullet) \ar[d] \\
Lf^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
Lf^*\mathcal{M}^\bullet \ar[d] &
f^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
\mathcal{M}^\bullet) \ar[d] \\
f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
f^*\mathcal{M}^\bullet \ar[r] &
\text{Tot}(f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}
f^*\mathcal{M}^\bullet)
}
$$
commutes.

\label{lemma-is-limit}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E \in D(\mathcal{O})$.
Assume there exists a function $p(-) : \mathbf{Z} \to \mathbf{Z}$
and a subset $\mathcal{B} \subset \Ob(\mathcal{C})$ such that
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item $H^p(V, H^{m - p}(E)) = 0$ for $p > p(m)$ and $V \in \mathcal{B}$.
\end{enumerate}
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-is-limit-dimension}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E \in D(\mathcal{O})$.
Assume there exists an integer $d \geq 0$
and a subset $\mathcal{B} \subset \Ob(\mathcal{C})$ such that
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item $H^p(V, H^q(E)) = 0$ for $p > d$, $q < 0$, and $V \in \mathcal{B}$.
\end{enumerate}
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-derived-limit-suitable-system}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $(K_n)$
be an inverse system of objects of $D(\mathcal{O})$.
Let $\mathcal{B} \subset \Ob(\mathcal{C})$ be a subset. Assume
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item for all $U \in \mathcal{B}$ and all $q \in \mathbf{Z}$ we have
\begin{enumerate}
\item $H^p(U, H^q(K_n)) = 0$ for $p > 0$,
\item the inverse system $H^0(U, H^q(K_n))$ has vanishing $R^1\lim$.
\end{enumerate}
\end{enumerate}
Then $H^q(R\lim K_n) = \lim H^q(K_n)$ for $q \in \mathbf{Z}$.

\label{lemma-olsson-laszlo}
\begin{reference}
This is \cite[Proposition 2.1.4]{six-I} with slightly changed
hypotheses; it is the analogue of \cite[Proposition 3.13]{Spaltenstein}
for sites.
\end{reference}
In Situation \ref{situation-olsson-laszlo} for any
$E \in D_\mathcal{A}(\mathcal{O})$ the map
$E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-bounded-in-image-upstairs}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $K$ be an object of $D(\mathcal{O}_\mathcal{C})$. Assume
\begin{enumerate}
\item $f$ is flat,
\item $K$ is bounded below,
\item $f^*Rf_*H^q(K) \to H^q(K)$ is an isomorphism.
\end{enumerate}
Then $f^*Rf_*K \to K$ is an isomorphism.

\label{lemma-bounded-in-image-downstairs}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $K$ be an object of $D(\mathcal{O}_\mathcal{D})$. Assume
\begin{enumerate}
\item $f$ is flat,
\item $K$ is bounded below,
\item $H^q(K) \to Rf_*f^*H^q(K)$ is an isomorphism.
\end{enumerate}
Then $K \to Rf_*f^*K$ is an isomorphism.

\label{lemma-descent-squares-helper}
With $\epsilon : (\mathcal{C}_\tau, \mathcal{O}_\tau) \to
(\mathcal{C}_{\tau'}, \mathcal{O}_{\tau'})$ as above. Let
$$
\xymatrix{
E \ar[d] \ar[r] & Y \ar[d] \\
Z \ar[r] & X
}
$$
be a commutative diagram in the category $\mathcal{C}$ such that
\begin{enumerate}
\item $h_X^\# = h_Y^\# \amalg_{h_E^\#} h_Z^\#$, and
\item $h_E^\# \to h_Y^\#$ is injective
\end{enumerate}
where ${}^\#$ denotes $\tau$-sheafification. Then for
$K' \in D(\mathcal{O}_{\tau'})$ in the essential image of
$R\epsilon_*$ the map $c^{K'}_{X, Z, Y, E}$ of Lemma \ref{lemma-c-square}
(using the $\tau'$-topology) is an isomorphism.

\label{lemma-compare-cohomology-general}
In Situation \ref{situation-compare}. Let $X$ be in $\mathcal{C}$.
\begin{enumerate}
\item for $\mathcal{F}'$ in $\mathcal{A}'_X$ we have
$H^n_{\tau'}(X, \mathcal{F}') = H^n_\tau(X, \epsilon_X^{-1}\mathcal{F}')$,
\item for $K' \in D^+_{\mathcal{A}'_X}(\mathcal{C}_{\tau'}/X)$
we have $H^n_{\tau'}(X, K') = H^n_\tau(X, \epsilon_X^{-1}K')$.
\end{enumerate}

\label{lemma-push-pull-LC}
Let $f : X \to Y$ be a morphism of $\textit{LC}_{qc}$.
Then there are commutative diagrams of topoi
$$
\vcenter{
\xymatrix{
\Sh(\textit{LC}_{qc}/X) \ar[r]_{f_{qc}} \ar[d]_{\epsilon_X} &
\Sh(\textit{LC}_{qc}/Y) \ar[d]^{\epsilon_Y} \\
\Sh(\textit{LC}_{Zar}/X) \ar[r]^{f_{Zar}} &
\Sh(\textit{LC}_{Zar}/Y)
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Sh(\textit{LC}_{qc}/X) \ar[r]_{f_{qc}} \ar[d]_{a_X} &
\Sh(\textit{LC}_{qc}/Y) \ar[d]^{a_Y} \\
\Sh(X) \ar[r]^f &
\Sh(Y)
}
}
$$
with $a_X = \pi_X \circ \epsilon_X$, $a_Y = \pi_X \circ \epsilon_X$.
If $f$ is proper, then $a_Y^{-1} \circ f_* = f_{qc, *} \circ a_X^{-1}$.

\label{lemma-compare-cohomology-LC}
With $X \in \Ob(\textit{LC}_{qc})$ and
$a_X : \Sh(\textit{LC}_{qc}/X) \to \Sh(X)$ as above:
\begin{enumerate}
\item for an abelian sheaf $\mathcal{F}$ on $X$ we have
$H^n(X, \mathcal{F}) = H^n_{qc}(X, a_X^{-1}\mathcal{F})$,
\item for $K \in D^+(X)$ we have $H^n(X, K) = H^n_{qc}(X, a_X^{-1}K)$.
\end{enumerate}
For example, if $A$ is an abelian group, then we have
$H^n(X, \underline{A}) = H^n_{qc}(X, \underline{A})$.

\label{lemma-cup-compatible-with-naive}
In the situation above the following diagram commutes
$$
\xymatrix{
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
f_*\mathcal{M}^\bullet \ar[r] \ar[d]
&
Rf_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
Rf_*\mathcal{M}^\bullet \ar[d]^{\text{Remark \ref{remark-cup-product}}} \\
\text{Tot}(
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
f_*\mathcal{M}^\bullet) \ar[d]_{\text{naive cup product}} &
Rf_*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
\mathcal{M}^\bullet) \ar[d] \\
f_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet) \ar[r] &
Rf_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet)
}
$$

\label{lemma-cup-product-associative}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}) \to (\Sh(\mathcal{C}'), \mathcal{O}')$
be a morphism of ringed topoi. The relative cup product of
Remark \ref{remark-cup-product} is associative in the sense that
the diagram
$$
\xymatrix{
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_\mathcal{O}^\mathbf{L} L)
\otimes_{\mathcal{O}'}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*(L \otimes_\mathcal{O}^\mathbf{L} M) \ar[r] &
Rf_*(K \otimes_\mathcal{O}^\mathbf{L} 
L \otimes_\mathcal{O}^\mathbf{L} M)
}
$$
is commutative in $D(\mathcal{O}')$ for all $K, L, M$ in $D(\mathcal{O})$.

\label{lemma-cone}
The cone on a morphism of strictly perfect complexes is
strictly perfect.

\label{lemma-tensor}
The total complex associated to the tensor product of two
strictly perfect complexes is strictly perfect.

\label{lemma-cone-pseudo-coherent}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site and $m \in \mathbf{Z}$.
Let $(K, L, M, f, g, h)$ be a distinguished triangle in $D(\mathcal{O})$.
\begin{enumerate}
\item If $K$ is $(m + 1)$-pseudo-coherent and $L$ is $m$-pseudo-coherent
then $M$ is $m$-pseudo-coherent.
\item If $K$ and $M$ are $m$-pseudo-coherent, then $L$ is $m$-pseudo-coherent.
\item If $L$ is $(m + 1)$-pseudo-coherent and $M$
is $m$-pseudo-coherent, then $K$ is $(m + 1)$-pseudo-coherent.
\end{enumerate}

\label{lemma-finite-cohomology}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $K$ be an object of
$D(\mathcal{O})$. Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m$, then $H^m(K)$ is a finite type $\mathcal{O}$-module.
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m + 1$, then $H^{m + 1}(K)$ is a finitely presented
$\mathcal{O}$-module.
\end{enumerate}

\label{definition-tor-amplitude}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
Let $a, b \in \mathbf{Z}$ with $a \leq b$.
\begin{enumerate}
\item We say $E$ has {\it tor-amplitude in $[a, b]$}
if $H^i(E \otimes_\mathcal{O}^\mathbf{L} \mathcal{F}) = 0$
for all $\mathcal{O}$-modules $\mathcal{F}$ and all $i \not \in [a, b]$.
\item We say $E$ has {\it finite tor dimension}
if it has tor-amplitude in $[a, b]$ for some $a, b$.
\item We say $E$ {\it locally has finite tor dimension} if for any
object $U$ of $\mathcal{C}$ there exists a covering $\{U_i \to U\}$
such that $E|_{U_i}$ has finite tor dimension for all $i$.
\end{enumerate}
An $\mathcal{O}$-module $\mathcal{F}$ has {\it tor dimension $\leq d$}
if $\mathcal{F}[0]$ viewed as an object of $D(\mathcal{O})$ has
tor-amplitude in $[-d, 0]$.

\label{lemma-tor-amplitude}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E$ be an object of
$D(\mathcal{O})$. Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following
are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item $E$ is represented by a complex
$\mathcal{E}^\bullet$ of flat $\mathcal{O}$-modules with
$\mathcal{E}^i = 0$ for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-tor-amplitude-stalk}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
Let $a, b \in \mathbf{Z}$.
\begin{enumerate}
\item If $E$ has tor amplitude in $[a, b]$, then for every point $p$
of the site $\mathcal{C}$ the object $E_p$ of $D(\mathcal{O}_p)$
has tor amplitude in $[a, b]$.
\item If $\mathcal{C}$ has enough points, then the converse is true.
\end{enumerate}

\label{lemma-perfect}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
The following are equivalent
\begin{enumerate}
\item $E$ is perfect, and
\item $E$ is pseudo-coherent and locally has finite tor dimension.
\end{enumerate}

\label{lemma-when-jshriek-compact}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $U$ be an object of
$\mathcal{C}$. The $\mathcal{O}$-module $j_!\mathcal{O}_U$ is a
compact object of $D(\mathcal{O})$ if there exists an integer $d$ such that
\begin{enumerate}
\item $H^p(U, \mathcal{F}) = 0$ for all $p > d$, and
\item the functors $\mathcal{F} \mapsto H^p(U, \mathcal{F})$
commute with direct sums.
\end{enumerate}

\label{lemma-limits-colimits-abelian-presheaves}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item All limits and colimits exist in $\textit{PAb}(\mathcal{C})$.
\item All limits and colimits commute with taking sections over objects of
$\mathcal{C}$.
\end{enumerate}

\label{definition-2-morphism-ringed-topoi}
Let
$f, g :
(\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be two morphisms of ringed topoi. A {\it 2-morphism from $f$ to $g$}
is given by a transformation of functors $t : f_* \to g_*$ such that
$$
\xymatrix{
& \mathcal{O}_\mathcal{D}
\ar[ld]_{f^\sharp}
\ar[rd]^{g^\sharp} \\
f_*\mathcal{O}_\mathcal{C} \ar[rr]^t & &
g_*\mathcal{O}_\mathcal{C}
}
$$
is commutative.

\label{lemma-exactness-pushforward-pullback}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to (\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi.
\begin{enumerate}
\item The functor $f_*$ is left exact. In fact it commutes with
all limits.
\item The functor $f^*$ is right exact. In fact it commutes
with all colimits.
\end{enumerate}

\label{lemma-special-locally-free}
Any of the properties (1) -- (8) of Definition \ref{definition-site-local}
is intrinsic (see discussion in Section \ref{section-intrinsic}).

\label{lemma-colimits-flat}
Colimits and tensor product.
\begin{enumerate}
\item A filtered colimit of flat presheaves of modules
is flat. A direct sum of flat presheaves of modules is flat.
\item A filtered colimit of flat sheaves of modules is flat.
A direct sum of flat sheaves of modules is flat.
\end{enumerate}

\label{lemma-flat-eq}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $\mathcal{F}$ be an
$\mathcal{O}$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}$-module.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U \xrightarrow{(f_1, \ldots, f_n)}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ (f_1, \ldots, f_n)|_{U_i} = 0$.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U^{\oplus m} \xrightarrow{A}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ A|_{U_i} = 0$.
\end{enumerate}

\label{lemma-module-quotient-direct-sum}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}) holds.
\begin{enumerate}
\item Every sheaf of sets is the target of a surjective map
whose source is a coproduct $\coprod h_{U_i}^\#$ with $U_i$ in $\mathcal{B}$.
\item If $\mathcal{O}$ is a sheaf of rings, then every $\mathcal{O}$-module
is a quotient of a direct sum $\bigoplus\nolimits j_{U_i!}\mathcal{O}_{U_i}$
with $U_i$ in $\mathcal{B}$.
\end{enumerate}

\label{lemma-module-filtered-colimit-constructibles}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}) and (\ref{item-enough-qc}) hold.
\begin{enumerate}
\item Every sheaf of sets is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible-sets}
\text{Coequalizer}\left(
\xymatrix{
\coprod\nolimits_{j = 1, \ldots, m} h_{V_j}^\#
\ar@<1ex>[r] \ar@<-1ex>[r] &
\coprod\nolimits_{i = 1, \ldots, n} h_{U_i}^\#
}
\right)
\end{equation}
with $U_i$ and $V_j$ in $\mathcal{B}$.
\item If $\mathcal{O}$ is a sheaf of rings, then every $\mathcal{O}$-module
is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible}
\Coker\left(
\bigoplus\nolimits_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
\right)
\end{equation}
with $U_i$ and $V_j$ in $\mathcal{B}$.
\end{enumerate}

\label{lemma-change-presentation-towards-constructibles}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}), (\ref{item-enough-qc}), and (\ref{item-enough-qc-qs})
hold. Let $\mathcal{O}$ be a sheaf of rings. Assume given a map
$$
\bigoplus\nolimits_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
$$
with $U_i$ and $V_j$ in $\mathcal{B}$, and coverings
$\{U_{ik} \to U_i\}_{k \in K_i}$ with $U_{ik} \in \mathcal{B}$.
Then there exist finite subsets $K'_i \subset K_i$ and
a finite set $L$ of $W_l \in \mathcal{B}$ and a commutative diagram
$$
\xymatrix{
\bigoplus_{l \in L} j_{W_l!}\mathcal{O}_{W_l} \ar[d] \ar[r] &
\bigoplus_{i = 1, \ldots, n} \bigoplus_{k \in K'_i}
j_{U_{ik}!}\mathcal{O}_{U_{ik}} \ar[d] \\
\bigoplus_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j} \ar[r] &
\bigoplus_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
}
$$
inducing an isomorphism on cokernels of the horizontal maps.

\label{lemma-constructions-invertible}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
\begin{enumerate}
\item If $\mathcal{L}$, $\mathcal{N}$ are invertible
$\mathcal{O}$-modules, then so is
$\mathcal{L} \otimes_\mathcal{O} \mathcal{N}$.
\item If $\mathcal{L}$ is an invertible
$\mathcal{O}$-module, then so is
$\SheafHom_\mathcal{O}(\mathcal{L}, \mathcal{O})$ and the evaluation map
$\mathcal{L} \otimes_\mathcal{O}
\SheafHom_\mathcal{O}(\mathcal{L}, \mathcal{O}) \to \mathcal{O}$
is an isomorphism.
\end{enumerate}

\label{lemma-NL-up-to-qis}
In the situation above there is a canonical isomorphism
$\NL(\alpha) = \NL_{\mathcal{B}/\mathcal{A}}$ in $D(\mathcal{B})$.

\label{lemma-skyscraper-modules-exact}
Let $(\Sh(\mathcal{C}), \mathcal{O})$ be a ringed topos.
Let $p$ be a point of the topos $\Sh(\mathcal{C})$.
\begin{enumerate}
\item The functor
$p_* : \textit{Mod}(\mathcal{O}_p) \to \textit{Mod}(\mathcal{O})$,
$M \mapsto p_*M$ is exact.
\item The canonical surjection $p^{-1}p_*M \to M$ is $\mathcal{O}_p$-linear.
\item The functorial direct sum decomposition
$p^{-1}p_*M = M \oplus I(M)$ of Lemma \ref{lemma-skyscraper-exact}
is {\bf not} $\mathcal{O}_p$-linear in general.
\end{enumerate}

\label{lemma-pullback-flat}
\begin{reference}
\cite[Expos\'e V, Corollary 1.7.1]{SGA4}
\end{reference}
Let
$(f, f^\sharp) :
(\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi or ringed sites.
Then $f^*\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{C}$-module
whenever $\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{D}$-module.

\label{lemma-ringed-stalk-not-zero}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Consider the statements
\begin{enumerate}
\item (\ref{equation-one-is-never-zero}) is an isomorphism, and
\item for every point $p$ of $\mathcal{C}$ the stalk $\mathcal{O}_p$
is not the zero ring.
\end{enumerate}
We always have (1) $\Rightarrow$ (2) and if $\mathcal{C}$ has enough points
then (1) $\Leftrightarrow$ (2).

\label{definition-locally-ringed}
A ringed site $(\mathcal{C}, \mathcal{O})$ is said to be
{\it locally ringed site} if (\ref{equation-one-is-never-zero})
is an isomorphism, and the equivalent properties of
Lemma \ref{lemma-locally-ringed}
are satisfied.

\label{lemma-locally-constant-finite-type}
Let $\mathcal{C}$ be a site. Let $\Lambda$ be a ring and let $M$ be a
$\Lambda$-module. Assume $\Sh(\mathcal{C})$ is not the empty topos. Then
\begin{enumerate}
\item $\underline{M}$ is a finite type sheaf of $\underline{\Lambda}$-modules
if and only if $M$ is a finite $\Lambda$-module, and
\item $\underline{M}$ is a finitely presented sheaf of
$\underline{\Lambda}$-modules if and only if $M$ is a 
finitely presented $\Lambda$-module.
\end{enumerate}

\label{definition-presheaves-injective-surjective}
Let $\mathcal{C}$ be a category, and let $\varphi : \mathcal{F}
\to \mathcal{G}$ be a map of presheaves of sets.
\begin{enumerate}
\item We say that $\varphi$ is {\it injective} if for every object
$U$ of $\mathcal{C}$ the map $\varphi_U : \mathcal{F}(U)
\to \mathcal{G}(U)$ is injective.
\item We say that $\varphi$ is {\it surjective} if for every object
$U$ of $\mathcal{C}$ the map $\varphi_U : \mathcal{F}(U)
\to \mathcal{G}(U)$ is surjective.
\end{enumerate}

\label{definition-image}
Notation as in Lemma \ref{lemma-image}. We
say that $\mathcal{G}'$ is the {\it image of $\varphi$}.

\label{lemma-pullback-representable-presheaf}
Let $u : \mathcal{C} \to \mathcal{D}$ be a functor between categories.
For any object $U$ of $\mathcal{C}$ we have $u_ph_U = h_{u(U)}$.

\label{definition-sheaf-sets}
Let $\mathcal{C}$ be a site, and let $\mathcal{F}$ be a presheaf of sets
on $\mathcal{C}$. We say $\mathcal{F}$ is a {\it sheaf} if
for every covering $\{U_i \to U\}_{i \in I} \in \text{Cov}(\mathcal{C})$
the diagram
\begin{equation}
\label{equation-sheaf-condition}
\xymatrix{
\mathcal{F}(U) \ar[r]
&
\prod\nolimits_{i\in I}
\mathcal{F}(U_i)
\ar@<1ex>[r]^-{\text{pr}_0^*} \ar@<-1ex>[r]_-{\text{pr}_1^*}
&
\prod\nolimits_{(i_0, i_1) \in I \times I}
\mathcal{F}(U_{i_0} \times_U U_{i_1})
}
\end{equation}
represents the first arrow as the equalizer of $\text{pr}_0^*$
and $\text{pr}_1^*$.

\label{definition-category-sheaves-sets}
The category {\it $\Sh(\mathcal{C})$}
of sheaves of sets is the full subcategory of the category
$\textit{PSh}(\mathcal{C})$ whose objects are the sheaves of sets.

\label{definition-sheaf}
Let $\mathcal{C}$ be a site, let $\mathcal{A}$ be a category
and let $\mathcal{F}$ be a presheaf on $\mathcal{C}$ with values in
$\mathcal{A}$. We say that $\mathcal{F}$ is a {\it sheaf}
if for all objects $X$ of $\mathcal{A}$ the presheaf of sets
$\mathcal{F}_X$ (defined above) is a sheaf.

\label{lemma-limit-sheaf}
\begin{slogan}
Limit of diagram of sheaves exists and coincides with limit as presheaves
\end{slogan}
Let $\mathcal{F} : \mathcal{I} \to \Sh(\mathcal{C})$
be a diagram. Then $\lim_\mathcal{I} \mathcal{F}$ exists
and is equal to the limit in the category of presheaves.

\label{theorem-plus}
With $\mathcal{F}$ as above
\begin{enumerate}
\item
\label{item-sep}
The presheaf $\mathcal{F}^+$ is separated.
\item
\label{item-sheaf}
If $\mathcal{F}$ is separated, then $\mathcal{F}^+$ is a sheaf
and the map of presheaves $\mathcal{F} \to \mathcal{F}^+$ is injective.
\item
\label{item-plus-iso}
If $\mathcal{F}$ is a sheaf, then $\mathcal{F} \to \mathcal{F}^+$
is an isomorphism.
\item
\label{item-plusplus}
The presheaf $\mathcal{F}^{++}$ is always a sheaf.
\end{enumerate}

\label{lemma-colimit-sheaves}
\begin{slogan}
Colimit in category of sheaves equals sheafification of colimit in
category of presheaves.
\end{slogan}
Let $\mathcal{F} : \mathcal{I} \to \Sh(\mathcal{C})$
be a diagram. Then $\colim_\mathcal{I} \mathcal{F}$ exists
and is the sheafification of the colimit in the category of presheaves.

\label{lemma-sheafification-exact}
The functor $\textit{PSh}(\mathcal{C}) \to \Sh(\mathcal{C})$,
$\mathcal{F} \mapsto \mathcal{F}^\#$ is exact.

\label{definition-sheaves-injective-surjective}
Let $\mathcal{C}$ be a site, and let $\varphi : \mathcal{F}
\to \mathcal{G}$ be a map of sheaves of sets.
\begin{enumerate}
\item We say that $\varphi$ is {\it injective} if for every object
$U$ of $\mathcal{C}$ the map $\varphi : \mathcal{F}(U)
\to \mathcal{G}(U)$ is injective.
\item We say that $\varphi$ is {\it surjective} if for every object
$U$ of $\mathcal{C}$ and every section $s\in \mathcal{G}(U)$
there exists a covering $\{U_i \to U\}$ such that for
all $i$ the restriction $s|_{U_i}$ is in the image of
$\varphi : \mathcal{F}(U_i) \to \mathcal{G}(U_i)$.
\end{enumerate}

\label{lemma-coequalizer-surjection}
Let $\mathcal{C}$ be a site. Let $\mathcal{F} \to \mathcal{G}$
be a surjection of sheaves of sets. Then the diagram
$$
\xymatrix{
\mathcal{F} \times_\mathcal{G} \mathcal{F}
\ar@<1ex>[r] \ar@<-1ex>[r]
&
\mathcal{F} \ar[r]
&
\mathcal{G}}
$$
represents $\mathcal{G}$ as a coequalizer.

\label{lemma-composition-morphisms-sites}
\begin{slogan}
Composition of site functors respects continuity of site functors.
\end{slogan}
Let $\mathcal{C}_i$, $i = 1, 2, 3$ be sites. Let
$u : \mathcal{C}_2 \to \mathcal{C}_1$ and
$v : \mathcal{C}_3 \to \mathcal{C}_2$ be continuous functors
which induce morphisms of sites. Then the functor
$u \circ v : \mathcal{C}_3 \to \mathcal{C}_1$ is continuous and
defines a morphism of sites $\mathcal{C}_1 \to \mathcal{C}_3$.

\label{lemma-quasi-compact}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $U$ is quasi-compact, and
\item for every surjection of sheaves
$\coprod_{i \in I} \mathcal{F}_i \to h_U^\#$
there is a finite subset $J \subset I$ such that
$\coprod_{i \in J} \mathcal{F}_i \to h_U^\#$ is surjective.
\end{enumerate}

\label{definition-quasi-compact-topos}
An object $\mathcal{F}$ of a topos $\Sh(\mathcal{C})$ is {\it quasi-compact}
if for any surjective map $\coprod_{i \in I} \mathcal{F}_i \to \mathcal{F}$
of $\Sh(\mathcal{C})$ there exists a finite subset $J \subset I$ such
that $\coprod_{i \in J} \mathcal{F}_i \to \mathcal{F}$ is surjective.
A topos $\Sh(\mathcal{C})$ is said to be {\it quasi-compact}
if its final object $*$ is a quasi-compact object.

\label{lemma-image-of-quasi-compact}
\begin{slogan}
Sheaf surjections transmit quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item If $U \to V$ is a morphism of $\mathcal{C}$ such that
$h_U^\# \to h_V^\#$ is surjective and $U$ is quasi-compact, then
$V$ is quasi-compact.
\item If $\mathcal{F} \to \mathcal{G}$ is a surjection of sheaves
of sets and $\mathcal{F}$ is quasi-compact, then $\mathcal{G}$
is quasi-compact.
\end{enumerate}

\label{lemma-coproduct-quasi-compact}
\begin{slogan}
Finite copoducts of sheaves conserve quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site. If $n \geq 1$ and
$\mathcal{F}_1, \ldots, \mathcal{F}_n$ are quasi-compact
sheaves on $\mathcal{C}$, then $\coprod_{i = 1, \ldots, n} \mathcal{F}_i$
is quasi-compact.

\label{lemma-colimit-sites}
In Situation \ref{situation-inverse-limit-sites} we can construct
a site $(\mathcal{C}, \text{Cov}(\mathcal{C}))$ as follows
\begin{enumerate}
\item as a category $\mathcal{C} = \colim \mathcal{C}_i$, and
\item $\text{Cov}(\mathcal{C})$ is the union of the images
of $\text{Cov}(\mathcal{C}_i)$ by $u_i : \mathcal{C}_i \to \mathcal{C}$.
\end{enumerate}

\label{lemma-compute-pullback-to-limit}
In Situation \ref{situation-inverse-limit-sites} let
$u_i : \mathcal{C}_i \to \mathcal{C}$ be as constructed in
Lemma \ref{lemma-colimit-sites}. Then $u_i$ defines a morphism
of sites $f_i : \mathcal{C} \to \mathcal{C}_i$. For
$U_i \in \Ob(\mathcal{C}_i)$ and sheaf $\mathcal{F}$ on $\mathcal{C}_i$ we have
\begin{equation}
\label{equation-compute-pullback-to-limit}
f_i^{-1}\mathcal{F}(u_i(U_i)) =
\colim_{a : j \to i} f_a^{-1}\mathcal{F}(u_a(U_i))
\end{equation}

\label{lemma-when-shriek}
\begin{slogan}
Sheafification is redundant in topoi morphisms associated to simultaneously
continuous and cocontinuous site functors.
\end{slogan}
Let $\mathcal{C}$ and $\mathcal{D}$ be sites.
Let $u : \mathcal{C} \to \mathcal{D}$ be a functor.
Assume that
\begin{enumerate}
\item[(a)] $u$ is cocontinuous, and
\item[(b)] $u$ is continuous.
\end{enumerate}
Let $g : \Sh(\mathcal{C}) \to \Sh(\mathcal{D})$
be the associated morphism of topoi. Then
\begin{enumerate}
\item sheafification in the formula $g^{-1} = (u^p\ )^\#$ is
unnecessary, in other words $g^{-1}(\mathcal{G})(U) = \mathcal{G}(u(U))$,
\item $g^{-1}$ has a left adjoint $g_{!} = (u_p\ )^\#$, and
\item $g^{-1}$ commutes with arbitrary limits and colimits.
\end{enumerate}

\label{lemma-existence-lower-shriek}
Let $\mathcal{C}$, $\mathcal{D}$ be two sites.
Let $f : \Sh(\mathcal{D}) \to \Sh(\mathcal{C})$ be a morphism of topoi.
Let $E \subset \Ob(\mathcal{D})$ be a subset such that
\begin{enumerate}
\item for $V \in E$ there exists a sheaf $\mathcal{G}$
on $\mathcal{C}$ such that $f^{-1}\mathcal{F}(V) = 
\Mor_{\Sh(\mathcal{C})}(\mathcal{G}, \mathcal{F})$ functorially
for $\mathcal{F}$ in $\Sh(\mathcal{C})$,
\item every object of $\mathcal{D}$ has a covering by objects of $E$.
\end{enumerate}
Then $f^{-1}$ has a left adjoint $f_!$.

\label{lemma-j-shriek-reflects-injections-surjections}
Let $\mathcal{C}$ be a site. Let $U \in \Ob(\mathcal{C})$.
The functor $j_{U!}$ reflects injections and surjections.

\label{lemma-localize-cartesian-square}
Let $\mathcal{C}$ be a site. Let
$$
\xymatrix{
U' \ar[d] \ar[r] & U \ar[d] \\
V' \ar[r] & V
}
$$
be a commutative diagram of $\mathcal{C}$. The
morphisms of Lemma \ref{lemma-relocalize}
produce commutative diagrams
$$
\vcenter{
\xymatrix{
\mathcal{C}/U' \ar[d]_{j_{U'/V'}} \ar[r]_{j_{U'/U}} &
\mathcal{C}/U \ar[d]^{j_{U/V}} \\
\mathcal{C}/V' \ar[r]^{j_{V'/V}} & \mathcal{C}/V
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Sh(\mathcal{C}/U') \ar[d]_{j_{U'/V'}} \ar[r]_{j_{U'/U}} &
\Sh(\mathcal{C}/U) \ar[d]^{j_{U/V}} \\
\Sh(\mathcal{C}/V') \ar[r]^{j_{V'/V}} &
\Sh(\mathcal{C}/V)
}
}
$$
of continuous and cocontinuous functors and of topoi.
Moreover, if the initial diagram of $\mathcal{C}$ is cartesian,
then we have
$j_{V'/V}^{-1} \circ j_{U/V, *} = j_{U'/V', *} \circ j_{U'/U}^{-1}$.

\label{definition-special-cocontinuous-functor}
Let $\mathcal{C}$, $\mathcal{D}$ be sites.
A {\it special cocontinuous functor $u$ from $\mathcal{C}$ to $\mathcal{D}$}
is a cocontinuous functor $u : \mathcal{C} \to \mathcal{D}$ satisfying
the assumptions and conclusions of Lemma \ref{lemma-equivalence}.

\label{definition-localize-topos}
Let $\mathcal{C}$ be a site.
Let $\mathcal{F}$ be a sheaf on $\mathcal{C}$.
\begin{enumerate}
\item The topos $\Sh(\mathcal{C})/\mathcal{F}$
is called the
{\it localization of the topos $\Sh(\mathcal{C})$ at $\mathcal{F}$}.
\item The morphism of topoi
$j_\mathcal{F} :
\Sh(\mathcal{C})/\mathcal{F}
\to
\Sh(\mathcal{C})$ of
Lemma \ref{lemma-localize-topos}
is called the {\it localization morphism}.
\end{enumerate}

\label{lemma-localize-compare}
Let $\mathcal{C}$ be a site. Let $\mathcal{F} = h_U^\#$ for some object $U$
of $\mathcal{C}$. Then $j_\mathcal{F} : \Sh(\mathcal{C})/\mathcal{F}
\to \Sh(\mathcal{C})$ constructed in
Lemma \ref{lemma-localize-topos}
agrees with the morphism of topoi
$j_U : \Sh(\mathcal{C}/U) \to \Sh(\mathcal{C})$
constructed in
Section \ref{section-localize}
via the identification
$\Sh(\mathcal{C}/U) = \Sh(\mathcal{C})/h_U^\#$
of
Lemma \ref{lemma-essential-image-j-shriek}.

\label{definition-point-topos}
Let $\mathcal{C}$ be a site.
A {\it point of the topos $\Sh(\mathcal{C})$}
is a morphism of topoi $p$ from $\Sh(pt)$ to
$\Sh(\mathcal{C})$.

\label{definition-point}
Let $\mathcal{C}$ be a site. A {\it point $p$ of the site
$\mathcal{C}$} is given by a functor $u : \mathcal{C}
\to \textit{Sets}$ such that
\begin{enumerate}
\item For every covering $\{U_i \to U\}$ of $\mathcal{C}$ the map
$\coprod u(U_i) \to u(U)$ is surjective.
\item For every covering $\{U_i \to U\}$ of $\mathcal{C}$ and
every morphism $V \to U$ the maps
$u(U_i \times_U V) \to u(U_i) \times_{u(U)} u(V)$ are bijective.
\item The stalk functor $\Sh(\mathcal{C}) \to \textit{Sets}$,
$\mathcal{F} \mapsto \mathcal{F}_p$ is left exact.
\end{enumerate}

\label{proposition-point-limits}
Let $\mathcal{C}$ be a site. Assume that finite limits exist
in $\mathcal{C}$. (I.e., $\mathcal{C}$ has fibre products, and a
final object.) A point $p$ of such a site $\mathcal{C}$
is given by a functor $u : \mathcal{C} \to \textit{Sets}$ such that
\begin{enumerate}
\item $u$ commutes with finite limits, and
\item if $\{U_i \to U\}$ is a covering, then
$\coprod_i u(U_i) \to u(U)$ is surjective.
\end{enumerate}

\label{definition-2-morphism-topoi}
Let $f, g : \Sh(\mathcal{C}) \to \Sh(\mathcal{D})$
be two morphisms of topoi. A {\it 2-morphism from $f$ to $g$}
is given by a transformation of functors $t : f_* \to g_*$.

\label{definition-enough-points}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item A family of points $\{p_i\}_{i\in I}$ is called {\it conservative}
if every map of sheaves $\phi : \mathcal{F} \to \mathcal{G}$
which is an isomorphism on all the fibres $\mathcal{F}_{p_i}
\to \mathcal{G}_{p_i}$ is an isomorphism.
\item  We say that $\mathcal{C}$ {\it has enough points}
if there exists a conservative family of points.
\end{enumerate}

\label{lemma-enough-points-local}
Let $\mathcal{C}$ be a site. Let $\{U_i\}_{i \in I}$ be a family of
objects of $\mathcal{C}$. Assume
\begin{enumerate}
\item $\coprod h_{U_i}^\# \to *$ is a surjective map of sheaves, and
\item each localization $\mathcal{C}/U_i$ has enough points.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{proposition-criterion-points}
\begin{reference}
\cite[Expos\'e VI, Appendix by Deligne, Proposition 9.0]{SGA4}
\end{reference}
Let $\mathcal{C}$ be a site. Assume that
\begin{enumerate}
\item finite limits exist in $\mathcal{C}$, and
\item every covering $\{U_i \to U\}_{i \in I}$
has a refinement by a finite covering of $\mathcal{C}$.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{lemma-criterion-points}
Let $\mathcal{C}$ be a site. Let $I$ be a set and for
$i \in I$ let $U_i$ be an object of $\mathcal{C}$ such that
\begin{enumerate}
\item $\coprod h_{U_i}$ surjects onto
the final object of $\Sh(\mathcal{C})$, and
\item $\mathcal{C}/U_i$ satisfies the hypotheses of
Proposition \ref{proposition-criterion-points}.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{lemma-w-contractible}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following conditions are equivalent
\begin{enumerate}
\item For every covering $\{U_i \to U\}$ there exists a map of
sheaves $h_U^\# \to \coprod h_{U_i}^\#$ right inverse to the sheafification
of $\coprod h_{U_i} \to h_U$.
\item For every surjection of sheaves of sets $\mathcal{F} \to \mathcal{G}$
the map $\mathcal{F}(U) \to \mathcal{G}(U)$ is surjective.
\end{enumerate}

\label{definition-w-contractible}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item We say an object $U$ of $\mathcal{C}$ is {\it weakly contractible}
if the equivalent conditions of Lemma \ref{lemma-w-contractible} hold.
\item We say a site has {\it enough weakly contractible objects}
if every object $U$ of $\mathcal{C}$ has a covering $\{U_i \to U\}$
with $U_i$ weakly contractible for all $i$.
\item More generally, if $P$ is a property of objects of $\mathcal{C}$
we say that $\mathcal{C}$ has {\it enough $P$ objects} if every object $U$ of
$\mathcal{C}$ has a covering $\{U_i \to U\}$ such that $U_i$ has $P$
for all $i$.
\end{enumerate}

\label{lemma-open-subtopos}
Let $\mathcal{C}$ be a site. Let $\mathcal{F}$ be a sheaf on
$\mathcal{C}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a subobject of the final object of
$\Sh(\mathcal{C})$, and
\item the topos $\Sh(\mathcal{C})/\mathcal{F}$ is a subtopos of
$\Sh(\mathcal{C})$.
\end{enumerate}

\label{definition-open-subtopos}
Let $\mathcal{C}$ be a site. A strictly full subcategory
$E \subset \Sh(\mathcal{C})$ is an {\it open subtopos}
if there exists a subsheaf $\mathcal{F}$ of the final object
of $\Sh(\mathcal{C})$ such that $E$ is the subtopos
$\Sh(\mathcal{C})/\mathcal{F}$ described in Lemma \ref{lemma-open-subtopos}.

\label{definition-closed-subtopos}
Let $\mathcal{C}$ be a site. A strictly full subcategory
$E \subset \Sh(\mathcal{C})$ is an {\it closed subtopos}
if there exists a subsheaf $\mathcal{F}$ of the final object
of $\Sh(\mathcal{C})$ such that $E$ is the subtopos
described in Lemma \ref{lemma-closed-subtopos}.

\label{definition-immersion-topoi}
Let $f : \Sh(\mathcal{D}) \to \Sh(\mathcal{C})$ be a morphism of topoi.
\begin{enumerate}
\item We say $f$ is an {\it open immersion} if $f$ is an embedding
and the essential image of $f_*$ is an open subtopos.
\item We say $f$ is a {\it closed immersion} if $f$ is an embedding
and the essential image of $f_*$ is a closed subtopos.
\end{enumerate}

\label{lemma-compute-global-sections}
Let $\mathcal{C}$ be a site. Let $a, b : V \to U$ be objects of $\mathcal{C}$
such that
$$
\xymatrix{
h_V^\# \ar@<1ex>[r] \ar@<-1ex>[r] & h_U^\# \ar[r] & {*}
}
$$
is a coequalizer in $\Sh(\mathcal{C})$. Then
$\Gamma(\mathcal{C}, \mathcal{F})$ is the equalizer of
$a^*, b^* : \mathcal{F}(U) \to \mathcal{F}(V)$.

\label{definition-sieve}
Let $\mathcal{C}$ be a category. Let $U \in \Ob(\mathcal{C})$.
A {\it sieve $S$ on $U$} is a subpresheaf $S \subset h_U$.

\label{lemma-topology-basic}
Let $\mathcal{C}$ be a category.
Let $J$ be a topology on $\mathcal{C}$.
Let $U \in \Ob(\mathcal{C})$.
\begin{enumerate}
\item Finite intersections of elements of $J(U)$ are in $J(U)$.
\item If $S \in J(U)$ and $S' \supset S$, then $S' \in J(U)$.
\end{enumerate}

\label{lemma-play-with-topologies}
Let $\mathcal{C}$ be a category.
Let $\{J_i\}_{i\in I}$ be a set of topologies.
\begin{enumerate}
\item The rule $J(U) = \bigcap J_i(U)$ defines
a topology on $\mathcal{C}$.
\item There is a coarsest topology finer than
all of the topologies $J_i$.
\end{enumerate}

\label{lemma-sieve-sheafification}
Let $\mathcal{C}$ be a category endowed with a topology $J$.
Let $U$ be an object of $\mathcal{C}$.
Let $S$ be a sieve on $U$. The following are equivalent
\begin{enumerate}
\item The sieve $S$ is a covering sieve.
\item The sheafification $S^\# \to h_U^\#$
of the map $S \to h_U$ is an isomorphism.
\end{enumerate}

\label{theorem-topology-and-topos}
Let $\mathcal{C}$ be a category.
Let $J$, $J'$ be topologies on $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $J = J'$,
\item sheaves for the topology $J$ are the same as
sheaves for the topology $J'$.
\end{enumerate}

\label{definition-strictly-standard}
Let $R \to A$ be a ring map of finite presentation.
We say an element $a \in A$ is {\it elementary standard in $A$ over $R$}
if there exists a presentation
$A = R[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
and $0 \leq c \leq \min(n, m)$ such that
\begin{equation}
\label{equation-elementary-standard-one}
a = a' \det(\partial f_j/\partial x_i)_{i, j = 1, \ldots, c}
\end{equation}
for some $a' \in A$ and
\begin{equation}
\label{equation-elementary-standard-two}
a f_{c + j} \in (f_1, \ldots, f_c) + (f_1, \ldots, f_m)^2
\end{equation}
for $j = 1, \ldots, m - c$. We say $a \in A$ is
{\it strictly standard in $A$ over $R$} if there exists a presentation
$A = R[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
and $0 \leq c \leq \min(n, m)$ such that
\begin{equation}
\label{equation-strictly-standard-one}
a = \sum\nolimits_{I \subset \{1, \ldots, n\},\ |I| = c}
a_I \det(\partial f_j/\partial x_i)_{j = 1, \ldots, c,\ i \in I}
\end{equation}
for some $a_I \in A$ and
\begin{equation}
\label{equation-strictly-standard-two}
a f_{c + j} \in (f_1, \ldots, f_c) + (f_1, \ldots, f_m)^2
\end{equation}
for $j = 1, \ldots, m - c$.

\label{lemma-parse-equation-strictly-standard-one}
Let $R$ be a ring. Let $A = R[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
and write $I = (f_1, \ldots, f_m)$. Let $a \in A$. Then
(\ref{equation-strictly-standard-one}) implies
there exists an $A$-linear map
$\psi : \bigoplus\nolimits_{i = 1, \ldots, n} A \text{d}x_i \to A^{\oplus c}$
such that the composition
$$
A^{\oplus c} \xrightarrow{(f_1, \ldots, f_c)}
I/I^2 \xrightarrow{f \mapsto \text{d}f}
\bigoplus\nolimits_{i = 1, \ldots, n} A \text{d}x_i
\xrightarrow{\psi}
A^{\oplus c}
$$
is multiplication by $a$. Conversely, if such a $\psi$ exists, then
$a^c$ satisfies (\ref{equation-strictly-standard-one}).

\label{proposition-lift-smooth}
\begin{slogan}
Smooth and syntomic algebras lift along surjections
\end{slogan}
Let $R \to R_0$ be a surjective ring map with kernel $I$.
\begin{enumerate}
\item If $R_0 \to A_0$ is a syntomic ring map, then there exists a syntomic
ring map $R \to A$ such that $A/IA \cong A_0$.
\item If $R_0 \to A_0$ is a smooth ring map, then there exists a smooth
ring map $R \to A$ such that $A/IA \cong A_0$.
\end{enumerate}

\label{lemma-neron-functorial}
In Situation \ref{situation-neron} N\'eron's blowup is functorial
in the following sense
\begin{enumerate}
\item if $a \in A$, $a \not \in \mathfrak p$, then N\'eron's blowup
of $A_a$ is $A'_a$, and
\item if $B \to A$ is a surjection of flat finite type $R$-algebras
with kernel $I$, then $A'$ is the quotient of $B'/IB'$ by its
$\pi$-power torsion.
\end{enumerate}

\label{lemma-neron-desingularization}
In Situation \ref{situation-neron}
assume that $R \to A$ is smooth at $\mathfrak q$
and that $R/\pi R \subset \Lambda/\pi \Lambda$ is a separable
extension of fields. Then after a finite number of affine N\'eron
blowups the algebra $A$ becomes smooth over $R$ at $\mathfrak p$.

\label{lemma-neron-colimit}
\begin{slogan}
Unramified extensions of DVRs are ind-smooth AKA N\'eron desingularization
\end{slogan}
Let $R \subset \Lambda$ be an extension of discrete valuation
rings which has ramification index $1$ and induces a separable
extension of residue fields and of fraction fields.
Then $\Lambda$ is a filtered colimit of smooth $R$-algebras.

\label{proposition-lift}
\begin{slogan}
Ind-smoothness of an algebra is stable under infinitesimal deformations
\end{slogan}
Let $R \to \Lambda$ be a ring map. Let $I \subset R$ be an ideal.
Assume that
\begin{enumerate}
\item $I$ is nilpotent,
\item $\Lambda/I\Lambda$ is a filtered colimit of smooth $R/I$-algebras, and
\item $R \to \Lambda$ is flat.
\end{enumerate}
Then $\Lambda$ is a filtered colimit of smooth $R$-algebras.

\label{lemma-reduce-to-field}
\begin{slogan}
Proving Popescu approximation reduces to algebras over a field
\end{slogan}
If for every Situation \ref{situation-global} where $R$
is a field PT holds, then PT holds in general.

\label{lemma-delocalize-weak}
\begin{reference}
\cite[Lemma 12.2]{swan} or
\cite[Lemma 2]{popescu-GND}
\end{reference}
Let $R \to A \to \Lambda \supset \mathfrak q$ be as in
Situation \ref{situation-local}. Let $\mathfrak p = R \cap \mathfrak q$.
Assume that $\mathfrak q$ is minimal over $\mathfrak h_A$ and that
$R_\mathfrak p \to A_\mathfrak p \to \Lambda_\mathfrak q
\supset \mathfrak q\Lambda_\mathfrak q$ can be resolved.
Then there exists a factorization $A \to C \to \Lambda$ with $C$ of
finite presentation such that $H_{C/R} \Lambda \not \subset \mathfrak q$.

\label{lemma-resolve-general}
Let $k \to A \to \Lambda \supset \mathfrak q$ be as in
Situation \ref{situation-local} where
\begin{enumerate}
\item $k$ is a field of characteristic $p > 0$,
\item $\Lambda$ is Noetherian and geometrically regular over $k$,
\item $\mathfrak q$ is minimal over $\mathfrak h_A$.
\end{enumerate}
Then $k \to A \to \Lambda \supset \mathfrak q$ can be resolved.

\label{definition-length-at-x}
Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $x \in |X|$. Let $d \in \{0, 1, 2, \ldots, \infty\}$.
We say {\it $\mathcal{F}$ has length $d$ at $x$}
if the equivalent conditions of Lemma \ref{lemma-length}
are satisfied.

\label{lemma-length-closed-immersion}
Let $S$ be a scheme. Let $i : Y \to X$ be a closed immersion of
algebraic spaces over $S$. Let $\mathcal{G}$ be a quasi-coherent
$\mathcal{O}_Y$-module. Let $y \in |Y|$ with image $x \in |X|$.
Let $d \in \{0, 1, 2, \ldots, \infty\}$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{G}$ has length $d$ at $y$, and
\item $i_*\mathcal{G}$ has length $d$ at $x$.
\end{enumerate}

\label{lemma-divisor-delta-dimension}
In Situation \ref{situation-setup} let $X/B$ be good. Assume $X$ is
integral.
\begin{enumerate}
\item If $Z \subset X$ is an integral closed subspace, then
the following are equivalent:
\begin{enumerate}
\item $Z$ is a prime divisor,
\item $|Z|$ has codimension $1$ in $|X|$, and
\item $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}
\item If $Z$ is an irreducible component of an effective Cartier
divisor on $X$, then $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}

\label{lemma-prepare-geometric-cap}
In Situation \ref{situation-setup} let $Y/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_Y$-module.
Let $s \in \Gamma(Y, \mathcal{L})$ be a regular section and
assume $\dim_\delta(Y) \leq k + 1$.
Write $[Y]_{k + 1} = \sum n_i[Y_i]$ where $Y_i \subset Y$ are the
irreducible components of $Y$ of $\delta$-dimension $k + 1$.
Set $s_i = s|_{Y_i} \in \Gamma(Y_i, \mathcal{L}|_{Y_i})$. Then
\begin{equation}
\label{equation-equal-as-cycles}
[Z(s)]_k =  \sum n_i[Z(s_i)]_k
\end{equation}
as $k$-cycles on $Y$.

\label{definition-bivariant-class}
\begin{reference}
Similar to \cite[Definition 17.1]{F}
\end{reference}
In Situation \ref{situation-setup} let $f : X \to Y$ be a morphism of
good algebraic spaces over $B$. Let $p \in \mathbf{Z}$.
A {\it bivariant class $c$ of degree $p$ for $f$} is given by a rule
which assigns to every morphism $Y' \to Y$ of good algebraic spaces over $B$
and every $k$ a map
$$
c \cap - : \CH_k(Y') \longrightarrow \CH_{k - p}(X')
$$
where $X' = Y' \times_Y X$, satisfying the following conditions
\begin{enumerate}
\item if $Y'' \to Y'$ is a proper morphism, then
$c \cap (Y'' \to Y')_*\alpha'' = (X'' \to X')_*(c \cap \alpha'')$
for all $\alpha''$ on $Y''$,
\item if $Y'' \to Y'$ a morphism of good algebraic spaces over $B$
which is flat of relative dimension $r$, then
$c \cap (Y'' \to Y')^*\alpha' = (X'' \to X')^*(c \cap \alpha')$
for all $\alpha'$ on $Y'$,
\item if $(\mathcal{L}', s', i' : D' \to Y')$ is as in
Definition \ref{definition-gysin-homomorphism}
with pullback $(\mathcal{N}', t', j' : E' \to X')$ to $X'$,
then we have $c \cap (i')^*\alpha' = (j')^*(c \cap \alpha')$
for all $\alpha'$ on $Y'$.
\end{enumerate}
The collection of all bivariant classes of degree $p$ for $f$ is
denoted $A^p(X \to Y)$.

\label{definition-chow-cohomology}
In Situation \ref{situation-setup} let $X/B$ be good. The {\it Chow cohomology}
of $X$ is the graded $\mathbf{Z}$-algebra $A^*(X)$ whose degree
$p$ component is $A^p(X \to X)$.

\label{lemma-first-chern-class}
In Situation \ref{situation-setup} let $X/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
The first Chern class of $\mathcal{L}$ on $X$ of
Definition \ref{definition-chern-classes}
is equal to the bivariant class of Lemma \ref{lemma-cap-c1-bivariant}.

\label{lemma-chern-classes-E-tensor-L}
In Situation \ref{situation-setup} let $X/B$ be good.
Let $\mathcal{E}$ be a finite locally free sheaf of
rank $r$ on $X$. Let $\mathcal{L}$ be an invertible
sheaf on $X$. Then we have
\begin{equation}
\label{equation-twist}
c_i({\mathcal E} \otimes {\mathcal L})
=
\sum\nolimits_{j = 0}^i
\binom{r - i + j}{j} c_{i - j}({\mathcal E}) c_1({\mathcal L})^j
\end{equation}
in $A^*(X)$.

\label{lemma-stalk-push-finite}
Let $S$ be a scheme. Let $f : X \to Y$ be a finite morphism of algebraic
spaces over $S$. Let $\overline{y}$ be a geometric point of $Y$ with
lifts $\overline{x}_1, \ldots, \overline{x}_n$ in $X$. Then
$$
(f_*\mathcal{F})_{\overline{y}} =
\prod\nolimits_{i = 1, \ldots, n}
\mathcal{F}_{\overline{x}_i}
$$
for any sheaf $\mathcal{F}$ on $X_\etale$.

\label{lemma-product-is-tensor-product}
Let $S$ be a scheme. Let $f_i : U_i \to X$ be \'etale morphisms
of algebraic spaces over $S$. Then there are isomorphisms
$$
f_{1, !}\underline{\mathbf{Z}} \otimes_{\mathbf{Z}}
f_{2, !}\underline{\mathbf{Z}}
\longrightarrow
f_{12, !}\underline{\mathbf{Z}}
$$
where $f_{12} : U_1 \times_X U_2 \to X$ is the structure morphism
and
$$
(f_1 \amalg f_2)_! \underline{\mathbf{Z}}
\longrightarrow
f_{1, !}\underline{\mathbf{Z}} \oplus
f_{2, !}\underline{\mathbf{Z}}
$$

\label{lemma-vanishing-above-dimension}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Assume $\dim(X) \leq d$ for some integer $d$.
Let $\mathcal{F}$ be a quasi-coherent sheaf $\mathcal{F}$ on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for any quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ for any closed subspace
$Z \subset X$ whose complement is quasi-compact.
\end{enumerate}

\label{definition-coherent}
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
A quasi-coherent module $\mathcal{F}$ on $X$ is called {\it coherent}
if $\mathcal{F}$ is a coherent $\mathcal{O}_X$-module on the site
$X_\etale$ in the sense of
Modules on Sites, Definition \ref{sites-modules-definition-site-local}.

\label{lemma-vanishing-base-change}
In Situation \ref{situation-vanishing}.
\begin{enumerate}
\item Given an affine morphism $X' \to X$ of algebraic spaces, we have
$H^1(X', \mathcal{F}') = 0$ for every quasi-coherent
$\mathcal{O}_{X'}$-module $\mathcal{F}'$.
\item Given an $A$-algebra $A'$ setting $X' = X \times_{\Spec(A)} \Spec(A')$
the morphism $X' \to X$ is affine and $\Gamma(X', \mathcal{O}_{X'}) = A'$.
\end{enumerate}

\label{lemma-vanishing-injective}
In Situation \ref{situation-vanishing} the morphism $p : X \to \Spec(A)$ is
universally injective.

\label{lemma-vanishing-separated}
In Situation \ref{situation-vanishing} the morphism $p : X \to \Spec(A)$ is
separated.

\label{proposition-vanishing-affine}
\begin{slogan}
Serre's criterion for affineness in the setting of algebraic spaces.
\end{slogan}
A quasi-compact and quasi-separated algebraic space is affine
if and only if all higher cohomology groups of quasi-coherent sheaves
vanish. More precisely, any algebraic space as in
Situation \ref{situation-vanishing} is an affine scheme.

\label{lemma-image-affine-finite-morphism-affine-Noetherian}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of algebraic
spaces over $S$. Assume
\begin{enumerate}
\item $f$ finite,
\item $f$ surjective,
\item $Y$ affine, and
\item $X$ Noetherian.
\end{enumerate}
Then $X$ is affine.

\label{lemma-surjective-finite-morphism-ample}
Let $R$ be a Noetherian ring. Let $f : Y \to X$ be a morphism of
algebraic spaces proper over $R$. Let $\mathcal{L}$ be an
invertible $\mathcal{O}_X$-module. Assume $f$ is finite and surjective.
The following are equivalent
\begin{enumerate}
\item $X$ is a scheme and $\mathcal{L}$ is ample, and
\item $Y$ is a scheme and $f^*\mathcal{L}$ is ample.
\end{enumerate}

\label{lemma-higher-direct-images-zero-above-dimension-fibre}
\begin{slogan}
For proper maps, stalks of higher direct images are trivial in degrees
larger than the dimension of the fibre.
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Let $\overline{y}$ be a geometric point of $Y$.
Assume
\begin{enumerate}
\item $Y$ locally Noetherian,
\item $f$ is proper, and
\item $\dim(X_{\overline{y}}) = d$.
\end{enumerate}
Then for any coherent sheaf $\mathcal{F}$ on $X$ we have
$(R^pf_*\mathcal{F})_{\overline{y}} = 0$ for all $p > d$.

\label{lemma-syntomic-smooth-etale-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$.
Assume that
\begin{enumerate}
\item $f$ is surjective, and syntomic (resp.\ smooth, resp.\ \'etale),
\item $p$ is syntomic (resp.\ smooth, resp.\ \'etale).
\end{enumerate}
Then $q$ is syntomic (resp.\ smooth, resp.\ \'etale).

\label{lemma-smooth-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is smooth (resp.\ \'etale).
\end{enumerate}
Then $q$ is smooth (resp.\ \'etale).

\label{lemma-syntomic-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is syntomic.
\end{enumerate}
Then both $q$ and $f$ are syntomic.

\label{lemma-descend-reduced}
\begin{slogan}
A flat and surjective morphism of algebraic spaces with a reduced source
has a reduced target.
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
If $f$ is flat and surjective and $X$ is reduced, then $Y$ is reduced.

